return {
  ["00:26f2"] = "Evento objeto",
  ["03:4d41"] = "{STRBUF} usou\nSUPERFORÇA!",
  ["03:4d46"] = "{STRBUF} pode\nmover pedras.",
  ["03:4d69"] = "Um #MON pode\nser capaz de mover\011isto.\012Deseja usar a\nSUPERFORÇA?",
  ["03:4d6e"] = "As pedras agora\npodem ser movidas!",
  ["03:4d73"] = "Um #MON pode\nser capaz de mover\011isto.",
  ["03:4f58"] = "{STRBUF} usou\nESMAGA-PEDRAS!",
  ["03:4f72"] = "Talvez um #MON\npossa quebrar\011isso.",
  ["03:4f77"] = "Essa pedra parece\nser quebrável.\012Quer usar o\nESMAGA-PEDRAS?",
  ["09:6f9b"] = "É um MAPA que\ncontém todas as\011CIDADES do CONTI-\011NENTE.",
  ["09:6fa3"] = "É um pôster de um\nlindo PIKACHU.",
  ["09:6fab"] = "É um pôster de uma\nlinda CLEFAIRY.",
  ["09:6fb3"] = "É um pôster de um\nlindo JIGGLYPUFF.",
  ["09:6fd8"] = "É adorável! {STRBUF}.",
  ["09:6fe6"] = "Um boneco gigante!\nÉ tão macio e\011fofo.",
  ["15:4122"] = "Oi! Sou WHITNEY!\012Todos viciaram em\n#MON, então eu\011viciei também!\012Os #MON são\nlindos!\012Quer batalhar?\nEntão te aviso--\011sou boa!",
  ["15:41a5"] = "Não…\012…Arrgh!\nVocê é mau!\012Não deveria ser\ntão sério! Sua…\011sua criança!",
  ["15:41f4"] = "Ahhhhh!\012Ahhhhh!\012…Sniff, hic…\n…Seu malvado!",
  ["15:4222"] = "…Sniff…\012O quê? O que quer?\nUma INSÍGNIA?\012Oh, certo.\nEu esqueci. Aqui\011está a INSÍGNIA\011DA PLANÍCIE.",
  ["15:4273"] = "{PLAYER} foi pre-\nsenteado com uma\012INSÍGNIA DA PLANÍ-\nCIE DO GINÁSIO DA\012CIDADE DE GOLDENROD.",
  ["15:428b"] = "A INSÍGNIA DA PLA-\nNÍCIE deixa seu\012#MON usar SUPERFORÇA\nfora da batalha.\012Também acelera\nseus #MON.\012Oh, leve isso\ntambém!",
  ["15:4302"] = "É o ATRAÇÃO!\nFaz uso total do\012charme dos #-\nMONS.\012Não é perfeito pa-\nra uma linda como\011eu?",
  ["15:4360"] = "Ah, esse foi um\nbom choro!\012Venha me ver de\nnovo! Tchauzinho!",
  ["15:439b"] = "Não deixe a be-\nleza de meus #-\012MONS enganá-lo.\nPodem destruí-lo!",
  ["15:43d6"] = "Droga… Achei que\nvocê era fraco…",
  ["15:43f6"] = "Meus #MON me\nacham linda?",
  ["15:4411"] = "Gosto mais de\n#MON lindos\011que fortes.\012Mas tenho ambos\ntipos!",
  ["15:445f"] = "Oh, não, não, não!",
  ["15:4470"] = "Estou tentando\nvencer WHITNEY,\011mas… É deprimente.\012Estou bem! Se\nperder, treinarei\012mais na próxima!",
  ["15:44d4"] = "Oh, não. Você fez\nWHITNEY chorar.\012Está bem. Logo\nela parará. Ela\012sempre chora\nquando perde.",
  ["15:452d"] = "Oh, você é um lin-\ndo treinador!\012Gosto de você, mas\nnão facilitarei!",
  ["15:4574"] = "Vamos ver… Opa,\njá acabou?",
  ["15:458f"] = "Uau, você deve ser\nbom para me derro-\011tar. Não relaxe!",
  ["15:45be"] = "Dê o seu melhor,\nou será derrotado!",
  ["15:45ed"] = "Não! Oh, MEOWTH,\nsinto muito!",
  ["15:460b"] = "Ensinei golpes ao\nMEOWTH para vencer\011qualquer tipo…",
  ["15:463a"] = "Ei! CAMPEÃO em\nprogresso!\012Nesse GINÁSIO\nestão treinadores\011de #MON\011normais.\012Recomendo-lhe usar\n#MON do tipo\011lutador.",
  ["15:46a7"] = "Você venceu?\nÓtimo! Estava\011ocupado admirando\011as damas daqui.",
  ["15:4787"] = "…poxa… Mudei-me\npara cá, mas não\012consigo vender\nminhas bicicletas.\012Por quê?\012Poderia usar uma\nBICICLETA e fazer\011propaganda para\011mim?",
  ["15:47f8"] = "Sério? Ótimo!\012Dê-me seu nome e\nnúmero de telefo-\012ne, e te empresta-\nrei uma BICICLETA.",
  ["15:4848"] = "{PLAYER} pegou uma\nBICLICLETA empres-\012tada.",
  ["15:485f"] = "Minhas BICICLETAS\nsão ótimas! Pode\012ir a todo lugar\ncom elas.",
  ["15:4898"] = "…poxa… Oh, pela\ngentileza das\011pessoas…",
  ["15:48ed"] = "É uma BICICLETA\nnova e brilhante!",
  ["15:49a3"] = "Se tratar bem seu\nPOKÉMON, eles o\012tratarão com amor.\012Oh? Deixe-me ver\nseu {STRBUF}…",
  ["15:49fc"] = "Ele está bem\nfeliz! Deve lhe\011amar muito.",
  ["15:4a2c"] = "Eu sinto que ele\nconfia mesmo em\011você.",
  ["15:4a5a"] = "É bem amigável com\nvocê. Ele parece\011estar feliz.",
  ["15:4a8e"] = "É bem lindo.",
  ["15:4a9f"] = "Deve tratá-lo me-\nlhor. Ele não se\011apegou a você.",
  ["15:4ad1"] = "Parece não gostar\nde você. Ele pare-\011ce triste.",
  ["15:4b04"] = "Eu sempre perco as\nbatalhas, e meu\012POKÉMON acaba des-\nmaiando…\012Talvez seja por\nele não gostar de\011mim…",
  ["15:4b67"] = "Quando uso um item\nno meu POKÉMON,\011ele fica alegre!",
  ["15:4c74"] = "BILL: Oi, {PLAYER}!\nFaça-nos um favor\011e leve esse EEVEE.\012Ele veio quando eu\nestava ajustando a\011CÁPSULA DO TEMPO.\012Alguém tem que\ncuidar dele, mas\012eu não gosto de\nficar saindo.\012Posso contar com\nvocê para isso,\011{PLAYER}?",
  ["15:4d3f"] = "BILL: Sabia que\nme ajudaria!\012Hora de ir! Você\né um grande amigo!\012Certo, estou con-\ntando com você.\012Cuide bem dele!",
  ["15:4dae"] = "{PLAYER} recebeu\nEEVEE!",
  ["15:4dc1"] = "BILL: O PROFESSOR\nELM diz que EEVEE\012pode evoluir em\nnovos modos des-\011conhecidos.",
  ["15:4e02"] = "Ei, espere. Você\nnão pode levar\011mais #MON.",
  ["15:4e2d"] = "Oh… Agora o que\nfarei?",
  ["15:4e42"] = "BILL: Papai não\ntrabalha. Tudo que\012faz é passear o\ndia todo.\012Ele está virando\numa dor de cabeça…",
  ["15:4ea8"] = "Oh, você coleta\n#MON? Meu fi-\011lho BILL é um\011expert.\012Ele acabou de\nser chamado pelo\012CENTRO #MON da\nCIDADE DE ECRUTEAK.\012Meu marido foi à\nCASA DE JOGOS sem\012ter sido chamado…",
  ["15:4f4e"] = "Meu marido já foi\nconhecido como um\012#MANÍACO.\nBILL deve ter\012puxado seu pai.",
  ["15:4f9e"] = "Você é um trei-\nnador?\012Tenho um telefone\nútil para você.",
  ["15:4fd9"] = "{PLAYER} gravou\no telefone do\011BILL.",
  ["15:4ff3"] = "Meu irmão fez\no sistema de guar-\011dar #MON no\012COMPUTADOR.\012Eu ia te dar\no telefone do\011BILL…",
  ["15:5046"] = "Você não pode\ngravar mais\011telefones.",
  ["15:5069"] = "Meu irmão mais\nvelho, BILL, fez\012o sistema de guar-\ndar #MON no\011COMPUTADOR.",
  ["15:5160"] = "O trem não veio…\012Já sei! Vou levar\nos passageiros nas\011minhas costas!\012Não vai funcionar.",
  ["15:51b7"] = "Logo partiremos\npara SAFFRON.\012Você vai embarcar?",
  ["15:51ed"] = "Posso ver seu\nPASSE, por favor?\012Certo. Por aqui,\npor favor.",
  ["15:522c"] = "Perdão. Voce não\ntem um PASSE.",
  ["15:524f"] = "Esperamos vê-lo\nde novo!",
  ["15:526a"] = "Nós chegamos em\nGOLDENROD.\012Esperamos vê-lo\nde novo.",
  ["15:52a3"] = "Sou o PRESIDENTE.\012Meu sonho era\nfazer um trem mais\012veloz que qualquer\n#MON.\012Ele realmente\ntorna JOHTO e\011KANTO próximos.",
  ["15:53d4"] = "Você viu aquela\nárvore que balan-\011ça na ROTA 36?\012Minha irmãzinha\nficou animada\012e foi ver a\nplanta…\012Estou preocupada…\nNão é perigoso?",
  ["15:5463"] = "Você o pote de\nágua emprestado\012também?\nNão quero que\012você faça algo\nperigoso com ele.",
  ["15:54c2"] = "Oh, você é melhor\nque WHITNEY…\012Você estará bem,\nentão. Aqui está\011o POTESQUIRT!",
  ["15:550d"] = "Não faça algo\nmuito perigoso!",
  ["15:552e"] = "Lalala lalalala.\nTome muita água,\011meu amor!",
  ["15:5561"] = "Quando contei a\nminha irmã sobre\012a árvore agitada,\nela me disse que\011era perigoso.\012Se eu derrotar\nWHITNEY, será que\012ela me emprestará\nseu pote de água…",
  ["15:55e6"] = "Uau, você venceu\nWHITNEY? Legal!",
  ["15:5604"] = "Então realmente\nera um #MON!",
  ["15:5659"] = "Uma vez quando eu\nestava batalhando,\012meu #MON não\npodia usar golpes.\012Os PONTOS DE PO-\nDER, ou PP, de\012seus golpes tinham\nacabado.",
  ["15:56ca"] = "Às vezes, um\n#MON saudável\012pode estar impedi-\ndo de golpear.\012Se isso ocorrer,\ncure-o em um\011CENTRO #MON ou\011use um item.",
  ["15:5993"] = "Bem-vindo à LOJA\nDE DEPARTAMENTOS\011DE GOLDENROD.",
  ["15:59b7"] = "A LOJA DE DEPAR-\nTAMENTOS tem bons\011produtos.\012Mas muitos itens\nsó estão disponí-\012veis na CASA DE\nJOGOS.",
  ["15:5a1a"] = "Hoje vim comprar\nde novo!",
  ["15:5a3a"] = "Mamãe é boa para\npechinchar.\012Ele sempre compra\ncoisas mais\011baratas.",
  ["15:5a80"] = "1ª ANDAR-RECEPÇÃO\0122ª-LOJA DO\nTREINADOR\0123ª-ITENS PARA\nBATALHAS\0124ª-FARMÁCIA\0125ª-LOJA DE TM\0126ª-PRAÇA DA\nTRANQÜILIDADE\012VISTA DO TELHADO.",
  ["15:5c25"] = "A #GEAR pode\nguardar até 10\011telefones.\012É difícil decidir\nquais números\011devem ficar.",
  ["15:5c7b"] = "Eu ganhei meu ABRA\nna CASA DE JOGOS.\012Agora é meu melhor\nparceiro.",
  ["15:5cb7"] = "A LOJA DE DEPARTA-\nMENTOS me confima\012que GOLDENROD é\numa cidade grande.\012Os produtos daqui\nnão se encontram\011em outro lugar.",
  ["15:5d28"] = "Seu Companheiro\nde Viagem.\0122ª ANDAR-LOJA DO\nTREINADOR.",
  ["15:5dcc"] = "Eu, eu, estou\nmesmo impaciente!\012Uso RAPIDEZ X na\nbatalha para ace-\011lerar meu #MON.",
  ["15:5e15"] = "Ei! Quando você\nbatalha, usa o\011ESPECIAL X?\012É ótimo. Realmente\nmelhora o ATAQUE\011ESPECIAL!",
  ["15:5e74"] = "Para Caçadores\nde Vitória.\0123ª ANDAR-ITENS\nPARA BATALHAS.",
  ["15:5f08"] = "Ei. Eu adoro\n#MON fortes.\012Eu dou PROTEÍNA\na eles para melho-\011rar seus ATAQUES.",
  ["15:5f52"] = "FERRO melhora a\nDEFESA do #MON.",
  ["15:5f74"] = "Muitos #MON\nevoluem apenas se\012forem trocados via\nCabo Link.\012Conheço quatro:\nMACHOKE, KADABRA,\012HAUNTER e, hum,\nGRAVELER.\012Soube que há\noutros também.",
  ["15:600d"] = "Deixe-nos Melhorar\nSeus #MON.\0124ª ANDAR-FARMÁCIA.",
  ["15:6143"] = "Olá. Oh, seu\n#MON…",
  ["15:615a"] = "É muito apegado\na você.\012Esse golpe deve\nser perfeito para\011vocês.",
  ["15:61a6"] = "É adorável!\012Você deve ensiná-\nlo bons golpes TM.",
  ["15:61d8"] = "Parece mau. Que\ntal esse TM para\011ele?",
  ["15:6202"] = "Certamente há TMs\nperfeitos para\012seus #MON.",
  ["15:6241"] = "ITEM SECRETO.\012Com apenas um\npequeno bip, você\011ganha um item.",
  ["15:6279"] = "A opção ITEM\nSECRETO requer um\011Game Boy Color.",
  ["15:62ad"] = "Aos domingos, uma\ndama vem para che-\011car os #MON.\012Ela até dá TMs!",
  ["15:62f3"] = "Você não pode re-\nnomear um #MON\011trocado.\012O nome é reflexo\ndos sentimentos do\012treinador original\npor ele.",
  ["15:6364"] = "Personalize seu\n#MON.\0125ª-ANDAR-LOJA DE\nTM.",
  ["15:64cb"] = "Uma máquina de\nvenda. Eis o menu.",
  ["15:64ef"] = "Clang! Uma lata de\n{STRBUF} saiu!",
  ["15:6512"] = "Oops, dinheiro in-\nsuficiente.",
  ["15:652b"] = "Não há espaço para\nisso.",
  ["15:654b"] = "Você ouve o\nCANAL SORTUDO?\012Se quiser ganhar,\ntroque #MON\012com muita gente\npara obter diver-\012sos NÚMEROS DE\nIDENTIFICAÇÃO.",
  ["15:65ca"] = "Se estiver can-\nsado, consuma be-\011bidas da máquina\011de venda.\012Seu #MON vai\namá-la também.",
  ["15:661a"] = "Descanse das\nCompras!\0126ª ANDAR-PRAÇA\nTRANQÜILA.",
  ["15:677f"] = "Ah, estou cansada.\012Às vezes venho\nao telhado para\011descansar das\011compras.",
  ["15:67d2"] = "Perdão? Quem disse\nque um adulto não\011pode vir?\012Eu voltarei aqui\ntodo dia para \012coletar todos\nbonecos.",
  ["15:6839"] = "Eles fazem liqui-\ndações aqui com\011frequência.",
  ["15:6867"] = "Oh, uau!",
  ["15:6871"] = "Vai desistir de\nme perturbar?",
  ["15:688e"] = "Há algo que quero\nmesmo, mas eu não\012tenho o dinheiro\nnecessário…\012Talvez eu venda\nas FRUTAS que eu\011coletei…",
  ["15:6901"] = "Oh, tudo é tão\nbarato!\012Eu comprei demais\ne minha BOLSA está\011cheira!",
  ["15:6942"] = "Meu #MON sempre\nfica paralizado ou\012envenenado quando\nalgo vai mal…\012Então eu venho\ncomprar CURA TUDO.\012Será que tem al-\ngum sobrando?",
  ["15:69c3"] = "Esses binóculos\nme permitem ver\012bem longe. Talvez\npossa ver minha\011casa.\012É aquela com\ntelhado verde?",
  ["15:6a2b"] = "Ei! Alguns trei-\nnadores estão\011batalhando na es-\011trada!\012Um #MON atirou\num monte de\011folhas!\012Isso me faz sentir\ncomo se eu\011estivesse na\011batalha!",
  ["15:6aa6"] = "Um PESCADOR pegou\nmuitas MAGIKARPS…\012Elas estão pulando\nsimultaneamente!\012Olhe à água indo a\ntodo lugar!",
  ["15:6b11"] = "Uma máquina de\nvendas para\011bonecos #MON? \012Insira dinheiro,\ndepois puxe a\011manivela…\012Mas está quase\nvazia…",
  ["15:6e50"] = "99a",
  ["15:6e8b"] = "Qual prêmio você\nquer?",
  ["15:6ea8"] = "{STRBUF}.\nVocê está certo?",
  ["15:6ebd"] = "Aqui está!",
  ["15:6ecb"] = "Perdão! Precisa\nde mais moedas.",
  ["15:6ee8"] = "Perdão. Não pode\nle7ar mais nada.",
  ["15:6f09"] = "Certo. Acumule\nsuas moedas e\011volte depois!",
  ["15:6f35"] = "Oh? Você não tem\num PORTA MOEDA.",
  ["15:6f55"] = "Sempre jogo nesta\nmáquina de roleta.\012Sempre paga mais\nque as outras, eu\011acho.",
  ["15:6f9e"] = "Eu amo essa nova\nmáquina de roleta.\012É mais desafiadora\nque as de CELADON.",
  ["15:6ff4"] = "A vida é um jogo.\nVou jogar cartas\011até eu despencar!",
  ["15:702b"] = "Jogo de cartas…\012Gosto mais dele\nque dos outros\012jogos pois é mais\nfácil de ganhar.\012Mas o pagamento é\nbem menor.",
  ["15:7097"] = "Não pararei até\neu ganhar!",
  ["15:70b1"] = "Eu ensinei NEVASCA\nao meu #MON.\012Foi duro obter\nmoedas suficientes\012para ele, mas\nvaleu a pena.",
  ["15:710d"] = "Não pude vencer\nnas roletas, nem\012no jogo de cartas…\012Fiquei tão furi-\noso que larguei\012meu PORTA MOEDA no\nSUBTERRÂNEO.",
  ["15:718a"] = "Hahahah! As moedas\ncontinuam caindo!",
  ["15:71af"] = "Lançamento:\012MINI-BICICLETAS\nde primeira!",
  ["16:40c7"] = "Hm? É uma #DEX,\ncerto? Eu posso\011vê-la?\012Há tantos tipos\nde #MON.\012Hm? O que é isso?\012Que #MON é\nesse?\012Parecem os\nestranhos desenhos\011nas paredes das\011RUÍNAS. \012Se estes desenhos\nsão mesmo\011#MON, devem\011haver muito mais.\012Já sei! Deixe-me\natualizar sua\011#DEX. Siga-me.",
  ["16:42eb"] = "Hmmm… Esse lugar é\nestranho.",
  ["16:430e"] = "Eu gosto de pensar\naqui.",
  ["16:4325"] = "PEDRA MISTERIOSA\nPALÁCIO DO PAINEL.",
  ["16:4342"] = "RUÍNAS ALFA\012SEJAM BEM-VINDOS,\nTURISTAS.",
  ["16:4362"] = "RUÍNAS ALFA\nCENTRO DE PESQUISA\012A AUTORIDADE NAS\nRUÍNAS ALFA.",
  ["16:43a4"] = "Enquanto\nexplorávamos as\011RUÍNAS, nós de\011repente notamos\011uma presença\011estranha.\012Todos ficamos\nassustados e\011fugimos.\012Você deve ter\ncuidado também.",
  ["16:4420"] = "As RUÍNAS escondem\num grande segredo!\012…Eu acho…",
  ["16:4449"] = "Há tantos tipos de\nUNOWN, então vamos\011usá-los para\011nossos códigos\011secretos.",
  ["16:448e"] = "A… C… I… M… A\nHm… \012O quê?\012Estou decifrando\nesta mensagem!",
  ["16:4612"] = "Símbolos surgiram\nna parede…",
  ["16:4644"] = "Símbolos surgiram\nna parede…",
  ["16:4665"] = "Há um grande\nburaco na parede!",
  ["16:4685"] = "É uma réplica de\num #MON ancião.",
  ["16:46aa"] = "Um #MON que\nvoava graciosamen-\011te com asas de\011arco-íris.",
  ["16:4800"] = "Bem-vindo a esse\npalácio.\012Há paineis\ndeslizantes que\011formam um #MON\011desenhado por\011anciões.\012Deslize os paineis\npara formar uma\011figura.\012À direita é a\ndescrição do\011#MON.\012Os cientistas\natrás estão\011examinando os\011novos símbolos\011encontrados.",
  ["16:48f5"] = "Recentemente,\nestranhos e secre-\011tos símbolos\011apareceram.\012É estranho. Não\nestavam aqui há\011pouco tempo…\012Você deve checar\nestas paredes.",
  ["16:497c"] = "Ah! Aqui há outro\nburaco grande!\012É grande o\nbastante para\011atravessar!",
  ["16:49b8"] = "Esse tremor foi\nbem assustador!\012Mas estou mais\nconcetrado nessas\011paredes aqui…",
  ["16:4aa7"] = "Símbolos surgiram\nna parede…",
  ["16:4ad9"] = "Símbolos surgiram\nna parede…",
  ["16:4afa"] = "Há um grande buraco\nna parede!",
  ["16:4b1a"] = "É uma réplica de\num #MON ancião.",
  ["16:4b3f"] = "Um #MON que se\nesconde no chão\011submarino.\012Olhos em suas\ncostas vasculharam\011a área.",
  ["16:4c8e"] = "Símbolos surgiram\nna parede…",
  ["16:4cc0"] = "Símbolos surgiram\nna parede…",
  ["16:4ce1"] = "Há um grande\nburaco na parede!",
  ["16:4d01"] = "É uma réplica de\num #MON ancião.",
  ["16:4d26"] = "Esse #MON\nagitou o mar ao\011mexer seus dez\011tentáculos.",
  ["16:4e4f"] = "Símbolos surgiram\nna parede…",
  ["16:4e81"] = "Símbolos surgiram\nna parede…",
  ["16:4ea2"] = "Há um grande\nburaco na parede!",
  ["16:4ec2"] = "É uma réplica de\num #MON ancião.",
  ["16:4ee7"] = "Esse #MON\nvoador atacou suas\011vítimas com presas\011tipo serras.",
  ["16:4f89"] = "Há uma presença\nestranha aqui…",
  ["16:4fac"] = "Essa é uma grande\nsala, mas não há\011nada aqui.",
  ["16:4fda"] = "Esse lugar é muito\nmístico.\012Parece ter forças\ndo além.",
  ["16:5024"] = "Construções anciãs\nsão geralmente\011tumbas de reis.\012Como as pirâmides,\npor exemplo.",
  ["16:5072"] = "É uma réplica de\num #MON ancião.",
  ["16:5278"] = "Pronto!\012Alterei sua\n#DEX.\012Eu adicionei uma\nparte para gravar\011dados de UNWONS.\012São gravados na\nordem em que são\011capturados.",
  ["16:52fa"] = "Atualizou-se a\n#DEX de\011{PLAYER}.",
  ["16:5311"] = "O UNOWN que\ncapturar será\011gravado.\012Cheque para ver\nquantos tipos\011existem.",
  ["16:535f"] = "Você capturou\ntodas variações de\011UNOWN?\012Que ótima\ndescoberta!\012Vou ajeitar a\nimpressora para\011manusear UNOWNS.\012Sinta-se à vontade\npara usá-la.",
  ["16:53ed"] = "As RUÍNAS têm uns\n1500 anos.\012Mas não se sabe\nporque foram\011construídas--ou\011por quem.",
  ["16:5445"] = "Quantos tipos de\n#MON devem ter\011nas RUÍNAS?",
  ["16:5478"] = "Surgiram #MON\nnas RUÍNAS? \012Que notícia\nincrível!\012Deveremos checar\nisso.",
  ["16:54cb"] = "Nossa investiga-\nção, com sua\011ajuda, está nos\011levando direto às\011RUÍNAS.\012Elas parecem ter\nsido construídas\011como habitat para\011#MON.",
  ["16:554f"] = "Há estranhos\nsímbolos pintados s\011nas paredes das\011RUÍNAS.\012Eles devem ser\na chave para\011desvendar o\011mistério das\011RUÍNAS.",
  ["16:55cb"] = "Os estranhos\n#MON que você\011viu nas RUÍNAS?\012Eles se parecem\nmuito com os\011desenhos das\011paredes de lá.\012Hmm…\012Isso quer dizer\nque há muitos\011tipos deles…",
  ["16:5769"] = "Por que aqueles\nsímbolos anciãos\011surgiram na parede\011agora?\012O mistério cresce…",
  ["16:57b6"] = "RUÍNAS ALFA\012Décimo ano de\nexploração.",
  ["16:57d9"] = "Misterioso nome\ndo #MON: UNOWN\012Um total de 26\ntipos achados.",
  ["16:580e"] = "Não parece\nfuncionar ainda.",
  ["16:582d"] = "UNOWNS podem ser\nimprimidos.",
  ["16:5886"] = "É uma foto do\ncriador do CENTRO\011DE PESQUISA,\012PROFESSOR\nSILKTREE.",
  ["16:5923"] = "Há muitos livros\nacadêmicos.\012Ruínas Anciãs…\nMistérios dos\011Anciãos…",
  ["16:59ad"] = "É uma réplica de\num #MON ancião.",
  ["16:5a37"] = "É uma réplica de\num #MON ancião.",
  ["16:5ac1"] = "É uma réplica de\num #MON ancião.",
  ["16:5c0b"] = "Está indo para\nAZALEA, né?\012Deixe meu #MON\nver se você sabe\011batalhar bem.",
  ["16:5c5f"] = "Oh, oh, oh!",
  ["16:5c6c"] = "Tudo bem, então!\nJá decidi.\012Não sairei daqui\nenquanto meu\011#MON não\011fortalecer!",
  ["16:5cb5"] = "Eu viajo bastante\nna procura de\011#MON.\012Está procurando\n#MON também?\012Então você é meu\nrival de coleta!",
  ["16:5d1b"] = "Ugh. Meu pobre\n#MON…",
  ["16:5d31"] = "Toda Sexta, você\npode ouvir rugidos\011de #MON das\011profundezas da\011caverna.",
  ["16:5d73"] = "Uau! Que surpresa!\nNão esperava ver\011alguém aqui!",
  ["16:5dae"] = "Uau! Fui\nderrotado!",
  ["16:5dc9"] = "Eu ia comprar um\nRABOSLOWPOKE.\012Mas eu fiquei com\npena do pobre\011#MON.",
  ["16:5e15"] = "O SUPERSÔNICO do\nZUBAT confunde\011meus #MON.\012Estou me\naborrecendo com\011isso!",
  ["16:5e60"] = "Eu me quemei!",
  ["16:5e6f"] = "Nos finais de\nsemana, pode-se\011ouvir estranhos\011rugidos de dentro \012da caverna.",
  ["16:5eaf"] = "Quando iluminada,\numa caverna não\011é assustadora.\012Se for forte, os\n#MON não se\011assustarão.",
  ["16:5ef4"] = "LUZES!",
  ["16:5efc"] = "É o fogo do meu\n#MON que\011ilumina essa\011caverna.",
  ["16:601d"] = "Já faz tempo que\nnão vejo uma\011pessoa.\012Não seja tímido.\nVamos batalhar!",
  ["16:606a"] = "Uurggh…",
  ["16:6073"] = "Estive perdido por\num tempo…\012Não me importo em\nficar aqui, mas\011estou tããão\011faminto!",
  ["16:60bf"] = "Quem é você?\nUm visitante!",
  ["16:60dd"] = "Hahaha! Você é bem\nagitado!",
  ["16:60fb"] = "Eu moro aqui.\012Você pode, também,\nse quiser.\012Há muito espaço,\ncomo pode ver.",
  ["16:614a"] = "Quem está aí?\012Deixe-me sozinho\ncom meu #MON!",
  ["16:6173"] = "Vá…\nVá embora!",
  ["16:6181"] = "Só eu e meu\n#MON.\012Eu deliro de\nalegria.",
  ["16:61b0"] = "Andei tudo por\naqui para conduzir\011minha pesquisa\011#MON.\012Deixe-me mostrar\nminhas descobertas\011numa batalha\011verdadeira!",
  ["16:6217"] = "Você me mostrou!",
  ["16:6230"] = "Eu devo arrumar\ne divulgar minhas\011descobertas.\012Eu até poderei ser\ntão famoso quanto\011o PROFESSOR ELM!",
  ["16:636e"] = "Há dois tipos\nde pessoas.\012Aquelas que têm\nestilo, e aquelas\011que não têm.\012Que tipo de pessoa\nvocê é?",
  ["16:63d5"] = "Você tem um\nestilo incrível!",
  ["16:63f0"] = "O estilo de\nseus #MON é\011colorido e\011ofuscante.\012Eu admito.\012Você só tende\na melhorar!",
  ["16:6444"] = "Estou treinado.\nSe importa em\011batalhar?",
  ["16:6467"] = "Aww, não! É bom\ndemais para mim.",
  ["16:6488"] = "Vou treinar\nsozinho até eu\011melhorar.",
  ["16:64b6"] = "Se o #MON que\ngosto estivesse\011aqui, eu iria a\011qualquer lugar.\012É o que um\ntreinadodor de\011verdade faz.",
  ["16:6507"] = "Uma vez por\nsemana, um #MON\011vem à beira da\011água.\012Eu queria ver\nesse #MON…",
  ["16:652b"] = "Uma vez por\nsemana, um #MON\011vem à beira da\011água.\012Eu queria ver\nesse #MON…",
  ["16:66b5"] = "KURT: Ei, {PLAYER}!\012O guarda acima se\nassustou quando\011eu gritei pra ele.\012Mas, eu levei um\ntombo e caí no\011POÇO.\012Eu bati forte\nminhas costas,\011logo, não me mexo.\012Carambolas! Se eu\nestivesse bem,\012meus POKÉMONS os\npuniria…\012Ah, fazer o quê.\012{PLAYER}, mostre-os\nsua fúria em meu\011lugar!",
  ["16:67ca"] = "KURT: Hora de ir,\n{PLAYER}!\012A EQUIPE ROCKET\nfugiu.\012Minhas costas me-\nlhoraram. Vamos\011sair daqui.",
  ["16:6825"] = "Droga! Eu estava\nde guarda quando\012um velhote me\ngritou.\012Assustei-me tanto\nque caí aqui.\012Acho que vou\ndescontar minha\011fúria em você!",
  ["16:68cc"] = "Arrgh! Esse NÃO é\nmeu dia!",
  ["16:68e8"] = "Claro, estamos\ntirando as caudas\012dos SLOWPOKE e\nas vendendo.\012Tudo que fazemos\né pelo lucro.\012Está certo!\nSomos a EQUIPE\012ROCKET, e faremos\ntudo por dinheiro!",
  ["16:698b"] = "O que você quer?\012Se perturbar nosso\ntrabalho, não se-\011remos piedosos!",
  ["16:69d0"] = "Você foi bem hoje,\nmas aguarde até a\011próxima!",
  ["16:69fc"] = "É, A EQUIPE ROCKET\nquebrou há três\011anos.\012Mas continuamos\nnossas atividades\011no subsolo.\012Agora pode se\ndivertir vendo-nos\011causar problemas!",
  ["16:6a8d"] = "Parar de tirar\nCAUDAS DE\011SLOWPOKE?\012Se obedecermos-\nlhe, a reputação\011da EQUIPE ROCKET\011estará arruinada!",
  ["16:6adf"] = "Simplesmente…\nMuito forte…",
  ["16:6af2"] = "Precisamos do ca-\npital, mas venden-\011do RABOSLOWPOKE?\012É duro ser um\nSOLDADO ROCKET!",
  ["16:6b43"] = "Parar de tirar\nCAUDAR?\012Claro, é só\nnos derrotar!",
  ["16:6b7b"] = "Seu fedelho!",
  ["16:6b8d"] = "O RABOSLOWPOKE\ncresce rápido!\012Qual o problema em\nvendê-los?",
  ["16:6bcb"] = "Um SLOWPOKE com\nsua CAUDA cortada…\012Hã? Tem uma CARTA.\nQuer lê-la?",
  ["16:6c09"] = "{PLAYER} leu a\nCARTA.\012Seja boa e cuide\nda casa com o\012Vovô e com o\nSLOWPOKE.\012Com amor, Papai.",
  ["16:6c61"] = "Um SLOWPOKE com\nsua CAUDA cortada…",
  ["16:6d2a"] = "Preferia cuidar\nde meus bebês!",
  ["16:6df2"] = "Serei como o\nSLOWPOKE.\012Esperarei com\npaciência para ver\011um evoluir.",
  ["16:6e6d"] = "As pessoas\ntreinam no FAROL.\012Não é facil subir\ndevido a todos os\011treinadores.",
  ["16:6ec2"] = "No passado,\nos #MON costu-\011mavam iluminar o\011mar ao redor de\011OLIVINE à noite.\012O FAROL foi feito\npara honrar\011aqueles #MON.",
  ["16:707a"] = "RHomens do mar\nestão sempre\011procurando uma boa\011briga!",
  ["16:70b0"] = "Urf!\nEu perdi!",
  ["16:70f8"] = "Hm? Esse não é\nlugar para\011brincar.",
  ["16:711b"] = "Ah! Posso ver\nque você é sério.",
  ["16:713e"] = "Lá em cima há um\n#MON que\011ilumina o FAROL.\012Mas eu soube que\nele está doente\011agora e não pode\011ser curado por um\011remédio comum.",
  ["16:71b6"] = "Cara! Você está\nforte como nunca!\012De todo modo,\neis o remédio\011procurado.",
  ["16:727b"] = "Por que está aqui?\nVocê vai ficar\011observando como um\011bobo! Sugiro-lhe\011que saia!",
  ["16:72c4"] = "Você está mesmo\npreocupado…",
  ["16:72df"] = "O que quer fazer\nlá em cima?\012Eu quero visitar\no #MON doente,\011mas não consigo\011ir lá…",
  ["16:7333"] = "Os marinheiros são\ngentis e fortes.\012E você?",
  ["16:7365"] = "Você é gentil e\nforte…",
  ["16:7384"] = "Sempre que volto\nà OLIVINE, eu\011visito o GINÁSIO.\012O tipo de #MON\ndo LÍDER do\011GINÁSIO mudou sem\011eu ser avisado.",
  ["16:73f4"] = "Eu viajo pelo\nmundo para treinar\011meus #MON.\012Eu quero batalhar\ncom você.",
  ["16:7437"] = "…poxa… Eu devo\ntreinar mais…",
  ["16:7457"] = "JASMINE usava\n#MONedra\011como o ONIX.",
  ["16:7512"] = "A JASMINE deve\nestar muito\011preocupada com o\011#MON aqui.\012Ela nem sorriu\nnesses dias.",
  ["16:7565"] = "Nem eu posso\nsorrir também…",
  ["16:7584"] = "Falando em doença,\neu soube que há\011uma boa FARMÁCIA\011em CIANWOOD.",
  ["16:75c5"] = "JASMINE é a LÍDER\ndo GINÁSIO desta\011cidade.\012Quero trazê-la de\nvolta comigo. É\011melhor ninguém\011atrapalhar!",
  ["16:762b"] = "Argh! Meus\n#MON!",
  ["16:763c"] = "Certo. Qualquer um\nficaria preocupado\011se seu próprio\011#MON se\011machucasse.\012Vou rezar pelo\n#MON daqui e\011JASMINE poderá\011voltar ao GINÁSIO.",
  ["17:41d3"] = "Olhe! Confira\nminha bolsa!\012Eu imprimi meus\nfavoritos da minha\011#DEX e os pus\011na minha bolsa.",
  ["17:422e"] = "Essa é uma CARTA\nenviada por minha\011filha.\012Isso me anima.",
  ["17:4265"] = "Preste atenção!\012…Opa, tenho que\nparar de pensar\011como um professor\011o tempo todo.\012Você deve ser um\ntreinador #MON.\012Como está\ntrabalhando duro,\011eu quero que leve\011isso.",
  ["17:430d"] = "Deixe um #MON\nsegurar essa\011GARRA VELOZ.\012Ele pode atacar\nprimeiro durante\011as batalhas.",
  ["17:435d"] = "Estou brincando\ncom figuras que\011imprimi da minha\011#DEX.",
  ["17:438f"] = "Se eu vencer, vou\npegar as figuras\011do outro cara.",
  ["17:43bc"] = "Eu caminho pelo\nPARQUE, mas nunca\011vou à grama.\012Os treinadores\nsempre querem\011batalhar…",
  ["17:4416"] = "PERSIAN: Fufushaa!",
  ["17:442a"] = "Estou imprimindo\nminha #DEX.\012Você pode imprimir\nalgo como CARTAS\011e BOXES do\011COMPUTADOR também.",
  ["17:447e"] = "O mundo\ndos #MON é\011profundo.\012Ainda há muitas\ncoisas que não\011sabemos.\012Mas eu sei mais\ndo que você!",
  ["17:44e4"] = "O-o-o-quê?",
  ["17:44f3"] = "Há muito para se\naprender.\012Por exemplo…\012Há 50 tipos de TM.\012#MON trocados\nsobem de nível\011mais rápido.",
  ["17:4552"] = "Meus #MON\nsão simplesmente\011lindos.\012Deixe-me contar o\nquanto me deixam\011orgulhosa.",
  ["17:459e"] = "Posso vencê-lo no\norgulho, mas…",
  ["17:45bd"] = "Devo dizer, seus\n#MON são\011lindos também.",
  ["17:45e9"] = "Nós adoramos\nnossos #MON,\011mesmo se eles não\011nos gostam.\012É assim que um\nFÃ age.",
  ["17:4639"] = "M-meus #MON!",
  ["17:4645"] = "Perdi a batalha,\nmas meus #MON\011ganharam o prêmio\011por serem mais\011amáveis.",
  ["17:468a"] = "Meu amigo tem um\nMARILL!\012Eu acho eles muito\ncontentes.\012Oh, queria ter\num MARILL só meu…",
  ["17:46e4"] = "Olá? Por que\nvocê está me\011encarando?\012Oh, uma batalha?",
  ["17:4715"] = "…Hmmm…",
  ["17:471d"] = "Pensei que você\nestava me olhando\011porque sou linda!",
  ["17:4750"] = "PRAÇA DO DESCANSO\nPARQUE NACIONAL.",
  ["17:4771"] = "Que aviso é este?\012Favor batalhar\nsomente na grama.\012ESCRITÓRIO DO\nCHEFE\012PARQUE NACIONAL.",
  ["17:47c6"] = "DICAS DO TREINADOR\012Imprima uma CARTA\nabrindo-a e\011apertando o START.",
  ["17:494c"] = "DON: Eu vou\nvencer!\012Não me atrapalhe.",
  ["17:4973"] = "ED: Meu PARASECT\nfaz #MON\011dormirem com\011ESPOROS.",
  ["17:49a3"] = "NICK: Estou\ncriando #MON\011rápidos para\011batalhas.",
  ["17:49cc"] = "WILLIAM: Não estou\npreocupado em\011vencer.\012Eu apenas procuro\n#MON raros.",
  ["17:4a15"] = "BENNY: Ssh! Vai\nespantar o\011SCYTHER.\012Depois eu converso\ncom você.",
  ["17:4a52"] = "BARRY: Você deve\nenfraquecer o\011#MON inseto\011antes de jogar a\011BOLA.",
  ["17:4a8f"] = "CINDY: Eu amo\n#MON insetos.\012Acho que você\ngosta deles\011também.",
  ["17:4ac8"] = "JOSH: Eu coleciono\n#MON insetos\011desde quando eu\011era um bebê.\012Não tem como eu\nperder!",
  ["17:4b25"] = "SAMUEL: Se você\ntiver tempo\011disponível, vá\011achar #MON\011insetos.",
  ["17:4b64"] = "KIPP: Eu estudei\nmuito sobre\011#MON insetos.\012Eu certamente\nvencerei.",
  ["17:4ba7"] = "PRAÇA DO DESCANSO\nPARQUE NACIONAL.",
  ["17:4bc8"] = "Que aviso é este?\012Favor batalhar\nsomente na grama.\012ESCRITÓRIO DO\nCHEFE\012PARQUE NACIONAL.",
  ["17:4c1d"] = "DICAS DO TREINADOR\012Imprima uma CARTA\nabrindo-a e\011apertando o START.",
  ["17:4e77"] = "Bem-vindo!",
  ["17:4e81"] = "Olá. Perdoe-me,\nmas não estamos\011sorteando passeios\011hoje.",
  ["17:4eba"] = "Oi, está aqui pa-\nra o SHOW DO NÚM-\011ERO SORTUDO?\012Quer que eu olhe\nos NÚMEROS DE\011IDENTIFICAÇÃO de\011seus #MON?\n\012Se tiver sorte,\nganhará um prêmio.",
  ["17:4f3a"] = "O número desta\nsemana é {STRBUF}.",
  ["17:4f5a"] = "Deixe-me ver\nalgum combinou.",
  ["17:4f7e"] = "Volte na próxima\nsemana para o\011NÚMERO SORTUDO.",
  ["17:4fb5"] = "Uau! Todos cinco\nnúmeros se combi-\011naram direito!\012Temos um grande\nvencedor!\012Você ganhou uma\nBOLA MESTRA!",
  ["17:5023"] = "Ei! Os três\núltimos números\011se combinaram!\012Você ganhou o\n2ª prêmio,\011um DIVIDE EXP.!",
  ["17:5076"] = "Ooh, os dois\núltimos números\011se combinaram.\012Você ganhou o\n3ª prêmio,\011um PP MAIS.",
  ["17:50c0"] = "Não, nenhum dos\nnúmeros combinou.",
  ["17:50e6"] = "Você não tem lugar\npara o prêmio.\012Libere lugar\ne volte depois.",
  ["17:512d"] = "Temos um show\nde perguntas e\011respostas.\012Responda às cinco\nquestões correta-\011mente para ganhar\011o CARTÃO DE RÁDIO.\012Use sua #GEAR\npara tocar rádio\012a qualquer hora ou\nlugar.\012Aceita o desafio?",
  ["17:51f2"] = "Pergunta 1:\012Há um #MON\nque só aparece\011de manhã?",
  ["17:5231"] = "Correto!\nPergunta 2:\012Esta frase está\ncorreta?\012Não há FRUTAS em\nLOJAS.",
  ["17:5282"] = "Na mosca!\nPergunta 3:\012O HM01 contém\no golpe LUZES?",
  ["17:52bc"] = "Muito bom!\nPergunta 4:\012É FALKNER, o LÍDER\nDO GINÁSIO DE\011VIOLET, que usa\011#MON pássaros?",
  ["17:530e"] = "Uau! Certo de\nnovo!\012Agora a pergunta\nfinal:\012As MÁQUINAS DA CA-\nSA DE JOGOS DE\011GOLDENROD têm\012CHARMANDERS nas\nroletas?",
  ["17:537b"] = "Bingo! Você conse-\nguiu! Parabéns!\012Aqui está seu,\nprêmio, CARTÃO DE\011RÁDIO.",
  ["17:53c0"] = "A #GEAR de\n{PLAYER} pode ser\011um rádio agora!",
  ["17:53e5"] = "Sintonize em nos-\nsos programas de\011rádio.",
  ["17:5409"] = "Oh, querido.\nPerdão, mas você\011errou.\012Tente de novo!",
  ["17:5443"] = "Oh. Entendo. Volte\naqui se mudar de\011idéia.",
  ["17:5476"] = "O BEN é um DJ\nfabuloso. \012Sua voz doce me\nfaz derreter!",
  ["17:54ac"] = "Eu amo a MARY, do\nSHOW #MON.\012Eu só sei do\nque ela parece\011gostar.",
  ["17:54f4"] = "Nós finalmente\ndominamos a\011TORRE DE RÁDIO!\012Agora todos expe-\nrimentarão o ver-\012dadeiro terror da\nEQUIPE ROCKET!\012Mostraremos-lhe\ncomo somos assus-\011tadores!",
  ["17:5582"] = "Bem forte! Só de-\nvemos observá-lo…",
  ["17:55a2"] = "Você é bem forte.\012Nosso plano pode-\nria ser arruinado.\011Devo avisar aos\011outros…",
  ["17:55e7"] = "1ª ANDAR-RECEPÇÃO\n2ª-LOJAS\0123ª-FUNCIONÁRIOS\n4ª-PRODUÇÃO\0125ª-ESCRITÓRIO DO\nDIRETOR.",
  ["17:5631"] = "CANAL SORTUDO!\012Ganhe com os núme-\nros dos #MON!\012Troque seus #-\nMONS para ter\011vários NÚMEROS DE\011IDENTIFICAÇÃO!",
  ["17:5924"] = "Você pode ouvir\nrádio em qualquer\011lugar. Sintonize!",
  ["17:5956"] = "As melodias no rá-\ndio fazem meus\011#MON dormirem.",
  ["17:5983"] = "Por que eles que-\nrem dominar a\011TORRE DE RÁDIO?",
  ["17:59b6"] = "JIGGLYPUFF:\nJiggly…",
  ["17:59cb"] = "Perdão. Só pessoas\nautorizadas passam\011daqui.\012Não era assim\nantes.\012Há algo de errado\ncom o DIRETOR…",
  ["17:5a44"] = "Ande à vontade\nonde quiser.\012O DIRETOR está\nbem de novo, como\011era antes.",
  ["17:5a9b"] = "Há 3 anos, a EQUI-\nPE ROCKET foi\011forçada a falir. \012Mas estamos retor-\nnando aqui!",
  ["17:5af1"] = "Argh! Não fique\nalegre!",
  ["17:5b07"] = "Não deixaremos\nvocê arruinar nos-\011sos planos de re-\011torno!",
  ["17:5b39"] = "Somos a EQUIPE\nROCKET, os explo-\011radores de #-\011MONS!\012Adoramos ser maus!\nAssustou-se?",
  ["17:5b80"] = "Você se acha um\nherói?",
  ["17:5b99"] = "Nem sempre somos\nmaus. Só fazemos\011tudo que gostamos.",
  ["17:5bcd"] = "Ei, ei! Afaste-se\ndo nosso caminho!",
  ["17:5bed"] = "Arggh. Eu desisto.",
  ["17:5c00"] = "Nossos EXECUTIVOS\nestão tentando do-\011minar este lugar.\012Eles têm grandes\nplanos. Quais será\011que são?",
  ["17:5c64"] = "Hahaha!\012Que chato.\nFoi muito fácil\012dominar este lu-\ngar!\012Venha, mantenha-me\nalegre!",
  ["17:5cbf"] = "Qu-quem é você?",
  ["17:5cd0"] = "Você me venceu. Eu\nlembrarei isso!",
  ["17:5cf4"] = "BUENA: Oi! Eu sou\nBUENA!\012Você sabe algo\ndo programa de rá-\011dio chamado SENHA?\012Se puder me contar\na senha do pro-\012grama, você ganha-\nrá pontos.\012Guarde estes pon-\ntos e troque-os\012com aquela linda\ne jovem dama ali\012para escolher\nos prêmios!\012Aqui está!\012É o seu próprio\ncartão de pontos!",
  ["17:5e10"] = "BUENA: Sintonize\nno meu SHOW DA \011SENHA!",
  ["17:5e35"] = "BUENA: Oi!\nVocê sintonizou em\011meu show de rádio?\012Se lembra da\nsenha de hoje?",
  ["17:5e84"] = "BUENA: Oh, uau!\nObrigada!\012Qual era seu nome\nmesmo?\012…{PLAYER}, Certo!\012Venha, {PLAYER}.\nJunte-se ao meu\011programa.",
  ["17:5edd"] = "BUENA: Todos\nprontos?\012Quero ouvir vocês\ngritando a senha\012de hoje de\n{PLAYER}!",
  ["17:5f29"] = "BUENA: Volte após\nvocê escutar ao\012meu show, certo?\nVejo-o depois!",
  ["17:5f6c"] = "BUENA: Perdão…\012Você só tem uma\nchance por dia.\012Volte amanhã para\noutra tentativa!",
  ["17:5fc1"] = "BUENA: IUPI!\nÉ isso aí!\012Você sintonizou!\nEstou tão feliz!\012Você recebeu um\nponto! Parabéns!",
  ["17:601c"] = "BUENA: Ahh…\nNão é isso…\012Se esqueceu da\nsenha?",
  ["17:6054"] = "BUENA: Yup! Nosso\nparticipante foi\012{PLAYER}.\nObrigada por vir!\012Espero que todos\nouvintes venham\012também!\nEstarei esperando!",
  ["17:60c2"] = "BUENA: Hã?\nA senha de hoje?\012AJUDA, é claro!",
  ["17:60f1"] = "BUENA: Seu CARTÃO\nAZUL está cheio.\012Troque seu conte-\núdo por prêmios\011fabulosos!",
  ["17:6131"] = "BUENA: Sintonize\nna SENHA toda\012noite das seis à\nmeia-noite!\012Sintonize, depois\nfaça uma visita!",
  ["17:6192"] = "BUENA: Oh? Se\nesqueceu de trazer\011seu CARTÃO AZUL?\012Não posso te\ndar pontos se não\011possui-lo.",
  ["17:61ee"] = "BUENA: Oh! Seu\nCARTÃO AZUL chegou\012a 30 pontos hoje!\nÉ tão selvagem!\012Hmm… Não há\nprêmios por chegar\011a 30 pontos, mas…\012Você vem muito\naqui, {PLAYER}.\012Farei-lhe uma\noferta especial!\012Gostaria de\nter o meu número\011de telefone?",
  ["17:62bf"] = "BUENA: {PLAYER},\ndeseja registrar\012meu número de\ntelefone?",
  ["17:62f3"] = "{PLAYER} registrou\no número de BUENA.",
  ["17:6310"] = "BUENA: Eu queria\nouvir isto de\011você!",
  ["17:633c"] = "BUENA: Ahh… É um\nprêmio especial…",
  ["17:635e"] = "BUENA: {PLAYER},\nsua lista de\012telefones não tem\nespaço para mim…",
  ["17:6392"] = "Você pode gastar\nseus pontos guar-\012dados em prêmios\nda sua escolha!",
  ["17:63d8"] = "Você não pode\ntrocar pontos sem\011seu CARTÃO AZUL.\012Não esqueça seu\nCARTÃO AZUL!",
  ["17:6426"] = "2ª ANDAR-LOJAS.",
  ["17:6430"] = "SHOW DO CARVALHO\012O Programa Mais\nQuente no Ar!",
  ["17:6463"] = "Anywhere, Anytime\nPOKéMON Radio",
  ["17:6621"] = "Temos gravações\ndos sons de todos\012#MON encon-\ntrados.\012Devemos ter uns\n200 tipos.",
  ["17:6682"] = "Para os treinado-\nres, #MON são\011seus amados par-\011ceiros.\012É terrível como\na EQUIPE ROCKET\012está tentando\ncontrolá-los.",
  ["17:66eb"] = "Transmitimos 24\npor dia programas\012de entretenimento.\012Farei o meu\nmelhor para\011cumprir esta meta!",
  ["17:6754"] = "O chefe da EQUIPE\nROCKET se trancou.\012Mas o DIRETOR\npode abrir a\011porta.\012Ele está no quinto\nandar.\012Salve-o!",
  ["17:67cb"] = "O DIRETOR está\nseguro?",
  ["17:67e2"] = "Obrigada!\nVocê é meu herói!\012Isso é um pre-\nsente pela minha\011gratidão.",
  ["17:6821"] = "É o DIA DE SOL.\nEle melhora golpes\011tipo fogo por um\011tempo.",
  ["17:685c"] = "Você foi simples-\nmente maravilhoso!",
  ["17:6878"] = "Estive dando\nordens severas.\012Esmagarei todos\nque desafiarem a\011EQUIPE ROCKET!",
  ["17:68c8"] = "O quê?!",
  ["17:68d0"] = "Eu falhei no\nmeu dever…\012Eu pagarei\npor isto…",
  ["17:6904"] = "Nos sentimos bem\nmandando os #-\011MONS cometerem\011crimes.",
  ["17:6934"] = "Está brincando!",
  ["17:6944"] = "Sinto-me horrível\nperdendo!\012Droga! Detesto\n#MON inúteis!",
  ["17:697d"] = "Por que a per-\nsiana abriu?\012Você está metido\nnisto?",
  ["17:69c2"] = "Estou cansado!",
  ["17:69d0"] = "O quê?! Você pas-\nsou por nosso ho-\011mens no SUBTERRÂ-\011NEO?\012Como pôde?",
  ["17:6a14"] = "Um garoto des-\nconhecido aqui?\012Quem é você?",
  ["17:6a43"] = "Tch! Não te\nlevei a sério!",
  ["17:6a61"] = "Bwahahaha…\012Posso enviar\nos sinais fortes\011que preciso aqui.",
  ["17:6aa4"] = "É o encaixe do\nCARTÃO.",
  ["17:6abc"] = "{PLAYER} inseriu\no CARTÃO.",
  ["17:6ad6"] = "3ª ANDAR-\nFUNCIONÁRIOS.",
  ["17:6ae4"] = "MÚSICA #MON\ncom o DJ BEN.",
  ["17:6c12"] = "Eu escutei ao rá-\ndio enquanto esta-\011va nas RUÍNAS.\012Havia uma estranha\ntransmissão lá.",
  ["17:6c68"] = "MARY: Por quê? Por\nque tenho que pas-\011sar por isso?\012MEOWTH, ajude-me!",
  ["17:6cab"] = "MARY: Oh! Você é\nmeu pequeno sal-\011vador!\012Aceitará isso como\nagradecimento?",
  ["17:6cef"] = "MARY: É ótimo\npara #MON que\012sabem golpes do\ntipo normal.",
  ["17:6d2c"] = "MARY: Sintonize\nno SHOW DO CARVA-\011LHO.",
  ["17:6d66"] = "MEOWTH: Meowth…",
  ["17:6d77"] = "Você planeja res-\ngatar o DIRETOR?\012Não será possível\nporque eu vou\011derrotar você!",
  ["17:6dcf"] = "Não!\nInacreditável!",
  ["17:6de2"] = "Eu não acredito!\nEu fui derrotado!",
  ["17:6e04"] = "Pare! Sou conheci-\ndo como Fortaleza\011EQUIPE ROCKET!\012Não dê mais\num passo!",
  ["17:6e50"] = "A fortaleza caiu!",
  ["17:6e69"] = "Você ganhou meu\nrespeito, então\011lhe darei avisos.\012Ainda não é tar-\nde. Você ainda\011pode voltar.",
  ["17:6ec4"] = "Se eu acho meus\n#MON bonitos?\012Eu os acharei\nbonitos--\012após derrotar os\nseus!",
  ["17:6f15"] = "Oh, não! Eles são\ntão inúteis!",
  ["17:6f31"] = "Eu amo minha\nbeleza!\012Quem liga para\n#MON?",
  ["17:6f62"] = "Excelente.\012Essa TORRE DE\nRÁDIO preencherá\011nosso grande\011projeto.",
  ["17:6fa3"] = "Hmmm…\012Todos grandes pla-\nnos têm erros.",
  ["17:6fcb"] = "Você honestamente\ncrê que pode parar\011a EQUIPE ROCKET?",
  ["17:6ffe"] = "4ª ANDAR-PRODUÇÃO.",
  ["17:700d"] = "4ª ANDAR-\nESTÚDIO 2.",
  ["18:4128"] = "Você! Você veio\nme resgatar?",
  ["18:4147"] = "Era o que você\nesperava?\012Errado!\nSou um impostor!\012Pretendo ser o\noriginal para\012preparar nossa\ndominação.\012Quer saber onde\no DIRETOR verda-\011deiro está?\012Claro, lhe conta-\nrei. Mas só se\011você me derrotar!",
  ["18:4223"] = "Certo. Contarei-\nlhe onde ele está.",
  ["18:4246"] = "Nós escondemos o\nDIRETOR original\012no DEPÓSITO do\nSUBTERRÂNEO.\012Está no final\ndo SUBTERRÂNEO.\012Mas duvido que\nchegue lá.",
  ["18:42cb"] = "Lembra-se de mim\ndo ESCONDERIJO da\011CIDADE DE MAHOGANY?\012Lá eu perdi, mas\nserá diferente\011agora.",
  ["18:431e"] = "Não pode ser!\012Eu lutei duro,\nmas ainda perdi…",
  ["18:4358"] = "{PLAYER}, não é?\012Um pirralho como\nvocê não apreci-\012ará a magnífica\nEQUIPE ROCKET.\012Que pena.\nEu realmente admi-\011ro sua força.",
  ["18:43d1"] = "Oh? Você chegou\naqui?\012Você deve ser\num bom treinador.\012Queremos dominar\nessa ESTAÇÃO DE\012RÁDIO e anunciar\nnosso retorno.\012Isso deve trazer\nde volta nosso\012chefe GIOVANNI de\nseu treinamento\011solo.\012Vamos recuperar\nnossa glória.\012Não deixarei você\ninterferir em nos-\011sos planos.",
  ["18:44f3"] = "Não! Perdôe-me,\nGIOVANNI!",
  ["18:450e"] = "Como pode?\012Nosso sonhos\nacabaram.\012Não era o adequado\nà tarefa.\012Como GIOVANNI fez\nantes de mim, vou\012finalizar a EQUIPE\nROCKET hoje aqui.\012Adeus.",
  ["18:45b2"] = "DIRETOR: {PLAYER},\nobrigado!\012Suas ações cora-\njosas salvaram a\012nação #MON.\012Sei que não é\nmuito, mas por\011favor aceite.",
  ["18:462c"] = "Havia uma torre\naqui na CIDADE\011GOLDENROD.\012Mas ela estava\nvelha.\012Então a substitui-\nmos pela nossa\011TORRE DE RÁDIO.\012Nós desenterramos\naquele sino na\011construção.\012Soube que vários\n#MON viveram\012em GOLDENROD no\npassado.\012Talvez…\012Aquele sino tinha\nconexão com a\012TORRE DO SINO na\nCIDADE DE ECRUTEAK…\012Ah!\012Isso me lembra…\012Eu ouvi a EQUIPE\nROCKET falando. \012Parece que algo\nestá acontecendo\011na TORRE DO SINO. \012Não faço idéia do\nque seja,\012mas você deve\nchecá-la.\012Certo, é melhor\neu ir ao meu ES-\011CRITÓRIO.",
  ["18:4824"] = "DIRETOR: Olá,\n{PLAYER}!\012Você sabe, eu amo\n#MON.\012Eu construí essa\nTORRE DE RÁDIO\012para mostrar-lhes\nmeu amor. \012Seria bom se as\npessoas gostassem\011de nossos progra-\011mas.",
  ["18:48be"] = "BEN: Você escuta à\nnossa música?",
  ["18:48e0"] = "5ª ANDAR-\nESCRITÓRIO DO\011DIRETOR.",
  ["18:48f9"] = "5ª ANDAR-\nESTÚDIO 1.",
  ["18:49b3"] = "{sound_caught_mon}Eu quis batalhar\ncom JASMINE, mas\011ela não pode\011fazê-lo agora.\012Que tal você,\nentão?",
  ["18:49fe"] = "Uau, uau. Você\né devastador!",
  ["18:4a1f"] = "Ser um LÍDER DE\nGINÁSIO não é só\011ser forte.\012Um LÍDER também\nprecisa ter\011compaixão.",
  ["18:4a74"] = "Estamos bem alto\naqui. Meus\011#MON pássaros\011estão na melhor\011forma!",
  ["18:4aaf"] = "Opa… Eles bateram…",
  ["18:4ac3"] = "Meus #MON\naprenderam a\011usar o VOAR em\011CIANWOOD.\012Bem, como eu\nperdi, vou voar\011sobre o mar…",
  ["18:4c81"] = "JASMINE: … Esse\n#MON sempre\011mantém o mar\011iluminado à noite.\012…Mas ele de\nrepente adoeceu…\012Não consegue\nrespirar…\012…Eu sei que há\numa FARMÁCIA\011maravilhosa em\011CIANWOOD…\012Mas é do outro\nlado do mar…\012E eu não posso\ndeixar AMPHY\011desacompanhado…",
  ["18:4d64"] = "…Posso pedi-lo\npara pegar remédio\011para mim?\012Por favor!",
  ["18:4d99"] = "JASMINE: …Esse\nremédio curará\011AMPHY?",
  ["18:4dc3"] = "{PLAYER} entregou a\nPOÇÃOSECRETA à\011JASMINE.",
  ["18:4dea"] = "JASMINE: …Hm, não\nfique ofendido…\012…AMPHY não vai\naceitar nada de\011alguém que não\011seja eu…",
  ["18:4e44"] = "JASMINE: …\012AMPHY, como está\nse sentindo?",
  ["18:4e6c"] = "JASMINE: …Oh,\nestou tão\011aliviada…\012Isso é explêndido…\012Muito obrigada,\nmuito mesmo.\012Vou retornar ao\nGINÁSIO…",
  ["18:4edf"] = "JASMINE: …Eu\nentendo…",
  ["18:4ef1"] = "…AMPHY, aguente!",
  ["18:4f03"] = "AMPHY: …\n…Pa… paloo…",
  ["18:4f19"] = "Sua respiração\nestá muito\011forçada…",
  ["18:4f3d"] = "AMPHY: Palu!\nPalulu!",
  ["18:6105"] = "O COLISEU acima\né para batalhas\011conectadas.\012Os resultados\ndas batalhas\011são postados na\011parede, então não\011posso perder.",
  ["18:6260"] = "Um #MON de\nnível maior nem\011sempre vence.\012Afinal, ele deve\nter um tipo de\011desvantagem.\012Eu não penso que\nhá um simples\011#MON que seja o\011mais forte.",
  ["18:62f0"] = "{PLAYER}, isn't it?\012Congratulations!\012As a special deal,\na GS BALL has been\011sent just for you!\012Please accept it!",
  ["18:6359"] = "Please do come\nagain!",
  ["18:63fb"] = "Nossa, sua bolsa\nparece pesada!\012Oh! Você por acaso\nnão tem algo\011chamado CARTA EON?\012Minha filha quer\numa.\012Você poderia me\ndar uma, não é?",
  ["18:648c"] = "Dar uma CARTA\nEON?",
  ["18:64a4"] = "Oh, isso é ótimo!\nObrigado, querido!\012Ei, isso é para\nvocê em troca!",
  ["18:64e9"] = "Minha filha ficará\nmuti feliz!",
  ["18:6509"] = "Oh? Você não tem\numa? Que pena.",
  ["18:652a"] = "Oh… Bem, outra\nhora, então.",
  ["18:6549"] = "{PLAYER} deu uma\nCARTA EON.",
  ["18:6674"] = "POKéCOM CENTER and\nMOBILE CENTER were\012built to satisfy\ndemands for trades\012and battles with\ntrainers far away\012and with total\nstrangers.",
  ["18:66f9"] = "When you linked\nwith someone by\012mobile phone for\nthe first time,\012weren't you\nimpressed?\012When my first try\nworked, I was so\012impressed that I\ngot the shakes!",
  ["18:6795"] = "They were able to\nbuild this huge\012facility thanks to\nadvances in wire-\011less technology.",
  ["18:67ee"] = "It's a notice\nabout where MOBILE\012ADAPTERS are to be\nused…",
  ["18:6828"] = "There's a POKéCOM\nCLUB upstairs in\012any POKéMON\nCENTER.\012There, you can\nbattle or trade\012with a friend far\naway by using a\011MOBILE ADAPTER.\012To link up, your\nfriend must have\012the same kind of\nMOBILE ADAPTER as\011you.",
  ["18:68f4"] = "To use the TRADE\nCORNER or read the\012POKéMON NEWS, you\nneed to phone the\011MOBILE CENTER.\012You must register\nat the MOBILE\012CENTER before\nconnecting there.",
  ["18:6989"] = "It's a notice\nabout using the\011phone…",
  ["18:69ae"] = "Please ensure that\nyour phone and\012MOBILE ADAPTER are\nproperly linked.\012Please make sure\nthe wireless phone\011signal is strong.\012Don't touch or\nhang up the phone\011while linking.",
  ["18:6a5a"] = "If the server is\nbusy, it may not\012be possible to log\non.\012If so, please call\nback later.\012If you are unable\nto log on or don't\012understand the\nerror messages,\012call a support\ncenter or read the\011instructions.",
  ["18:6b26"] = "The ADMINISTRATION\nOFFICE received an\011e-mail. It says…\012DADE DADE DADE\012To the #COM\nCENTER staff…\012Wireless communi-\ncation has enabled\012#MON trainers\nto interact across\012the nation. LetÇ\nkeep working for\012the day when all\nthe trainers in\012the world can link\nwithout barriers!\012DADE DADE DADE",
  ["18:6c80"] = "A FLORESTA DE ILEX é\ngrande. Cuidado!\011Não se perca.",
  ["18:6cb0"] = "A FLORESTA é\nobservada pelo seu\011protetor.\012Não faça travessu-\nras!",
  ["18:6d9d"] = "Oh, querido. Você\nestá completando a\011#DEX?\012Deve ser difícil\nse um #MON não\011surgir.\012Tente usar esse\nTM.",
  ["18:6df6"] = "É o ODOR DOCE.\012Use-o em lugares\nonde apareçam\011#MON. \012Isso vai\natraí-los.",
  ["18:6e41"] = "Há algo de errado\nna FLORESTA DE ILEX…\012Você deve ficar\nlonge de lá\011agora.",
  ["18:6e83"] = "BUTTERFREE: Freeh!",
  ["18:6e97"] = "Você viu\no santuário\011homenageando o\011protetor?\012Ele observa toda\nFLORESTA através\011do tempo.\012Acho que ele é\num #MON do tipo\011grama.",
  ["18:6fda"] = "Vovô o procurava.",
  ["18:70ce"] = "Sou o HOMEM DO\nCRIATÓRIO. Você\011conhece os OVOS?\012Eu estava criando\n#MON com minha\011esposa, você sabe.\012Ficamos chocados\nao acharmos um\011OVO!\012Que coisa\nincrível é essa?\012Bem, não gostaria\nde ter esse OVO?\012Ótimo, agora pode\ntê-lo para você.",
  ["18:71ae"] = "{PLAYER} recebeu\nOVO ESTRANHO!",
  ["18:71c3"] = "Eu achei isso\nquando eu cuidava\011do #MON\011de alguém\011anteriormente.\012Mas o treiandor\nnão quis o OVO,\011então eu fiquei\011com ele.",
  ["18:7237"] = "Você não tem lugar\npara isso.",
  ["19:4000"] = "Destesto ter que\nque desligar!\012Depois eu te ligo!",
  ["19:4032"] = "{PLAYER}, você já\nsoube?\012A TORRE DE RÁDIO\nfoi dominada pela\011EQUIPE ROCKET!\012…Hm… O que é\na EQUIPE ROCKET?",
  ["19:4099"] = "{PLAYER}, eu soube!\012Você derrotou a\nWHITNEY?\012Isso me deixa\norgulhoso em ser\011seu amigo!",
  ["19:40e6"] = "Ei, ouvi falar\nde você!\012Você salvou aquele\n#MON no FAROL,\012não foi?\012{PLAYER}, eu quero\nque você me visite\012quando eu pegar\num resfriado!",
  ["19:416d"] = "Eu soube,\neu soube!\012Você arrasou o\nesconderijo da\011EQUIPE ROCKET!\012Você parece um\nherói de cinema!\012Mas hum… O que era\na EQUIPE ROCKET?",
  ["19:41e8"] = "Eu soube,\neu soube!\012Da sua heróica\nlibertação da\012TORRE DE RÁDIO!\nVocê trabalha\011tão duro!",
  ["19:4247"] = "Eu vi, eu vi!\012Eu o vi entrando\nna TOCA DO DRAGÃO!\012Tenho certeza que\npassou! Ahh, sem\012modestias!\nVocê não falha!",
  ["19:42bb"] = "Ontem eu fui à\nCIDADE DE NEW BARK.\012Havia uma dama\nmuito parecida\012com você,\n{PLAYER}.\012O quê? Essa dama\nera sua mãe?\012Ahh, deveria ter\nme apresentado!\012Aposto que sua\nmãe se orgulha\012de todos as suas\nconquistas.\012É, continue assim.\nEu teria orgulho\012se eu fosse sua\nmãe, acredite!",
  ["19:43d4"] = "Eu vi, eu vi,\neu vi!\012Você embarcando em\num navio, {PLAYER}!\012Você nem imagina\no quanto é bom\012olhar o mar como\nseu plano de\011fundo!",
  ["19:4448"] = "Eu soube,\neu soube!\012Você obteve uma\nPASSAGEM DE TREM\011ÍMÃ!\n \012Quando eu o vi\npartindo em um\012navio, fiquei\ntriste porque eu\012poderia vê-lo por\num tempo.\012Mas como você tem\nesse passe, poderá\012voltar a qualquer\011momento!\012Isso é ótimo!\012O quê? Você pode\nvoltar VOANDO em\011qualquer hora?\012O que quer dizer\ncom VOAR?",
  ["19:455b"] = "Eu vi, eu vi!\012Você acordando o\nSNORLAX!\012Eu o observava de\nlonge, logo não\012posso descrever o\nque fez com exa-\011tidão.\012Você tocou uma\nflauta para acordá-\011lo?\012Uau! Parece\nmágica!",
  ["19:45ff"] = "Ouvi boatos sobre\nvocê tem todo\011lugar.\012Isso me impres-\nsiona, {PLAYER}.\012Como ficou tão\nforte?\012Vá ao campeonato\nmundial agora!\012Sempre estarei\ntorcendo por você!",
  ["19:46a3"] = "Hehe, acabei\nde ligar!\012Acho que podemos\nser bons amigos!",
  ["19:46df"] = "Eu vi, eu soube!\012Você venceu MORTY\ndo GINÁSIO\011ECRUTEAK!\012I-isso é inacre-\nditável!\012Na verdade eu fui\nà entrada do GINÁ-\012SIO para animá-lo.\nVocê sabia?\012Todos estavam\nflutuando e havia\012fantasmas por todo\nlugar! Daí eu\012fiquei com medo\ne fugi para casa…",
  ["19:47d8"] = "{PLAYER}, eu soube!\012Está fazendo uma\nótima campanha\012em KANTO!\nDeve ser algo\012espetacular!\nVocê é demais!",
  ["19:4846"] = "Saber de suas\naventuras agita\012minha alma!\nE como agita!",
  ["19:4881"] = "Estou tão feliz\npor ter ligado!\012Estava prestes a\nte ligar também!\012Acho que nós\ncombinamos!",
  ["19:48dc"] = "Como vai você?\012O que está\nfazendo?\012Onde está?\012Quantas INSÍGNIAS\npossui agora?\012Quando dinheiro\neconomizou?\012Como vai sua mãe?\012Capturou muitos\n#MON?\012Vai fazer sol\namanhã?\012Arrgh, sobre mui-\ntas coisas quero\012conversar! Isso\nnão vai a lugar\011algum!",
  ["19:49dc"] = "I'm always with my\n{STRBUF}!\012It's so cute!\nI just love it!",
  ["19:4a13"] = "Changing the topic\nhere, I saw this\012{STRBUF} for the\nfirst time.\012It was easy to\nbeat, actually.",
  ["19:4a71"] = "I was wondering,\ndo you happen to\011have {STRBUF}?\012I can't seem to\ncatch one. What is\012its weakness, I\nwonder.",
  ["19:4ada"] = "Hey, let's battle\nour POKéMON!\012I won't lose to\nyou battling or in\012the Bug-Catching\nContest!\012I'll be here on\n{STRBUF}!",
  ["19:4b48"] = "Vamos conversar\nde novo, hã?",
  ["19:4b5f"] = "Boy, am I glad I\ncaught you!\012A whole bunch of\n{STRBUF} have\012appeared around\n{STRBUF}!\012You have to see\nthis!",
  ["19:4bc6"] = "Não tive a sorte\nde ver #MON\011raros ultimamente…\012Mas eu sei que\neles estão em\011algum lugar!",
  ["19:4c13"] = "Hey, where are you\nnow?\012Let's battle. I'll\nbe waiting for you\011on {STRBUF}!",
  ["19:4c5a"] = "Alô? Você vai\nvir ou não?\012Está deixando de\nver um YANMA!\012Venha à ROTA 35\nagora!",
  ["19:4cbd"] = "My {STRBUF}'s\ngetting stronger,\012exactly as I\ncalculated!",
  ["19:4cf3"] = "By the way, we\nknocked out a wild\012{STRBUF} just\nthe other day.\012Studying up in\nadvance worked!",
  ["19:4d4f"] = "By the way, a wild\n{STRBUF} escaped\011on me yesterday.\012A computational\nerror on my part…",
  ["19:4da4"] = "I've studied quite\na bit since then,\012and I've gotten a\nlot better!\012I'm hanging out on\n{STRBUF}.\012Can you come down\nfor a battle?",
  ["19:4e1f"] = "Até mais!",
  ["19:4e2f"] = "Hehehe, I picked\nup something nice!\012You can have it!\nWhy don't you come\012to {STRBUF}\nand pick it up?",
  ["19:4e90"] = "Eu não peguei\nnada ainda.\012Vou telefonar se\neu achar algo.",
  ["19:4ed4"] = "If we don't battle\nsoon, I'll forget\011my strategy!\012I'm waiting on\n{STRBUF}!",
  ["19:4f1a"] = "I have to do my\nhomework, so can\012you come get your\ngift right away?\012I'm waiting on\n{STRBUF}!",
  ["19:4f74"] = "My {STRBUF} is\ngetting prettier!\012I've been taking\nphotos galore!",
  ["19:4fb2"] = "It took only an\ninstant to KO a\011wild {STRBUF}.\012It must be because\nyou gave me some\012battling tips last\ntime.",
  ["19:501c"] = "You know what?\nA wild {STRBUF}\012got away from me\nagain.\012It was so close!\nReally, just a\012little bit more,\nand I would've…",
  ["19:5091"] = "Right now, I'm on\n{STRBUF}.\012If you're close\nby, let's battle!\012I'll be waiting\nfor you!",
  ["19:50e2"] = "Até depois!",
  ["19:50ec"] = "You know what?\nI got a good gift!\012As I promised,\nit's yours!\012I'm sure you'd\nlike it. Come get\012it! I'm waiting on\n{STRBUF}!",
  ["19:5161"] = "Oh! Você quis um\npresente, certo?\012Eu tenho um, mas\nquero guardá-lo.\012Pode esperar um\npouco mais?",
  ["19:51bf"] = "Hi! You haven't\nforgotten about\012your promise to\nbattle me?\012I'm waiting on\n{STRBUF}!",
  ["19:520f"] = "Hello?\012If you don't come\nget your present\012soon, I'll give it\nto someone else.\012I'm waiting on\n{STRBUF}!",
  ["19:5271"] = "I recently began\nobserving wild\011{STRBUF}.\012I've been learning\nall sorts of new\012things through my\nobservations.\012I wish I could\nbecome a POKéMON\012researcher like\nPROF.OAK soon.",
  ["19:5318"] = "Oh yes, I managed\nto knock out a\012wild {STRBUF} a\nwhile back.\012Well, considering\nall the studying I\012do every day, it\nwas inevitable.",
  ["19:5399"] = "Oh yes, I came\nclose to catching\012a wild {STRBUF},\nbut it got away.\012For the longest\ntime, I've been\012wanting to observe\n{STRBUF}. Rats…",
  ["19:5419"] = "Want to battle?\nI have to battle\012every so often to\navoid rusting out.\012I'll be on\n{STRBUF}!",
  ["19:5471"] = "Até mais!",
  ["19:5481"] = "Você conhece o\nGARY?\012Ele é neto do\nPROFESSOR CARVALHO\012e antigo CAMPEÃO\nda LIGA #MON!\012Ele é um super\ntreinador #MON!",
  ["19:54ea"] = "PROFESSOR CARVALHO\ntem uma neta cha-\011mada DAISY.\012Quando ela está\npor perto, até\012o #MON mais\nferoz se acalman.",
  ["19:5555"] = "Todos estão con-\nversando sobre o\011PROFESSOR ELM.\012Ele era um assis-\ntente do grande\011PROFESSOR CARVA-\011LHO!\012Isso é tão legal!\nEu o invejo!",
  ["19:55c7"] = "O sonho do\nPROFESSOR CARVALHO\012é compilar uma\n#DEX compreen-\011siva.\012Eu o invejo por\nfazer parte\011desse projeto…",
  ["19:5628"] = "Conhece KURT, o\ncriador da BOLA?\012Ele e o PROFESSOR\nandavam juntos.\012Acho que ótimas\npessoas se atraem!",
  ["19:569b"] = "A LIGA #MON\né um grande lugar\011de reunião para\012todos treinadores\nque desejam ser\011CAMPEÕES.\012O PROFESSOR CARVA-\nLHO atua como aju-\012dante do quartel\ngeneral da LIGA\011#MON.\012Ele realmente é\num grande homem.",
  ["19:574a"] = "O SHOW DO CARVALHO\né um show de rádio\011popular, certo?\012Você sabia que\nele interromperia\012o show pela\nprimeira vez?\012Mas a energia e\npersistência de\011MARY não permitiu.\012Então devemos\nagradecer-lhe por\011isso!",
  ["19:5810"] = "PROFESSOR CARVALHO\nera um treinador\011há muito tempo.\012Porém, mais do\nque batalhar, ele\012achava os #MON\ninteressantes.\012Então abandonou seu\ntreinamento para\012se tornar um\npesquisador.",
  ["19:58c6"] = "PROFESSOR CARVALHO\ntem uma neta cha-\011mada DAISY.\012Ela toma chá todos\nos dias por uma\012hora a partir\ndas 15 horas.\012Eu queria poder\nestar presente\012para conversar\nsobre o PROFESSOR\011CARVALHO.",
  ["19:5969"] = "Você sabia?\nPROFESSOR CARVALHO\012viajou por todo\no mundo quando\011era jovem.\012Enquanto viajava,\ndevia ter aprendi-\012do sobre #MON\nnaturalmente.\012Eu o invejo…\nGostaria de viajar\012e aprender coisas\ntambém…",
  ["19:5a23"] = "Vou estudar duro\npara o PROFESSOR\012CARVALHO me fazer\nse assistente!",
  ["19:5a63"] = "Do you remember\nabout our battle?\012The place is\n{STRBUF}.\012Hurry over--I'm\nwaiting.",
  ["19:5ab2"] = "Listen to this.\nMy {STRBUF}\012grins happily when\nI pinch its cheek.\012But it never grins\nfor anyone else.\012I must be special.",
  ["19:5b29"] = "Oh, and recently,\nmy PIKACHU beat a\011wild {STRBUF}!\012A wild {STRBUF},\nI tell you!\012Don't you think\nthat's astounding?\012My PIKACHU is\nawesome!\012My PIKACHU is the\ngreatest!",
  ["19:5bc8"] = "Oh, and I saw a\nwild {STRBUF} a\011little while ago.\012But it wasn't very\ncute, so I left\012it…\nPOKéMON have to be\012cute. They're no\ngood otherwise.",
  ["19:5c4e"] = "Bem, nos falaremos\nde novo!",
  ["19:5c66"] = "Você se lembra?\nO Concurso Caça-\011Inseto é hoje.\012Você vai lá,\ncerto?\012Acho que partici-\nparei com PIKACHU\012para mostrar sua\nbeleza.",
  ["19:5cf9"] = "Eu queria ter\numa PEPITA.\012Meu PIKACHU a\nadora.\012Tenho certeza que\nseu PIKACHU vai\011gostar também!",
  ["19:5d5c"] = "Como vai o seu\nPIKACHU?\012Vamos nos reunir\npara nos vanglo-\011riarmos a res-\011peito de nossos\011PIKACHUS!",
  ["19:5da6"] = "What's wrong?\012I'm waiting on\n{STRBUF}.\012Come pick this up\nanytime.",
  ["19:5de4"] = "My {STRBUF} has\ngrown again.\012It was only about\nso big when I\012caught it, but now\nit's way bigger.",
  ["19:5e42"] = "Oh yeah, I KO'd a\nwild {STRBUF}.\012It was huge, like\nthis big even.\012Heh, I guess you\ncan't tell over\011the phone…",
  ["19:5eac"] = "Oh yeah, I lost a\nwild {STRBUF}.\012It was huge, like\nthis big even.\012Heh, I guess you\ncan't tell over\011the phone…",
  ["19:5f17"] = "We should get a\nbattle going!\012I'll be fishing on\n{STRBUF}.\012Swing by if you\nhave the time.",
  ["19:5f6e"] = "Bem, vou manter\ncontato.",
  ["19:5f88"] = "I picked up a good\nlittle thing at\011the water's edge.\012Like I promised,\nit's yours.\012I'll be waiting on\n{STRBUF}.",
  ["19:5ff2"] = "Se eu achei\nalgo bom?\012Ainda não.\012É como pescar,\né necessário ter\011paciência.",
  ["19:6043"] = "Yup, TULLY here…\012{PLAYER}? What?\nYou're lost?\012Our battle will be\non {STRBUF}.",
  ["19:6087"] = "I've got something\ngood for you.\012Hustle over to\n{STRBUF}.",
  ["19:60be"] = "Oh sim, obtive um\n#MON extrema-\012mente raro em uma\ntroca há um tempo.\012Quer saber qual\nque é?\012Hehe, manterei\nem segredo!",
  ["19:613c"] = "Oh yeah, I took\ndown this wild\012{STRBUF}.\nIt wasn't rare\012enough to bother\ncatching.",
  ["19:618c"] = "Oh sim, eu vi um\n#MON raro há\011uma hora.\012Foi a primeira\nvisão. Mas eu\012não tinha\n# BOLAS…\012Será que BILL\nia rir de meus\011erros?",
  ["19:6214"] = "You've got time\nlike usual, right?\012Feel like having a\nbattle?\012It'll be a chance\nto see my rare\012POKéMON. It'll be\nworth your time!\012You know where--\n{STRBUF}.",
  ["19:62a9"] = "É só isso então.",
  ["19:62bc"] = "Você sabia…?\nDizem que o pai de\012BILL é um grande\n#MANÍACO.",
  ["19:62fc"] = "Você sabia…?\nAparentemente, o\012avô de BILL não é\num #MANÍACO.",
  ["19:6335"] = "Você sabia…?\nBILL é originá-\011rio de GOLDENROD.",
  ["19:6366"] = "Você sabia…?\nBILL evidentemen-\012te mora na ROTA 25\nem KANTO.",
  ["19:63a1"] = "Você sabia…?\nABRA foi o primei-\012ro #MON que\nBILL capturou.",
  ["19:63e6"] = "Você sabia…?\nA irmã caçula de\012BILL aparentemente\nnão pode piscar.",
  ["19:6421"] = "Você sabia…?\nDizem que BILL\012odeia leite e\nnão o bebe.",
  ["19:645f"] = "Você sabia…?\nEvidentemente,\012BILL não é muito\nbom em batalhas.",
  ["19:649b"] = "Você sabia…?\nBILL parece\012gostar da dama\nda LOJA DE FLORES.",
  ["19:64dd"] = "Você sabia…?\nDizem que a mãe\012de BILL foi uma\nGAROTA KIMONO.",
  ["19:651e"] = "Você quer ouvir\nsobre o BILL?\012Perdão, mas estou\nsem tempo para\011você.\012Ligarei quando\neu tiver tempo.",
  ["19:6579"] = "You want to see my\nrare POKéMON.\012Hurry over to\n{STRBUF}.",
  ["19:65ad"] = "My {STRBUF}'s\nadorable, don't\012you think so?\nI always sleep\012with it--it's so\nfluffy and warm!",
  ["19:6605"] = "Oh, and we had to\nbattle a wild\012{STRBUF} a while\nago…\012My CLEFAIRY came\nclose to fainting!\012Isn't that awful?\012I hate those nasty\n{STRBUF}!",
  ["19:6688"] = "Oh, and we had to\nbattle a wild\012{STRBUF} a while\nago…\012My CLEFAIRY got\nfrightened, so we\012ran away as fast\nas we could!\012I just can't help\nfeeling protective\011of my CLEFAIRY.",
  ["19:6730"] = "I know this might\nsurprise you, but\012would you like to\nbattle?\012I'll be waiting\nwith CLEFAIRY on\011{STRBUF}.",
  ["19:6796"] = "{STRBUF}!\012É terrível.\nMinha CLEFAIRY…\012Hã? {PLAYER}?\012Oh, perdão! Estava\ncom pressa, e eu…\012Tenho que ir!\nTchau, tchau!",
  ["19:67f7"] = "Tchau tchau!",
  ["19:6801"] = "I bought some PINK\nBOWS at GOLDENROD\012DEPT.STORE for my\nCLEFAIRY.\012I got too many, so\nI'll give you one!\012Come collect it on\n{STRBUF}.",
  ["19:6882"] = "Adoro vestir\nminha CLEFAIRY!",
  ["19:68a3"] = "What's wrong?\nCan't you visit?\012CLEFAIRY got tired\nand fell asleep.\012I'm not sure if I\ncan wake it up…\012Please hurry to\n{STRBUF}!",
  ["19:691d"] = "What's wrong?\nCan't you visit?\012I'm sure this will\nlook good on your\011CLEFAIRY.\012Please hurry to\n{STRBUF}!",
  ["19:6980"] = "My {STRBUF}'s\nbecome tougher.\012We've achieved\nliftoff!",
  ["19:69b2"] = "We can easily beat\n{STRBUF}!\012…Huh? You too?\nIsn't that great?",
  ["19:69ed"] = "But get this, a\nwild {STRBUF}\012just barely eluded\nus.\012I wanted to FLY\nafter it…",
  ["19:6a3a"] = "Right now, I'm on\n{STRBUF}.\012You know, where I\nfirst met you?\012Want to battle?\nI'll wait here.",
  ["19:6a93"] = "Certo, até mais!",
  ["19:6aa5"] = "Estarei aguar-\ndando nossa pró-\011xima batalha!",
  ["19:6ad1"] = "Oh, {PLAYER}!\nHurry, hurry!\012{STRBUF}!\nFLY over now!",
  ["19:6afc"] = "My {STRBUF}'s\ngrown impressive!\012My fishing skills\nhave improved too!",
  ["19:6b3e"] = "We beat a wild\n{STRBUF}…\012You know, I have\nmore fun fishing\012than beating wild\nPOKéMON.",
  ["19:6b8f"] = "But a while back,\nwe came this close\012to landing a wild\n{STRBUF}.\012I tell you, it was\nhuge. Believe me.",
  ["19:6bf3"] = "I'm fishing on\n{STRBUF},\012but nothing's\nbiting today.\012Help me while my\ntime away, come\011over for a battle.",
  ["19:6c58"] = "Certo, até\noutra hora.",
  ["19:6c6b"] = "I snagged an item\nwhile fishing.\012Come pick it up on\n{STRBUF}.",
  ["19:6ca7"] = "Não, não achei\nnada de valor\012para você. Tem\nque ter paciência.",
  ["19:6cf7"] = "Sigh…\nThey're not biting\012like before on\n{STRBUF}…\012You have to come\nfor a battle!",
  ["19:6d45"] = "Don't you want\nthis item?\012Hah? You don't\nknow where?\012{STRBUF}…\nJust head from\012MAHOGANY toward\nBLACKTHORN!",
  ["19:6dab"] = "De qualquer modo,\nconversaremos de\011novo!",
  ["19:6dc5"] = "Ainda está em\nsua jornada?\012Ainda estou dedi-\ncado em meu\011treinamento.\012Oooooaaarrrgh!",
  ["19:6e17"] = "Estou treinando\nagora. Perdão.\012Ligue-me de novo\nmais tarde.\012Oooooaaarrrgh!",
  ["19:6e67"] = "Perdão, mas não\ntenho tempo para\012conversar quando\ntreino!\012Amanhã poderei\nconversar!\012Yiiihah!",
  ["19:6ed3"] = "Eu pretendo parar\npara almoçar, en-\012tão venha me ver!\nAyiiiyah!",
  ["19:6f11"] = "Estou descansando\nna ROTA 45!\012Por que não ir lá\nse estiver livre?",
  ["19:6f52"] = "Eu descansei du-\nrante meu almoço.\012Agora é hora de\nvoltar a treinar!\012Oooryaah!",
  ["19:6f9f"] = "Nothing can match\nmy {STRBUF} now.",
  ["19:6fc0"] = "Yeah, we KO'd a\nwild {STRBUF}!\012That was OK, but I\nwanted to get it…",
  ["19:7001"] = "And yesterday, we\nspotted a wild\012{STRBUF}.\nWe were debating\012whether to catch\nit or beat it.\012When along came\nanother guy who\012caught it!\nHow about that!",
  ["19:7096"] = "You're thinking\nyou'd like to\012battle me. Am I\nright or what?\012Yep! We'll meet on\n{STRBUF}!",
  ["19:70eb"] = "Certo, ligue-me\nde novo!",
  ["19:7106"] = "Batalhará comigo\nde novo, certo?",
  ["19:712a"] = "Haven't you gotten\nto {STRBUF}?\012Waiting here isn't\nbad, but I'd sure\011like to battle!",
  ["19:717a"] = "{STRBUF}'s {STRBUF}\nis much stronger\011than before!",
  ["19:71a4"] = "And, and…\nI just battled and\011beat {STRBUF}!\012I've raised my\nPOKéMON properly!",
  ["19:71eb"] = "But, but…\012A wild {STRBUF}\ngot away from me\012again. It's just\nnot fair!",
  ["19:722e"] = "I'm ERIN. Want to\nbattle me again?\012I won't lose this\ntime!\012I'll be waiting on\n{STRBUF}!",
  ["19:7281"] = "Até mais. Tchau!",
  ["19:7294"] = "Estou trabalhando\nduro para criar\011meu #MON!\012Volte depois para\noutra batalha!",
  ["19:72d5"] = "Oh, {PLAYER}!\nCome battle ERIN!\012I'll be waiting on\n{STRBUF}!",
  ["1a:405a"] = "É proibido roubar\nem #MON.\012Vamos fazer uma\npartida limpa!",
  ["1a:4097"] = "Hã? Como isso\naconteceu?",
  ["1a:40b2"] = "Eu fiz uma luta\nlimpa com honra.\012Não me arrependo\nde nada.",
  ["1a:40f3"] = "Tenho muita\ncoceira quando\011visto uma bermuda\011curta na grama.",
  ["1a:4131"] = "Aiyaaah!\nFui pisado!",
  ["1a:414a"] = "Vou pegar mais\n#MON na grama.",
  ["1a:417b"] = "…\012Perdi quando\nestava de olhos\011fechados…",
  ["1a:41a1"] = "Não posso ver…\012Tudo ao seu\nrespeito…",
  ["1a:41cd"] = "Não pude prever\nseu poder…",
  ["1a:41ec"] = "Força é convicção…\012Você é forte\nporque acredita\011em seus #MON.",
  ["1a:4238"] = "ROTA 11.",
  ["1a:42a2"] = "Quando captura um\n#MON, ele pode\011estar fraco.\012Mas ele ficará\nforte um dia.\n \012É importante\ntratar o #MON\011com amor.",
  ["1a:4323"] = "Os #MON podem\nsegurar itens como\011POÇÃO e ANTÍDOTO.\012Mas eles parecem\nnão saber como\011usar itens feitos\011pelos homens.",
  ["1a:4473"] = "Sou FALKNER, o\nLÍDER desse\011GINÁSIO! \012Dizem que pode\njuntar as asas do\012#MON voador com\no Choque do\011#MON elétrico…\012Não permito \ninsultos aos\011#MON pássaros!\012Vou lhe mostrar o \npoder real dos\011ótimos #MON\011pássaros!",
  ["1a:454a"] = "…Não! Meu pai\ncuidava de\011#MON pássaros.\012Tudo bem. Leve\nisso.\012É uma oficial\nINSÍGNIA DA BRISA\011da LIGA #MON.",
  ["1a:45af"] = "{PLAYER} foi\npresenteado com\011uma INSÍGNIA DA\011BRISA DO GINÁSIO\011DA CIDADE DE VIOLET.",
  ["1a:45c8"] = "A INSÍGNIA DA\nBRISA melhora os\011poderes dos\011#MON.\012Também permite o\n#MON usar\011LUZES, se tiver, a\011qualquer hora.\012Leve isso também.",
  ["1a:4648"] = "Usando um TM, o\n#MON aprenderá\011um golpe num\011instante.\012Pense antes de\nagir--só pode\011usar o TM uma\011vez.\012O TM31 tem o\nTAPA DE LAMA.\012Ele reduz a\nprecisão do\012inimigo enquanto\ncausa danos. \012Em outras\npalavras, é\011defensivo quanto\011ofensivo.",
  ["1a:4735"] = "Tem outros\nGINÁSIOS nas\011cidades adiante. \012Você deve testar\nsuas técnicas\011nesses GINÁSIOS.\012Vou treinar duro\npara me tornar\011o melhor mestre\011de pássaros!",
  ["1a:47cd"] = "O segredo é\ntécnica!\012Esses aqui\nestão treinando\011dia e noite para\011serem mestres\011também.\012Vamos lá!",
  ["1a:482f"] = "Gaaah!",
  ["1a:4837"] = "FALKNER é muito\nhabilidoso! \012Não comemore só\nporque você me\011derrotou!",
  ["1a:487f"] = "Vamos ver se você\né bom para\011encarar o\011FALKNER!",
  ["1a:48b3"] = "Não pode ser real!",
  ["1a:48c7"] = "Isso é horrível,\num treinador\011novato me vencer…",
  ["1a:48f9"] = "Ei! Não sou\ntreinador mas\011posso ajudá-lo!\012Acredite em mim!\nSe acreditar, um\011sonhado\011campeonato\011será real. \012Você acredita?\nEntão escute.\012#MON do tipo\ngrama são fracos\011contra o tipo\011voador.\012Pense nisso.",
  ["1a:49c8"] = "Boa batalha!\nContinue assim e\011você vai ser um\011CAMPEÃO em pouco\011tempo!",
  ["1a:4b3b"] = "Sou EARL!\012Os #MON são\nmaravilhosos!\012Vou ensiná-lo a\nser um treinador\011melhor!\012O que você quer\nsaber? Deseja ser\011um vencedor?",
  ["1a:4bbd"] = "Bom! Eu vou\nensiná-lo!\012Na batalha, o\n#MON topo de\011lista será o\011primeiro!\012Mude a ordem na\nlista, facilita a\011batalha, talvez!\012Quer ouvir mais\ncoisas?",
  ["1a:4c51"] = "Então, quer saber\ncomo criar bem\011os #MON?",
  ["1a:4c7b"] = "Ótimo! Vou\nensiná-lo!\012Mesmo batalhando\npouco, o #MON\011ganhará um pouco\011de PONTOS DE\011EXPERIÊNCIA.\012Coloque o #MON\nfraco no topo de\011lista.\012Troque-o rápido\nna batalha!\012Assim, #MON\nfracos ficam\011fortes!",
  ["1a:4d31"] = "Oh! Você é um aluno\nesperto! Não tenho\011mais nada a te\011ensinar.\012Você deve ser\nbom com os\011#MON!",
  ["1a:4d80"] = "Estou atento\nà leitura do\011professor.\012É melhor eu\ncopiar o que está \011no quadro também.",
  ["1a:4dda"] = "Eu troquei meu\nmelhor #MON com\011o rapaz ao lado.",
  ["1a:4e07"] = "Hã? O #MON que\nacabei de receber\011está segurando\011algo!",
  ["1a:4e39"] = "Um #MON\nsegurando uma FRUTA\011se curará sozinho\011na batalha.\012Vários outros\nitens podem ser\011segurados pelo\011#MON…\012É bem difícil\nentender essa\011matéria…",
  ["1a:4eb2"] = "O quadro mostra as\nmudanças de estado\011dos #MON na\011batalha.",
  ["1a:4efe"] = "Se envenenado, um\n#MON perde\011periodicamente HP.\012O veneno age após\nas batalhas, e o\011HP é perdido a\011medida que você\011anda.\012Para curá-lo,\nuse um ANTÍDOTO.",
  ["1a:4f80"] = "A paralisia reduz\na velocidade e\011pode impedir o\011movimento.\012Continua após a\nbatalha, então use\011DESPARALISIA para\011curar.",
  ["1a:4fe2"] = "Se dormir, seu\n#MON não pode\011se mover.\012Um #MON\ndorminhoco não\011acorda após\011batalhar.\012Acorde-o com um\nACORDADOR.",
  ["1a:5055"] = "O fogo tira HP\nperiodicamente.\012Também reduz o\npoder de ataque.\012O fogo age após\na batalha.\012Use um CURA FOGO\ncomo cura.",
  ["1a:50cb"] = "Se seu #MON\nestá congelado,\011ele não pode\011fazer nada.\012Continua congelado\napós a batalha. \012Cure-o com o CURA\nGELO.",
  ["1a:5136"] = "É o caderno desse\ngaroto…\012Capture #MON\nusando # BOLAS.\012Até seis #MON\npodem estar na sua\011equipe.\012Continuar lendo?",
  ["1a:5197"] = "Antes de lançar\numa # BOLA,\011enfraqueça o alvo\011antes.\012Um #MON\nqueimado ou\011envenenado é mais\011fácil de capturar.\012Continuar lendo?",
  ["1a:5207"] = "Muitos golpes\npodem causar\011confusão.\012A confusão pode\nfazer o #MON se\011atacar.\012Sair da batalha\nacaba com a\011confusão.\012Continuar lendo?",
  ["1a:5287"] = "Quem pega e usa\nos #MON\011nas batalhas\011são treinadores\011#MON.\012Eles devem visitar\nos GINÁSIOS\011#MON e vencer\011outros treinado-\011res.\012A próxima página\nestá… Branca!\012Garoto: He-he-he…\012Eu não escrevi\nmais nada…",
  ["1a:53fa"] = "Ela usa o nome\nde suas comidas\011prediletas.\012Pelo menos nos\napelidos que dá\011aos seus #MON.",
  ["1a:545e"] = "Eu chamo meu\nPIDGEY de MORANGO!",
  ["1a:547c"] = "MORANGO: Pijji!",
  ["1a:5555"] = "{PLAYER}, há quanto\ntempo.\012O PROFESSOR ELM\nme pediu para\011achá-lo.\012Ele tem outro\nfavor a pedir.\012Você levaria o OVO\n#MON?",
  ["1a:55c5"] = "Nós descobrimos\nque um #MON não\011nascerá até\011crescer no OVO.\012Deve estar junto\nde outros\011#MON ativos\011para nascer.\012{PLAYER}, você é a\núnica pessoa\011em que podemos\011confiar.\012Ligue para o\nPROFESSOR ELM\011quando o OVO\011chocar!",
  ["1a:5693"] = "Oh, não. Você não\npode carregar mais\011#MON contigo.\012Esperarei aqui\nenquanto você\011libera espaço para\011o OVO.",
  ["1a:56f2"] = "M-mas… O PROFESSOR\nELM te pediu…",
  ["1a:5712"] = "{PLAYER}, vai levar\no OVO?",
  ["1a:5809"] = "Um rapaz chamado\nBILL fez o\011SISTEMA DE\011GUARDAR #MON\011no COMPUTADOR.",
  ["1a:583c"] = "Foi há três anos.\n \012A EQUIPE ROCKET\nmaltratava os\011#MON.\012Mas a justiça\nvenceu--um jovem\011garoto acabou com\011eles.",
  ["1a:58b8"] = "Os #MON são\nespertos.\012Eles não obedece-\nrão a um treinador\011sem respeito.\012Sem as INSÍGNIAS\nDE GINÁSIO certas,\011eles farão o que\011bem entenderem.",
  ["1a:5997"] = "Um #MON pego\nem trocas cresce\011rápido.\012Mas se não tiver\nas INSÍGNIAS\011DE GINÁSIO\011certas, eles o\011desobedecerão.",
  ["1a:5a36"] = "RUÍNAS ALFA\012Um lugar onde\nturistas podem\011tocar.\012Tente mover os\npainéis de pedra!",
  ["1a:5a81"] = "Você está\nestudando as\011RUÍNAS?\012Eu vi cientistas\nestudando-as.",
  ["1a:5abd"] = "Há desenhos nos\npainéis de pedra.\012Eu tentei movê-\nlos. O que será\011que eles são?",
  ["1a:5b83"] = "Esse é um ótimo\nponto de pesca.\012Você viu pessoas\npescando? E você?\012Gostaria de ter\numa das minhas\011VARAS?",
  ["1a:5be8"] = "Eh, isso é bom.\012Agora você é um\npescador também!",
  ["1a:5c1b"] = "Pescar é ótimo!\012Se tiver água,\nseja mar ou\011oceano, tente\011pescar com a sua\011VARA.",
  ["1a:5c6c"] = "Oh. Mas que\ndesapontamento…",
  ["1a:5c8d"] = "Você, garoto. Como\nvai a pesca?",
  ["1a:5cac"] = "O que devo fazer\nmeu #MON\011segurar?\012Talvez algo que\nfortaleça seus\011ATAQUES…",
  ["1a:5ddd"] = "Perdão, garoto!\012Pode fazer um\nfavor a um rapaz?\012Pode levar esse\n#MON com CARTA\011para meu amigo?\012Está na ROTA 31.",
  ["1a:5e48"] = "Você vai?\nPerfeito!\012Obrigado, garoto!\012Meu amigo é\ngordinho e dorme\011o tempo todo.\012Você vai\nreconhecê-lo\011certamente!",
  ["1a:5eb8"] = "{PLAYER} recebeu um\n#MON com CARTA.",
  ["1a:5ed6"] = "Você pode lê-la,\nmas não a perca!\011ROTA 31!\012Oh, sim. Havia uma\nestranha árvore\011bloqueando a\011estrada.\012Será que foi\nextirpada?",
  ["1a:5f56"] = "Você não pode\ncarregar outro\011#MON…",
  ["1a:5f74"] = "Oh… Não importa,\nentão…",
  ["1a:5f8b"] = "Obrigado, garoto.\nVocê fez a entrega\011para mim!\012Eis algo para os\nseus problemas!",
  ["1a:5fd9"] = "Meu amigo estava\ndormindo, certo?\012Bem, o posso\ndizer?",
  ["1a:600a"] = "Uma estranha\nárvore está\011bloqueado a\011estrada.\012Ela rebola se você\nfalar com ela.\012Soube que ela fica\nferoz quando\011alguém a rega com\011o POTE SQUIRT.",
  ["1a:609a"] = "Eu gosto da Canção\n#MON que eles\011tocam no rádio.",
  ["1a:60cb"] = "Quantos tipos de\n#MON deve\011haver em todo o\011mundo.\012Há três anos, o\nPROFESSOR CARVALHO\011disse que havia\011150 tipos\011diferentes.",
  ["1a:62eb"] = "Today's {STRBUF}.\nThat means the\012Bug-Catching Con-\ntest is on today.\012The rules are sim-\nple.\012Using one of your\nPOKéMON, catch a\012bug POKéMON to be\njudged.\012Would you like to\ngive it a try?",
  ["1a:639d"] = "Aqui estão as\nBOLAS PARQUE para\011o Concurso.",
  ["1a:63c7"] = "{PLAYER} recebeu\n20 BOLAS PARQUE.",
  ["1a:63e2"] = "A pessoa que pegar\no #MON inseto\011mais forte é a\011vencedora.\012Você tem\n20 minutos.\012Se suas BOLAS\nPARQUE acabarem, o\011Concurso acaba.\012Você pode ficar\ncom o último\011#MON que\011capturar.\012Vá lá fora e\ncapture o #MON\011inseto mais forte\011que puder achar!",
  ["1a:64c6"] = "Uh-oh…\012You have more than\none POKéMON.\012You'll have to use\n{STRBUF}, the\012first POKéMON in\nyour party.\012Is that OK with\nyou?",
  ["1a:6537"] = "Ótimo, guardaremos\nseus outros\011#MON enquanto\011você compete.",
  ["1a:656b"] = "Os #MON de\n{PLAYER} foram\011deixados com\011o ASSISTENTE DO\011CONCURSO.",
  ["1a:6597"] = "Escolha o #MON\npara ser usado no\011Concurso, e depois\011venha me ver.",
  ["1a:65dc"] = "Certo. Esperamos\nque participe no\011futuro.",
  ["1a:6608"] = "Opa…\nO primeiro #MON\011na sua equipe não\011pode batalhar.\012Troque-o com um\n#MON que deseja\011usar, e depois\011venha me ver.",
  ["1a:667c"] = "Opa…\nTanto sua equipe\011quanto o BOX do\011COMPUTADOR estão\011cheios.\012Você não tem lugar\npara pôr o #MON\011inseto que pegou.\012Libere espaço na\nsua equipe ou no\011BOX do COMPUTADOR\011e venha me ver.",
  ["1a:671f"] = "Opa… O primeiro\n#MON na sua\011equipe é um OVO.\012Troque-o com um\n#MON que deseja\011usar, e depois\011venha me ver.",
  ["1a:679a"] = "You still have {STRBUF}\nminute(s) left.\012Do you want to\nfinish now?",
  ["1a:67db"] = "Certo. Espere no\nPortão Norte para\011o anúncio dos\011vencedores.",
  ["1a:6823"] = "Certo. Volte para\nfora e termine.",
  ["1a:684f"] = "O Concurso de hoje\nacabou.\012Esperamos que\nparticipe no\011futuro.",
  ["1a:6894"] = "Nós realizamos\nConcursos\011regularmente no\011PARQUE.\012Você deve tentar.",
  ["1a:68d8"] = "Quando o próximo\nConcurso Caça\011Inseto vai\011acontecer?",
  ["1a:690e"] = "O Concurso\nCaça-Inseto é\011feito às Terças,\011às Quintas e aos\011Sábados.\012Você além de\nganhar um prêmio\011por participar,\011pode ficar com o\011último #MON\011inseto que\011capturou no fim do\011Concurso.",
  ["1a:6a20"] = "Você imagina\nquem faria algo\011como isso? E por\011quê?",
  ["1a:6a5b"] = "Você viu a árvore\nestranha na\011estrada?\012Isso deve explicar\nporque menos\011pessoas estão\011visitando as\011RUÍNAS ALFA.",
  ["1a:6dd5"] = "Today's {STRBUF}.\nThat means the\012Bug-Catching Con-\ntest is on today.\012The rules are sim-\nple.\012Using one of your\nPOKéMON, catch a\012bug POKéMON to be\njudged.\012Would you like to\ngive it a try?",
  ["1a:6e87"] = "Aqui estão as\nBOLAS PARQUE para\011o Concurso.",
  ["1a:6eb1"] = "{PLAYER} recebeu\n20 BOLAS PARQUE.",
  ["1a:6ecc"] = "A pessoa que pegar\no #MON inseto\011mais forte é a\011vencedora.\012Você tem 20\nminutos.\012Se suas BOLAS\nPARQUE acabarem,\011o Concurso acaba.\012Você pode ficar\ncom o último\011#MON que\011capturar.\012Vá lá fora e\ncapture o #MON\011inseto mais forte\011que puder achar!",
  ["1a:6fb0"] = "Uh-oh…\012You have more than\none POKéMON.\012You'll have to use\n{STRBUF}, the\012first POKéMON in\nyour party.\012Is that OK with\nyou?",
  ["1a:7021"] = "Ótimo, guardaremos\nseus outros\011#MON enquanto\011você compete.",
  ["1a:7055"] = "Os #MON de\n{PLAYER} foram\011deixados com\011o ASSISTENTE DO\011CONCURSO.",
  ["1a:7081"] = "Escolha o #MON\npara ser usado no\011Concurso, e depois\011venha me ver.",
  ["1a:70c6"] = "Certo. Esperamos\nque participe no\011futuro.",
  ["1a:70f2"] = "Opa…\nO primeiro #MON\011na sua equipe\011não pode batalhar.\012Troque-o com um\n#MON que deseja\011usar, e depois\011venha me ver.",
  ["1a:7166"] = "Opa…\nTanto sua equipe\011quanto o BOX do\011COMPUTADOR\011estão cheios.\012Você não tem lugar\npara pôr o #MON\011inseto que pegou.\012Libere espaço na\nsua equipe ou no\011BOX do COMPUTADOR\011e venha me ver.",
  ["1a:7209"] = "Opa… O primeiro\n#MON na sua\011equipe é um OVO.\012Troque-o com um\n#MON que deseja\011usar, e depois\011venha me ver.",
  ["1a:7284"] = "You still have {STRBUF}\nminute(s) left.\012Do you want to\nfinish now?",
  ["1a:72c5"] = "Certo. Espere aqui\npara o anúncio dos\011vencedores.",
  ["1a:7300"] = "Certo. Volte para\nfora e termine.",
  ["1a:732b"] = "O Concurso de hoje\nacabou. Esperamos\011que participe no\011futuro.",
  ["1a:7370"] = "Muitos #MON\nsó podem ser\011vistos no PARQUE.",
  ["1a:7399"] = "DON: Uau, me\nvenceu. Você é\011muito bom.",
  ["1a:73c4"] = "DON: A sorte faz\ngrande parte\011disso.\012Você nunca sabe\nqual #MON vai\011aparecer.",
  ["1a:740f"] = "ED: Eu o invejo.\nNão consegui desta\011vez.",
  ["1a:7440"] = "ED: Talvez se\nvença com #MON\011grandes.",
  ["1a:7462"] = "NICK: Muito bem!\nVou criar melhor\011meus #MON.",
  ["1a:7496"] = "NICK: Talvez se\nobtenha mais\011pontos com\011#MON de cores\011incomuns.",
  ["1a:74da"] = "WILLIAM: Você é\no vencedor? O que\011capturou?",
  ["1a:750a"] = "WILLIAM: Bem,\nestou satisfeito\011pois capturei o\011#MON que quis.",
  ["1a:754e"] = "BENNY: Parabéns!\nVocê ganhou meu\011respeito!",
  ["1a:757c"] = "BENNY: Eu\ncapturara um\011SCYTHER, mas não\011venci.",
  ["1a:75b0"] = "BARRY: Aquele\n#MON que você\011capturou…\011é fantastico!",
  ["1a:75dd"] = "BARRY: É mais\nfácil vencer se\011você pegar um\011#MON inseto de\011nível alto.\012Mas eu acho que\neles levam outros\011pontos em\011consideração.",
  ["1a:764b"] = "CINDY: Você\nvenceu? Isso é\011ótimo!\012Importa-se de\nprocurar #MON\011insetos comigo?",
  ["1a:7698"] = "CINDY: Eu\nrealmente amo\011#MON insetos!",
  ["1a:76b8"] = "JOSH: Eu… Eu\nnão acredito que\011perdi na Caça de\011Insetos…",
  ["1a:76e9"] = "JOSH: Eu soube que\nalguém venceu com\011um CATERPIE!",
  ["1a:771b"] = "SAMUEL: Na próxima\nvez, eu vencerei.",
  ["1a:7740"] = "SAMUEL: Droga. Eu\nachei que\011pontuaria mais…",
  ["1a:776f"] = "KIPP: Você poderia\nme dar umas dicas?\012Quero estudar seu\nestilo.",
  ["1a:77af"] = "KIPP: Eu estudo\nmuito, mas não é\011o bastante para\011vencer.",
  ["1a:7910"] = "Opa… Sua BOLSA\nestá cheia.\012Vamos guardar seu\nprêmio, mas\011somente por hoje.\012Libere espaço,\ne venha me ver\011depois.",
  ["1a:797f"] = "{PLAYER}?\012Aqui está o prêmio que guardamos para você.",
  ["1b:406e"] = "Somos o grupo\nde treinadores da\011FEDERAÇÃO KANTO\011DE #MON.\012Vamos passar por\ncima de você!",
  ["1b:40be"] = "P-perdão!",
  ["1b:40c8"] = "A FEDERAÇÃO KANTO\nDE #MON nunca\011acabará!",
  ["1b:40f4"] = "Os tiras fecharam\no CAMINHO DO\011SUBSOLO!\012Isso realmente me\nirrita!",
  ["1b:4134"] = "P-perdoe-me!",
  ["1b:4143"] = "Derrotado por um\ndoidão de JOHTO…",
  ["1b:4167"] = "Somos a FEDERAÇÃO\nKANTO DE #MON!\011Prepare-se!",
  ["1b:4194"] = "Droga! Perdão!",
  ["1b:41a3"] = "Tentaremos não\nperturbar ninguém\011a partir de agora…",
  ["1b:41d0"] = "Como funciona o\nTREM ÍMÃ?",
  ["1b:41f3"] = "Só quero ver o\nTREM ÍMÃ…",
  ["1b:4219"] = "O poder dos ímãs\né fantástico!",
  ["1b:423d"] = "Hm… Possui\nvárias INSÍGNIAS\011DE GINÁSIO.",
  ["1b:425d"] = "Como pensei…\nVocê é forte!",
  ["1b:427e"] = "INSÍGNIAS DE\nGINÁSIO lhe\011beneficiam nas\011batalhas.",
  ["1b:42aa"] = "Está trancada…",
  ["1b:42b7"] = "O aviso está\nrasgado.\012É impossível\nler…",
  ["1b:446b"] = "Arrgh… Você achou\nnossas escadas\011secretas…",
  ["1b:4494"] = "Hehe! A experiên-\ncia funcionou\011perfeitamente.\012MAGIKARPS nada\nvalem, mas\011GYARADOS são\011fábricas de\011dinheiro.",
  ["1b:4501"] = "Urrgh…\012O #MON dragão\ndaquele rapaz é\011forte…",
  ["1b:452a"] = "LANCE: DRAGONITE,\nHÍPER RAIO.",
  ["1b:4549"] = "O que o trouxe,\n{PLAYER}?\012Como eu pensei,\naquele estranho\011sinal de rádio\011vem daqui.",
  ["1b:459e"] = "As escadas ficam\naqui.",
  ["1b:45ba"] = "LANCE: {PLAYER},\ndevemos nos\011separar para olhar\011esse lugar.\012Irei primeiro.",
  ["1b:4b12"] = "Ei! Alerta\nintruso!",
  ["1b:4b28"] = "Não… Eu falhei…",
  ["1b:4b39"] = "É minha vez!\nNão tem saída!",
  ["1b:4b59"] = "Há sensores de\nmovimento nas\011estátuas dos\011#MON.\012Continuaremos\naparecendo até\011você achar o\011botão secreto.",
  ["1b:4bbb"] = "Isso já foi um\nesconderijo ninja.\012Há armadilhas\npara confundir\011intrusos como\011você.",
  ["1b:4c0b"] = "Está trancada…",
  ["1b:4c16"] = "Tudo bem.\n\nFalarei um\011segredo do nosso\011esconderijo.\012Aquela coisa no\nchão acima é\011o painel de\011teletransporte.\011Se pisar nele,\011você voltará para\011a entrada.",
  ["1b:4cb7"] = "Hehe. Sentindo-se\nsortudo, garoto?\011Vá em frente, dê\011outro passo.\011Temos armadilhas\011no chão!",
  ["1b:4d12"] = "Kaboom!",
  ["1b:4d1b"] = "Eu nem sei onde\nas armadilhas\011estão.\012Você terá que\nter coragem e\011caminhar.",
  ["1b:4d7c"] = "É uma estátua do\nPERSIAN…\012Seus olhos têm um\nbrilho estranho.",
  ["1b:4dad"] = "Um botão secreto!\nÉ melhor\011apertá-lo.",
  ["1b:4dd0"] = "O botão está\ndesligado.",
  ["1b:52ad"] = "Fique bem aí!",
  ["1b:52c3"] = "Não podemos deixar\num pirralho como\011você livre.\012É nocivo ao\norgulho da EQUIPE\011ROCKET, você sabe.\012Mesmo sendo forte,\nvocê não pode nos\011vencer ao mesmo\011tempo.\012Perdão, amigo.\nAgora prepare-se\011para ser lixado.",
  ["1b:538c"] = "Ei! Não seja\negoísta. Espalhe\011a diversão.",
  ["1b:53bd"] = "O quê? Você tem\num cúmplice?\012Aonde está seu\nsenso de honra?\012Como chefe\nprovisório no\011lugar de GIOVANNI,\011vou lhe mostrar\011o quanto é errado\011atrapalhar a\011EQUIPE ROCKET!",
  ["1b:545c"] = "Tch, você é\nrealmente forte.\012É uma pena.\012Se você se unisse\nà EQUIPE ROCKET,\011poderia ser um\011EXECUTIVO.",
  ["1b:54c6"] = "…Esse esconderijo\né feito para…\012Mas tudo bem.\nA experiência da\011transmissão foi um\011sucesso total.\012Não importa o que\nocorrer com esse\011esconderijo agora.\012Temos planos bem\nmaiores.\012Em breve você\napreciará o\011verdadeiro poder\011da EQUIPE ROCKET.\012Divirta-se\nenquanto puder…\012Hahahaha…",
  ["1b:55d8"] = "LANCE:\nConseguimos. Nós\011derrotamos todos\011os ROCKETS aqui.\012Mas estou\npreocupado com um\011jovem com quem\011batalhei por\011aqui…",
  ["1b:564e"] = "Perdão, {PLAYER}.\nEu vi como você\011era bom, por isso\011recuei.\012Agora tudo o que\nresta fazer é\011desligar aquele\011estranho sinal\011de rádio.",
  ["1b:56cf"] = "É essa máquina\nque está causando\011todos os\011problemas.\012Não vejo um\nbotão nela…\012Não temos escolha.\nTemos que\011fazer todos\011os ELECTRODES\011desmaiarem.\012Isso deve parar\nessa máquina de\011transmitir esse\011estranho sinal.\012Não é culpa dos\n#MON, então\011isso me faz sentir\011culpado.\012{PLAYER}, vamos\ndividir a tarefa.",
  ["1b:57ea"] = "LANCE: Deixe\nesse lado comigo.",
  ["1b:5809"] = "LANCE: O estranho\nsinal finalmente\011parou.\012O LAGO deve ter\nvoltado ao normal.\012Você é o herói!\nDeixe-me lhe\011agradecer em\011benefício de todos\011#MON.\012Oh, sim. Você deve\nlevar isso.\012Eu achei aqui,\nmas eu não\011necessito disso.",
  ["1b:58f8"] = "É o REDEMOINHO.\nEnsine-o a um\011#MON para\011atravessar águas\011selvagens.\012Mas lembre-se\ndisso.\012Você só pode\nusá-lo fora de\011batalhas se tiver\011a INSÍGNIA DO\011GINÁSIO MAHOGANY.",
  ["1b:5994"] = "{PLAYER}…\012A jornada para se\ntornar o MESTRE\011#MON é longa e\011difícil.\012Mesmo sabendo\ndisso, pretende\011continuar?\012…\012Entendo. Não, você\nestá certo.\012Se você desistisse\nfacilmente, nunca\011teria perseguido\011esse sonho como\011a coisa mais\011importante.\012Eu espero vê-lo\nnovamente!",
  ["1b:5a97"] = "LANCE: Você está\nbem?\012Seus #MON\nestão machucados\011e cansados.\012Ei, dê a eles um\npouco do meu\011remédio.",
  ["1b:5af7"] = "LANCE: {PLAYER},\nvamos dar nosso\011melhor pelos\011#MON.",
  ["1b:5b22"] = "A porta não abre?\012Seu idiota! Você\nprecisa da senha\011que apenas a\011EQUIPE ROCKET\011sabe.",
  ["1b:5b79"] = "O quê? Eu perdi?",
  ["1b:5b88"] = "É, eu sou apenas\num NOVATO. Eu\011não sei a senha.\011Pior para você.",
  ["1b:5bca"] = "Oh, um garoto?\nEu não gosto\011disso, mas eu devo\011eliminá-lo.",
  ["1b:5c09"] = "Eu sabia que\nperderia…",
  ["1b:5c1a"] = "Eu fui derrotado\nna última missão\011por um garoto\011também.\012Quando estávamos\nmaltratando os\011#MON, esse\011garoto de cabelo\011longo e vermelho\011e de olhar ruim\011me derrotou…",
  ["1b:5cb0"] = "Você é um\npestinha!",
  ["1b:5cc9"] = "Grrrr…",
  ["1b:5cd1"] = "É, só o chefe sabe\na senha para\011aquela porta.\012Onde está o\nchefe? Quem sabe?\011Vá procurá-lo\011sozinho.",
  ["1b:5d39"] = "A porta está\nfechada…\012Ela precisa de\nsenha para abrir.",
  ["1b:5d6b"] = "A porta está\nfechada…\012{PLAYER} usou a\nsenha.\012A porta se abriu!",
  ["1b:5da7"] = "É o rádio\ntransmissor que\011está enviando o\011sinal sinistro.\012Está funcionando\ncom capacidade\011total.",
  ["1b:5e03"] = "O terrível sinal\ndo transmissor de\011rádio finalmente\011parou.",
  ["1b:6179"] = "LANCE: Precisamos\nde duas senhas\011para acessar a\011sala do chefe.\012Essas senhas só\nsão sabidas por\011poucos ROCKETS.\012Foi um ROCKET que\nme contou isso.\012{PLAYER}, vamos\npegar as senhas.",
  ["1b:6235"] = "Urrggh… O cara de\ncapa é incrivel-\011mente forte…",
  ["1b:6267"] = "…\012Eu não te disse\nque destruiría a\011EQUIPE ROCKET?\012…Conte-me, quem\nera o cara de\011capa que usava\011#MON dragões?\012Meus #MON não\nforam páreos.\012Eu não me importo\nem perder. Eu\011posso derrotá-lo\011se eu capturar\011#MON mais\011fortes.\012O que me incomoda\nfoi o que ele\011disse…\012Contou-me que\neu não amo e\011nem confio em\011meus #MON o\011bastante.\012Estou furioso\npor perder para\011um coração mole\011como ele.\012…Humph! Não tenho\ntempo para gente\011como você!",
  ["1b:6400"] = "O quê? Quem é\nvocê? Esse é o\011escritório do\011nosso líder,\011GIOVANNI.\012Desde quando a\nEQUIPE ROCKET\011faliu, há três\011anos, ele está em\011treinamento.\012Mas sabemos que\nele voltará algum\011dia para reassumir\011o comando.\012Por isso estamos\nem alerta.\012Não deixarei\nninguém perturbar\011esse lugar!",
  ["1b:6511"] = "Eu… Nada pude\nfazer…\012GIOVANNI, por\nfavor me perdoe…",
  ["1b:6548"] = "Não, não posso\ndeixar isso me\011afetar.\012Devo informar\nos outros…",
  ["1b:6585"] = "MURKROW: A senha\né…\012GRANDE GIOVANNI.",
  ["1b:65af"] = "Se eu sei a\nsenha?\012Talvez.\012Mas nenhum\nfracote vai\011obtê-la!",
  ["1b:65f1"] = "Tudo bem. Pare.\nEu lhe contarei.",
  ["1b:6611"] = "A senha para a\nsala do chefe é\011RABO DO SLOWPOKE.\012Mas ela é inútil\nse você não tiver\011duas senhas.",
  ["1b:6671"] = "Lá-lá-lá-lá!\012Está me desafiando\npara um batalha?\012Hah! Você é um\ntolo, mas tem\011habilidades!\012Eu gosto disso!\012Se você me\nderrotar, eu lhe\011contarei a senha\011para a sala do\011chefe!",
  ["1b:6717"] = "Lá-lá-lá-lá! Você\né bom!",
  ["1b:6737"] = "Lá-lá-lá-lá!\012A senha para a\nsala do chefe…\012Uh, eu acho que é\nCAUDA DO RATICATE.",
  ["1b:678d"] = "Eu trabalhava\npara a SILPH,\011mas agora faço\011pesquisas para a\011EQUIPE ROCKET.\012Um pirralho como\nvocê deve ser\011punido.",
  ["1b:6802"] = "Minha tática\nerrada me puniu…",
  ["1b:6822"] = "Um sinal de rádio\nque deixa os\011#MON doidos.\012Minha experiência\né um sucesso\011total.\012Minha promoção\nestá garantida.\011Essa derrota não\011atrapalhará.",
  ["1b:68ac"] = "Não me importo se\nnossa experiência\011feriu #MON.",
  ["1b:68df"] = "Pensar é o meu\nponto forte, não\011batalhar.",
  ["1b:690a"] = "Se nós acionarmos\no rádio para uma\011transmissão em\011grande escala…\012Esses pensamentos\nme entuasiasmam!",
  ["1b:6970"] = "A porta está\nfechada…\012Ela usa duas\nsenhas para abrir.",
  ["1b:69a3"] = "A porta está\nfechada…\012{PLAYER} usou as\nduas senhas.\012A porta abriu!",
  ["1b:6f5c"] = "Ah, cara…\nMeu chefe ficará\011irritado…\n \012O FARFETCH'D que\nCORTA árvores para\011fazer carvão\011fugiu.\012Não posso\nprocurá-lo aqui\011na FLORESTA DE ILEX.\012Ela é grande,\nassustadora e\011escura demais para\011mim.",
  ["1b:7019"] = "Uau! Muito\nobrigado!\012O #MON do meu\nchefe não me\011obedece porque\011eu não tenho\011INSÍGNIAS.",
  ["1b:706f"] = "Este é o #MON\nperdido.",
  ["1b:7086"] = "FARFETCH'D: FARF!",
  ["1b:7099"] = "Ah! Meu\nFARFETCH'D!\012Você o achou para\nnós {PLAYER}?\012Sem ele, não\npoderíamos cortar\011árvores para fazer\011carvão.\012Muito obrigado!\012Como posso\nagradecê-lo?\012Já sei! Leve isso\naqui.",
  ["1b:7141"] = "Este é o HM CORTA.\nEnsine ele a um\011#MON para\011cortar árvores.\012Claro, é preciso\nter a INSÍGNIA DO\011GINÁSIO DE AZALEA\011para poder usá-lo.",
  ["1b:71c0"] = "Deseja aprender\ncomo se fabrica\011carvão comigo? \012Você será o\nprimeiro em dez\011anos!",
  ["1b:721b"] = "O que estou\nfazendo?\012Estou sacudindo as\nárvores usando\011CABEÇADA.\012É divertido. Tente\ntambém!",
  ["1b:726d"] = "Balance árvores\nusando CABEÇADA.\012Às vezes caem\n#MON dormindo.",
  ["1b:72af"] = "Ocorreu alguma\ncoisa ao guardião\011da floresta?",
  ["1b:72de"] = "A FLORESTA DE ILEX\ntem árvores tão\011grandes que te\011impedem de ver o\011céu.\012Fique atento com\nitens que podem\011ter sido largados.",
  ["1b:7358"] = "SANTUÁRIO DA\nFLORESTA DE ILEX\012É em homenagem\nao protetor da\011floresta…",
  ["1b:7394"] = "SANTUÁRIO DA\nFLORESTA DE ILEX\012É em homenagem\nao protetor da\011floresta…\012Oh! O que é isso?\nÉ um buraco.\012Parece que a BOLA\nGS encaixa aí.\012Deseja colocar a\nBOLA GS aqui?",
  ["1b:743b"] = "{PLAYER} colocou a\nBOLA GS.",
  ["1b:7452"] = "Uau, o que foi\nisso?\012{PLAYER}, isso foi\nfantástico.\012Obrigado!\012As lendas sobre\nesse SANTUÁRIO\011eram reais.\n \012Sinto-me inspirado\npelo que acabei de\011ver.\012Isso me motivou\na fazer BOLAS\011melhores!\012Estou indo!",
  ["1b:7515"] = "Não fique me\nespiando assim!\012Você assustou um\n#MON!",
  ["1b:7551"] = "Eu não tinha visto\naquele #MON…",
  ["1b:7571"] = "Um #MON que eu\nnunca tinha visto\011caiu da árvore\011quando eu usei a\011CABEÇADA.\012Devo usar a\nCABEÇADA em outros\011lugares também.",
  ["1c:4157"] = "Esse lago é cheio\nde GYARADOS e\011nada mais…\012Então as MAGIKARPS\nestão sendo\011forçadas a\011evoluir…",
  ["1c:41b4"] = "Você veio aqui\ndevido aos boatos?\012Você é {PLAYER}?\nEu sou LANCE, um\011treinador como\011você.\012Eu ouvi boatos,\nentão eu vim\011investigar…\012Eu vi o modo como\nvocê batalhou\011anteriormente,\011{PLAYER}.\012Posso dizer\nque você é\011um treinador\011com grandes\011habilidades.\012Se não se\nimportar, poderia\011me ajudar a\011investigar?",
  ["1c:42c6"] = "LANCE: Excelente!\012Parece que as\nMAGIKARPS do LAGO\011estão sendo\011forçadas a\011evoluir.\012Uma misteriosa\ntransmissão de\011rádio vinda de\011MAHOGANY é a\011causa.\012Estarei te\nesperando,\011{PLAYER}.",
  ["1c:4371"] = "Oh… Bem, se você\nmudar de idéia,\011venha me ajudar.",
  ["1c:43a5"] = "LANCE: Hm? Você\nvai me ajudar?",
  ["1c:43cb"] = "GYARADOS: Gyashaa!",
  ["1c:43df"] = "{PLAYER} obtained a\nRED SCALE.",
  ["1c:43f8"] = "Os GYARADOS estão\nnervosos!\012Isso é um mau\nsinal!",
  ["1c:4421"] = "Haha! As MAGIKARPS\nestão mordendo!",
  ["1c:4444"] = "Eu soube que esse\nlago foi feito\011por rituais de\011GYARADOS.\012Será que tem\nalguma conexão com\011seus poderes\011destrutivos?",
  ["1c:44bb"] = "Meus olhos estão\nme enganando? Eu\011vi um GYARADOS\011vermelho no LAGO…\012Mas pensei que os\nGYARADOS eram\011azuis?",
  ["1c:4522"] = "Deixe-me batalhar\ncom o #MON que\011acabei de pegar!",
  ["1c:454e"] = "Posso ser um\nótimo pescador,\011mas sou horrível\011como treinador\011#MON…",
  ["1c:458f"] = "Não perderei\ncomo pescador!\011Pego #MON o\011dia todo.",
  ["1c:45c0"] = "Não importa o\nque eu faça, eu\011sempre pego o\011mesmo #MON.",
  ["1c:45f7"] = "Minha linha está\nenrolada…",
  ["1c:4611"] = "Por que não\ncapturo um bom\011#MON?",
  ["1c:4632"] = "Se um treinador\nver outro\011treinador, ele\011tem que fazer um\011desafio.\012Esse é nosso\ndestino.",
  ["1c:4688"] = "Nossa…\nBoa batalha.",
  ["1c:469c"] = "Os #MON e\nseus treinadores\011ficam poderosos\011após constantes\011batalhas.",
  ["1c:46df"] = "O que ocorreu ao\nGYARADOS vermelho?\012Ele sumiu?\012Oh, droga. Eu vim\naqui para nada?\012Já sei--vamos\nbatalhar!",
  ["1c:4745"] = "Boa jogada!",
  ["1c:4752"] = "Falando nisso, eu\nvi uma BUTTERFREE\011rosa.",
  ["1c:4784"] = "WESLEY: Bem, como\nvai você?\012Como sabe, hoje\né Quarta-feira.\011Sou WESLEY da\011Quarta.",
  ["1c:47dd"] = "Que bom\nconhecê-lo. Leve\011Essa lembrança.",
  ["1c:480b"] = "WESLEY: A\nFAIXAPRETA melhora\011os golpes do tipo\011lutador.",
  ["1c:4844"] = "WESLEY: Como você\nme achou, você\011deve ter\011conhecidos meus\011irmãos.\012Ou você teve pura\nsorte?",
  ["1c:48a9"] = "WESLEY: Hoje não\né Quarta. Isso é\011tão ruim.",
  ["1c:48d7"] = "LAGO DA FÚRIA,\ntambém chamado de\011LAGO DO GYARADOS.",
  ["1c:4903"] = "CASA DOS\nPESCADORES.",
  ["1c:49ef"] = "Olá! Bem-vindo\nà LOJA DE\011DEPARTAMENTOS DE\011CELADON!\012O que há em\ncada andar está\011na parede.",
  ["1c:4a35"] = "Esta LOJA DE\nDEPARTAMENTOS é da\011mesma linha\011daquela da CIDADE\011GOLDENROD.\012Elas foram\nrenovadas ao mesmo\011tempo.",
  ["1c:4aa9"] = "É minha primeira\nvez aqui.\012É tão grande…\012Tenho medo de me\nperder.",
  ["1c:4aea"] = "1ª ANDAR-RECEPÇÃO\0122ª-LOJA DO\nTREINADOR\0123ª-LOJA DE TM\0124ª-PRESENTES DO\nSÁBIO\0125ª-FARMÁCIA\0126ª-PRAÇA DA\nCOBERTURA.",
  ["1c:4bc9"] = "Tornei-me\ntreinador\011recentemente.\012Meu filho me\nincentivou a\011fazê-lo.\012Estou\nimpressionado pelo\011acervo de itens\011úteis.",
  ["1c:4c3e"] = "Meu pai está\ntendo dificuldades\011para aprender\011nomes de itens\011e como eles\011supostamente são\011usados…",
  ["1c:4c9c"] = "Ótimos itens para\ntreinadores!\0122ª ANDAR-LOJA DO\nTREINADOR.",
  ["1c:4d53"] = "Não consigo me\ndecidir em qual\011#MON usar esse\011TM…",
  ["1c:4d86"] = "Uh-oh! Troquei meu\n#MON sem\011retirar a\011MELHORA dele.",
  ["1c:4dc7"] = "Beleza! Finalmente\nconsegui um\011PORYGON!\012Não sou bom nas\nroletas e não\011conseguiria moedas\011suficientes…\012…Hã?\012O PORYGON trocado\nse tornou um\011#MON diferente!",
  ["1c:4e61"] = "A LOJA DE TM\nvende golpes\011raros.",
  ["1c:4e85"] = "3ª ANDAR-LOJA DE\nTM.\012Fortaleça seu\n#MON!",
  ["1c:4f21"] = "Vim aqui comprar\numa CARTA SURFE\011para enviá-la a\011minha namorada.",
  ["1c:4f55"] = "Este é o único\nlugar em que você\011pode comprar a\011CARTA AMÁVEL.",
  ["1c:4f8c"] = "PISTA DE CICLISMO\012A Subida Começa\nAqui.",
  ["1c:5023"] = "Quero comprar\nitens que melhorem\011o estado dos\011#MON, mas não\011tenho dinheiro\011suficiente…",
  ["1c:5072"] = "Quero usar o PP\nMAIS para aumentar\011o PP dos golpes.\011Mas ele não é\011vendido.",
  ["1c:50b6"] = "Usar itens\nnos #MON os\011alegra.\012Porém, odeiam\ncertos itens…",
  ["1c:5100"] = "5ª ANDAR-FARMÁCIA.",
  ["1c:5250"] = "Uma máquina de\nvenda!\012Eis o menu.",
  ["1c:5274"] = "Clang!\012{STRBUF}\npopped out.",
  ["1c:528e"] = "Opa, pouco\ndinheiro…",
  ["1c:52a7"] = "Não há espaço para\no item…",
  ["1c:52c7"] = "Uma máquina de\nvenda com roleta\011de prêmio…\012Não se vê mais\ndessas por aí.",
  ["1c:5310"] = "Aww! Não há jogos\naqui!\012Eu queria brincar…",
  ["1c:533e"] = "６º ANDAR-PRAÇA\nDA COBERTURA\012MÁQUINAS DE VENDA.",
  ["1c:5416"] = "Meus queridos\n#MON me\011acompanham, logo,\011não me sinto só.\012MEOWTH até traz\ndinheiro para cá.",
  ["1c:5470"] = "MEOWTH: Meow!",
  ["1c:547f"] = "CLEFAIRY: Clef\ncleff!",
  ["1c:5496"] = "NIDORAN: Kya\nkyaoo!",
  ["1c:54ab"] = "MANSÃO CELADON\nSUÍTE DO GERENTE.",
  ["1c:5539"] = "{PLAYER} ligou o\nCOMPUTADOR.\012…\012Alguém estava\nescrevendo um\011e-mail.\012…Espero que você\nvenha visitar\011KANTO.\012Acho que ficará\nsurpreso com as\011mudanças das\011coisas por aqui.\012Você também verá\nvários #MON\011que não são\011nativos em JOHTO.\012Ao PRODUTOR\012…",
  ["1c:562c"] = "GAME FREAK\nSALA DE ENCONTRO.",
  ["1c:56ce"] = "Isso está certo?\012Sou o DESIGNER DO\nJOGO!\012Preencher sua\n#DEX é difícil,\011mas não desista!",
  ["1c:5725"] = "Uau! Excellente!\nVocê completou sua\011#DEX!\012Parabéns!",
  ["1c:5763"] = "O ARTISTA GRÁFICO\nvai imprimir um\011DIPLOMA para você.\012Você deveria\nexibi-lo.",
  ["1c:57b4"] = "Sou o ARTISTA\nGRÁFICO.\012Eu o desenhei!",
  ["1c:57d8"] = "Sou o ARTISTA\nGRÁFICO.\012Oh, você completou\nsua #DEX?\012Quer que eu\nimprima o seu\011DIPLOMA?",
  ["1c:5830"] = "Avise-me se você\nquiser ter seu\011DIPLOMA impresso.",
  ["1c:5895"] = "Quem, eu? Sou o\nPROGRAMADOR.\012Jogue as máquinas\nde roleta!",
  ["1c:58ca"] = "As GÊMEAS não\nsão adoráveis?\012JASMINE é bela\ntambem.\012Oh, eu as amo!",
  ["1c:590b"] = "GAME FREAK\nSALA DE PRODUÇÃO.",
  ["1c:5928"] = "É um dEsenho\ndetalhado de uma\011bela garota.",
  ["1c:5952"] = "É o programa do\njogo. Bagunçá-lo\011pode causar erros\011no jogo!",
  ["1c:5996"] = "Está cheio de\nmaterias de\011referência.\012Tem até um BONECO.",
  ["1c:5a3f"] = "Lugares altos, eu\nos adoro tanto!\012Diria que a única\ncoisa que ama\011altura como eu\011é a fumaça!",
  ["1c:5aa1"] = "Há um desenho na\nparede…\012{PLAYER} adicionou\num bigode!",
  ["1c:5b27"] = "Deixe-me lhe\ncontar uma\011história terrível…",
  ["1c:5b4a"] = "Porém, não é\ntão assustadora\011enquanto está de\011dia.\012Volte após o\npôr-do-sol, certo?",
  ["1c:5ba3"] = "Era uma vez, um\ngarotinho que\011tinha ganhado uma\011nova BICICLETA…\012Ele queria\ntestá-la de\011qualquer jeito…\012Ele estava se\ndivertindo tanto\011que nem notou o\011pôr-do-sol…\012Enquanto voltava\npara casa na\011noite escura,\011a bicicleta de\011repente ficou\011lenta!\012Os pedais ficaram\npesados!\012Quando parou\nde pedalar, a\011bicicleta começou\011a escorregar para\011trás.\012Como se\nela estivesse\011amaldiçoada e\011tentando jogá-lo\011na escuridão!\012…\012SHRIEEEEK!\012O garoto estava\nsubindo a PISTA\011DE CICLISMO!\012…\nBa-dum ba-dum!\012Por ter escutado\ntão pacientemente,\011poderá levar isso,\011o TM03!",
  ["1c:5db3"] = "TM03 é o\nAMALDIÇOAR.\012É um golpe\nterrível que reduz\011o HP da vítima\011lentamente.",
  ["1c:5e70"] = "ERIKA é a mestra\nde #MON grama.\012Ela vai fazê-lo\nsofrer se não\011ficar bem atento.",
  ["1c:5ec1"] = "O esconderijo da\nEQUIPE ROCKET é\011no porão da CASA\011DE JOGOS.\012Oh, espere. Isso\nfoi há três anos.",
  ["1c:5f22"] = "EUSINE: Oi!\012Vim visitar minha\ncidade natal.\011Já fazia um tempo.",
  ["1c:5f65"] = "{PLAYER}, você\nsoube?\012Há boatos recentes\nde que um #MON\011cor de arco-íris\011está aparecendo na\011TORRE DO SINO.\012Acabei de curar\nminha equipe,\011então estou indo a\011ECRUTEAK.\012Até a próxima\nvez, {PLAYER}!",
  ["1c:601a"] = "Oh, a propósito,\n{PLAYER}.\012Você capturou os\n#MON lendários\011RAIKOU e ENTEI?\012………\012Certo…\012Se capturar pelo\nmenos um, espero\011que me informe.\012Estou contando com\nvocê, {PLAYER}!",
  ["1c:61d0"] = "Bem-vindo!\012Você pode trocar,\nao lado, suas\011moedas por prêmios\011fabulosos.",
  ["1c:6215"] = "As máquinas de\njogo são uma obra\011de arte.",
  ["1c:6242"] = "É essa máquina\nque quero.\012Ela me limpou\nontem, então ela\011deverá pagar algum\011dia.",
  ["1c:6295"] = "Acho que essa\nmáquina de jogo\011pagará…\012As chances variam\nentre elas.",
  ["1c:62dc"] = "Gahahaha!\012As moedas\ncontinuam a cair!\012Hm? O que, garto?\nQuer jogar?\012Dividirei minha\nsorte com você!",
  ["1c:6345"] = "Gahahaha!\012Sinto-me bem ao\nfazer boas coisas\011a outras pessoas!",
  ["1c:638a"] = "Ei, você não tem\num PORTA MOEDA.\012Como poderei\nlhe dar algumas\011moedas, garoto?",
  ["1c:63d9"] = "Ei, seu PORTA\nMOEDA está cheio,\011garoto.\012Você deve estar\nvencendo bastante\011também.",
  ["1c:6425"] = "Ei! CAMPEÃO em\nprogresso!\012Está jogando as\nmáquinas também?\012Tento ganhar\nmoedas suficientes\011para obter\011#MON.\012Mas não tenho\nmuitas moedas\011ainda…",
  ["1c:64ad"] = "Hmmm… Há mais\nchances para a\011linha do PIKACHU.\012Mas… O que faço?",
  ["1c:64f3"] = "Ei!\012Debaixo desse\npôster…\012Não há nada!",
  ["1c:6521"] = "Ei!\012Debaixo desse\npôster…\012Não há nada!",
  ["1c:654f"] = "Há um esqueiro\naqui.",
  ["1c:6567"] = "Um refrigerante…\012Alguém deve tê-lo\ndeixado…\012Hã? Está vazio!",
  ["1c:68b8"] = "Quis um PORYGON,\nmas eu só tenho\011100 moedas…",
  ["1c:68e9"] = "Nossa…\012Tenho que ficar\ncalmo…\012Não posso me\nirritar, pois\011posso perder todo\011meu dinheiro.",
  ["1c:693e"] = "Bem-vindo!\012Trocamos suas\nmoedas por prêmios\011fabulosos!",
  ["1c:6974"] = "Qual prêmio você\nquer?",
  ["1c:6991"] = "OK, so you wanted\na {STRBUF}?",
  ["1c:69ad"] = "Aqui está!",
  ["1c:69bb"] = "Você não\ntem moedas\011suficientes.",
  ["1c:69d8"] = "Você não possui\nespaço.",
  ["1c:69f2"] = "Oh. Volte com\nmoedas por favor!",
  ["1c:6a14"] = "Oh? Você não tem um\nPORTA MOEDA.",
  ["1c:6b28"] = "ERIKA: Olá…\nTempo adorável,\011não é?\012É tão agradável…\012Tenho medo de\nadormecer…\012Meu nome é ERIKA.\nSou a LÍDER DO\011GINÁSIO DE\011CELADON.\012…Oh? Veio de lá\nde JOHTO, foi o\011que disse? Que\011ótimo…\012Oh. Desculpe-me,\nnão percebi que\011você queria me\011desafiar.\012Muito bem, mas eu\nnão perderei.",
  ["1c:6c3e"] = "ERIKA: Oh!\nAdmito a derrota…\012Você é\nincrivelmente\011forte…\012Darei-lhe\na INSÍGNIA\011ARCO-ÍRIS…",
  ["1c:6c96"] = "{PLAYER} obteve uma\nESCAMA RUBRA.",
  ["1c:6cb0"] = "ERIKA: Foi uma\npartida magnífica.\012Senti-me\ninspirada. Quero\011que você leve\011esse TM.\012É o GIGA DRENO.\012É um golpe\nmaravilhoso que\011drena metade do\011dano que causa e\011fornece ao seu\011#MON.\012Por favor, use\nisso se lhe\011agradar…",
  ["1c:6d8f"] = "ERIKA: Perder\ndeixa um gosto\011amargo…\012Mas saber que há\nfortes treinadores\011me incentiva a\011melhorar…",
  ["1c:6dfc"] = "Você acha raro\n\nGINÁSIOS só de\011meninas?",
  ["1c:6e24"] = "Oh, bleah!",
  ["1c:6e30"] = "Eu me descuidei,\nfoi só isso!",
  ["1c:6e53"] = "Oh, uma batalha?\nEstou um pouco\011assustada, mas\011está certo!",
  ["1c:6e7f"] = "Oh! É isso?",
  ["1c:6e8e"] = "Oh, olha todas\nsuas INSÍGNIAS.\011Sem dúvida eu\011perderia!",
  ["1c:6ec5"] = "Estava olhando\nessas flores ou\011eu?",
  ["1c:6ef2"] = "Que irritante!",
  ["1c:6f01"] = "Que tal se eu me\ntornasse uma dama\011como ERIKA?",
  ["1c:6f32"] = "Mostraremos-lhe\ngolpes #MON\011que ERIKA nos\011ensinou!",
  ["1c:6f62"] = "Oh… Perdemos…",
  ["1c:6f70"] = "ERIKA vai vencê-lo\npor nós!",
  ["1c:6f91"] = "Vamos proteger\nERIKA!",
  ["1c:6faf"] = "Não pudemos\nvencer…",
  ["1c:6fc0"] = "ERIKA é muito,\nmuito forte!",
  ["1c:70de"] = "Oi!\012Estamos fazendo\num concurso de\011comer.\012Não podemos\nservi-lo agora.\011Perdão.",
  ["1c:7129"] = "…Snarfle, chew…",
  ["1c:713a"] = "Não fale comigo!\012Vai quebrar minha\nconcentração!",
  ["1c:716a"] = "…Gulp… Chew…",
  ["1c:7178"] = "Prefiro quantidade\nà qualidade!\012Fico feliz quando\ncheio!",
  ["1c:71ae"] = "Munch, munch…",
  ["1c:71bd"] = "A comida é boa\naqui, mas a de\011GOLDENROD é a\011melhor que existe.",
  ["1c:7201"] = "Crunch… Crunch…",
  ["1c:7212"] = "Ninguém aqui lhe\ndará um pORTA\011MOEDA. Você deve\011procurar em JOHTO.",
  ["1c:7254"] = "Crunch… Crunch…\012Posso ficar\ncomendo!",
  ["1c:7278"] = "Mais, CHEFE!",
  ["1c:7285"] = "Concurso de Comer!\nSem limite de\011tempo!\012Uma batalha sem\nfim! Quem comer\011mais não pagará\011nada!",
  ["1c:72e7"] = "{PLAYER} found\n{STRBUF}!",
  ["1c:72f7"] = "Mas {PLAYER} não\ntem mais espaço…",
  ["1c:7379"] = "Se você descer na\nPISTA DE CICLISMO,\011vai chegar na\011CIDADE DE FUCHSIA.",
  ["1c:7408"] = "Aqui começa a\nPISTA DE CICLISMO.\012É só descida,\nlogo, é pura\011adrenalina.\012É um ótimo tipo\nde sentimento que\011não se sente em\011navios ou em\011trens.",
  ["1c:7496"] = "Ei! Opa! Pare!\012Você não pode\ncruzar a PISTA DE\011CICLISMO sem uma\011BICICLETA.",
  ["1c:752c"] = "Levo meu trabalho\nde GUARDA a sério!\012Ei! Você tem uma\n#DEX!\012Certo. Você pode\nir.",
  ["1c:7592"] = "Espere! Você não\ntem uma BICICLETA?\012A PISTA DE CICLISMO\né ao lado.\012Você precisa de\numa BICICLETA\011para ir lá.",
  ["1c:762c"] = "Expresse-se com\npresentes!\0124ªANDAR-PRESENTES\nDO SÁBIO.",
  ["1c:764d"] = "6ª ANDAR-PRAÇA\nDA COBERTURA\012MÁQUINAS DE VENDA.",
  ["1d:4008"] = "Um bando de\nDIGLETT saiu da\011terra!\012Isso foi chocante.",
  ["1d:4105"] = "… … …\012Há quanto tempo,\n{PLAYER}.\012…Desde que perdi\npara você, tenho\011pensado no que tem\011faltado aos meus\011#MON.\012E me veio uma\nresposta.\012{PLAYER}, agora\nvamos lhe mostrar!",
  ["1d:419d"] = "… … …\012Pensei que\ntreinara meus\011#MON para\011serem os melhores\011que pudessem…\012… Mas ainda não\né o bastante…",
  ["1d:41fa"] = "… … …\012… Você venceu\nhonestamente.\011Eu admito. Mas\011esse não é o fim.\012Serei o melhor\ntreinador #MON\011que já existiu.\012Porque esses\ncaras estão me\011apoiando…\n \012…Ouça, {PLAYER}.\012Um dia eu vou\nprovar o quanto\011eu sou bom ao\011derrotá-lo.",
  ["1d:42e0"] = "… … …\012Eu paguei minha\ndívida com você.\012Com meus #MON,\nvou derrotar o\011CAMPEÃO e me\011tornar o melhor\011treinador do\011mundo.",
  ["1d:455f"] = "… … …\012… Você venceu\nhonestamente.\011Eu admito. Mas\011esse não é o fim.\012Serei o melhor\ntreinador #MON\011que já existiu.\012Porque esses\ncaras estão me\011apoiando…\n \012…Ouça, {PLAYER}.\012Um dia eu vou\nprovar o quanto\011eu sou bom ao\011derrotá-lo.",
  ["1d:463d"] = "…Não pude vencer…\012Dei tudo que\ntinha…\012O que você tem,\ne o que falta em\011mim…\012Estou começando a\nentender o que o\011mestre de dragões\011me disse…",
  ["1d:46ce"] = "…Não desisti de me\ntornar o melhor\011treinador.\012Vou descobrir\nporque eu não\011posso vencer e me\011tornarei mais\011forte…\012Quando o fizer,\nvou desafiá-lo.\012E o derrotarei\nusando todo o meu\011poder.\012…Humph! E você\ncontinue assim\011até lá.",
  ["1d:47aa"] = "…Humph!\012Quando se trata\nde força, nada\011pode me vencer.\012Não preciso de\nmais nada.",
  ["1d:4a55"] = "Partiremos em\nbreve. Por favor\011embarque.",
  ["1d:4a80"] = "Perdão. Você não\npode embarcar\011agora.",
  ["1d:4a9c"] = "Bem-vindo À BALSA SANTA AQUA.\011Você vai embarcar hoje?",
  ["1d:4ada"] = "Posso ver sua\nPASSAGEM?",
  ["1d:4af6"] = "Esperamos vê-lo\nde novo!",
  ["1d:4b11"] = "{PLAYER} mostrou\na PASSAGEM.\012É isso. Obrigado!",
  ["1d:4b41"] = "{PLAYER} tentou\nmostrar a\011PASSAGEM…\012…Mas não há!\012Perdão! Você só\npode embarcar se\011tiver uma\011PASSAGEM.",
  ["1d:4ba8"] = "A BALSA\nsairá na próxima\011Segunda.",
  ["1d:4bce"] = "A BALSA\nsairá na próxima\011Sexta.",
  ["1d:4bf4"] = "SHELLDERS são\nfáceis de capturar\011aqui mas não em\011outros lugares.",
  ["1d:4c35"] = "Quantas VARAS\nvocê tem?\012VARAS distintas\ncapturam distintos\011#MON.",
  ["1d:4c76"] = "O S.S.AQUA usa\njatos para\011deslizar sobre a\011água!",
  ["1d:4ca2"] = "Há muitos #MON\nem KANTO.\012Eu queria ir lá…",
  ["1d:4cd7"] = "Não queremos que\nvocê caia no mar,\011logo você não pode\011entrar.",
  ["1d:4f06"] = "Partiremos em\nbreve. Por favor\011embarque.",
  ["1d:4f31"] = "Perdão. Você não\npode embarcar\011agora.",
  ["1d:4f4d"] = "Bem-vindo à BALSA SANTA AQUA.\011Você vai embarcar\011hoje?",
  ["1d:4f8b"] = "Oosso ver sua\nPASSAGEM?",
  ["1d:4fa7"] = "Esperamos vê-lo\nde novo!",
  ["1d:4fc2"] = "{PLAYER} mostrou a\nPASSAGEM.\012É isso. Obrigado!",
  ["1d:4ff2"] = "{PLAYER} tentou\nmostrar a\011PASSAGEM…\012…Mas não há\nPASSAGEM!\012Perdão. Você só\npode embarcar\011se tiver uma\011PASSAGEM.",
  ["1d:5059"] = "A BALSA\nsairá na próxima\011Quarta.",
  ["1d:5080"] = "A BALSA\nsairá no próximo\011Domingo.",
  ["1d:50a6"] = "Você veio de\nJOHTO?\012Soube que muitos\n#MON raros\011vivem por lá.",
  ["1d:523b"] = "A BALSA SANTA AQUA está a\011caminho da CIDADE DE\011VERMILION.\012Vamos avisar\nquando chegarmos\011lá.",
  ["1d:529b"] = "A BALSA SANTA AQUA está a\011caminho da CIDADE DE\011OLIVINE.\012Vamos avisar\nquando chegarmos\011lá.",
  ["1d:52f9"] = "Aqui está sua\ncabine.\012Se seus #MON\nse ferirem,\011descanse na cama.\012Isso vai\ncurá-los.",
  ["1d:534f"] = "Aqui está sua\ncabine.\012Você pode curar\nseus #MON ao\011dormir na cama.\012O navio vai chegar\nenquanto você\011estiver dormindo.",
  ["1d:53c0"] = "Todos passageiros\nsão treinadores.\012Estão todos\nansiosos para\011batalhar em suas\011cabines.",
  ["1d:5412"] = "Nossa! Perdoe-me.\nEstava com pressa!\012Minha neta está\nperdida!\012Ela é apenas uma\ngarotinha. Caso\011a veja, venha me\011avisar!",
  ["1d:548d"] = "A BALSA SANTA AQUA chegou à\011CIDADE DE OLIVINE.",
  ["1d:54be"] = "A BALSA SANTA AQUA chegou à\011CIDADE DE VERMILION.",
  ["1d:5643"] = "Vou a KANTO testar\nminhas técnicas.",
  ["1d:5669"] = "Eu quis vencer!",
  ["1d:567b"] = "Treinadores de\nJOHTO podem\011batalhar com\011LÍDERES DE GINÁSIO\011DE KANTO.",
  ["1d:56b3"] = "Estou treinando\npara ser um\011CAMPEÃO!",
  ["1d:56d5"] = "O que nos difere\ntanto?",
  ["1d:56f7"] = "Um dia eu ainda\nvou vencê-lo!",
  ["1d:5716"] = "Você conhece LILY?\nÉ uma grande DJ\011em KANTO.",
  ["1d:5741"] = "Gyaaaah!",
  ["1d:574b"] = "LILY é boa, mas\nMARY é a melhor!\012Quero conferir\nos programas de\011rádio de JOHTO!",
  ["1d:5797"] = "Você está só?\nVamos batalhar\011então!",
  ["1d:57b9"] = "É muito serviço\npara mim!",
  ["1d:57d4"] = "Queria saber se\nhá alguma montanha\011boa de escalar em\011KANTO.",
  ["1d:5812"] = "Sim, sou um\nmarinheiro. Certo.\012Não estava à toa!\012Essa cabine estava\nvaga, então só\011tirei um rápido\011cochilo.\012Ah, esqueça!\nVamos batalhar!",
  ["1d:5897"] = "Perdão! É tudo\nculpa minha!",
  ["1d:58b1"] = "Para ser\nmarinheiro, tenho\011que usar a força.\011É exaustivo!",
  ["1d:58f1"] = "Oh, não. Perdi\nalgo que é muito\011importante.",
  ["1d:5923"] = "Eu… eu não\nposso achá-lo…",
  ["1d:5937"] = "Desisto. Você não\ntem que procurar.\011Apenas esqueça\011isso!",
  ["1d:5970"] = "Legal!\nSorte!",
  ["1d:5980"] = "Que azar!\nEu perdi!",
  ["1d:5996"] = "Achei uma linda\nmoeda aqui.\012Alguém deve tê-la\nperdido…",
  ["1d:5b04"] = "Vou a KANTO para\nfazer shows de\011sopro de fogo!",
  ["1d:5b38"] = "Ihh…A chama está\nfraca…",
  ["1d:5b52"] = "Acho que fogo é\nfraco no mar.\012Isso não importa?\nSério?",
  ["1d:5b8e"] = "Visitarei minha\navó para capturar\011insetos!",
  ["1d:5bbd"] = "Oh, uau. Você é\nforte!",
  ["1d:5bd5"] = "Você pode achar\nmuitos #MON\011nas árvores de\011JOHTO!",
  ["1d:5c07"] = "Estou tentando\nesquecer meus\011problemas. Vamos\011batalhar.",
  ["1d:5c32"] = "Meu coração\nsofre…",
  ["1d:5c43"] = "Viajar é ótimo\npara curar um\011coração partido.\012Mas a viagem na\nBALSA é\011curta para isso.",
  ["1d:5ca6"] = "Vou publicar\nminhas músicas na\011ESTAÇÃO DE RÁDIO\011DE GOLDENROD.",
  ["1d:5ce4"] = "Nossa!\nDistorção total!",
  ["1d:5cfe"] = "Eu ia fazer\nminha apresentação\011na TORRE DE\011BATALHA…\012Devo voltar\na VERMILION e\011refazer meu\011treinamento…",
  ["1d:5d65"] = "Falando na\nESTAÇÃO DE RÁDIO,\011qua é o número\011sortudo dessa\011semana?",
  ["1d:5da4"] = "Uma cama\nconfortável!\n\012Hora de dormir…",
  ["1d:5dc1"] = "Ah, refrescado e\ncurado!",
  ["1d:5dde"] = "A BALSA SANTA AQUA chegou\011à CIDADE DE OLIVINE.",
  ["1d:5e0f"] = "A BALSA SANTA AQUA chegou\011à CIDADE DE VERMILION.",
  ["1d:6012"] = "Uau! Obrigado por\nvir.\012Manter essa garota\nse divertindo\011foi exaustivo.",
  ["1d:6064"] = "O que acha\ndo passeio no\011S.S.AQUA?\012Ele praticamente\npatina nas ondas.",
  ["1d:60ae"] = "Oh, olá…\012Ainda não pude\nachar minha neta.\012Se ela estiver\nno navio, está\011ótimo.\012É uma garota\nenergética e deve\011estar atrapalhando\011alguém.\012Estou preocupado…",
  ["1d:6143"] = "{PLAYER}, não é?\n\012Soube que você\ndivertiu minha\011neta.\012Quero agradecê-lo\npor isso.",
  ["1d:619b"] = "Já sei! Eu\ngostaria que você\011levasse isso!",
  ["1d:61be"] = "Estamos viajando\naro redor do\011mundo.",
  ["1d:61e0"] = "CAPITÃO, brinque\ncomigo por favor?\012Estou com tédio.\nQuero brincar\011mais!",
  ["1d:621f"] = "Oi! Vai brincar\ncomigo?\012…Oh!\012Vovô está\npreocupado comigo?\012Tenho que ir!\012Tenho que achar\no vovô!",
  ["1d:6284"] = "Vovô, aqui estou!\nEstava brincando\011com o CAPITÃO e\011com esse rapaz!",
  ["1d:62c6"] = "Vovô, aqui estou!\nEstava brincando\011com o CAITÃO e\011com essa moçona!",
  ["1d:630d"] = "Diverti-me muito\nbrincando!",
  ["1d:6329"] = "Ei, garoto! Quer\nbatalhar comigo?",
  ["1d:634c"] = "Você é forte!",
  ["1d:635b"] = "Você está viajando\nsozinho?\012Sua mãe não está\npreocupada?",
  ["1d:638e"] = "Acha que sou um\nbebê? Não é justo!",
  ["1d:63b4"] = "Oh! Perdemos!",
  ["1d:63c2"] = "Bebê é um nome\nrude para nós\011garotas!",
  ["1d:63e9"] = "Não sou um bebê!\012Não é bom dizer\nisso a uma dama!",
  ["1d:641a"] = "Oh! Perdemos!",
  ["1d:6428"] = "Às vezes, garotos\nsão mais espertos\011que homens!",
  ["1d:6455"] = "Ssh! Meu cérebro\nestá captando\011sinas de rádio!",
  ["1d:6481"] = "…Eu ouvi algo!",
  ["1d:6497"] = "Já sei. Você pode\nouvir rádio de\011JOHTO na BALSA.",
  ["1d:64ce"] = "O que você acha?\nMeus #MON\011são lindos,\011certo?",
  ["1d:64fe"] = "Oh, não! Meus\nlindos #MON!",
  ["1d:651c"] = "Devo ir ao\nSALÃO #MON\011e consertar o\011visual deles!",
  ["1d:654f"] = "Vou comprar\nna LOJA DE\011DEPARTAMENTOS e\011então…",
  ["1d:657d"] = "O que eu ia\nfazer?",
  ["1d:6596"] = "Oh, sim! Tenho\nque buscar meus\011#MON no\011CRIATÓRIO!",
  ["1d:65c7"] = "Quais tipos de\n# BOLAS você\011tem aí?",
  ["1d:65f4"] = "Espere! Pare!\nNão! Por favor!",
  ["1d:660f"] = "Você deve usar\nas BOLAS certas\011para cada\011situação.",
  ["1d:6645"] = "A BALSA SANTA AQUA chegou à\011CIDADE DE VERMILION.",
  ["1d:687b"] = "Ei, garoto. Eu\npoderia lhe pedir\011para achar meu\011amigo?\n \012Ele está à\ntoa por aí,\011aquele vagabundo\011preguiçoso!\012Quero achá-lo,\nmas estou ocupado\011agora.",
  ["1d:6907"] = "Oh, nossa…\012O CAPITÃO ficará\nnervoso…",
  ["1d:692e"] = "Obrigado, garoto!\012Eu briguei com\nele para que não\011fique à toa!",
  ["1d:696d"] = "Uma garotinha?\012Eu devo tê-la\nvisto por aqui.",
  ["1d:699d"] = "A sala de jantar\né acima.\012As Escadas no\nfinal o levam à\011cabine do CAPITÃO.",
  ["1d:69ed"] = "Ninguém me vence\nquando estou no\011recreio.",
  ["1d:6a1a"] = "Vencendo ou não,\no recreio acabou!",
  ["1d:6a38"] = "Acho que não\nposso vencer sem\011ser sério.",
  ["1d:6a63"] = "Estou tão\nentediada. Quer\011batalhar?",
  ["1d:6a81"] = "Uau! Você é muito\nforte!",
  ["1d:6a99"] = "SAFFRON, CELADON…\nSoube que há\011várias cidades\011grandes em KANTO.",
  ["1d:6ad7"] = "Urrf…\nEstou enjoado!",
  ["1d:6aea"] = "Não posso me mover\nmais…",
  ["1d:6b02"] = "Chega de navios\npara mim. Na\011próxima vez irei\011de TREM ÍMÃ.",
  ["1d:6b40"] = "É aqui que\nnós marinheiros\011trabalhamos!",
  ["1d:6b60"] = "Perdi jogando\nem casa…",
  ["1d:6b7a"] = "Recebemos\ndiferentes\011passageiros da\011CIDADE DE VERMILION\011para a CIDADE\011OLIVINE.",
  ["1d:6bbc"] = "Embora estamos\nno mar, não posso\011pescar.\012Isso é chato!\nVamos batalhar!",
  ["1d:6c08"] = "Eu… não estou\nchateado mais…",
  ["1d:6c22"] = "Planejo pescar no\npíer de VERMILION.",
  ["1d:6c47"] = "Estou fortalecendo\nminhas pernas ao\011forçá-las contra\011o balanço do\011navio!",
  ["1d:6c85"] = "Não pude achar\no REI CARATÊ em\011JOHTO.\012Ele deve treinar\nem uma caverna em\011algum lugar.",
  ["1d:6c9e"] = "Não pude achar\no REI CARATÊ em\011JOHTO.\012Ele deve treinar\nem uma caverna em\011algum lugar.",
  ["1d:6cf9"] = "Sou um marinheiro!\012Mas estou\ntreinando\011#MON, daí\011posso ser o\011CAMPEÃO!",
  ["1d:6d3c"] = "Minha falta de\ntreino é óbvia…",
  ["1d:6d5f"] = "Oito INSÍGNIAS!\nElas provam que\011você derrotou\011os LÍDERES DE\011GINÁSIO. Você\011certamente é bom!",
  ["1d:6db6"] = "Não ponha um dedo\nem meus alunos!",
  ["1d:6dd9"] = "Aaack!",
  ["1d:6de1"] = "Estamos em\nexcursão para as\011RUÍNAS fora de\011VIOLET.",
  ["1d:6e14"] = "Você conhece as\nRUÍNAS ALFA?",
  ["1d:6e34"] = "Yaargh!",
  ["1d:6e3d"] = "Rádios recebem\nsinais estranhos\011nas RUÍNAS.",
  ["1d:6e6f"] = "Há muitos painéis\nestranhos nas\011RUÍNAS ALFA.",
  ["1d:6ea6"] = "Estava cansado!",
  ["1d:6eb6"] = "Eu li que há quatro\ndaqueles painéis\011de pedra.",
  ["1d:6faf"] = "A BALSA SANTA AQUA vai a\011KANTO às Segundas\011e às Sextas.",
  ["1d:701d"] = "A BALSA SANTA AQUA sai às Quartas e\011aos Domingos de\011toda semana.",
  ["1d:713b"] = "Shaoooh!",
  ["1d:71b3"] = "Quando o sol se\npõe, os CLEFAIRY\011saem para brincar.",
  ["1d:7260"] = "Shaoooh!",
  ["1e:433d"] = "Aqui é o local\ndo meu treino!",
  ["1e:435e"] = "Derrotado por um\nforasteiro!",
  ["1e:43d8"] = "Vou treinar ainda\nmais.\012Afinal, estou\ntentando me tornar\011um LÍDER DE\011GINÁSIO.",
  ["1e:4425"] = "Sou o melhor na\nminha sala em\011#MON.",
  ["1e:4447"] = "Não! Há treinado-\nres melhores…",
  ["1e:4469"] = "Treino duro, logo,\nposso ser o melhor\011em minha sala.",
  ["1e:449b"] = "Estou confiante em\nminha técnica de\011criar #MON?\012Quer ver?",
  ["1e:44d3"] = "Será que errei ao\ntreinar?",
  ["1e:44f0"] = "Talvez eu deva\nlevar um ao\011CRIATÓRIO #MON.\012Ou usar alguns\nitens…",
  ["1e:4532"] = "Comprar abaixo do\ncéu!\012É tão bom ficar na\ncobertura.",
  ["1e:456d"] = "Você é um\ntreinador?\012Vamos ter uma\nbatalha para\011praticar.",
  ["1e:459e"] = "Oh, não! Não\nposso vencer…",
  ["1e:45b8"] = "Você é muito forte\npara ser parceiro\011de luta.",
  ["1e:45e4"] = "Aonde vai?\nE o que pretende\011fazer?",
  ["1e:4609"] = "Você é poderoso,\ngarotinho.",
  ["1e:4624"] = "É, não vejo nada\nde errado hoje.\011Seja bom e fique\011longe de proble-\011mas.",
  ["1e:466a"] = "Estou patrulhando\nà busca de gente\011suspeita.",
  ["1e:4696"] = "Acabei de pegar\nmeu #MON do\011CRIATÓRIO.\012Vamos ver o quanto\nele fortaleceu!",
  ["1e:46e1"] = "Por que isso\nacabou assim?",
  ["1e:46fc"] = "Meus #MON\nsabiam golpes que\011eu não tinha\011ensinado.\012Isso me confundiu\ntodo!",
  ["1e:4743"] = "IRENE: Kyaaah!\nAlguém nos achou!",
  ["1e:4765"] = "IRENE: Ohh!\nMuito forte!",
  ["1e:477f"] = "IRENE: Minha irmã\nKATE o vencerá por\011isso!",
  ["1e:47ad"] = "IRENE: Essa praia\nnão é ótima?\012É o nosso refúgio\nsecreto!",
  ["1e:47eb"] = "JENN: Você não\npode vencer IRENE\011e ir impune!",
  ["1e:4819"] = "JENN: Perdão,\nIRENE! Irmã!",
  ["1e:4836"] = "JENN: Não se\norgulhe! Minha\011irmã KATE é forte!",
  ["1e:4866"] = "JENN: A luz solar\nfortalece seu\011corpo.",
  ["1e:4890"] = "KATE: Você foi\nmesmo rude com\011minhas irmãzinhas!",
  ["1e:48c0"] = "KATE: Não! Não\nacredito que\011perdi.",
  ["1e:48e2"] = "KATE: Você é muito\nforte. Nem tive\011chances.\012Ei. Você merece\nisso.",
  ["1e:492b"] = "KATE: Perdão por\nassustá-lo.\012Não esperávamos\nser achAdas por\011alguém aqui.\n \012Você nos assustou.",
  ["1e:49a8"] = "ROTA 34\012CIDADE DE GOLDENROD-\nCIDADE DE AZALEA.\012FLORESTA DE ILEX\nENTRE ALGUM LUGAR.",
  ["1e:49ed"] = "DICAS DO TREINADOR\012Crescem novas\nFRUTAS nas árvores\011todos dias.\012Lembre-se da FRUTA\nque cada árvore\011dá.",
  ["1e:4a52"] = "CRIATÓRIO #MON\012DEIXE-NOS CRIAR\nSEUS #MON!",
  ["1e:4fb6"] = "ELM: {PLAYER}!\nVocê está aí!\012Preciso de um\nfavor seu.\012Estou fazendo uma\nnova pesquisa\011#MON agora.\012Eu queria saber\nse você poderia\011me ajudar com\011ela, {PLAYER}.\012Veja…\012Estou escrevendo\num artigo que quero\011apresentar na\011conferência.\012Mas há muitas\ncoisas que não\011entendo bem ainda.\012Então!\012Quero que você\ntreine um #MON\011que capturei\011recentemente.\012Você aceita?",
  ["1e:50fa"] = "Obrigado, {PLAYER}!\012Você é uma grande\najuda!",
  ["1e:511a"] = "Mas… Eu preciso\nde sua ajuda!",
  ["1e:513a"] = "Quando anunciar\nminhas descober-\011tas, certamente\011nos aprofundaremos\011nos vários\011mistérios dos\011#MON.\012Você pode apostar!",
  ["1e:51ae"] = "Oh, ei! Recebi um\ne-mail!\012………\nHm… Opa…\012Certo…",
  ["1e:51df"] = "Ei, escute.\012Eu tenho um\nconhecido chamado\011SENHOR #MON.\012Ele descobre\ncoisas estranhas,\011delirando com as\011suas descobertas.\012De qualquer modo,\neu recebi um\011e-mail dele\011dizendo que dessa\011vez era verdade.\012Isto é incrível,\nmas estamos\011ocupados com nossa\011pesquisa #MON…\012Espere! Já sei!\012{PLAYER}, pode ir\npara nós?",
  ["1e:52ff"] = "Eu quero que\ntreine um dos\011#MON contidos\011nessas BOLAS.\012Você será o\nprimeiro parceiro\011deste #MON,\011{PLAYER}!\012Vá em frente.\nPegue um!",
  ["1e:5375"] = "Se um #MON\nselvagem surgir,\011deixe seu #MON\011batalhar com ele!",
  ["1e:53a7"] = "ELM: Espere!\nAonde está indo?",
  ["1e:53c8"] = "ELM: Você quer\no CYNDAQUIL, um\011#MON do tipo\011fogo?",
  ["1e:53f3"] = "ELM: Você quer\no TOTODILE, um\011#MON do tipo\011água?",
  ["1e:541f"] = "ELM: Então, gostou\nda CHIKORITA, um\011#MON grama?",
  ["1e:544d"] = "ELM: Pense com\ncuidado.\012Seu parceiro é\nmuito importante.",
  ["1e:5487"] = "ELM: Eu acho\nque é um ótimo\011#MON!",
  ["1e:54ad"] = "{PLAYER} received\n{STRBUF}!",
  ["1e:54c0"] = "O SENHOR #MON\nmora um pouco após\011CHERRYGROVE, a \011próxima cidade.\n \012Há uma rota que\nvai quase direto\011até lá, não tem\011erro.\012Caso qualquer\ncoisa, aqui está\011meu telefone.\012Ligue-me se algo\nacontecer!",
  ["1e:5581"] = "Se seu #MON\nse ferir, você\011deve curá-lo\011nessas máquinas.\012Você pode usá-la à\nvontade.",
  ["1e:55db"] = "{PLAYER}, eu estou\ncontando com você!",
  ["1e:55f3"] = "{PLAYER} obteve o\ntelefone de ELM.",
  ["1e:560d"] = "O SENHOR #MON\nvai à todo lugar\011e acha raridades.\012Pena que eles são\nraros porém pouco\011úteis…",
  ["1e:5668"] = "Contém um #MON\npego pelo\011PROFESSOR ELM.",
  ["1e:5690"] = "O que será que\nisso faz?",
  ["1e:56aa"] = "Você gostaria de\ncurar seus\011#MON?",
  ["1e:56cd"] = "ELM: {PLAYER}, isso\né terrível…\012Oh, sim, qual\nfoi a grande\011descoberta do\011SENHOR #MON?",
  ["1e:5712"] = "{PLAYER} entregou o\nOVO ESTRANHO ao\011PROFESSOR ELM.",
  ["1e:5739"] = "ELM: Isso?",
  ["1e:5745"] = "Mas… Isso é um\nOVO #MON?\012Se for, será uma\ngrande descoberta!",
  ["1e:5780"] = "ELM: O quê?!?\012O PROFESSOR\nCARVALHO te deu\011uma #DEX?\012{PLAYER}, é sério?\nQue incrível!\012Ele é bom\nem enxergar o\011potencial de\011pessoas como\011treinadoras.\012Uau, {PLAYER}.\nVocê deve ter o\011que precisa para\011se tornar um\011CAMPEÃO.\012Parece que você\nvai se dar bem\011com os #MON\011também.\012Você deve aceitar\no desafio dos\011GINÁSIOS #MON.\012O GINÁSIO mais\nperto seria o da\011CIDADE DE VIOLET.",
  ["1e:58cf"] = "A estrada até o\ncampeonato será\011longa.\012Antes de sair,\ncertifique-se de\011falar com sua mãe.",
  ["1e:593c"] = "ELM: Não desista!\nEu te ligarei se\011eu aprender algo\011sobre aquele OVO!",
  ["1e:597d"] = "ELM: {PLAYER}? Você\nnão encontrou meu\011assistente?\012Ele deveria\nte encontrar\011possuindo o OVO no\011CENTRO #MON\011da CIDADE DE VIOLET.\012Você deve não ter\nvisto ele. Tente\011achá-lo lá.",
  ["1e:5a1b"] = "ELM: Ei, o OVO\nteve alguma\011alteração?",
  ["1e:5a40"] = "{PLAYER}? Eu pensei\nque o OVO chocara.\012Onde está o\n#MON?",
  ["1e:5a72"] = "ELM: {PLAYER}, você\nparece ótimo!",
  ["1e:5a8b"] = "O quê?\nEsse #MON!?!",
  ["1e:5a9f"] = "O OVO chocou!\nEntão, os #MON\011nascem de OVOS…\012Não, talvez nem\ntodos os #MON.\012Uau, ainda há\nmuita pesquisa a\011ser feita.",
  ["1e:5b1c"] = "Obrigado, {PLAYER}!\nVocê está nos aju-\011dando a desvendar\011os mistérios dos\011#MON!\n\012Eu quero que você\nleve esse pre-\011sente nosso.",
  ["1e:5b8d"] = "É a PEDRETERNA.\012Muitas espécies de\n#MON evoluem\012quando alcançam\ncertos nçveis.\012Um #MON segu-\nrando a PEDRETER-\011NA não evolue.\012Dê isso ao #MON\nque não queira\011que evolua.",
  ["1e:5c37"] = "ELM: {PLAYER}, eu\nte ligarei se algo\011acontecer.",
  ["1e:5c65"] = "…poxa… Aquele\n#MON roubado.\012Como será que\nele estar?\012Dizem que um\n#MON treinado\012por genta má\nse torna igual.",
  ["1e:5cd0"] = "ELM: Oi, {PLAYER}!\nGraças a você, a\n \012pesquisa está\nótima!\012Eu quero que\naceite esse pre-\011sente meu.",
  ["1e:5d31"] = "A BOLA MESTRA é\na melhor!\012É a BOLA final! \nEla capturará\012qualquer #MON\nsem falhar.\012É dada apenas a\nfamosos pesquisa-\011dores #MON.\012Acho que você\npode fazer melhor\012uso dela que\neu, {PLAYER}!",
  ["1e:5df3"] = "ELM: {PLAYER}!\nAí está você!\012Liguei porque eu\ntenho algo para\011você.\n \012Vê? É uma PASSAGEM\nde navio.\012Agora pode captu-\nrar #MON em\011KANTO.",
  ["1e:5e6f"] = "O navio parte da\nCIDADE DE OLIVINE.\012Você já sabia\ndisso, {PLAYER}.\012Aliás, você\nviajou por tudo\011com seu #MON.\012Dê meus cumprimen-\ntos ao PROFESSOR\011CARVALHO em KANTO!",
  ["1e:5f38"] = "{PLAYER}, eu quero\nque tenha isso\011para sua missão.",
  ["1e:5f65"] = "Há apenas dois de\nnós, então estamos\011sempre ocupados.",
  ["1e:5f95"] = "Havia um barulho\nlá fora…\012Quando fomos\nolhar, alguém\011roubou um #MON.\012É inacreditável\nque alguém tenha\011feito aquilo!\012…poxa… Aquele\n#MON roubado.\012Como ele deve\nestar.\012Dizem que um\ntreinado por\012gente má se\ntorna igual.",
  ["1e:6078"] = "{PLAYER}!\012Use estas na sua\nmissão da #DEX!",
  ["1e:609a"] = "Para preencher sua\n#DEX, você deve\011capturar #MON.\012Jogue # BOLAS\nnos #MON sel-\011vagens para pegá-\011los.",
  ["1e:60f0"] = "Soube que um POKé-\nMON foi roubado\011aqui…\012Eu estava colhendo\ninformações do\011PROFESSOR ELM.\012Aparentemente, foi\num jovem rapaz de\011longos cabelos\011rubros…\012O quê?\012Você batalhou com\num treinador\011assim?\012Você conhece o\nnome dele?",
  ["1e:61c0"] = "Certo! Então\n{RIVAL} era o\011nome dele.\012Obrigado por aju-\ndar minha investi-\011gação!",
  ["1e:61fd"] = "A janela está\naberta.\012Uma boa brisa\nestá soprando.",
  ["1e:6231"] = "Ele quebrou por\naqui!",
  ["1e:624c"] = "{PLAYER} abriu um\nlivro.\012Dica de Viagem 1:\012Aperte START para\nabrir o MENU.",
  ["1e:628a"] = "{PLAYER} abriu um\nlivro.\012Dica de Viagem 2:\012Grave sua viagem\ncom o SALVAR!",
  ["1e:62c6"] = "{PLAYER} abriu um\nlivro.\012Dica de Viagem 3:\012Abra sua BOLSA e\naperte SELECT para\011mover itens.",
  ["1e:6315"] = "{PLAYER} abriu um\nlivro.\012Dica de Viagem 4:\012Cheque os golpes\nde seu #MON.\012Aperte o botão A\npara mover golpes.",
  ["1e:6370"] = "OBSERVAÇÕES NA\nEVOLUÇÃO #MON\012…Está dito na\ntela…",
  ["1e:63a6"] = "ELM: Então gostou\nda CHIKORITA, um\011#MON do tipo\011grama?",
  ["1e:6604"] = "Oh, {PLAYER}…!\nNosso vizinho,\011PROFESSOR ELM,\011procurava por\011você.\012Ele disse que\nqueria um favor\011seu.\012Oh! Eu quase me\nesqueci!\012Sua #MON GEAR \nchegou da oficina \011de reparos. Aqui\011está ela!",
  ["1e:66bd"] = "#MON GEAR, ou\napenas #GEAR.\012É essencial se\nvocê quiser ser um\011bom treinador.\012Oh, o dia da sema-\nna não está\011ajustado.\012Não deve esquecer\nisto!",
  ["1e:6742"] = "Nós estamos no\nHORÁRIO DE VERÃO?",
  ["1e:6763"] = "Volte depois para\najustar seu\011relógio para o\011HORÁRIO DE VERÃO.\012A propósito, você\nsabe usar o\011CELULAR?",
  ["1e:67cb"] = "Apenas ligue sua\n#GEAR e escolha\011o ícone do CELU-\011LAR.",
  ["1e:6807"] = "Eu lerei as\ninstruções.\012Ligue a #GEAR\ne selecione o ícone\011do CELULAR.",
  ["1e:6850"] = "Os telefones\nficarão guardados\011na memória.\012Apenas escolha a\npessoa desejada.\012Nossa, não é\nsimples?",
  ["1e:68b5"] = "O PROFESSOR ELM\nestá te esperando.\012Apresse-se,\nquerido(a)!",
  ["1e:68e5"] = "Então, o que o PROFESSOR ELM queria?\012…\012Isso parece bem\ndesafiador.\012 Mas, deve se\norgulhar pois as\011pessoas confiam\011em você.",
  ["1e:6957"] = "{PLAYER}, faça-o!\012Sempre estarei\npor perto!",
  ["1e:697d"] = "Bom dia,\n{PLAYER}!\012Eu estou visitando!",
  ["1e:699c"] = "Oi, {PLAYER}!\nEstou visitando!",
  ["1e:69b4"] = "Boa noite, {PLAYER}!\012Estou visitando.",
  ["1e:69d3"] = "{PLAYER}, já soube?\012Minha filha sonha\nem ser assistente\011do PROFESSOR ELM.\012Ela realmente ama\nos #MON!",
  ["1e:6a3a"] = "Especialidade da\nMamãe!\012HAMBURGER VULCÃO\nCINNABAR!",
  ["1e:6a64"] = "O fogão está\nlimpinho. Mamãe\011adora limpeza.",
  ["1e:6a91"] = "Vamos ver o que\nhá na geladeira…\012ÁGUA FRESCA e\nLIMONADA GOSTOSA!",
  ["1e:6ad0"] = "Há um filme na TV:\nEstrelas surgem\011no céu enquanto\011dois garotos andam\011de trem…\012É melhor eu ir\ntambém!",
  ["1e:6c24"] = "O lixo do lanche\ndo PROFESSOR ELM\011está ali…",
  ["1e:6c55"] = "CANAL #MON!",
  ["1e:6c64"] = "Aqui é a DJ MARY,\nsua co-anfitriã!",
  ["1e:6c84"] = "#MON\nCANAL #MON…",
  ["1e:6d2f"] = "O PIKACHU é um\n#MON evoluído.\012As descobertas do\nPROFESSOR ELM me\011fascinam.\012Ele é tão famoso\npor suas pesquisas\011na evolução\011#MON.\012…poxa…\012Gostaria de ser\numa pesquisadora\011como ele…",
  ["1e:6dd4"] = "Minha filha sonha\nem ser assistente\011do PROFESSOR ELM.\012Ela realmente ama\nos #MON!\012Mas por enquanto,\neu ajudo-o!",
  ["1e:6e3b"] = "SHOW DO CARVALHO!\nSintonize na\011próxima vez!",
  ["1e:6e6c"] = "CANAL #MON!",
  ["1e:6e7b"] = "Essa é sua\nco-apresentadora,\011DJ MARY!",
  ["1e:6e9b"] = "#MON!\nCANAL #MON…",
  ["1e:6ef7"] = "Oi, {PLAYER}! Meu\nmarido vive muito\011ocupado… Espero\011que ele esteja OK.\012Quando ele se\nempolga com suas\011pesquisas #MON,\011ele esquece até\011de comer.",
  ["1e:6f6b"] = "Quando eu crescer,\nvou ajudar o meu\011Pai!\012Vou ser um grande\nprofessor #MON!",
  ["1e:701b"] = "#MON. De onde\neles vêm?\012Para onde eles\nvão?\012Por que ninguém\nnunca testemunhou\011o nascimento de um\011#MON?\012Eu quero saber!\nVou dedicar minha\012vida para estudar\nos #MON!\012…\012É um trecho dos\nartigos de\011pesquisa do\011PROFESSOR ELM.",
  ["1e:714d"] = "Seus #MON\nparecem estar\011cansados.\012Você deve dar um\ndescanso a eles.",
  ["1e:718b"] = "Pronto!\012Seus #MON\nparecem bons!\012Continue assim!",
  ["1e:71f9"] = "Há algo escrito\naqui.\012Deseja ler?",
  ["1e:7222"] = "Aos meus irmãos e\nirmãs:\012Temos orgulho\nem servir\011os treinadores\011#MON.\012Quando eles\nconversarem com\011você, dê-lhes\011algo útil.\012Com amor, MÔNICA\012Continuar lendo?",
  ["1e:72b9"] = "Segunda, MÔNICA\nROTA 40\012Terça, TUSCANY\nROTA 29\012Quarta, WESLEY\nLAGO DA FÚRIA\012Quinta, ARTHUR\nROTA 36\012Sexta, FRIEDA\nROTA 32\012SáBado, SANTOS\nVILA BLACKTHORN\012Domingo, SUNNY\nROTA 37.",
  ["1e:73c6"] = "Aonde está indo\ncom os #MON?\012LIGA #MON?\012Seus #MON são\nleais a você o\011bastante para\011vencerem?\012Deixe-me ver…",
  ["1e:742b"] = "Ah! Seus #MON\nconfiam muito em\011você.\012É ótimo ver um\nbom treinador.\012Ei. Eis um\npresente para sua\011jornada.",
  ["1e:748f"] = "O TM37 é o AREIAL.\012É um golpe que\ncausa danos\011em ambos\011batalhadores.\012É apenas\npara treinadores\011avançados.\012Use-o se tiver\ncoragem.\012Boa sorte!",
  ["1e:751f"] = "Se não confiarem\nmais pouco em\011você, vai ser\011difícil ganhar.\012Confiança é o laço\nque une #MON\011a treinadores.",
  ["1e:75c1"] = "Você não pode\nsubir as beiras.\012Mas você pode\npulá-las para\011pegar um atalho.",
  ["1e:760d"] = "Diferentes tipos\nde #MON\011aparecem por aqui.\012Se quiser\ncapturá-los, terá\011que procurar em\011todos lugares.",
  ["1f:4005"] = "LIGA #MON\012ROTA DA VITÓRIA\nENTRADA.",
  ["1f:4314"] = "NÃO É PERMITIDO A\nENTRADA A PARTIR\011DESTE PONTO.",
  ["1f:4361"] = "…Droga…",
  ["1f:436c"] = "Acho que eu devo\nfazer as coisas\011justamente…",
  ["1f:439a"] = "Você leva os tipos\nem consideração\011nas batalhas?\012Se você souber das\nvantagens de seu\011tipo, irá melhor\011nas batalhas.",
  ["1f:4403"] = "Ei, ei, ei!",
  ["1f:4410"] = "Eu conheço bem o\ntipo do meu\011#MON.\012Mas eu uso apenas\num tipo de\011#MON.",
  ["1f:4452"] = "Meu #MON acabou\nde cortar o\011cabelo.\012Vou mostrá-lo sua\nforça!",
  ["1f:448e"] = "Aiyeeee!",
  ["1f:4498"] = "Seus #MON\ngostarão mais de\011você se lhes\011cortar o cabelo.",
  ["1f:44d1"] = "Acho que você tem\nalguns #MON\011raros.\012Deixe-me vê-los!",
  ["1f:450d"] = "Gaah! Perdi! Isso\nme enlouquece!",
  ["1f:452f"] = "Você está\npreenchendo a\011#DEX? Aqui vai\011uma dica.\012O ANDARILHO da\nROTA 33, ANTHONY,\011é um bom rapaz.\012Ele te ligará se\nvir algum #MON\011raro.",
  ["1f:45b0"] = "A porta está\ntrancada…",
  ["1f:45c3"] = "A porta está\naberta.",
  ["1f:45d6"] = "A CHAVE PORÃO\nabriu a porta.",
  ["1f:45f9"] = "Bem-vindo!\012Eu comando o SALÃO\n#MON!\012Sou o mais velho\ne melhor dos\011dois IRMÃOS\011CABELEIREIROS.\012Posso deixar seus\n#MON bonitos\011por apenas ¥500.\012Gostaria que eu\nfizesse isso?",
  ["1f:469a"] = "Em qual #MON\neu devo trabalhar?",
  ["1f:46b8"] = "Certo! Veja-o\nficando bonito!",
  ["1f:46d8"] = "Veja! Está pronto!",
  ["1f:46ea"] = "Está certo?\nQue vergonha!",
  ["1f:4709"] = "Precisa ter mais\ndinheiro que isso.",
  ["1f:472b"] = "Faço apenas um\ncorte de cabelo ao\011dia.\012Já o fiz hoje.",
  ["1f:475c"] = "Bem vindo ao SALÃO\n#MON!\012Sou o mais jovem e\nmenos caro dos\011dois IRMÃOS\011CABELEIREIROS.\012Farei o serviço em\nseu #MON por\011apenas ¥300.\012Então? O que acha?",
  ["1f:47f1"] = "Certo, em qual\n#MON devo\011trabalhar?",
  ["1f:480e"] = "Certo! Vou\ndeixá-lo com um\011ótimo visual!",
  ["1f:482a"] = "Está escrito\nBOTÃO 3.",
  ["1f:4842"] = "Não? Que\ndesapontamento!",
  ["1f:485b"] = "Você está com\npouco dinheiro.",
  ["1f:487b"] = "Posso fazer apenas\num corte de cabelo\011ao dia.\012Perdão, mas já o\nfiz hoje.",
  ["1f:48bf"] = "{STRBUF} parece\nestar mais feliz",
  ["1f:48dc"] = "{STRBUF} está\nfeliz.",
  ["1f:48ee"] = "{STRBUF} está\nmuito alegre!",
  ["1f:4904"] = "Não estamos abertos\nhoje.",
  ["1f:491a"] = "…Por quê…\nPor que perdi?\012Eu reuni os mais\nfortes #MON.\012Eu não facilitei.\012Então por que eu\nperdi?",
  ["1f:4e9d"] = "Espere!\012Eu o vi,\nentão quis\011interrompê-lo.\012Não preciso de\nvocê no meu pé\011enquanto eu cuido\011da EQUIPE ROCKET…\012Só um segundo.\012Você me derrotou\nantes, não foi?\012Foi pura sorte.\012Mas pagarei meus\ndébitos!",
  ["1f:4f5d"] = "…Por quê…\nPor que perdi?\012Eu reuni os mais\nfortes #MON.\012Eu não facilitei.\012Então por que eu\nperdi?",
  ["1f:4fc2"] = "…Eu não entendo…\012Será que LANCE\ndisse a verdade?\012Que eu não trato\nos #MON\011corretamente?\012Amor…\012Confiança…\012São essas coisas\nque faltam?\012Elas que estão me\nprivando da\011vitória?\012Eu… Eu não\nentendo.\012Mas isso não vai\nacabar aqui.\012Não agora.\nNão devido a isso.\012Não desistirei\ndo meu sonho de\011tornar-me o melhor\011treinador #MON\011do mundo!",
  ["1f:5102"] = "Humph. Esse é meu\nverdadeiro poder,\011bobo.\012A EQUIPE ROCKET\nserá passado.\012E eu vou triturar\no LANCE com meu\011calcanhar.",
  ["1f:5176"] = "Fui desafiado para\nbatalhar aqui\011abaixo.\012É perigoso ir lá.\nTenha muito\011cuidado.",
  ["1f:51d0"] = "Há muitas lojas\nlá embaixo…\012Mas há treinadores\ntambém.\n\012Estou com medo de\nir lá.",
  ["1f:522b"] = "Abra uma persiana\ne a outra fechará.\012Aposto que você\nnão chegará aonde\011quer!",
  ["1f:526f"] = "Droga! Fui derro-\ntado pela dúvida!",
  ["1f:5290"] = "Estou confuso\ntambém…\nO botão no final é\011o primeiro a ser\011apertado, mas…",
  ["1f:52d8"] = "Hahahah!\012As persianas estão\nnos confundindo,\011né?\012Vou te contar um\nsegredo se você\011me derrotar!",
  ["1f:5335"] = "Uwww…\nEu perdi.",
  ["1f:5347"] = "Certo. Uma dica!\012Mude a ordem dos\nbotões.\012Isso mudará o\nmodo em que as\011persianas abrem\011e fecham.",
  ["1f:53ae"] = "Vou roubar seus\nbens!",
  ["1f:53c7"] = "Piedade!",
  ["1f:53cf"] = "Roubar e vender.\nIsso é o básico do\011crime, garoto!",
  ["1f:53fb"] = "Eles abandonaram\nesse projeto antes\011de terminá-lo.\011Estou saqueando as\011sobras.",
  ["1f:544c"] = "Sobre o topo!",
  ["1f:545b"] = "DEPÓSITO DO\nSUBTERRÂNEO?\012Para que você quer\nir lá?\012Não tem nada lá\nembaixo.",
  ["1f:54b2"] = "Eu não me importo\nse você está\011perdido.\012Chegou até aqui,\nmas não passa de\011uma vítima!",
  ["1f:54fc"] = "Urk! É, acho que\nvocê é legal!",
  ["1f:551f"] = "Você deve ter\ngelo nas veias\011para destruir a\011EQUIPE ROCKET.",
  ["1f:5554"] = "Você está perdido?\nNão, é impossível.\012Tu não tens aquela\nface assustada.\012Vou lhe dar\nalgo que vai\011assustá-lo!",
  ["1f:556b"] = "Você está perdido?\nNão, é impossível.\012Tu não tens aquela\nface assustada.\012Vou lhe dar\nalgo que vai\011assustá-lo!",
  ["1f:55d6"] = "Como pôde?",
  ["1f:55e6"] = "Vá aonde quiser!\nSaia daqui!\012Eu nem ligo, viu!",
  ["1f:5617"] = "Está DESLIGADO.\nDeseja LIGÁ-LO?",
  ["1f:562d"] = "Está escrito\nBOTÃO 2.",
  ["1f:5643"] = "Está LIGADO.\nDeseja DESLIGÁ-LO?",
  ["1f:565a"] = "Está escrito\nBOTÃO 2.",
  ["1f:5671"] = "Aqui está!\nTudo pronto.",
  ["1f:57cb"] = "Eu perco a paixão\npelo trabalho se\011alguém me vê.\012Vamos garoto,\nfora!",
  ["1f:582c"] = "Oohah! Oohah!\012O negócio no chão\né um lixo.\012Pegue-o se\ndesejar!",
  ["1f:5875"] = "MACHOKE: Maaacho!",
  ["1f:58bb"] = "MACHOKE: Maaacho!",
  ["1f:59ea"] = "Como chegou aqui?\012Eu achei que isso\nnão aconteceria.\011Vou liquidá-lo.",
  ["1f:5a34"] = "Eu fui liquidá-lo…",
  ["1f:5a48"] = "A EQUIPE ROCKET\ncontinuará,\011esperando pelo\011retorno do\011GIOVANNI.\012Vamos fazer o que\nfor preciso.",
  ["1f:5aa7"] = "Você não vai tão\nlonge!\012Não tenho piedade\nde meus inimigos,\011mesmo sendo um\011pirralho.",
  ["1f:5af6"] = "Que estouro!",
  ["1f:5b01"] = "Eu perdi…\012Perdoe-me\nGIOVANNI!",
  ["1f:5b27"] = "Lá-lá-lá-lá!\nLembro-me de você!\012Humilhou-me no\nesconderijo!",
  ["1f:5b6b"] = "Lá-lá-lá-lá!\nEntão é assim?",
  ["1f:5b8e"] = "Lá-lá-lá-lá!\nIsso foi uma\011explosão!\012Lembrar-me-ei de\nvocê!",
  ["1f:5bc6"] = "DIRETOR: Quem?\nO quê? Você veio\011me resgatar?\012Obrigado!\012A TORRE DE RÁDIO!\012O que está havendo\naqui?\012Dominados pela\nEQUIPE ROCKET?\012Ei. Leve este\nCARTÃO.",
  ["1f:5c5b"] = "DIRETOR: Use isso\npara abrir as\011persianas no 3ª\011ANDAR.",
  ["1f:5c8d"] = "Estou implorando\npela sua ajuda.\011Nem quero dizer\011o que ocorrerá se\011eles controlarem\011o transmissor.\012Podem até\ncontrolar #MON\011usando um sinal\011especial!\012Você é o único com\nquem eu posso\011contar.\012Por favor salve a\nTORRE DE RÁDIO…\012E toda a nação\n#MON!",
  ["1f:5e8d"] = "Não perderei desta\nvez!",
  ["1f:5ea7"] = "Perdi para um\ngaroto…?",
  ["1f:5ebd"] = "Agora mesmo, um\ncarateca quis\011batalhar.\012Ele era\nincrivelmente bom.\012Ele simplesmente\nnos fez de bobo.\012Ele seguiu em\nfrente dizendo\011que era para seu\011treinamento.\012Como deve ser?",
  ["1f:5f6a"] = "Ei! HUGH!",
  ["1f:5f76"] = "Eu te confundi\ncom alguém…",
  ["1f:5f97"] = "Eu vim explorar a\nMONTANHA MORTEIRO,\011mas me separei de\011meu parceiro…\012Você viu um\ntreinador que\nusa um SEADRA\011que conhece o\011CACHOEIRA?",
  ["1f:60ed"] = "Ei! MARKUS!",
  ["1f:60fa"] = "Perdão, me\nconfundi.",
  ["1f:610e"] = "Estou investigando\na MONTANHA\011MORTEIRO, mas meu\011amigo sumiu.\012Você viu um\ntreinador que teu\011um SLOWPOKE que\011pode usar SUPERFORÇA?",
  ["1f:624d"] = "Ei!\012Eu sou o REI\nCARATÊ!\012Treino sozinho\naqui no escuro!\012Você! Batalhe\ncomigo!\012Hwaaarggh!",
  ["1f:62a9"] = "Waaaarggh!\nFui derrotado!",
  ["1f:62c0"] = "Fui… fui esmagado…\012Meu treinamento\nainda não é o\011bastante.\012Mas derrota é\nderrota.\012Eu admito.\012Como prova de\nque me derrotou,\011lhe darei um raro\011#MON lutador.",
  ["1f:6355"] = "{PLAYER} recebeu\nTYROGUE.",
  ["1f:636a"] = "TYROGUE é do\ntipo lutador.\012Ele evolui em\n#MON mais\011fortes.\n\012Continue treinando\nduro. Continuarei\011treinando também.\012Adeus!",
  ["1f:63df"] = "Não tem espaço na\nsua equipe!",
  ["1f:6512"] = "Hã? Meus próprios\nolhos me\011enganaram?",
  ["1f:65ad"] = "Está todo\nimobilizado no\011gelo.",
  ["1f:66bd"] = "Ao norte de\nLAVENDER está o\011TÚNEL DE ROCHA.\011Atravesse-o para\011chegar à USINA ELÉTRICA.",
  ["1f:6710"] = "O DIRETOR da\nESTAÇÃO DE RÁDIO\011certamente es-\011tava feliz.\012Ele disse que a\ntransmissão voltou\011porque a USINA ELÉTRICA voltou\011a funcionar\011corretamente de\011novo.",
  ["1f:6779"] = "Há um programa de\nrádio que toca a\011musica da #\011FLAUTA.\012Oh! Seu rádio\nnecessita do\011CARTÃO EXPANSÃO\011para sintonizá-la.",
  ["1f:67ed"] = "Se a USINA ELÉTRICA não\011funcionasse, o\011TREM IMÃ também\011não funcionaria…\012Isso também\nsignifica que\011a TORRE DE RÁDIO\011não poderia\011realizar transmis-\011sões…",
  ["1f:68f1"] = "O SENHOR FUJI mora\naqui, mas não está\011agora.\012Deve estar\nna CASA DA ALMA.",
  ["1f:6940"] = "Umas pessoas de\ncoração ruim\011pararam de cuidar\011de seus #MON.\012O vovô pega os\npobres #MON\011sem casa e cuida\011deles.",
  ["1f:69b6"] = "PSYDUCK: Gu-guwa?",
  ["1f:69c9"] = "NIDORINO: Gyun!",
  ["1f:69da"] = "PIDGEY: Pijji!",
  ["1f:6a4d"] = "LAVENDER é uma\npequena e quieta\011cidADe no pé das\011montanhas.\012Ficou mais agitada\ndesde a construção\011da TORRE DE RÁDIO.",
  ["1f:6b29"] = "O REPELENTE é\nnecessário se você\011for explorar uma\011caverna.\012Apesar de gostar\nde explorar, eu\011ainda não o fiz\011em todas as\011cavernas.",
  ["1f:6bac"] = "Soube de um\nartesão que faz\011BOLAS sob medida\011na CIDADE DE AZALEA\011de JOHTO.\012Eu queria ter\numas.",
  ["1f:6c53"] = "SENHOR FUJI:\nBem-vindo.\012Hmm… Você\nparece criar\011seus #MON de\011maneira gentil e\011amável.\012Amantes de\n#MON vêm aqui\011para prestar\011homenagens aos\011#MON mortos.\012Por favor, ofereça\ncondolências às\011almas dos #MON\011mortos.\012Tenho certeza que\nisso vai deixá-las\011felizes.",
  ["1f:6d4d"] = "Há outras covas\nde #MON aqui,\011eu acho.\012Há várias câmaras\nem que só o SENHOR\011FUJI pode entrar.",
  ["1f:6db1"] = "Vim com minha\nmãe para visitar\011covas de #MON…",
  ["1f:6ddb"] = "Os #MON que\nviveram comigo…\012Eu gosto deles\ncomo meus netos…",
  ["1f:6ebf"] = "Bem-vindo!\nFique à vontade\011para checar todo\011esse andar.",
  ["1f:6efa"] = "Perdão, mas você\nsó pode visitar o\011andar de baixo.\012Desde que a TORRE\nDE RÁDIO de JOHTO\011foi dominada por\011uma gangue\011criminosa, temos\011reforçado nossa\011segurança.",
  ["1f:6f90"] = "Várias pessoas\ntrabalham duro na\011TORRE DE RÁDIO.\012Devem dar\nseu melhor para\011transmitir bons\011shows.",
  ["1f:6ffb"] = "Oh, não, não, não!\012Estivemos fora\ndo ar desde que a\011USINA ELÉTRICA\011parou.\012Todo meu Esforço\npara iniciar essa\011estação seria\011inútil se eu não\011transmitisse.\012Estaria arruinado!",
  ["1f:70a1"] = "Ah! Então foi\nvocê {PLAYER} quem\011resolveu o\011problema da USINA\011ELÉTRICA?\012Graças a você,\nnão perdi meu\011trabalho.\012E lhe digo,\nsalvou minha vida!\012Leve isso como\nagradecimento.",
  ["1f:7141"] = "Com isso, poderá\nsintonizar nos\011programas de rádio\011daqui de KANTO.\012Hahahaha!",
  ["1f:7193"] = "Olá!\n \012Sou o super\nDIRETOR de MÚSICA!\012Hã? Sua #GEAR\nnão sintoniza\011nos meus programas\011de música. Que\011má sorte!\012Se atualizá-la\ncom o CARTÃO\011EXPANSÃO, poderá\011sintonizar.\012É melhor\natualizá-la!",
  ["1f:7248"] = "Olá!\n \012Sou o super\nDIRETOR de MÚSICA.\011Sou o responsável\011pelas belas\011melodias que vão\011ao ar.\012Não seja careta.\nSintonize em\011nossas músicas!",
  ["1f:72e3"] = "1ª ANDAR-RECEPÇÃO\n2ª-VENDAS\0123ª-PESSOAL\n4ª-PRODUÇÃO\0125ª ESCRITÓRIO DO\nDIRETOR.",
  ["1f:732d"] = "Desperte #MON\nCom o Alegre Som\011da # FLAUTA no\011Canal 20.",
  ["1f:7419"] = "Já foi à\nCIDADE DE LAVENDER?\012Há uma alta\nTORRE DE RÁDIO lá.",
  ["1f:74af"] = "Sou o irmão mais\nnovo do GURU DA\011PESCA.\012Vejo que você\ngosta de pescar.\012E não tenho a\nmenor dúvida\011disso!\012Então? Sei que\nacertei.",
  ["1f:752f"] = "Sim, sim. Como\neu pensei!\012Ei, fã da pesca!\nLeve isso, é a\011SUPER VARA.",
  ["1f:757c"] = "Tente pescar em\nqualquer lugar\011que tenha água.\012Lembre-se,\nvocê pode\011capturar #MON\011diferentes usando\011VARAS diferentes.",
  ["1f:75ec"] = "Está escrito\nEMERGÊNCIA.",
  ["21:652c"] = "New Hall of Famer!",
  ["21:66fc"] = "Mestre do Hall da\nFama!",
  ["21:670c"] = "    -Time Famer",
  ["24:423c"] = "Hã? Perdão, número\nerrado!",
  ["24:465b"] = "Esse número está\nfora da área.",
  ["24:4664"] = "Vá falar pessoal-\nmente com essa\011pessoa!",
  ["26:40d1"] = "A TORRE DO SINO\nestá fora do\011alcance de quem\011não tem a INSÍGNIA\011DO GINÁSIO DE\011ECRUTEAK.\n\012Você terá que\nsair.",
  ["26:4131"] = "A TORRE DO SINO\nestá fora do\011alcance de quem\011não tem a INSÍGNIA\011DO GINÁSIO DE\011ECRUTEAK.\012Oh! A INSÍGNIA\nDO GINÁSIO DE\011ECRUTEAK!\012Você pode ir.",
  ["26:41a4"] = "Ocorreu algo\nmuito importante.\011Peço-lhe perdão,\011mas devo pedi-lo\011para sair.\012…O que acalma\na alma…\012O TRIO DE SÁBIOS\ndiz coisas muito\011difíceis de\011entender…",
  ["26:4250"] = "Ocorreu algo\nmuito importante.\011Peço-lhe perdão,\011mas devo pedi-lo\011para sair.\012………\012Ah!\012O som do SINO\nPURO!\012É… É sublime!\012Eu nunca tinha\nouvido um som tão\011bonito.\012O som desse sino\né o indicador da\011alma do portador.\012Você…\012Você pode ir para\na TORRE DO SINO.\012Siga em frente.",
  ["26:437e"] = "Siga em frente.",
  ["26:4391"] = "O som desse sino\né o indicador da\011alma do portador.\012Você…\012Você pode ir para\na TORRE DO SINO.\012Siga em frente.",
  ["26:440b"] = "A TORRE ESTRAHA\nadiante é uma\011torre de 9 andares\011de beleza.\012Ela acalma a alma\nde todos que a\011vêem.",
  ["26:446f"] = "A TORRE DO SINO\ntremeu. Um #MON\011deve ter retornado\011ao topo!",
  ["26:44ab"] = "Duas torres…\nDois #MON…\012Mas quando uma\nqueimou, ambos\011#MON foram\011embora e nunca\011retornaram.",
  ["26:462b"] = "Minha nossa…\012SUICUNE, ENTEI e\nRAIKOU despertaram\011de seus sonos…\012A lenda está se\nrealizando?",
  ["26:468b"] = "Nós treinamos na\nTORRE QUEIMADA,\011mas nunca soubemos\011que havia um\011buraco aberto lá.\011Deve ter sido\011feito proposital-\011mente por alguém.",
  ["26:4712"] = "Só aqueles que\npossuem a INSÍGNIA\011DO GINÁSIO DE\011ECRUTEAK podem\011entrar na TORRE\011ESTRANHA.\n\012Porém, agora que\nSUICUNE, RAIKOU e\011ENTEI surgiram,\011peço-lhe para não\011entrar!",
  ["26:47af"] = "Nós, o TRIO DE\nSÁBIOS, somos\011os protetores\011dos #MON\011lendários.",
  ["26:47ed"] = "A lenda diz que,\nem caso de\011emergência, se um\011treinador tiver a\011habilidade de\011tocar almas de\011#MON, um\011#MON virá em\011seguida para pôr\011esse treinador em\011teste na TORRE\011ESTRANHA.\012A lenda está se\nrealizando!\012O #MON lendário\nSUINCUNE chegou!\012Nós, o TRIO DE\nSÁBIOS, vamos\011testar seus\011méritos para você\011entrar!",
  ["26:4914"] = "Mais forte do que\npensávamos?\011Talvez…",
  ["26:4938"] = "Ah, então é você\nquem afirma ter\011visto SUICUNE,\011ENTEI e RAIKOU\011enquanto eles\011dormiam?\012Inacreditável!\012A lenda diz que\neles não podem\011ser vistos\011enquanto dormem…",
  ["26:49d2"] = "Você pode ser\nconfiado com a\011verdade?\012Eu devo averiguar\nseus méritos…",
  ["26:4a18"] = "…Vou lhe contar a\nverdade…",
  ["26:4a35"] = "No passado, havia\nduas torres de\011nove andares aqui.\012A TORRE DE LATÃO,\nque foi dita ter\011acordado os\011#MON, e a\011TORRE DO SINO,\011onde os #MON\011descansavam, como\011diziam.\012A visão do topo\ndas TORRES devia\011ser incrível.\012Naquela época,\ndizia-se que um\011#MON imenso e\011cinza usava o topo\011da TORRE DE LATÃO\011como seu poleiro.\012Porém…\012Há uns 150 anos,\numa faísca de\011relâmpago golpeou\011uma das TORRES.\012Ela foi tomada\npelas chamas que\011queimaram por três\011dias.\012Um aguaceiro\nrepentino final-\011mente apagou as\011chamas.\n \012É assim que surgiu\na TORRE QUEIMADA.",
  ["26:4c42"] = "Deixe-me ver seu\npoder!",
  ["26:4c5a"] = "Forte demais!\nPor quê?",
  ["26:4c6c"] = "Você… É você o\ntreinador que é\011esperado pelos\011#MON lendá-\011rios?",
  ["26:4cac"] = "Eu entendo…\012A nós, o TRIO DE\nSÁBIOS, foi dada\011a responsabilidade\011de proteger\011os #MON\011lendários.\012Só podemos\npermitir a\011passagem daquelas\011pessoas que tenham\011o poder e a alma\011da verdade.\n \012Vá em frente e\nentre na TORRE\011ESTRANHA.\012SUICUNE vai\nsubmeter você ao\011teste.",
  ["26:4db5"] = "Siga em frente.\012SUICUNE vai\nsubmeter você ao\011teste.",
  ["26:4ed8"] = "Oi, sou BILL.\nE quem é você?\012Hum, {PLAYER}, hã?\nVocê veio na hora\011certa.",
  ["26:4f22"] = "Eu acabei agora\nos ajustes na\011minha CÁPSULA DO\011TEMPO.\012Você sabe que um\n#MON pode ser\011trocado, certo?\012Minha CÁPSULA DO\nTEMPO foi feita\011para permitir\011trocas com o\011passado.\012Mas não se pode\nenviar algo que\011não existia no\011passado.\012Se o fizer, o\nCOMPUTADOR no\011passado vai ter\011problemas.\012Então você deve\nremover tudo que\011não havia no\011passado.\012Simplesmente, não\nenvie novos golpes\011ou novos #MON\011na CÁPSULA DO\011TEMPO.\012Não se preocupe.\nEu já acabei os\011ajustes.\012Amanhã, as\nCÁPSULAS DO\011TEMPO estarão\011funcionando em\011todos CENTROS\011#MON.\012Tenho que voltar\nrápido para\011GOLDENROD para ver\011meus conhecidos.\012Tchaaau!",
  ["26:5155"] = "O modo em que as\nGAROTAS KIMONO\011dançam é\011explêndido.\012Do jeito que elas\nusam seus\011#MON!",
  ["26:51aa"] = "Você deve querer\nbatalhar com mais\011pessoas, certo?\012Há, aparentemente,\nmuitos lugares\011onde treinadores\011se reúnem.\012Onde que é?\012É um pouco depois\nda CIDADE DE OLIVINE.",
  ["26:5240"] = "MORTY, o LÍDER\nDO GINÁSIO, é\011tãão legal.\012Seus #MON são\nbem fortes também.",
  ["26:5286"] = "LAGO DA FÚRIA…\012A aparição de\num enxame de\011GYARADOS…\012Isso me cheira\nconspiração.\012Eu sei!",
  ["26:533d"] = "Isso ocorreu\nquando eu era\011jovem.\012O céu de repente\nficou preto. Um\011#MON voador\011gigante estava\011bloqueando o sol.\012Que #MON\ndeveria ser\011aquele?\012Era como um\npássaro e um\011dragão.",
  ["26:53ec"] = "Realmente existe\num #MON grande\011assim?\012Se existir, deve\nser poderoso.",
  ["26:552e"] = "Vitórias e\nderrotas, conheço\011ambas.",
  ["26:555f"] = "Oh, você é muito\nforte.",
  ["26:5579"] = "Eu gostei muito.\nGostaria de vê-lo\011de novo.",
  ["26:55ae"] = "Eu sempre danço\ncom meus #MON.\012Claro, eu também\nos treino.",
  ["26:55ea"] = "Oh, foi perto!\nEu quase venci.",
  ["26:560b"] = "O ritmo é\nimportante para a\011dança e para os\011#MON.",
  ["26:563f"] = "O meu pregador não\né lindo?\012Oh, uma batalha\n#MON?",
  ["26:566c"] = "Não restou mais\nnenhum #MON…",
  ["26:5688"] = "Eu ponho uma flor\ndiferente no meu\011pregador todo\011mês.",
  ["26:56c0"] = "Oh, você é um\ntreinador bonito.\011Gostaria de\011batalhar?",
  ["26:56f5"] = "Você é mais forte\ndo que parece.",
  ["26:5714"] = "Eu treinei muito,\nentão achei que\011era uma boa\011treinadora.\012Parece que não.",
  ["26:575c"] = "Gosta da minha\ndança?\012Sou boa com\n#MON também.",
  ["26:578a"] = "Ooh, você também é\nbom com #MON.",
  ["26:57a8"] = "Eu posso continuar\ndançando pois há\011pessoas que gostam\011do que faço.\012Meus #MON\ntambém mantêm meu\011espírito alto.",
  ["26:580a"] = "Além de serem\nótimas dançarinas,\011as GAROTAS KIMONO\011também são boas\011com #MON.\012Eu sempre as\ndesafio, mas nem\011chego a arranhar…",
  ["26:5891"] = "Rapaz! Se você\npuder derrotar\011todas GAROTAS\011KIMONO, vou\011presenteá-lo.",
  ["26:58d4"] = "Garota! Se você\nderrotar todas\011GAROTAS KIMONO, vou\011presenteá-la.",
  ["26:591a"] = "O modo em que\nbatalhou, foi como\011assistir a uma\011dança.\012Foi algo bem raro\nde se ver!\012Quero que leve\nisso.\012Não se preocupe,\nleve-o!",
  ["26:599b"] = "É o SURFE.\012É um golpe que\ndeixa o #MON\011nadar através da\011água.",
  ["26:59d5"] = "Eu queria que\nmeus #MON\011fossem elegantes\011como as GAROTAS\011KIMONO!",
  ["26:5a0a"] = "RHYDON: Gugooh\ngugogooh!",
  ["26:5a24"] = "Esse homem está\nsempre com seu\011RHYDON.\012Dizem que ele quer\num #MON que\011possa SURFAR e\011dançar.\012Ele está tentando\nfazer um\011#MON de nado\011sincronizado?",
  ["26:5aaa"] = "As GAROTAS KIMONO\nsão tão bonitas…\012Mas elas devem\npassar por\011um rigoroso\011treinamento.\012E devem aprender\na seguir costumes\011antes da exibição\011pública.\n \012Mas se você ama\nalguma coisa, tudo\011é possível.",
  ["26:5b79"] = "É um lindo painel\ndecorado com\011flores.",
  ["26:5c48"] = "Meu EEVEE evoluiu\nem um ESPEON.\012Mas o EEVEE do\nmeu amigo virou\011um UMBREON.\012Por que será?\nAmbos criávamos\011nossos EEVEES do\011mesmo modo…",
  ["26:5cd5"] = "Se você usar o\nREVIVE, um #MON\011desmaiado vai\011acordar.",
  ["26:5e65"] = "Que bom você ter\nvindo.\012Aqui em ECRUTEAK,\nos #MON têm\011sido honrados.\012Dizem que um\n#MON cor de\011arco-íris vai\011descer e aparecer\011para um treinador\011realmente podero-\011so.\012Eu acreditei\nnesse conto,\011então treinei aqui\011secretamente por\011toda minha vida.\012Como resultado,\nposso ver agora o\011que outros não\011podem.\012Um pouco mais…\012Com um pouco mais,\npoderei ver o\011futuro no qual\011eu conhecerei o\011#MON cor de\011arco-íris.\012Você me ajudará a\nchegar nesse\011nível!",
  ["26:600a"] = "Não sou bom o\nbastante ainda…\012Tudo bem. Essa\nINSÍGNIA é sua.",
  ["26:6043"] = "{PLAYER} foi\npresenteado com\011uma INSÍGNIA DA\011NÉVOA DO GINÁSIO\011DA CIDADE\011ECRUTEAK.",
  ["26:6059"] = "Por ter a INSÍGNIA\nDA NÉVOA, #MON\011até o NÍVEL 50 vão\011lhe obedecer.\012E mais, #MON\nque sabem o SURFE\011poderão usá-lo a\011qualquer hora.\012Eu quero que você\ntenha isso também.",
  ["26:60ec"] = "É a BOLA SOMBRIA.\nEla causa danos\011e pode reduzir a\011DEFESA 2.\012Use-a quando\nnecessitar.",
  ["26:6145"] = "Eu vejo…\012Sua jornada te\nlevou para lugares\011distantes.\012E você testemunhou\nmuito mais do que\011eu.\012Eu o invejo por\nisso…",
  ["26:61bd"] = "Eu gastei a\nprimavera com meu\011#MON.\012Depois o verão,\no outono e o\011inverno.\012A primavera veio\nde novo. Nós temos\011vivido juntos por\011um longo tempo.",
  ["26:623d"] = "Eu vou vencer!",
  ["26:6263"] = "De onde vieram\nos #MON?",
  ["26:627e"] = "Você pode causar\ndanos em nossos\011#MON?",
  ["26:62a7"] = "Ah! Muito bem!",
  ["26:62b7"] = "Só usamos #MON\ndo tipo fantasma.\012Técnicas do tipo\nnormal não os\011machucam.",
  ["26:62fb"] = "Quem mais quiser\nvencer--vencerá!",
  ["26:6309"] = "Eu, eu, eu perdi!",
  ["26:6318"] = "Quem mais quiser\nvencer--vencerá!",
  ["26:633e"] = "Confuso com nosso\nchão invisível?\012Derrote-me se\nquiser uma dica!",
  ["26:637f"] = "O-o quê?",
  ["26:638a"] = "Bom. Vou te contar\no segredo do chão\011invisível.\012O caminho é em\nfrente aos nossos\011olhos!",
  ["26:63e8"] = "Os treinadores\naqui têm motivos\011secretos.\012Se você vencer,\neles devem te\011contar segredos\011profundos de\011ECRUTEAK.",
  ["26:6452"] = "Uau, {PLAYER}.\nVocê foi ótimo!\012Eu estava agachado\nno canto, livre do\011puro terror!",
  ["26:649c"] = "MORTY, o LÍDER DO\nGINÁSIO, está\011ausente.\012Perdão, mas terá\nque sair.\012Hohohoho.",
  ["26:663c"] = "Ah. Você está em\numa aventura com\011seus #MON?\012Bem, o que é uma\naventura sem uma\011Caça ao Tesouro?\012Estou certo, ou\nestou certo?",
  ["26:66b5"] = "Bom! Você entende\no verdadeiro\011espírito da\011aventura.\012Eu gosto disso!\nLeve isso com\011você.",
  ["26:670e"] = "Há muitos itens\nque não podem ser\011vistos.\012Use o BUSCA-ITENS\npara checar se há\011um item no chão\011perto de você.\012Ele não mostra o\nponto exato, logo\011você terá que\011procurar por você\011mesmo.\012Oh sim--eu soube\nque há itens na\011TORRE QUEIMADA da\011CIDADE DE ECRUTEAK.",
  ["26:6805"] = "Oh… Cada um deve\nter seu gosto…",
  ["26:6826"] = "HISTÓRIA DE\nECRUTEAK.\012Quer ler?",
  ["26:684c"] = "Em ECRUTEAK, havia\nduas torres.\012Cada torre era\no poleiro de\011poderosos #MON\011voadores.\012Mas uma das torres\nqueimou até o\011chão.\012Os dois #MON\nnão foram vistos\011desde então…\012Continuar lendo?",
  ["26:6902"] = "ECRUTEAK era\ntambém o lar de\011três #MON que\011corriam ao redor\011da cidade.\012Era dito que foram\nnascidos da água,\011do relâmpago e do\011fogo.\012Mas não\npuderam conter\011seus poderes\011excessivos.\012Dizem que os três\ncorriam do modo\011que o vento passa\011pela grama.",
  ["26:6a7b"] = "AZUL: Você!\nFinalmente chegou\011aqui, hã?\012Eu não estava\ndisposto em\011CINNABAR, mas\011agora Estou pronto\011para batalhar com\011você.\012…\012Você está me\ndizendo que\011conquistou todos\011GINÁSIOS em JOHTO?\012Bah! Esses\nGINÁSIOS devem ser\011muito patéticos\011então.\012Ei, não se\npreocupe!\012Saberei se é bom\nou não nas\011batalhas agora.\012Pronto, CAMPEÃO\nDE JOHTO?",
  ["26:6bae"] = "AZUL: O quê?\012O que fez para\neu perder para\011você?\012…\012Tsc, está certo…\nEi, leve isso,\011é a INSÍGNIA DA\011TERRA.",
  ["26:6c0f"] = "{PLAYER} foi pre-\nsenteado com uma\011INSÍGNIA DA TERRA\011DO GINÁSIO DA\011CIDADE DE VIRIDIAN.",
  ["26:6c27"] = "AZUL: …\012Certo, eu estava\nerrado. Você é\011realmente bom.\012Você é um ótimo\ntreinador.\012Mas um dia\neu ainda vou\011derrotá-lo.\012Não se esqueça\ndisso!",
  ["26:6cab"] = "AZUL: Ouça,\ncara.\012É melhor não\nperder até que\011eu o vença.\011Entendeu?",
  ["26:6cee"] = "Ei, CAMPEÃO em\nprogresso.\012Como vai você?\nParece que está\011encrencado.\012O LÍDER DO GINÁSIO\né um cara que\011batalhou com o\011CAMPEÃO há três\011anos.\012Ele é dureza.\012Dê na batalha\ntudo que você\011tiver!",
  ["26:6da0"] = "Cara, você é\nrealmente forte…\012Essa foi uma\nmagnífica batalha\011inspiradora.\012Trouxe lágrimas\naos meus olhos.",
  ["26:6e54"] = "Você pensa\nbastante ao\011colocar um nome\011em seus #MON?\012Dar-lhes bons\napelidos torna\011mais divertidas\011as trocas.",
  ["26:6ecb"] = "Eles são SPEARY,\num SPEAROW,\012e RATTEY, um\nRATTATA.",
  ["26:6efe"] = "SPEARY: Ch-chun!",
  ["26:6f10"] = "RATTEY: Kikiii!",
  ["26:6f7f"] = "Bem-vindo à CASA\nDO TREINADOR, o\011lugar mais novo\011e agitado em\011VIRIDIAN.\012Nós abrimos\nsomente para\011treinadores.\012Você pode\nbatalhar contra\011o melhor dos\011melhores no andar\011de baixo.",
  ["26:7025"] = "VIRIDIAN é a\ncidade mais\011próxima do\011PLANALTO ÍNDIGO.\012Construíram\nesse lugar\011porque vários\011treinadores passam\011por aqui ao irem\011ao PLANANTO\011ÍNDIGO.",
  ["26:70b5"] = "Eles fazem\nbatalhas de\011prática no andar\011de baixo.\012Adoraria ver como\nbatalha bem um\011treinador vindo\011de JOHTO.",
  ["26:711d"] = "Acho que não é\npossível ser o\011CAMPEÃO até que\011você vá a todos\011os lugares e\011batalhe com todos\011tipos de pessoa.\012O CAMPEÃO de\nPALLET viajou por\011todas as cidades\011e vilas em KANTO.",
  ["26:71c9"] = "Nossa… Estou\ndescansando de\011batalhas #MON.",
  ["26:71f4"] = "Batalhas de\nprática são\011feitas na SALA\011DE TREINAMENTO\011abaixo.\012Treinadores\nhabilidosos são\011convidados a\011participar.",
  ["26:725d"] = "Não há regras ou\nregulamentos para\011partidas práticas.\011Como nas batalhas\011reais, vale tudo!",
  ["26:72c1"] = "…O que é isso?\nUma estratégia?\012Essa escrita se\nparece com marcas\011de ONIX…\012Está completamente\nilegível…",
  ["26:7420"] = "Oi. Bem-vindo\na nossa SALA DE\011TREINAMENTO.\012Pode batalhr com\num treinador por\011dia.",
  ["26:746a"] = "{STRBUF} é\nseu oponente de\011hoje.",
  ["26:7487"] = "Você gostaria de\nbatalhar?",
  ["26:74a2"] = "Por favor vá por\naqui.\012Você pode começar\nlogo.",
  ["26:74d6"] = "Perdão. Só aqueles\ntreinadores que\011vão batalhar agora\011podem entrar.",
  ["26:751d"] = "Perdoe-me. Essa\nseria sua segunda\011vez hoje.\012Você só pode\nentrar aqui apenas\011uma vez ao dia.",
  ["26:7578"] = "Perdi…\nDroga…",
  ["26:7587"] = "Viajei para cá\npara então poder\011batalhar com você.",
  ["26:75f4"] = "O LÍDER DE GINÁSIO\ndaqui é todo\011legal.",
  ["26:761a"] = "Já foi a CINNABAR?\012É uma ilha que\nfica ao sul daqui.",
  ["26:76ad"] = "Onde estará o\nLÍDER DE GINÁSIO\011DE VIRIDIAN?\012Eu queria\ndesafiá-lo.",
  ["26:76f5"] = "Não há TREINADORES\nDE GINÁSIO no\011GINÁSIO DE\011VIRIDIAN.\012O LÍDER diz que\nsua política é\011vencer sem ajuda\011de subordinados.",
  ["26:776b"] = "Soube que\no GINÁSIO em\011CINNABAR se foi.\012O que acontecerá\na BLAINE, O LÍDER\011DO GINÁSIO.",
  ["26:77c8"] = "Meu sonho é\nser um LÍDER DE\011GINÁSIO.",
  ["26:7865"] = "Oi! Uau, Estou\nfeliz por vê-lo.\012É o primeiro\nvisitante a vir\011em um longo tempo.\012Estou super-feliz!\012Vou lhe dar um\npresentinho.",
  ["26:78e5"] = "É uma PEPITA.\012Não posso lhe dar\numa pepita da\011sabedoria, então\011vai essa mesmo!",
  ["26:7955"] = "Você é {PLAYER}?\012Eu trabalho\ncomo AJUDANTE\011DO PROFESSOR\011CARVALHO.\012Eu nem fazia\nidéia de que você\011estava por aqui.\012O LABORATÓRIO DO\nPROFESSOR CARVALHO\011é aqui perto, na\011CIDADE DE PALLET.",
  ["26:7a29"] = "Só treinadores que\nprovaram seu valor\011podem passar.",
  ["26:7a5f"] = "Você não tem todas\nas INSÍGNIAS DE\011GINÁSIO DE JOHTO.\012Perdão, mas não\nposso deixá-lo\011entrar.",
  ["26:7ab4"] = "Oh! As oito\nINSÍGNIAS de\011JOHTO!\012Por favor pode\nentrar!",
  ["26:7af1"] = "Esse caminho leva\nao MONTE PRATA.\012Verá #MON\nextremamente for-\011tes lá.",
  ["26:7b37"] = "Para a LIGA\n#MON, você está\011indo?\012A ELITE QUATRO é\ntão forte que\011assusta, e eles e\011tão prontos para\011você!",
  ["27:400e"] = "O MARINHEIRO na\nLANCHONETE OLIVINE\011na próxima casa é\011generoso mesmo.\012Ele ensinou SUPERFORÇA\nao meu #MON.\012Agora ele pode\nmover grandes\011pedras.",
  ["27:4086"] = "Há uma pessoa na\nCIDADE DE CIANWOOD\011após o mar.\012Ouvi ele se\ngabando de seu\011#MON raro.",
  ["27:41b9"] = "…Obrigada por usa\najuda no FAROL…\012Mas isso já é\ndiferente.\012Permita que eu me\nintroduza.\012Eu sou JASMINE, a\nLÍDER DO GINÁSIO.\011Eu uso o tipo-aço.\012…Você conhece o\ntipo-aço?\012É um tipo que\nfoi recentemente\011descoberto.\012…Hm… Posso\ncomeçar?",
  ["27:42bb"] = "…Você é um\ntreinador melhor\011do que eu, tanto\011na habilidade\011quanto na\011gentileza.\012De acordo com as\nregras da LIGA,\011eu lhe confiro\011essa INSÍGNIA.",
  ["27:433a"] = "{PLAYER} foi\npresenteado com\011uma INSÍGNIA\011MINERAL DO GINÁSIO\011DA CIDADE DE OLIVINE.",
  ["27:4354"] = "A INSÍGNIA MINERAL\nmelhora a DEFESA\011dos #MON.\012…Hm… Leve isso\ntambém…",
  ["27:43a5"] = "…Você poderia usar\nesse TM para\011ensinar a CAUDA\011FERRO.",
  ["27:43d1"] = "Hm… Não sei como\ndizer isso, mas,\011boa sorte…",
  ["27:4402"] = "JASMINE usa o\ntipo-aço que\011foi descoberto\011recentemente. Não\011sei muito sobre\011ele.",
  ["27:4451"] = "Isso foi incrível.\012O tipo-aço, hã?\012Foi um confronto\ndireto com o tipo\011desconhecido!",
  ["27:44a8"] = "JASMINE, a LÍDER\nDO GINÁSIO, está\011no FAROL.\012Ela está cuidando\nde um #MON\011doente.\012Um treinador forte\nprecisa ter\011compaixão.",
  ["27:45a2"] = "Quando meu #MON\nadoeceu, o\011FARMACEÚTICO em\011ECRUTEAK me fez\011uns remédios.",
  ["27:45f0"] = "RHYDON: Gugooh!",
  ["27:4643"] = "No caminho para\nCIANWOOD, há\011quatro ilhas\011desertas.\012As crianças más\nsão levadas para\011as ilhas como\011punição!",
  ["27:46b1"] = "Sempre que me\nencrenco, o meu\011Pai me assusta.",
  ["27:4749"] = "OLIVINE está no\nmar!\012E se está no mar,\nsignifica que há\011muita pescaria!\012Eu pesquei aqui\npor 30 anos.\012Você gostaria de\nencarar o mar e\011pescar?",
  ["27:47db"] = "Ah, haha! Temos\num novo pescador!",
  ["27:4807"] = "Os peixes não\nestão só no mar.\012Eles estão em\ntodo lugar que há\011água.",
  ["27:484c"] = "O queê? Você não\ngosta de pescar!?\011É imcompreensível!",
  ["27:487f"] = "Como vai você?\nPegou um grandão?",
  ["27:48df"] = "Hah! Seus #MON\nparecem mesmo\011pesos-leves!\012Eles não têm força\npara mover pedras\011à parte.\012Ei, use isso e\nensine SUPERFORÇA a\011eles!",
  ["27:4965"] = "No mar, a única\ncoisa com que pode\011contar é você\011mesmo!\012Estou tão\norgulhoso do meu\011corpo!",
  ["27:49c5"] = "O cardápio da\nLANCHONETE OLIVINE\011está cheio de\011boa comida\011para fortes\011MARINHEIROS!",
  ["27:4a09"] = "Sempre que visito\nOLIVINE, venho\011à LANCHONETE\011OLIVINE.\012Tudo no cardápio\nme faz sentir mais\011forte. Não consigo\011parar de comer!",
  ["27:4ad4"] = "O seu #MON já\nsabe um golpe\011para carregar\011pessoas na água?",
  ["27:4b16"] = "Minha BUTTERFREE\nveio do meu\011namorado do outro\011lado do mar.\012Ela trazia uma\nCARTA dele.\012Quer saber o que\nela diz?\012Deixe-me ver…\nNada! É segredo!",
  ["27:4bda"] = "De onde você disse\nque veio?\012CIDADE DE NEW BARK?\012O PROFESSOR ELM\nmora lá, certo?\012Você caminhou\nbastante para\011chegar até aqui.",
  ["27:4d2e"] = "MOOMOO está\ndoente…\012Ela precisa de\nmuitas FRUTAS.",
  ["27:4d5a"] = "Estamos dando\ncomida à MILTANK.",
  ["27:4d70"] = "Seu mugido está\nfraco…",
  ["27:4d80"] = "Seu mugido está\nfraco…",
  ["27:4d92"] = "MILTANK: Mooo!",
  ["27:4da2"] = "Dar uma FRUTA à\nMILTANK?",
  ["27:4dbc"] = "{PLAYER} deu uma\nFRUTA à MILTANK.",
  ["27:4dd8"] = "A MILTANK ficou\num pouco mais\011saudável!",
  ["27:4dfc"] = "A MILTANK ficou\nmais saudável!",
  ["27:4e1b"] = "A MILTANK\nestá totalmente\011saudável!",
  ["27:4e3c"] = "{PLAYER} não tem\nFRUTAS…",
  ["27:4e4f"] = "{PLAYER} não dará\numa FRUTA.\012A MILTANK parece\ntriste.",
  ["27:4f38"] = "Minha MILTANK não\nestá dando mais\011leite.\012Essa FAZENDA tem\num leite famoso.\012Muita gente quer\nbebê-lo.\012Ela vai me dar\nmuito leite se eu\011alimentá-la com\011muitas FRUTAS.",
  ["27:4fe1"] = "O que acha do meu\nLEITE MOOMOO?\012Ele me orgulha e\nalegra.\012Dê-o a um #MON\npara restaurar\011seu HP.\012Eu lhe vendo por\napenas ¥500.",
  ["27:505d"] = "Aqui está!\nBeba e divirta-se!",
  ["27:507c"] = "Perdão. Sem\ndinheiro, sem\011venda!",
  ["27:509d"] = "Vejo que sua\nBOLSA está cheia.",
  ["27:50b7"] = "Você não o quer?\nVolte depois,\011certo?",
  ["27:50dc"] = "É melhor eu ir\nordenhar.",
  ["27:50f6"] = "Nosso leite vai\naté para KANTO.\012Logo, se nossa\nMILTANK não nos\011der leite, teremos\011problemas.",
  ["27:5156"] = "Você curou nossa\nMILTANK.\012Agora ela dá LEITE\nMOOMOO de novo.\012Eis algo para os\nseus problemas.",
  ["27:51c7"] = "É o RONCAR.\012É um golpe raro\nque só funciona\011enquanto o #MON\011estiver dormindo.\012É melhor pensar\nbem quando se deve\011usá-lo, rapaz.",
  ["27:5303"] = "Eu, eu estou\nchocado!\012Um garoto de sua\nidade com olhos\011penetrantes e\011cabelo longo veio\011aqui.\012Ele me assustou\ne eu dei meu\011#MON premiado a\011ele.\012Eu ainda tenho um\nsobrando. E se\011ele voltar?\012Você parece forte.\nPoderia cuidar\011do meu #MON por\011enquanto?",
  ["27:53ed"] = "Oh, obrigado!\012Cuide bem dele,\npor favor!",
  ["27:541b"] = "{PLAYER} recebeu um\n#MON.",
  ["27:542f"] = "Sua equipe #MON\nestá cheia.",
  ["27:5449"] = "Oh, não… O que\nfarei se ele\011voltar?",
  ["27:5470"] = "Oi! Como vai meu\n#MON?\012Devo estar seguro\nagora.\012Poderia me\ndevolvê-lo?",
  ["27:54b1"] = "Obrigado!",
  ["27:54bd"] = "Ei, meu #MON\nnão está com você.",
  ["27:54e3"] = "Meu #MON passou\na gostar de você.\012Tudo bem, pode\nficar com ele.\012Mas prometa\ntratá-lo bem!",
  ["27:553f"] = "Oh, não, não…\nÉ o mesmo que ser\011roubado.",
  ["27:556c"] = "Para os #MON,\na felicidade é\011estar com a\011pessoa que os\011tratem bem.",
  ["27:56f9"] = "HAHAHAH!\012Então você chegou\naqui!\012Deixe-me te\ncontar, sou forte!\011Meus #MON\011esmagarão pedras\011e quebrarão ossos!\012Veja isso!",
  ["27:576f"] = "CHUCK: Urggh!\n…\012Oooarrgh!",
  ["27:578a"] = "E aí! Está\nassustado agora?\012O quê? Não tem\nnada a ver com\011#MON?\012É verdade!\012Vamos lá! Vamos\nbatalhar!",
  ["27:57f6"] = "Quê? Hã? Eu perdi!\012Muito bem! Você\nmerece a INSÍGNIA\011DA TEMPESTADE!",
  ["27:5835"] = "{PLAYER} foi\npresenteado com\011uma INSÍGNIA DA\011TEMPESTADE DO\011GINÁSIO DA CIDADE\011CIANWOOD.",
  ["27:584d"] = "A INSÍGNIA DA\nTEMPESTADE faz\011todos #MON até\011o NÍVEL 70 lhe\011obedecerem, mesmo\011os trocados.\012Também permite seu\n#MON usar o\011VOAR quando não\011estiver em uma\011batalha.\012Ei, leve isso\ntambém!",
  ["27:58da"] = "É o SOCODINÂMICO.\012Ele nem sempre\nacerta, mas quando\011consegue, causa\011confusão!",
  ["27:5930"] = "HAHAHA! Eu gostei\nde batalhar com\011você.\012Mas derrota é\nderrota. Daqui\011para frente,\011treinarei 24 horas\011por dia!",
  ["27:5997"] = "Meus #MON e eu\nsomos ligados pela\011amizade.\012Nosso laço nunca\nserá quebrado!",
  ["27:59e9"] = "Isso não é real!",
  ["27:59fa"] = "Você parece ter um\nlaço forte com\011seus #MON\011também!",
  ["27:5a2e"] = "Nós, lutadores\nmarciais, não\011tememos nada!",
  ["27:5a50"] = "Foi chocante!",
  ["27:5a61"] = "#MON lutadores\ntêm medo dos\011psíquicos…",
  ["27:5a8a"] = "Palavras são\ninúteis. Deixe seu\011punho falar!",
  ["27:5ac0"] = "Eu perdi! Estou\ncalado!",
  ["27:5ad9"] = "Meus raivosos\npunhos destruirão\011seus #MON!",
  ["27:5b02"] = "Eu fui vencido!",
  ["27:5b14"] = "Meus #MON\nperderam…\012…meu orgulho está\nquebrado…",
  ["27:5bed"] = "Você conheceu o\n#MANÍACO?\012Ele está sempre se\ngabando de seu\011#MON raro.",
  ["27:5c33"] = "Os treinadores do\nGINÁSIO #MON\011daqui são bem\011machos.\n\012Se eu ficar aqui,\neles podem me\011procurar.\012Aqui vai um\nconselho: o LÍDER\011DO GINÁSIO usa o\011tipo-lutador.\012Então você deve\nconfundi-lo\011com #MON\011psíquicos.\012Vença seus\n#MON antes\011que eles possam\011usar suas forças\011psíquicas.\012E aquelas pedras\nno meio do\011GINÁSIO?\012Se não movê-las\ncorretamente,\011você não alcançará\011o LÍDER DO\011GINÁSIO.\012Se ficar preso,\nvá para forta.",
  ["27:5dc5"] = "{PLAYER}! Você\nvenceu! Posso\011dizer só de te\011olhar!",
  ["27:5ed7"] = "Eu estive\nbatalhando com meu\011amigo em VIOLET\011usando o ADAPTADOR\011MÓVEL.\012Estou perdendo de\n5 a 7. Eu tenho\011que vencer!",
  ["27:5fcd"] = "Eu adoro mostrar\nos #MON que eu\011criei. E você?\012Eu vou entrar em\nmuitas batalhas,\011e mostrar meus\011#MON!",
  ["27:6056"] = "{PLAYER} recebeu\nPOÇÃOSECRETA.",
  ["27:6070"] = "Minha POÇÃOSECRETA\né muito forte.\012Eu só ofereço\nem caso de\011emergência.",
  ["27:60f9"] = "Você tem #MON\nmagníficos com\011você.\012Que tal tirar\numa foto como\011lembrança?",
  ["27:6142"] = "Certo! Sorria\nagora!",
  ["27:6156"] = "Oh, isso é tão\nruim. Eu achei que\011seria uma boa\011lembrança…",
  ["27:61bc"] = "Você veio de\nOLIVINE?\012Você se lembra das\nquatro ilhas que\011tem no caminho?\012Eu soube que uma\nmística criatura\011aquática se\011esconde nelas.",
  ["27:623f"] = "Eu soube que só se\npode vê-lo se\011tiver a ASA DE\011PRATA.\012Parece ter o\nmesmo cheiro da\011criatura.",
  ["27:62a9"] = "Eu soube que os\nredemoinhos ao\011redor das ilhas\011são causados pela\011criatura do mar.\012Você pode precisar\nde um golpe\011especial para\011pulá-las.",
  ["27:65ab"] = "Bem-vindo à\nTORRE DE BATALHA!\012Vou lhe mostrar\numa SALA DE\011BATALHA.",
  ["27:65ea"] = "Quer ir a uma\nSALA DE BATALHA?",
  ["27:660a"] = "A SALA DE BATALHA\né por aqui.",
  ["27:6886"] = "A TORRE DE BATALHA\né uma facilidade\011feita para\011batalhas #MON.\012Muitos treinadores\n#MON se reúnem\011de todas as partes\011para batalhas nas\011SALAS DE BATALHAS\011feitas para isso.\012Há muitas SALAS\nDE BATALHA na\011TORRE DE BATALHA.\012Cada SALA tem sete\ntreinadores.\012Derrote-os e ganhe\num prêmio.\012Para interromper\numa sessão, você\011deve SALVAR.\012Se não, você não\npoderá continuar\011seu desafio na\011SALA.\012",
  ["27:6a49"] = "Obrigada por\nvisitar!",
  ["27:6aef"] = "Parabéns!\012Você derrotou\ntodos os\011treinadores!\012Por isso, receberá\nesse ótimo prêmio!\012",
  ["27:6b7e"] = "{PLAYER} got five\n{STRBUF}!",
  ["27:6b94"] = "As portas da TORRE\nDE BATALHA estão\011fechadas…",
  ["27:6c09"] = "Esperamos servi-lo\nde novo.",
  ["27:6c26"] = "Entre por aqui.",
  ["27:6c3d"] = "Quer saber algo\nsobre a TORRE DE\011BATALHA?",
  ["27:6d3c"] = "As regras da TORRE\nDE BATALHA estão\011aqui.\012Quer lê-las?",
  ["27:6d72"] = "Só três #MON\npodem entrar nas\011batalhas.\012Todos os três\ntem que ser\011diferentes, e os\011itens que seguram\011também.\012Alguns #MON\npodem ter também\011restriçõs de nível\011neles.",
  ["27:6e18"] = "Desculpe-me! Você\nnão SALVOU antes\011de sair da SALA\011DE BATALHA.\012Eu sinto muito\nmesmo, mas seu\011desafio será dado\011como inválido.",
  ["27:6e92"] = "Seus #MON\nserão totalmente\011curados.",
  ["27:6ebc"] = "Next up, opponent\nno.{STRBUF}. Ready?",
  ["27:6f1f"] = "Antes de entrar\nna SALA DE\011BATALHA, seu\011progresso será\011salvado.",
  ["27:6f5e"] = "SALVAR e acabar\na sessão?",
  ["27:6fbf"] = "Cancelar seu\ndesafio na SALA\011DE BATALHA?",
  ["27:7037"] = "Estávamos espe-\011rando por você.\012A SALA DE BATALHA\né por aqui.",
  ["27:7264"] = "Destruído pelo\nprimeiro oponente\011em pouco tempo…\011Não sou bom…",
  ["27:72a4"] = "Há muitas SALAS DE\nBATALHA, mas eu\011vencer todas\011elas!",
  ["27:72e3"] = "É uma tarefa\nirritante, não\011poder usar itens\011na batalha.\012Fazer seus\n#MON segurarem\011itens é a chave\011para vencer as\011batalhas.",
  ["27:735b"] = "Estou tentando\nver até onde eu\011vou usando apenas\011#MON inseto.\012Tomara que não\nhaja #MON de\011fogo…",
  ["27:7716"] = "Você está indo\npara a TORRE DE\011BATALHA?\012Isso é um segredo,\nmas se vencer\011várias vezes,\011ganhará presentes\011especiais.",
  ["27:77c8"] = "Os nível dos\n#MON que quero\011usar são todos\011diferentes.\012Eu tenho que ir\ntreinar agora!",
  ["27:7930"] = "Uau, a TORRE DE\nBATALHA é grande!\012Deve haver muitos\ntipos de #MON\011lá dentro!",
  ["27:79db"] = "Você só pode usar\ntrês #MON.\012É tão difícil\ndecidir os três\011que devem ir para\011a batalha…",
  ["27:7a8c"] = "Hehehe, eu fugi\ndo trabalho.\012Não posso ir\nembora até eu\011vencer!\012Eu tenho que\nvencer. É meu\011dever!",
  ["27:7afc"] = "TORRE DE BATALHA\012Tome o Desafio\nFinal de um\011Treinador!",
  ["28:4c28"] = "Oi, aqui é BUENA…\012Oh! Bom dia,\n{PLAYER}!\012Fico meio desli-\ngada pela manhã…",
  ["28:4c72"] = "Oi, aqui é BUENA…\nOh! Oi, {PLAYER}!\012Você sintoniza no\nshow da BUENA?",
  ["28:4caf"] = "Aqui é BUENA.\nNão posso falar\011ao telefone agora.\012Se quiser conver-\nsar, sintonize na\012SENHA DA BUENA\nno rádio e me li-\012gue depois da\nmeia-noite!",
  ["28:4d42"] = "Oi, aqui é BUENA…\nOh! Oi, {PLAYER}!\012Acabei de sair\ndo trabalho.\012Vou lhe contar,\nestou exausta!",
  ["28:4d96"] = "{PLAYER}!\nOi, é BUENA!\012Levantei-me cedo,\npor isso decidi\011telefonar!",
  ["28:4dcf"] = "{PLAYER}!\nOi, é BUENA!\012Eu queria alguém\npara conversar!",
  ["28:4e01"] = "{PLAYER}!\nOi, é BUENA!\012Eu estou na\nminha folga.",
  ["28:4e29"] = "{PLAYER}!\nOi, é BUENA!Não consegui dor-\nmir, por isso te-\011lefonei para você.",
  ["28:4e5e"] = "Oh. Oi, {PLAYER}!\012Você está como?\012Aiyee! Essa não é\na hora de ficar\012jogando conversa\nfora!\012A TORRE DE RÁDIO\nestá em grandes\011apuros!\012{PLAYER}, é melhor\ntomar cuidado!",
  ["28:4efb"] = "Em outro dia, fui\ncomer com o\012DJ BEN!\nNão é ótimo?\012E tem mais, ele\ndisse que a música\012em meu programa\né legal!\012Oh, uau! Bem,\no que devo fazer?\012…Opa, tenho que\nme preparar para\012o meu show! Falo\ncom você depois!",
  ["28:4fcf"] = "Você conhece a\nrecepcionista da\011TORRE DE RÁDIO?\012'Bem-vindo,' é tudo\nque ela diz.\012Mas ela é mes-\nmo a pessoa mais\011comunicativa na\011TORRE DE RÁDIO.\n\012Então ela deve\nestar mudando.\012Não é divertido\nsaber?\012Depois falo com\nvocê!",
  ["28:509d"] = "Conte-me, {PLAYER}.\nJá ganhou um\012prêmio no SHOW\nDO NÚMERO SORTUDO?\012REED reclama pois\nnunca ganhou,\012e afirma que\nmantém o programa\011no ar até ganhar.\012Mais tarde conver-\nsaremos de novo!",
  ["28:5143"] = "Você sabe, na\núltima noite…\n\012Fiquei tão estres-\nsada do meu tra-\012balho que comi\num monte de\011porcaria!\012MARY e eu fi-\nzemos um acordo\011para perder peso…\012Isso não vai…\012Hã? Qual é o\npeso?\012Isso tem que ser\num segredo total!\012MARY pesa…\012Aiyee! M-MARY!\012Uh… Um… P… Perdoe-\nme, número errado!",
  ["28:5244"] = "Ontem, o PROFES-\nSOR CARVALHO\012estava no estúdio\npara gravar seu\011programa.\012Então eu fui e\nme apresentei.\012Saiba disso--ele\nsintoniza no meu\011programa!\012Oh! Aqui vem o\nPROFESSOR CARVALHO\011de novo!\012Vou conversar com\nele de novo!\012Conversaremos\ndepois!",
  ["28:5318"] = "…Cof, cof!\012Uhm perdão, fiquei\ngribada agora.\012Bas tenho que\ndisfarçar enquanto\011estou no ar.\012Vou poupar minha\nvoz agora.\012Falo com você\ndepois. Essa foi\011BUENA!",
  ["28:53d8"] = "Ei, {PLAYER}.\nVocê ganhou o\012CARTÃO RÁDIO ao\nvencer o teste\012na recepção, não\né verdade?\012Adivinhe só? Fui\neu quem inventou\011as questões!\012…Elas foram fáceis\ndemais para você?\012Bem, mas tarde\nnós conversamos!",
  ["28:5488"] = "Estou feliz pois\nmais pessoas estão\012participando do\nprograma da SENHA.\012Mas quando PIKACHU\nfoi a senha,\012foi algo… nossa…\ngigantesco.\012Pessoas de FÃS\nCLUBES vieram aos\012montes, gritando\n'PIKACHU!' mais\012e mais. E digo,\nforam barulhentos.\012Qualquer um que\nsintonizou deve\012ter ficado chocado\ndevido à comoção!\012De qualquer modo,\ntenho que voltar\011ao trabalho!\012Conversaremos de\nnovo mais tarde!",
  ["28:55de"] = "Adivinhe só?\nO DIRETOR DA TORRE\012DE RÁDIO é um gra-\nda fã da TV!\012Hã um tempo, um\nprograma de moda\012na TV disse que\nternos pretos\011estavam na moda.\012Agora ele só veste\nternos pretos.\012Mas é segredo que\nnosso DIRETOR é\012um fã da TV, então\nse você o vir,\012nem ouse mencionar\nisso!\012Oh! O DIRETOR lo-\ngo estará aqui!\012Até depois!\nSintonize no meu\011programa!",
  ["28:5717"] = "{PLAYER}, conte-me.\012Quando você relaxa\nmais?\012Para mim, tem que\nser no estúdio\012logo após meu\nprograma, me de-\012liciando com uma\nboa xícara de chá.\011É tão agradável\012que gradualmente\nvai me relaxando…\012… … …\012… … …Zzz\012Opa, eu cochilei\nsó de pensar\012nisso! Que, hmm…\nconstrangedor!\012Por favor esqueça\nque isso ocorreu!\011Até depois!",
  ["28:583d"] = "{PLAYER}, qual foi\no primeiro #MON\011que capturou?\012…Oh, sério?\012Já vi vários\n#MON por aí,\012mas nunca capturei\num.\012Eu deveria tentar\num dia.\012Sabia que o\nprimeiro #MON\012que MARY capturou\nfoi um DROWZEE?\012Não é bem\nincomum?\012Mas o DROWZEE de\nMARY a fazia\012dormir no traba-\nlho, então ela\012o trocou com um fã\npelo MEOWTH.\012Vamos conversar\nsobre #MON\011de novo!\012Tchau tchau!",
  ["28:59b1"] = "Adivinhe só? Todos\nnós da TORRE DE\012RÁDIO estamos indo\nnumas férias da\012empresa à TORRE\nDE RÁDIO em\011LAVENDER.\012Estamos gastando\nnossas férias em\012uma viagem a outra\nTORRE DE RÁDIO?\012Eu preferiria ir\nà praia!\012{PLAYER}, espero\nque você tenha\012diversão o bastan-\nte para nós dois\011em sua jornada!\012Tchau tchau!",
  ["28:5ac0"] = "Você sabia…?\012BEN e FERN falam\nao telefone por\012horas sobre qual\nmúsica #MON\012eles devem tocar\nem diferentes\011dias da semana.\012Uma vez, o estilo\nrap de FERN\012irritou BEN \nestranhamente.\012Então acabamos\naguentando as\012reclamações e\nos resmungos do\011BEN por um tempo.\012Mais tarde nos\nfalamos de novo!",
  ["28:5bed"] = "Vou fazer compras\ncom MARY e LILY\011em breve.\012Seria ótimo\nse a LOJA DE\012DEPARTAMENTOS DE\nGOLDENROD fizesse\011uma promoção\011quando formos lá…\012{PLAYER}, talvez\npossamos ir\011juntos!\012Até depois!",
  ["28:5c88"] = "Estou pensando em\nir à CASA DE\012JOGOS amanhã.\nJá faz tempo que\011não vou.\012Sabe, tenho minha\nmáquina favorita…\012Ela paga muito,\né verdade!\012Hã? Não, não, é\nmeu segredo!\012Você tem que\nachá-la sozinho!\012Até depois!",
  ["28:5d5f"] = "Ei, {PLAYER}. Você\nusa sua #GEAR\012para escutar ao\nrádio, certo?\012Soube que você\ntambém pode ver\012mapas de cidades\ncom a #GEAR.\012Tenho um senso de\ndireção ruim,\012então a #GEAR\nseria útil…\012De qualquer modo,\nobrigada por\011ligar!\012Até depois!",
  ["28:5e2f"] = "O dia hoje está\nensolarado?\012Quando se passa\nmuito tempo na\012TORRE DE RÁDIO\ncomo eu, se perde\012contato com o\011mundo exterior.\011Pode ser chato.\012Ligue de novo!",
  ["29:4000"] = "A propósito, sou\num ANDARILHO, e\012geralmente vou a\nmontanhas e caver-\011nas.\012Eu às vezes vejo\n#MON raros.\012Eu poderia ligar\npara você quando\011eu vir um.\012Quer trocar núme-\nros de telefone?",
  ["29:40a9"] = "Eu poderia ligar\npara você quando\011eu vir um.\012Quer trocar núme-\nros de telefone?",
  ["29:40f8"] = "Seja paciente.\nVou achar #MON\011raros para você!",
  ["29:4126"] = "Você é frio. É\nmelhor eu ir às\011montanhas…",
  ["29:4158"] = "Seu telefone está\ncheio.\012Não posso regis-\ntrar meu número de\011telefone.",
  ["29:418d"] = "Tudo bem!\012Meus #MON e eu\nprecisamos ir!",
  ["29:41c0"] = "Daqui, eu posso\nver a LOJA DE\011DEPARTAMENTOS DE\012GOLDENROD. Eles\ntêm promoções na\012cobertura com\nfrequência.\012Eu poderia pegar\nseu número de\011telefone?\012Eu vou te ligar\nquando tiver uma\011promoção.",
  ["29:426a"] = "Se você me der\nseu número de\011telefone, eu vou\012te ligar quando\nhouver uma pro-\011moção.",
  ["29:42ab"] = "Eu vou à LOJA DE\nDEPARTAMENTOS DE\011GOLDENROD todos os\012dias, então eu\nsei quando tem\011uma promoção.",
  ["29:42f2"] = "De qualquer modo…\012Se você tiver pou-\nco dinheiro, pe-\011gue meu número.\012Vou te ligar\nquando houver uma\011promoção.",
  ["29:434a"] = "Seu telefone não\ntem memória sufi-\011ciente para mais\011números.",
  ["29:4382"] = "Eu esperei por\nvocê!\012Até interrompi mi-\nnhas compras para\012criar melhor meu\n#MON!",
  ["29:4405"] = "Sempre que eu vejo\num treinador for-\012te, desejo ser\nsua torcedora.\012Quando estou na\nminha caminhada,\011às vezes eu pego\011itens.\012Se eu pegar algo,\neu lhe darei!\012Quer me dar seu\nnúmero?\012Vou telefoná-lo\nquando eu obtiver\011alguma coisa.",
  ["29:44db"] = "Se eu pegar algo,\nlhe darei!\012Quer me dar o seu\nnúmero?",
  ["29:451d"] = "Vou telefoná-lo\nquando eu obtiver\011alguma coisa.",
  ["29:4542"] = "É isso? Bem,\neu ainda vou\011procurá-lo!",
  ["29:4573"] = "Mas eu telefone\njá está cheio!",
  ["29:4595"] = "Estive esperando!\012Fiquei bem melhor\nnisso!",
  ["29:45c9"] = "Você finalmente\nestá aqui!\012Acho que isso\nvai alegrá-lo.",
  ["29:4603"] = "Sua BOLSA está\ntoda cheia.\012Tenho que guardar\nisso.",
  ["29:4642"] = "Você é o melhor\ntreinador com\011quem eu já bata-\011lhei!\012Hã? Você é quem\nsalvou todos os\011SLOWPOKE?\012Bem, certamente\neu não poderia\011derrotá-lo!\012Tudo bem em\npegar seu número?\012Não quero perder\nnada do que você\011faça a partir de\011agora!",
  ["29:470b"] = "Vai me contar seu\nnúmero de telefo-\011ne?",
  ["29:4730"] = "Uau! Nossa,\nobrigado!\012Agora posso te\nligar a qualquer\011hora, estando bem\012ou não. Sabe, só\npara conversar!",
  ["29:4794"] = "Oh, mas…\nNão sou perigoso!\012Só quero ligar\ne conversar sobre\012tudo e nada!",
  ["29:47eb"] = "Sua lista de\ntelefones já está\011cheia…\012Você deve ser\npopular mesmo…",
  ["29:4829"] = "Você percebe que\nhá mais #MON\011raros ao redor?\012Eu sei que há,\nentão procuro\011o tempo todo.\012Se eu achar um,\nquero dividir a\012boa notícia com\nalguém que eu\011conheça.\012Eu sei! Dê-me\nseu número de\011telefone.",
  ["29:48fc"] = "Quero deixar as\npessoas saberem\011se eu vi um\011#MON raro.\012Por favor me dê\nseu número de\011telefone!",
  ["29:494d"] = "Se eu vir algum\n#MON incrível,\012certamente eu\nvou te ligar!",
  ["29:498a"] = "Ahh! Eu quero con-\ntar a alguém as\011minhas descober-\011tas!",
  ["29:49bd"] = "Não há espaço para\no meu número.\012Se você liberar\nespaço, me\011registre!",
  ["29:49fc"] = "Agora é minha vez\nde vencer!\012Eu virei uma\nnova página!",
  ["29:4a31"] = "Ler textos geral-\nmente é útil.\012Quando estou an-\ndando e lendo,\011eu olho para o\011chão.\012Então eu notei\nitens no chão.\012Na próxima vez\nque eu achar\011algo, vou dá-lo\011para você\012Posso ter seu\nnúmero de tele-\011fone?",
  ["29:4b03"] = "Se eu achar algo,\ndou dá-lo para\011você.\012Então posso ter\nseu número de\011telefone?",
  ["29:4b47"] = "Vou te ligar\nquando eu achar\012algo. Pode contar\ncom isso!",
  ["29:4b87"] = "Oh… Eu achei que\nseria um bom\012descanso te ligar\nquando estou es-\011tudando…",
  ["29:4bcd"] = "Não há espaço\npara meu número.",
  ["29:4bec"] = "Eu esperei por\nvocê!\012Estou perfeita-\nmente preparado\011hoje!",
  ["29:4c24"] = "Isto, isto! Isto\né seu! Ta-da!",
  ["29:4c47"] = "Opa!\012Você não pode\ncarregar mais\011itens!\012Vou guardá-lo para\na próxima vez.",
  ["29:4c8c"] = "Você é realmente\nbom com #MON!\012Os garotos me dão\nitens após as ba-\011talhas, mas às\012vezes eles exage\nram.\012Na próxima vez, eu\ndividirei uns se\012você quiser.\nDeixe-me pegar seu\011número de tele-\011fone.",
  ["29:4d36"] = "Vou dividir meus\nitens com você.\012Deixe-me pegar seu\nnúmero de tele-\011fone.",
  ["29:4d72"] = "Da próxima vez que\num garoto me der\012algo após uma\nbatalha, eu vou\011dividir!\012Isso me torna\nruim?",
  ["29:4dcd"] = "Ahh, você não\nquer nada?\012Mas é tudo de\ngraça…",
  ["29:4e01"] = "Mas seu telefone\nestá sem memória!",
  ["29:4e21"] = "Você está bem\natrasado!\012Estou ancioso para\ncomeçar!",
  ["29:4e4c"] = "Oi! Você está\naqui para pegar\011seu item?\012Isso realmente\ndeve agradá-lo!",
  ["29:4e8f"] = "Onde você vai\ncolocar isso?\012Eu vou guardar\npara depois você\011vir pegar!",
  ["29:4ed4"] = "Hã? Essa coisa é\numa #DEX? Você\011conheceu o PROFES-\011SOR CARVALHO?\012Hã? Conheceu? \nQue legal!\012Meu sonho é me\ntornar um pesqui-\012sador #MON como\nPROFESSOR CARVA-\011LHO.\012Eu poderia pegar\nseu número de\011telefone?\012Nós devemos con-\nversar sobre o\011PROFESSOR CARVA-\011LHO.\012Estou certo que\nserá bem legal!",
  ["29:4fc8"] = "Posso pegar seu\nnúmero de tele-\011fone?\012Nós devemos con-\nversar sobre o\011PROFESSOR CARVA-\011LHO.\012Estou certo que\nserá bem legal!",
  ["29:502e"] = "Você deve escutar\nao SHOW DO CAR-\011VALHO, certo?",
  ["29:505f"] = "Oh… Eu queria ter\numa chance de co-\011nhecer o PROFESSOR\011CARVALHO…",
  ["29:508c"] = "Sua lista de te-\nlefone está toda\011cheia!",
  ["29:50b1"] = "Estive esperando!\nVamos batalhar\011agora!",
  ["29:50d5"] = "Oh, uau! PIKACHU!\nÉ tão macio e\011peludo! Que lindo!\012Vamos ser amigos!\nAmantes de PIKACHU\011nunca são más\011pessoas!\012Vamos conversar\nsobre PIKACHU!\012Posso pegar seu\nnúmero de tele-\011fone?",
  ["29:5175"] = "Vamos conversar\nsobre PIKACHU!\012Posso pegar seu\nnúmero de tele-\011fone?",
  ["29:51ac"] = "PIKACHU é o que\nhá! Se algo ocor-\012rer, eu vou te\nligar.",
  ["29:51ee"] = "Você…\012Aposto que nem\ngosta de PIKACHU…",
  ["29:5216"] = "Espere um pouco!\nSua lista de te-\011lefone está cheia!",
  ["29:523a"] = "Estive procurando\npor você! Ei, vê\011isso? É isso!\012Estou certo que\nseu PIKACHU amará\011meu item também!",
  ["29:52a0"] = "Opa, que pena.\nVocê não tem\012espaço. Volte\noutra hora.",
  ["29:52e2"] = "Ei, você está ten-\ntando ser o melhor\012treinador também?\nEntão somos com-\011panheiros!\012Se eu achar mais\nitens na água,\011vou te dar uns.\012Apenas me dê seu\nnúmero de tele-\011fone.",
  ["29:5383"] = "Se eu achar mais\nitens na água,\011vou te dar uns.\012Apenas me dê seu\nnúmero de tele-\011fone.",
  ["29:53de"] = "Irei avisá-lo\nse eu encontrar\011algo de bom.",
  ["29:5412"] = "É isso? Então\nvai ficar tudo\011para mim.",
  ["29:5446"] = "Sua lista de te-\nlefone está cheia.\012Volte ao liberar\nespaço.",
  ["29:548c"] = "Eu estava fa-\nzendo mais coisas\012do que pescar\ndesde o nosso úl-\011timo encontro.\012Você vai ter uma\ngrande surpresa!",
  ["29:54e3"] = "Ei, aí está\nvocê!\012Aqui está o item,\ncomo eu prometi!",
  ["29:5513"] = "Sua BOLSA está\ncheia?\012Volte aqui depois\nque liberar es-\011paço.",
  ["29:5545"] = "A propósito, você\né um #MANÍACO…\012Posso dizer.\nSim, você é.\012Mas seu conheci-\nmento é básico\011ainda!\012Você conhece BILL?\nEle é um incrível\012#MANÍACO.\nEu o reverencio.\012Vou ensiná-lo tudo\nque sei sobre o\012BILL, então me\ndê seu número de\011telefone.",
  ["29:5621"] = "Vou ensiná-lo tudo\nque sei sobre o\012BILL, então me\ndê seu número de\011telefone.",
  ["29:5666"] = "BILL--ele é mais\nque incrível!\012Ser um #MANÍACO\ncomo ele um dia…\012Este é meu sonho.",
  ["29:56b6"] = "Você vai se\narrepender…\012E eu não vou\nme importar…",
  ["29:56e2"] = "Hã? Sua lista de\ntelefone está\011cheia.\012Um #MANÍACO\ndeve ser mais\011organizado!",
  ["29:571e"] = "Estive esperando.\012Olhe, confira meu\n#MON!",
  ["29:574a"] = "Oi! Você gosta de\nCLEFAIRY também?\012Elas são lindas,\nnão acha?\012Acho que podemos\nser bons amigos!\012Quero saber seu\nnúmero de tele-\011fone!\012Vamos conversar\nsobre CLEFAIRY!",
  ["29:57e3"] = "Quero saber seu\nnúmero de tele-\011fone!\012Vamos conversar\nsobre CLEFAIRY!",
  ["29:5820"] = "Minha CLEFAIRY não\né super-adorável?",
  ["29:5842"] = "Ahh… Oh bem.\nProcure-me se qui-\012ser conversar\nsobre CLEFAIRY.",
  ["29:5881"] = "Oh? O registro do\nseu telefone está\011cheio.",
  ["29:58a3"] = "Aí está você!\012CLEFAIRY, quero\nque se esforce!",
  ["29:58d5"] = "Você demorou\nmuito. Vê isso?\012Não é lindo?\nÉ um ARCO ROSA.",
  ["29:5914"] = "Opa. Sua BOLSA\nestá lotada.",
  ["29:5937"] = "Sabe, você é\nforte mesmo.\012Mas eu não quero\napenas fugir…\012Já sei! Posso pe-\ngar seu número?\012Vamos nos encon-\ntrar para bata-\011lharmos mais!",
  ["29:59bc"] = "Quero batalhar com\ntreinadores fortes\011sempre quando eu\011puder!\012Posso pegar seu\nnúmero?\012Vamos nos encon-\ntrar para bata-\011lharmos mais!",
  ["29:5a28"] = "Não se esqueça de\nvir me ver quando\011eu desafiá-lo!",
  ["29:5a5a"] = "Um amigo usuário\nde pássaros não\011é algo ruim de\011ter, eu acho…\012Não vai recon-\nsiderar?",
  ["29:5aa6"] = "A memória do seu\ntelefone está\011cheia. Apague um\011número para mim!",
  ["29:5ada"] = "Estou feliz em\nvê-lo! Não per-\011derei!",
  ["29:5aff"] = "Oh, que pena.\nVocê não tem\011espaço.\012Vou ter dar o\nitem na próxima\011vez!",
  ["29:5b3f"] = "Você é muito,\nmuito forte!\012Agradeço-lhe pelos\nfrequentes desa-\011fios. Eu aprendi\011muito com você.\012Já sei! Isso vai\nservir de agra-\011decimento!",
  ["29:5bc4"] = "Eh, nossa batalha\ndivertida, para\011mim…\012Quando pesco, às\nvezes esbarro com\012itens que pessoas\ndeixaram cair.\012Você os quer?\nQual é o número?",
  ["29:5c4b"] = "Se eu encontram um\nitem enquanto eu\011estiver pescando,\012ele será seu.\nQual é o seu\011número?",
  ["29:5c8e"] = "Se eu encontrar\nalgo de bom, eu\011certamente vou\011informá-lo.",
  ["29:5cc5"] = "Tudo bem… Volte\nse tiver mudado\011de opinião.",
  ["29:5cfa"] = "Você não pode\nregistrar outro\011número.",
  ["29:5d1d"] = "Argh! Você assus-\ntou POLIWAG e o\011fez fugir de novo!",
  ["29:5d4d"] = "Então está aí.\012Vê isso?\nEu o encontrei\012há pouco tempo.\nAgora é seu.",
  ["29:5d9a"] = "Sua BOLSA está\ncheia?\012Vou te dar\ndepois.",
  ["29:5dc6"] = "Nossa batalha foi\nextraordinária!\012Quero alguma\ncoisa para eu\011me lembrar de\011você!\012Talvez seu número\nde telefone?\012Meu treinamento me\nimpossibilita de\011conversar muito,\011porém…",
  ["29:5e63"] = "Meu treinamento\ndificulta muito\011conversar, mas\012você vai pegar\nmeu número?",
  ["29:5ea8"] = "Eu devo treinar\nduro para me\011tornar o mais\011poderoso!",
  ["29:5ed6"] = "Se decidir ficar\ncom meu número,\011venha me ver.",
  ["29:5f06"] = "Seu telefone pa-\nrece estar cheio.\012Volte depois!",
  ["29:5f37"] = "Quero agradecê-\nlo, {PLAYER}!\012Eu estive trei-\nnando sozinho…\012Fiquei feliz por\nvocê ligar…\012Eu quero que\nleve isso!",
  ["29:5faa"] = "Sua força não\npermite que você\012leve outra coisa!\nVou guardar isso\012até você esvaziar\num pouco a sua\011BOLSA!",
  ["29:600c"] = "Nossa, o modo\nque atacou! Foi\012incrível! Devemos\nnos encontrar de\011novo!\012Que tal me dar\nseu número?",
  ["29:6076"] = "Então quer regis-\ntrar meu número\012de telefone para\noutra batalha, né?",
  ["29:60b5"] = "Vou te ligar\nsempre quando\011eu quiser ba-\011talhar!",
  ["29:60e2"] = "Não? Está certo.\012Uma decisão não\né facil de tomar!\012Estarei bem aqui\nquando você esti-\011ver pronto para\011outra batalha.",
  ["29:6144"] = "Oh? Não há espa-\nço para registrar\011meu número de\011telefone.",
  ["29:6175"] = "Ei, aí vem o\nmenino! Vamos lá!\012Pronto para o\nmeu usual sem-\011cérebro e muita-\011ofensiva?",
  ["29:61c9"] = "Sua BOLSA parece\nestar estufada!\012Você não pode\npegar isso\011agora.",
  ["29:6200"] = "Bem, você está\ntodo certo.\n\012Se eu tivesse\ncomeçado a mexer\011com #MON quando\011eu era um pouco\011mais jovem…\012Quero que você\ntrabalhe e ajude\012a nós dois.\nEntão leve isso,\011certo?",
  ["29:6295"] = "Eu realmente me\nirrito quando\011perco.\012Eu tenho que\ntreinar mais…\012Eis o meu número.\nSou ERIN--não\012esqueça! Quer\nbatalhar de novo?",
  ["29:6316"] = "Quero batalhar\ncom você de novo.\012Você quer trocar\nnúmeros?",
  ["29:6359"] = "Vou me lembrar de\nte ligar quando\011eu quiser batalhar\011de novo!",
  ["29:638c"] = "Oh… Estou triste…\nSe quiser bata-\012lhar, venha ver\nERIN--sou eu!",
  ["29:63cc"] = "Oh não. Seu tele-\nfone está cheio.",
  ["29:63f1"] = "Ei! Eu esperei!\nVamos começar\011agora!",
  ["29:6411"] = "Que pena! Você\nnão tem espaço…\012Vou dá-lo a\nvocê outra hora.",
  ["29:6454"] = "Ahh… Eu perdi\nde novo!\012Imagino quantas\nvezes eu já…\012Obrigado por vir!\nEis um presente!",
  ["5d:4000"] = "Olá, {PLAYER}!\nAs vendas das\nBICICLETAS subiram\012muito, estamos até\no teto com tantas\nencomendas!\012Nós devemos tudo a\nsua propaganda\012andando por aí com\na nossa BICICLETA.\012Como forma de nós\nagradecermos você,\012a BICICLETA agora\né sua.\011Muito obrigado!",
  ["5d:40c0"] = "My {STRBUF}'s\nintelligence keeps\012rising. It might\nbe smarter than\011yours!",
  ["5d:4106"] = "The other day, I\neasily defeated a\011{STRBUF}.\012I think swapping\ntips with you is\011starting to help.",
  ["5d:4165"] = "Oh, and listen.\nI missed catching\012a {STRBUF} by\njust a tiny bit.\012If I'd been a bit\nmore informed, I'm\012sure I would've\ncaught it…",
  ["5d:41e1"] = "Do you want to\nbattle? I'll show\012you how to battle\nlogically.\012I'll be in\n{STRBUF}.\012Give me a shout if\nyou're nearby.",
  ["5d:4251"] = "Até mais!",
  ["5d:4261"] = "Você sabia?\012Quando chove, o\nTROVÃO certamente\011acertará.",
  ["5d:429d"] = "Você sabia…?\012Se você usar o\nROLODEFENSOR,\012o poder do ROLAR\naumenta.",
  ["5d:42ee"] = "Você sabia…?\012Se a luz solar\nestiver forte, o\012RAIO SOLAR não\nprecisa de ser\011carregado.",
  ["5d:4340"] = "Você sabia…?\012Se o oponente\nusar o MINIMIZAR,\012o ESTOURO se\nfortalece.",
  ["5d:4391"] = "Você sabia…?\012Se seu oponente\nestiver VOANDO,\012a VENTANIA fica\nbem mais forte.",
  ["5d:43e3"] = "Você sabia…?\012Se seu oponente\nestiver VOANDO,\012o CICLONE fica\nmais poderoso.",
  ["5d:4433"] = "Você sabia…?\012Se seu oponente\nusar o CAVAR,\012o TERREMOTO fica\nmais poderoso.",
  ["5d:4485"] = "Você sabia…?\012Se seu oponente\nusar o CAVAR,\012a MAGNITUDE fica\nmais forte.",
  ["5d:44d6"] = "Você sabia…?\012Os tipos pedra,\nterra e aço não\012podem ser feridos\npelo AREIAL.",
  ["5d:4522"] = "Você sabia…?\012A a luz solar\nestiver forte,\012os golpes do tipo\nágua ficam mais\011fracos.",
  ["5d:4571"] = "Você sabia…?\012Quando chove, os\ngolpes do tipo\012fogo ficam mais\nfracos que de\011costume.",
  ["5d:45c2"] = "Meu amigo ouviu\nmuitas dicas boas.\012Ele vai me deixar\nsabendo.\012Quando ele me\ncontar, eu vou\011telefoná-lo e\011contá-lo.",
  ["5d:4638"] = "Hey, {PLAYER}!\012Do you remember\nyour promise?\012We have to battle\nsoon!\012I'll be at\n{STRBUF}.",
  ["5d:4688"] = "I fancied up my\n{STRBUF} and\012made it even cuter\nthan before!",
  ["5d:46c3"] = "Eu recentemente\nme encontrei com\011um SNUBBULL sel-\011vagem.\012Meu SNUBBULL, eu\nte garanto, era\012bem mais bonito\nque o selvagem.",
  ["5d:4734"] = "I happened to see\na wild MARILL the\012other day.\nOr so I thought.\012A closer look\nshowed it was\012{STRBUF}. I was\nquite miffed.",
  ["5d:47ac"] = "Você pode es-\nperar uma li-\011gação de mim.",
  ["5d:47cc"] = "My husband got\nsome NUGGETS.\012If you'd like, you\ncould have one as\012thanks for helping\nme out.\012I'll be at\n{STRBUF}.\012Please come see me\nwhen you can.",
  ["5d:485b"] = "Seus #MON\nestão em suas\011melhores formas?\012Vamos conversar\nsobre #MON\011de novo.",
  ["5d:4895"] = "Pardon?\nOh, the NUGGET?\012There's no need to\nhurry. Come see me\012in {STRBUF}\nwhen you can.",
  ["5d:48ea"] = "Hey, I challenge\nyou to a battle!\012It won't be like\nlast time!\012{STRBUF}'s\nwhere I'm waiting\012for you. Hustle\nover here pronto!",
  ["5d:4962"] = "Até depois!",
  ["5d:496b"] = "Nós devemos ba-\nlhar de novo em\011outra hora.\012Fique sabendo que\no desafiarei até\012eu vencer.",
  ["5d:49c7"] = "Hey, you'd better\nnot have forgotten\011about our battle!\012{STRBUF}!\012Hustle over quick!\nI'm waiting!",
  ["5d:4a24"] = "My {STRBUF}\nmight be greater\011than I imagined.\012I doubt I'll see a\n{STRBUF} that's\011better than mine.",
  ["5d:4a80"] = "Oh, e eu pude\nderrotar um\012{STRBUF} com\ndificuldade em\011um dia desses.\012Eu nunca vi um\n{STRBUF} fi-\011car tão forte…\012Eu não deveria\nter baixado a\011guarda, mesmo com\012um #MON que\nestou acostumado\011a ver.",
  ["5d:4b2d"] = "And a while back,\nI tried to catch a\011wild {STRBUF}.\012But it managed to\nelude me.\012One wrong decision\ncould mean total\012failure… You ought\nto be careful too.",
  ["5d:4bc5"] = "Let's battle!\012I'll be waiting on\n{STRBUF}.\012Give me a shout\nwhen you're close.",
  ["5d:4c0e"] = "Certo, em breve\nconversarei com\011você!",
  ["5d:4c29"] = "Estou obcecado\nem derrotá-lo.",
  ["5d:4c49"] = "{PLAYER}, why\naren't you here?\012I'll take you down\nwith {STRBUF}!",
  ["5d:4c7f"] = "Do you remember my\nsweet {STRBUF}?\012{STRBUF} runs\nvery fast.\012It's exhilarating\nto ride on its\012back when it\nreally gets going.",
  ["5d:4cf6"] = "Oh, have you ever\nseen a {STRBUF}\011before?\012I just battled\none…\012It was much faster\nthan I expected.\012I was a little\nshocked.\012I still won, of\ncourse.",
  ["5d:4d86"] = "Oh, acabei de ver\num {STRBUF}\011selvagem.\012Eu estava tentando\npegá-lo quando\011notei que estava\011sem POKé BOLAS.\012Se não checar\nseus itens, você\012pode ficar sem\nna pior hora.\012Espero que você\naprenda com meu\011erro.",
  ["5d:4e4e"] = "Você quer uma ba-\ntalha? Eu vou ven-\011cer dessa vez!\012Vou te esperar nas\nredondezas da\012{STRBUF}.\nMe procure ok!",
  ["5d:4eb7"] = "Certo, tchau-\ntchau!",
  ["5d:4ec5"] = "Vamos batalhar\nde novo em outra\011hora!",
  ["5d:4ee2"] = "Um… {PLAYER}?\nWhat's wrong?\012Did you forget our\ndeal?\012{STRBUF}.\012That's where I'm\nwaiting.",
  ["5d:4f2f"] = "Hey listen, my\n{STRBUF}'s stick\012has this really\ndelicious aroma.\012That aroma gets my\nappetite going!",
  ["5d:4f90"] = "A while ago, my\nFARFETCH'D KO'd\011this {STRBUF}.\012You should have\nseen FARFETCH'D\012wield that stick.\nAmazing stuff!",
  ["5d:4ffd"] = "I ran into a wild\n{STRBUF}…\012I was trying to\ncatch it, but it\012took off faster\nthan I thought it\012would. It was a\nbit disappointing.",
  ["5d:507d"] = "Want to battle\nagain?\012For some reason,\nmy FARFETCH'D is\012all worked up and\nraring to go.\012{STRBUF}'s\nwhere I'm at.\012Keep an eye out\nfor me, OK?",
  ["5d:5106"] = "Vejo-o em breve!",
  ["5d:5116"] = "My FARFETCH'D had\nsomething pretty\011in its beak.\012Like I promised,\nyou can have it.\012Catch up to me on\n{STRBUF},\012and I'll let you\nhave it.",
  ["5d:519b"] = "Eu ainda não\ntenho o que lhe\011prometi.\012Vou telefoná-lo\nquando eu obtê-lo,\012então você poderia\nesperar mais um\011pouco?",
  ["5d:520a"] = "{PLAYER}, could you\nhurry over?\012FARFETCH'D is\nagitated.\012If you don't come\nsoon, it might\012smack me with its\nstick!\012{STRBUF}!\012Please come as\nsoon as you can!",
  ["5d:52f5"] = "Listen, dear…\012Do you recall my\n{STRBUF}?\012Yes, exactly. That\nlovely {STRBUF}.\012Wouldn't you agree\nit's a perfect\011match for me?",
  ["5d:536b"] = "Have I ever faced\na wild {STRBUF}?\012You need to ask?\012{STRBUF} I've\nbeaten on numerous\011occasions!",
  ["5d:53c5"] = "Se já falhei na\ncaptura de um\011#MON selvagem?\012Precisa perguntar?\012Eu nunca falharia\npara capturar\012um {STRBUF}\nselvagem…\012Oh! Nem pensar!",
  ["5d:543a"] = "We are going to\nbattle!\012The place shall be\n{STRBUF}!\012Don't make me\nwait! Got it?",
  ["5d:5488"] = "Certo, você pode\nir.",
  ["5d:549b"] = "Não se orgulho\nsó porque ocorreu\012de me derrotar…\nFoi pura sorte!",
  ["5d:54e5"] = "What are you\ndoing?\012I told you that\nthe place was\012{STRBUF}!\nDon't try to run!",
  ["5d:5530"] = "Meu {STRBUF}\nparece estar me-\011lhor do que antes!\012Duvido que haja um\n#MON legal como\012esse na sua\nequipe!",
  ["5d:5591"] = "Oh yeah, I took\ndown a {STRBUF}\012in the wild the\nother day.\012It was a cakewalk.\nWell, I guess it\012can't be helped,\nus being so tough.",
  ["5d:5611"] = "Oh yeah, I saw a\nwild {STRBUF}!\012I thought about\ngoing for it, but\012I decided to work\nwith my one-and-\012only right to the\nextreme end.",
  ["5d:5693"] = "Let's get together\nand battle!\012I promise things\nwill be different!\012{STRBUF}'s\nwhere I'll be.\012Give me a shout\nwhen you come.",
  ["5d:570a"] = "Certo. Até depois!",
  ["5d:571d"] = "I'm checking out\n{STRBUF}'s moves\012and devising some\nstrategies.\012When I come up\nwith a good one,\011let's battle!",
  ["5d:5786"] = "What's keeping\nyou, {PLAYER}!\012Let's get down and\nbattle already!\012I'm waiting on\n{STRBUF}!",
  ["5d:57d4"] = "Seus #MON\nestão crescendo?\012Meus #MON\nestão crescendo\012rápido demais\npara mim.\011É espantoso!\012{STRBUF} é\no que mais cresce.\012Acho que ele\nserá forte.",
  ["5d:5869"] = "Oh yeah, we KO'd a\nwild {STRBUF}\012with one hit a\nwhile back.\012It went down so\neasily, I felt a\012little sorry for\nthe poor thing.",
  ["5d:58e4"] = "Oh sim, um selva-\ngem {STRBUF}\012escapou de mim no\núltimo segundo.\012Sei que era um\n#MON comum…\012Mas me irrita\nsaber que ele\012fugiu quando quase\nera meu.",
  ["5d:5976"] = "Você gosta de\nbatalhas #MON?\012Não será como da\núltima vez!\012{STRBUF} é\nonde estarei.\012Informe-me quando\nchegar.",
  ["5d:59e7"] = "Até mais!",
  ["5d:59f7"] = "Hoje tem Concurso\nCaça-Inseto no\012no PARQUE NACIONAL.\012Você vai,\n{PLAYER}?\012Estou tentando\nme decidir.",
  ["5d:5a60"] = "I found all kinds\nof BERRIES. If you\012want, I'll share\nsome with you.\012I'll be waiting on\n{STRBUF}.",
  ["5d:5abe"] = "Hã? FRUTAS?\012Perdão, não achei\nnenhuma ainda.\012Telefonarei para\nvocê se eu achar.\011Você vai aguardar?",
  ["5d:5b1e"] = "Let's battle\nalready!\012{STRBUF} is\nwhere I am.\012Please get here as\nsoon as you can!",
  ["5d:5b6d"] = "How come you're\nnot here yet?\012{STRBUF} is\nwhere I am.\012Please get here as\nsoon as you can!",
  ["5d:5bc4"] = "I've been spending\nmore time with my\012{STRBUF} than I\nhave with my kids.\012That's a bit sad,\nactually.",
  ["5d:5c24"] = "I just beat a wild\n{STRBUF}.\012I told my kid, but\nhe scoffed that he\012could do the same\nthing easily.\012Boy, has he gotten\ncocky…",
  ["5d:5c9f"] = "Ontem um selvagem\n{STRBUF} fugiu\012de mim na frente\nde meu filho.\012Senti-me triste\naté ele dividir\012suas POKé BOLAS\ncomigo.\012Haha, isso me\nfez sentir um pai!",
  ["5d:5d40"] = "What do you say to\na battle with me?\012Good, you're going\nto do it!\012For a kid, you're\nquite agreeable.\012{STRBUF} is\nthe spot!",
  ["5d:5db7"] = "Você liga para\nsua mãe muitas\011vezes também!",
  ["5d:5dd9"] = "Listen, I… Yowch!\012Uh, sorry! See,\n{STRBUF} are\012biting like there\nis no tomorrow\012over here on\n{STRBUF}!\012Aiyee! Ouch!\nOne jabbed me!\012Heh, they're some\nkind of feisty!\012{PLAYER}, you have\nto see this rare\012sight! Get ready\nto fish!",
  ["5d:5eaf"] = "Sim, eu sei.\012Está procurando\n#MON raros.\012Porém, tudo que\npeguei recentemen-\011te foi MAGIKARPS…",
  ["5d:5f11"] = "So where are you?\nI'm waiting for\012you to show up on\n{STRBUF}.\012You shouldn't make\nyour elders wait!",
  ["5d:5f70"] = "Ei, qual o pro-\nblema com você?\012Você não vai vir\npara pescar um\011QWILFISH?\012Estou na ROTA 32,\nentão se apresse!",
  ["5d:5fda"] = "Oh, you have to\nhear this.\012My {STRBUF} is\nso adorable!\012It always wants to\nnuzzle me!",
  ["5d:602d"] = "And, and! Um…\012We beat a wild\n{STRBUF} with\012just one hit a\nlittle while ago.\012We felt sorry for\nit, though.",
  ["5d:6095"] = "And, and! Uh…\012We just saw a\nreally gorgeous\011{STRBUF}.\012But I was on the\nphone, so it got\012away. It made us\nreally angry!",
  ["5d:610a"] = "Hi! Do you have\nsome free time?\012I've got all sorts\nof time. If you're\012free, would you\nlike to battle?\012I'll be waiting on\n{STRBUF}.\012Let me know when\nyou get here!",
  ["5d:61a7"] = "Oi, TÂNIA. Como\nestá? Aqui é LIZ.\012Estou bem, mas\nestou entediada!\012Hã… Número errado?\nOpa! Perdão!",
  ["5d:620a"] = "Certo, depois eu\nte ligo!",
  ["5d:6223"] = "Ouça, ouça!\012Eu escutava ao\nrádio nas RUÍNAS\011ALFA quando um\011estranho sinal de\011repente cortou a\011programação normal.\012Eu queria saber\no que foi. Tão\011estranho!",
  ["5d:62c3"] = "Ouça, ouça!\012Você não acha\nFALKNER do GINÁSIO\012DE VIOLET é legal\ne bonito?\012Mas dizem que seu\npai, que está\012treinando fora, é\nainda mais legal\012e bonito que\nFALKNER.\012Eu queria poder\nconhecê-lo!",
  ["5d:638a"] = "Ouça, ouça!\012Você conhece EARL,\no professor que\012dirige a ACADEMIA\n#MON em VIOLET?\012Eu o vi fazendo\npiruetas enquanto\012corria. Era muito\nengraçado!",
  ["5d:6424"] = "Ouça, ouça!\012Eu coleciono bone-\ncos #MON de\011pelúcia.\012Mas não consigo\nobter um BONECO\012PIKACHU SURFE.\nNenhum de meus\012amigos o têm.\nDeve ser bem\012raro! Você poderia\nse gabar se tives-\011se um.",
  ["5d:64eb"] = "Ouça, ouça!\012Você conhece o\nLEITE MOOMOO?\012Pode comprá-lo na\nFAZENDA MOOMOO.\012Dizem que é bom\npara a saúde e\012beleza. Eu real-\nmente quero prová-\012lo. Aposto que\né delicioso!",
  ["5d:6599"] = "Ouça, ouça!\012Há um SALÃO #-\nMON em GOLDENROD\012que é dirigido por\ndois irmãos.\012O mais velho é\nbom, porém o mais\012jovem não é.\012Mas às vezes o\nmais jovem traba-\012lha melhor que\nseu irmão.\012Sempre que vou,\ntenho problema em\012decidir quem eu\ndevo escolher…",
  ["5d:66ac"] = "Ouça, ouça!\012WHITNEY, DO GINÁ-\nSIO DE GOLDENROD\012batalha a pouco\ntempo!\012Porém, a LIGA\n#MON a escolheu\011como LÍDER DE\011GINÁSIO!\012Aposto que ela\ntem muito talento.",
  ["5d:674f"] = "Ouça, ouça!\012Você já participou\ndo Concurso Caça-\012Inseto no PARQUE\nNACIONAL?\012Já fui uma vez,\nmas tudo que obtive\011foi um CATERPIE.\012Mas adivinhe!\012Eu venci com esse\nCATERPIE. Isso\011não é ótimo?",
  ["5d:6816"] = "Listen, listen!\012I saw a beautiful\n{STRBUF}!\012I wish I could\nbecome a beautiful\011{STRBUF} too.",
  ["5d:686d"] = "Ouça, ouça!\012Hã… Hm… Opa!\012Eu esqueci o que\neu ia dizer!",
  ["5d:68b0"] = "Listen, listen!\012My {STRBUF}…\nit… so pretty…\012and… giggle… so\nawesome… yes… but…\012very much… eeek!\nAnd… lovely…\012Just ravishing…\nOh, too much!\012…Hug it… sleeping…\nThat's right…\012pretty… sigh… So\nnice… Cute…\012…Oops! Look at the\ntime! I chatted\011too long!\012I'm sorry I took\nso much of your\012time!\nI love chatting!",
  ["5d:69da"] = "I've got too much\ntime on my hands!\012Let's battle right\naway!\012I'll be waiting on\n{STRBUF}!",
  ["5d:6a2f"] = "The other day, I\nwas watching my\012{STRBUF} eat\nsome BERRIES.\012It looked like it\nwas enjoying its\012meal, so I decided\nto try some.\012I'm not sure if\npeople should eat\012that stuff, but it\nwas delicious!",
  ["5d:6aef"] = "Lately, I've been\nrunning across\012wild {STRBUF}\nquite often.\012They're easily\ntaken care of.",
  ["5d:6b45"] = "Oh yeah, I was\nbattling this\012{STRBUF} the\nother day…\012It took off when I\ngot distracted by\011a passing BEAUTY.\012Learn from my\nmistake--always\012stay focused on\nthe job at hand!",
  ["5d:6bee"] = "Come on--let's\nbattle right now!\012{STRBUF} is\nwhere I am.\012Come on down if\nyou feel up to it!",
  ["5d:6c47"] = "Certo então!\nPassar bem!",
  ["5d:6c61"] = "{PLAYER}! É\nmagnífico!\012Eu saí de\n{STRBUF}\011ontem, vê?\012Bem, há vários\n{STRBUF} por\012aqui! Você tem\nque ver!\012Eu achava que\nos {STRBUF}\012eram tímidos.\nNunca os vejo\012onde há fortes\n#MON.",
  ["5d:6d32"] = "#MON raros?\012Ei, perdão! Estava\ntão concentrado em\012minha caminhada,\nque não prestei\011atenção.",
  ["5d:6d85"] = "Hello! You haven't\nforgotten about\012our battle, have\nyou?\012{STRBUF}!\nI'm waiting!",
  ["5d:6dd1"] = "Olá? O quê? Cadê\no DUNSPARCE?\012CAVERNA ESCURA!\nCorra!\012Sei que eu já\ndisse isso, mas\012DUNSPARCE não\naparece onde tem\012#MON fortes.",
  ["5d:6e5d"] = "My {STRBUF} is\nlooking more and\012more like me. It's\ngetting cuter!",
  ["5d:6e9c"] = "And, you know?\012Now we can KO\n{STRBUF} easily.\012I should challenge\nthe GOLDENROD GYM.",
  ["5d:6eee"] = "E você sabia?\nPor pouco não\012vencemos o\n{STRBUF}.\012Será que os níveis\nde meus #MON\012não são altos\no bastante…",
  ["5d:6f60"] = "You must be a lot\nbetter now, huh?\012How about showing\nme your technique\012in a real battle\nwith me?\012I'll be waiting on\n{STRBUF}.",
  ["5d:6fdb"] = "Até mais!",
  ["5d:6feb"] = "É isso--o que\nnós estávamos\011esperando!\012Está ocorrendo a\nliquidação na LOJA\011DE DEPARTAMENTOS\011DE GOLDENROD!\012Quer preço bom?\nQuer bastante?\012Não perca essa\nchance de OURO!\012Hã? Eu pareço um\ncamelô?\012Bem, sim. Eu os\nimitava…\012De qualquer modo,\nvocê deve ir lá\011o mais rápido\011que puder!",
  ["5d:70fb"] = "Estou me guardan-\ndo para a próxima\012promoção. Quando\nela será?",
  ["5d:7138"] = "Where are you?\012Let's have our\nbattle soon!\012I'll be waiting on\n{STRBUF}.",
  ["5d:717c"] = "Você não foi à LO-\nJA DE DEPARTAMEN-\011TOS DE GOLDENROD?\012Eu já fui lá! Eles\ntêm boas ofertas.\012Você deve ir\nlá rapidamente.",
  ["5d:71fd"] = "My {STRBUF} and\nI are getting more\012in sync with each\nother.",
  ["5d:7237"] = "We battled a wild\n{STRBUF} and\012managed to drop it\nin a close match.\012We're getting into\nthe groove!",
  ["5d:7297"] = "But, you know?\012I still haven't\ncaught {STRBUF}.\012It's getting past\nfrustrating…",
  ["5d:72e2"] = "Would you be my\npractice partner\011again sometime?\012I'll be waiting on\n{STRBUF}.\012…Could you take it\na little easier on\011me next time?",
  ["5d:7361"] = "Tchau! Em breve\nconversaremos!",
  ["5d:7378"] = "Você soube da\nEQUIPE ROCKET?\012Eles dominaram a\nTORRE DE RÁDIO\011em GOLDENROD.\012As pessoas de lá\nestão seguras?",
  ["5d:73e7"] = "I picked up some-\nthing nice today.\012I want you to have\nit, so I called!\012You will come for\nit, won't you?\012{STRBUF} is\nwhere I am.",
  ["5d:7465"] = "Perdão, eu ainda\nnão achei nada\012útil…\nEu prometo, se\012eu achar algo,\nvocê poderá ficar\011com ele!",
  ["5d:74c1"] = "Oh, {PLAYER}!\nHow soon can I\012expect to see you\nfor our battle?\012Don't forget,\n{STRBUF}!",
  ["5d:750e"] = "I'm getting really\nimpatient, waiting\012to give you my\npresent!\012Hurry over to\n{STRBUF}!",
  ["60:4178"] = "Na LIGA #MON,\nvocê será testado\011pela ELITE QUATRO.\012Você tem que\nderrotar todos\011eles.\012Se você perder,\nterá que começar\011tudo de novo!",
  ["60:41f5"] = "Espere.\012Você vai encarar o\ndesafio da LIGA\011#MON agora?\012Isso não vai\nacontecer.\012Meu #MON super\nbem treinado vai\011derrotá-lo.\012{PLAYER}!\nEu o desafio!",
  ["60:4295"] = "ABRA? Aabra…",
  ["60:42a4"] = "…Droga… Ainda não\nposso vencer…\012Eu… tenho que\npensar mais em\011meus #MON.\012Humph! Tente não\nperder!",
  ["60:42fd"] = "…\012Nossa…\nCom meus\011parceiros, serei\011o CAMPEÃO!",
  ["60:4335"] = "Ah! Você está\ndesafiando a\011ELITE QUATRO?\012Tem certeza de\nque está pronto?\012Se precisar de\nmais treino, meu\011ABRA pode\011ajudá-lo.\012Ele pode\nTELEPORTÁ-lo para\011casa.\012Deseja ir para\ncasa agora?",
  ["60:43e7"] = "Certo, certo.\nAgora imagine sua\011casa…",
  ["60:4411"] = "Certo, certo. A\nmelhor sorte para\011você!",
  ["60:4433"] = "…\012Certo, eu perdi…",
  ["60:4531"] = "Bem-vindo à LIGA\n#MON, {PLAYER}.\012Deixe-me\napresentar-me.\011Eu sou WILL.\012Eu treinei ao\nredor do mundo,\011tornando meus\011#MON psíquicos\011fortes.\012E, por último,\neu fui aceito na\011ELITE QUTRO.\012Eu só consigo\nficar melhorando.\012Perder não existe\ncomo opção!",
  ["60:462c"] = "Eu… Eu não…\nacredito…",
  ["60:4644"] = "Mesmo que eu tenha\nderrotado, eu não\011mudarei meu curso.\012Continuarei\nbatalhando até\011eu superar todos\011os treinadores!\012Agora, {PLAYER},\nande e experimente\011a verdadeira\011ferocidade da\011ELITE QUATRO.",
  ["60:4793"] = "Fwahahahaha!\012Eu sou KOGA da\nELITE QUATRO.\012Vivo nas sombras,\nsou um ninja!\012Meu estilo\nintricado vai\011confundi-lo e\011destruí-lo!\012Confusão, sono,\nveneno…\012Prepare-se para\nser vítima da\011minha técnica\011sinistra!\012Fwahahahaha!\012#MON não se\nresumem a força\011bruta--em breve\011você verá o\011motivo!",
  ["60:48a9"] = "Ah!\nVocê provou o seu\011valor!",
  ["60:48ca"] = "Eu o submeti a\ntudo que pude.\n \012Mas meus esforços\nfalharam. Eu devo\011melhorar minhas\011técnicas.\012Vá à próxima sala,\ne teste as suas\011habilidades!",
  ["60:49fe"] = "Eu sou BRUNO da\nELITE QUATRO.\012Sempre treino ao\nextremo porque\011eu acredito em\011nosso potencial.\012É assim que\nficamos fortes.\012Você poderá\nresistir ao\011nosso poder?\012Hm? Não vejo medo\nem você. Parece\011determinado.\011Perfeito para\011batalhar!\012Pronto, {PLAYER}?\nVocê se curvará\011ao nosso poder\011supremo!\012Hoo hah!",
  ["60:4b23"] = "Por quê? Como\npudemos perder?",
  ["60:4b3c"] = "Como perdi, não\ntenho direito de\011dizer nada…\012Vá enfrentar seu\npróximo desafio!",
  ["60:4c27"] = "Eu sou KAREN da\nELITE QUATRO.\012Você é {PLAYER}?\nQue divertido.\012Adoro #MON\ndo tipo escuro.\012Acho-os selvagens,\nideais para\011apelar. E eles\011são tão fortes.\n\012Acha que pode\ncombatê-los?\011Apenas tente me\011divertir.\012Vamos lá.",
  ["60:4cf8"] = "Bem, você é bom\nmesmo. Gosto disso\011em treinadores.",
  ["60:4d29"] = "#MON fortes.\012#MON fracos.\012É apenas uma\npercepção egoísta\011das pessoas.\012Treinadores\nrealmente\011habilidosos\011devem tentar\011vencer com seus\011favoritos.\012Gosto de seu\nestilo. Entendeu o\011que é importante.\012Vá--o CAMPEÃO\nestá esperando.",
  ["60:4f67"] = "LANCE: Estive\nesperando por\011você.\012{PLAYER}!\012Eu sabia que\nvocê, com sua\011técnica, poderia\011conseguir chegar\011aqui.\012Não há necessidade\nde palavras agora.\012Vamos batalhar\npara determinar\011quem de nós é o\011mais forte.\012Como treinador\nmais poderoso e\011como CAMPEÃO da\011LIGA #MON…\012Eu, LANCE, o\nmestre de dragões,\011aceito o seu\011desafio!",
  ["60:50a4"] = "…Acabou.\012Mas é\num sentimento\011estranho.\012Não estou nervoso\npor perder.\011De fato, estou\011feliz.\012Feliz pois\ntestemunhei o\011ascensão do novo\011grande CAMPEÃO!",
  ["60:5132"] = "…Nossa.\012Você ficou forte\nmesmo, {PLAYER}.\012Seus #MON\nresponderam à\011sua força e à\011sua natureza\011persistente.\012Como treinador,\nvocê continuará\011a se fortalecer\011com seus #MON.",
  ["60:51dd"] = "MARY: Oh, não!\nJá acabou!\012PROFESSOR CARVA-\nLHO, se não fosse\011tão lento…",
  ["60:521b"] = "CARVALHO: Ah,\n{PLAYER}!\012Já faz um bom\ntempo.\012Você certamente\nparece mais\011poderoso.\n\012Sua conquista da\nLIGA é fantástica!\012Sua dedicação,\nconfiança e amor\011pelos seus\011#MON fez\011isso acontecer.\012Seus #MON\ntiveram excelente\011desempenho também,\011pois acreditaram\011em você como\011treinador, foram\011perseverantes.\n \012Parabéns, {PLAYER}!",
  ["60:534b"] = "MARY: Vamos entre-\nvistar o mais\011novo CAMPEÃO!",
  ["60:537b"] = "LANCE: Isso está\nficando um pouco\011barulhento…\012{PLAYER}, poderia\nvir comigo?",
  ["60:53c5"] = "MARY: Oh, espere!\nNão fizemos a\011entrevista!",
  ["60:54a6"] = "LANCE: Já faz um\nbom tempo que\011não venho aqui.\012Aqui é onde\nhomenageamos os\011CAMPEÕES DA\011LIGA por toda\011eternidade.\012Seus #MON\ncorajosos também\011são honrados.\012Aqui hoje,\ntestemunhamos a\011ascensão do novo\011CAMPEÃO DA LIGA,\011um treinador que\011sente compaixão\011pelos #MON e\011que confia neles.\012Um treinador que\nfoi bem sucedido\011através da\011perseverança e da\011determinação.\012O novo CAMPEÃO\nDA LIGA que é\011excelente por\011completo!\n \012{PLAYER}, deixe-me\nregistrar você\011e seus parceiros\011como CAMPEÕES!",
  ["61:40bc"] = "USINA ELÉTRICA\nDE KANTO?\012É perto do fim da\nROTA 9, a estrada\011a leste daqui.\012Acho que houve\nalgum tipo de\011acidente lá.",
  ["61:4144"] = "Você está\ncoletando todo\011tipo de #MON?\012Deve ser bastante\ndesafiador, mas\011isso parece\011divertido também.",
  ["61:41a8"] = "A PENÍNSULA ao\nnorte é um\011bom lugar para\011encontros.\012As garotas adoram!",
  ["61:41e9"] = "SLOWBRO: Yarah?",
  ["61:41fa"] = "Meu SLOWBRO e\neu fazemos uma\011ótima combinação!",
  ["61:4229"] = "SLOWBRO, mostre-me\nsua CONFUSÃO!",
  ["61:424e"] = "Sou um grande\nfã da MISTY\011do GINÁSIO DE\011CERULEANA.",
  ["61:4275"] = "Vi um cara\nestranho indo\011à PENINSULA\011CERULEANA.",
  ["61:42a9"] = "Havia uma caverna\nque tinha #MON\011extremamente\011fortes nela.",
  ["61:42ee"] = "Ayuh?\012Meu BUSCA-ITENS está respondendo.",
  ["61:4312"] = "CIDADE DE CERULEAN\012Uma Misteriosa\nÁura Azul a\011Envolve.",
  ["61:4345"] = "CIDADE DE CERULEAN\012LÍDER DO GINÁSIO\n#MON: MISTY\012A Mais Bela\nSereia.",
  ["61:4381"] = "Há um aviso aqui…\012A LOJA DE\nBICICLETA se mudou\011para a CIDADE\011GOLDENROD em\011JOHTO…",
  ["61:43cc"] = "Há um aviso aqui…\012Acabar com\na Bandidagem e\011tornar a cidade\011um lugar mais\011amigável e\011animado!\012POLÍCIA DE\nCERULEANA.",
  ["61:443b"] = "PENÍNSULA CERULE-\nANA A SEGUIR.",
  ["61:4450"] = "A porta está\nfechada…",
  ["61:4523"] = "Ficamos em guarda\nnessa torre.\012Aqui, expressamos\nnossa gratidão\011em honrar os\011#MON.",
  ["61:4574"] = "O-Obrigado!",
  ["61:4583"] = "Todos seres-vivos\ncoexistem através\011de cooperações.\012Devemos ser sempre\ngratos a isso.",
  ["61:45d8"] = "Só vai obter um HM\nse chegar ao topo\011daqui.",
  ["61:460a"] = "A TORRE BROTINHO\nfoi contruída há\011muito tempo para\011o treinamento\011#MON.",
  ["61:4649"] = "Um BELLSPROUT de\nuns 33 metros…\012Dizem que ele se\ntornou o pilar\011central daqui.",
  ["61:469d"] = "Vê o pilar se\nmexendo?\012As pessoas estão\ntreinando lá em\011cima.",
  ["61:46d6"] = "Uma estátua\n#MON…\012Parece ser bem\nconhecida.",
  ["61:47a9"] = "Quanto mais\nbatalharmos, mais\011a TORRE se fixará.",
  ["61:47df"] = "Eu lutei duro, mas\nsou muito fraco.",
  ["61:47ff"] = "O pilar flexível\nprotege a TORRE,\011até de terremotos.",
  ["61:4841"] = "…Move-se como\nfolhas ao vento…",
  ["61:4861"] = "Oh, sou fraco!",
  ["61:486f"] = "Eu tentei copiar\nos movimentos do\011BELLSPROUT para\011batalhar…\012Mas não treinei o\nbastante.",
  ["61:48c8"] = "Uma estátua\n#MON…\012Parece ser bem\nconhecida.",
  ["61:4a27"] = "LÍDER: Você é\ncertamente um\011treinador\011habilidoso.\012Como prometi, aqui\nestá seu HM.\012Mas ouça: Você\ndeve tratar melhor\011seu #MON.\012O modo que batalha\né inadequado.\012Os #MON não\nsão instrumentos\011de guerra…",
  ["61:4aec"] = "…\n…Humph!\012Ele afirma ser o\nLÍDER mas ele é\011fraco.\012Ele é muito\ncertinho.\012Nunca perderei\npara bobos que se\011importam em ser\011legais com os\011#MON.\012Só ligo para\n#MON fortes\011que podem vencer.\012Eu realmente não\nme importo com\011#MON fracos.",
  ["61:4bc8"] = "{RIVAL} usou um\nCABO DE FUGA!",
  ["61:4be0"] = "Que bom que veio\naqui!\012A TORRE BROTINHO\né um local de\011treinamento.\012As pessoas e os\n#MON testam\011suas habilidades\011para construírem\011um futuro\011brilhante.\012Sou o teste final.\012Deixe-me checar os\nlaços entre seus\011#MON e você!",
  ["61:4cb2"] = "Ah, excelente!",
  ["61:4cc2"] = "Você e seus\n#MON não devem\011ter problemas para\011usar esse golpe.\012Ele esse HM,\nLUZES.",
  ["61:4d13"] = "LUZES iluminam\naté o mais escuro\011dos lugares.\012Mas para usá-lo\nfora de batalha,\011você precisa da\011INSÍGNIA do\011GINÁSIO DE\011VIOLET.",
  ["61:4d88"] = "Espero que tenha\naprendido e que\011cresça na sua\011jornada.",
  ["61:4db6"] = "Treino para achar\na luz nos\011#MON!",
  ["61:4dde"] = "Meu treinamento\nestá incompleto…",
  ["61:4dfa"] = "Quando o #MON\nfortalece, o\011treinador melhora\011também.\012Não, espere.\nQuando o treinador\011fortalece, o\011#MON melhora\011também.",
  ["61:4e60"] = "Deixe-me ver o\nquanto confia em\011seus #MON.",
  ["61:4e8a"] = "Sim, você confia\nmesmo!",
  ["61:4ea4"] = "Não está longe do\nLÍDER.",
  ["61:4ec1"] = "O HM do LÍDER\nilumina até\011lugares totalmente\011escuros.",
  ["61:4ef3"] = "É minha cabeça\nque está clara!",
  ["61:4f12"] = "Deixe haver luz em\nsua jornada.",
  ["61:4f37"] = "É uma poderosa\npintura de um\011BELLSPROUT.",
  ["61:4f61"] = "Uma estátua\n#MON…\012Parece ser bem\nconhecida.",
  ["61:5203"] = "EUSINE: Incrível!\nÉ impressionante!\012Nunca vi uma\nbatalha tão boa.\012Foi algo\ninspirador.\012O SUICUNE era\nforte, mas você\011era mais incrível\011ainda, {PLAYER}.\012Eu soube que os\npoderes místicos\011de SUICUNE invocam\011um #MON de cor\011de arco-íris.\012Talvez, talvez\nmesmo, o que\011ocorreu hoje vai\011causar a\011apararição desse\011#MON.\012Vou estudar mais as\nlendas.\012Obrigado por\nme mostrar\011essa batalha\011fantástica.\012Até outra hora,\n{PLAYER}!",
  ["61:5386"] = "De acordo com a\nlenda…\012Quando as almas\nde #MON e\011humanos se\011comunicam, do céu\011desce um #MON\011de cor de\011arco-íris…\012Poderia significar\nque o #MON\011lendário está\011testando nós\011humanos?",
  ["61:5433"] = "Quando a TORRE DE\nLATÃO queimou,\011dizia-se que três\011#MON sem nomes\011pereceram. Foi uma\011tragédia.\012Porém…\012Um #MON de cor\nde arco-íris…\012Em outras\npalavras…\012HO-OH desceu do\ncéu e deu nova\011vida aos três\011#MON.\012Eles são…\012SUICUNE, ENTEI e\nRAIKOU.\012Isso é o que\ndizem.",
  ["61:5544"] = "Dizem que as duas\nTORRES foram\011construídas para\011incentivar a\011amizade e\011confiança entre\011as pessoas e os\011#MON.\012Foi a 700 anos,\nmas os\011ideais continuam\011importantes hoje.",
  ["61:55ee"] = "HO-OH parece ter\ndescido até aqui,\011na TORRE DO SINO!",
  ["61:5629"] = "Isso vai\nprotegê-lo.\012Leve-o.",
  ["61:564a"] = "Agora, vá.",
  ["61:5654"] = "Eu acredito que\nvocê está sendo\011testado.\012Livre sua mente\nda incerteza e\011avance.",
  ["61:56a3"] = "Eu sabia.\012Eu sabia que você\nviria o #MON\011de cor de\011arco-íris,\011{PLAYER}.\012Aconteceu do modo\nque eu previ.\012Minha pesquisa\nnão está ruim,\011devo dizer.\012Continuarei\nestudando os\011#MON para me\011tornar um famoso\011#MANÍACO!",
  ["61:5765"] = "Dizem que os\n#MON lendários\011incorporam três\011poderes…\012O raio que atingiu\na TORRE.\012O fogo que queimou\na TORRE.\012E a chuva que\napagou o fogo…",
  ["61:5803"] = "Quando os\n#MON lendários\011apareceram…\012Eles assustaram\naqueles que os\011viram surgir.\012E…\012Muitos até\ntentaram ataques\011fúteis.\012Os #MON\nlendários, sabendo\011de seus poderes,\011fugiram, ignorando\011as pessoas\011assustadas.",
  ["61:58d0"] = "A respeito\ndos #MON\011lendários, é dito\011que SUICUNE é o\011mais próximo de\011HO-OH.\012E que também há\num #MON de\nligação chamado\011de UNOWN.\012O #MON UNOWN\ndeve estar\011dividindo uma\011ligação cooperada\011com SUICUNE.",
  ["61:5cd9"] = "… … …\012…Oh, é você.\012Eu vim procurar\npor alguns\011#MON lendários\011que moram aqui,\011como dizem.\012Mas não há nada\naqui!\012Nada após todos\nproblemas para\011chegar a esse\011lixo? De modo\011algum!\012A culpa é toda\nsua!",
  ["61:5d9b"] = "…Humph!\012É por isso que\nodeio batalhar com\011bobos.\012Não há desafio\nalgum.",
  ["61:5de2"] = "…Ah, seja o que\nfor.\012Você nunca será\ncapaz de capturar\011um #MON\011lendário mesmo.",
  ["61:5e2c"] = "…Humph!\012É por isso que\nodeio batalhar com\011bobos.\012É uma perda de\ntempo.",
  ["61:5e75"] = "Humph!\012O que faz\ncaindo em um\011buraco?\012Que gênio você é!\012Faz totalmente\nseu estilo!",
  ["61:5ecc"] = "EUSINE: Meu nome\né EUSINE.\012Estou procurando\num #MON chamado\011SUICUNE.\012E você é…?\012{PLAYER}? Estou\nfeliz em\011conhecê-lo!\012Ouvi boatos que\nSUICUNE está nessa\011TORRE QUEIMADA,\011então vim aqui\011procurar.\012Mas onde deve\nestar exatamente?",
  ["61:5f99"] = "EUSINE: Eu soube\nque SUICUNE está\011nessa TORRE\011QUEIMADA, então\011vim aqui procurar.\012Mas onde\nexatamente poderia\011estar?",
  ["61:6002"] = "MORTY: O LÍDER\nDO GINÁSIO DE\011ECRUTEAK tem que\011estudar os\011chamados #MON\011lendários:\012SUICUNE, ENTEI e\nRAIKOU.\012EUSINE está aqui,\nentão decidi\011investigar a TORRE\011com ele.",
  ["61:626a"] = "EUSINE: Eu cavei\num buraco, também…\012Fiquei chocado!\012SUICUNE correu\ncomo uma mancha,\011na frente de meus\011olhos!\012Por dez anos\npersegui SUICUNE,\011e eu finalmente\011pude vê-lo.\012Estou chocado!\012{PLAYER}, eu devo\ntudo isso a você!\012Obrigado!\012Eu soube do teste\ndo #MON\011lendário de\011ECRUTEAK que\011escolheu humanos\011para deixá-los se\011aproximar.\n \012Vou seguir\nSUICUNE.\012{PLAYER}, vamos nos\nver depois!\012Adeus!",
  ["62:4005"] = "Are you collecting\nKANTO GYM BADGES?",
  ["62:405a"] = "Soube que um rapaz\nsuspeito está\011anda aqui por\011perto.\012Não ficarei\nparado se ele for\011um ladrão.",
  ["62:40c3"] = "Fomos rendidos\npor bandidos no\011passado.",
  ["62:40e7"] = "DIGLETT: Dug dug.",
  ["62:414d"] = "Meu marido vive\nfeliz com os\011#MON que\011obteve em trocas.",
  ["62:418a"] = "Ah… Sou tão feliz…",
  ["62:419c"] = "KANGASKHAN: Garu\ngaruu.",
  ["62:41b5"] = "ZUBAT: Zuba zubaa.",
  ["62:4221"] = "Para batalhas,\nprefiro usar um\011#MON que treino\011há algum tempo,\011mesmo sendo fraco,\011a usar #MON\011capturados\011recentemente.",
  ["62:428c"] = "Você batalha por\ntelefone celular?\012Se o tempo acabar\ndurante a batalha,\011esperar para ver\011quem ganhou\011é realmente\011irritante.",
  ["62:42ff"] = "O TREM ÍMÃ viaja\na 544 km/h. Ele\011percorre o caminho\011entre KANTO e\011JOHTO quase sem\011gastar tempo.\012Ele realmente\ntorna JOHTO\011acessível.",
  ["62:44fb"] = "Opa! Perdoe-me!\nNão se feriu,\011certo?\012Estou muito\nocupado, sem tempo\011para conversar\011com você.\012Não é bom para mim\nser visto por\011alguém.",
  ["62:4574"] = "Oh não! Já me\nviu! Fiz um grande\011erro!",
  ["62:45a5"] = "Ei, você! Esqueça\nque me viu,\011certo?\012Não viu, ouviu\nnem sabe de nada,\011certo?\012Tchau garoto!\nNada! Adeeeus!",
  ["62:4610"] = "Perdão, sairei por\num tempo.\012MISTY, A LÍDER\nDO GINÁSIO.",
  ["62:4642"] = "Como MISTY saiu,\nsairemos também.\012TREINADORES DO\nGINÁSIO.",
  ["62:4674"] = "MISTY: Eu o\nesperava, peste!\012Você pode ter\nvárias INSÍGNIAS\011DE GINÁSIO DE\011JOHTO, mas é\011melhor me levar a\011sério.\012Meus #MON\ntipo água são\011fortes!",
  ["62:470c"] = "MISTY: Você\nrealmente é bom…\012Admitirei que é\nhabilidoso…\012Aqui está. É a\nINSÍGNIA DA\011CASCATA.",
  ["62:4768"] = "{PLAYER} received\nCASCADEBADGE.",
  ["62:4782"] = "MISTY: Há muitos\ntreinadores fortes\011em JOHTO? Digo,\011como você.\012Um dia viajarei\npara lá, então\011poderei batalhar\011com treinadores\011habilidosos.",
  ["62:480a"] = "Perdão por ter\nsaído. Vamos\011começar isso!",
  ["62:4838"] = "Desisto! Você é o\nvencedor!",
  ["62:4856"] = "Vou nadar quieta-\nmente.",
  ["62:4870"] = "Não deixe meu\nnado elegante\011irritá-lo.",
  ["62:489f"] = "Ooh, venceu-me\ncalmamente…",
  ["62:48c0"] = "Não fique tão\nalegre por me\011vencer.\012MISTY o derrotará\nse você não for\011sério.",
  ["62:4912"] = "Glub…\012Eu primeiro! Venha\nme pegar!",
  ["62:4934"] = "Não pode ser…",
  ["62:4943"] = "MISTY melhorou\nmuito nesses\011últimos anos.\012Não abaixe sua\nguarda, caso\011contrário, será\011esmagado!",
  ["62:49a7"] = "Ei! CAMPEÃO em\nprogresso!\012Como MISTY saiu,\ntambém saí para\011me divertir.\011He-he-he.",
  ["62:49fa"] = "Hoo, você me\nmostrou como é\011forte.\012Como sempre,\nessa foi outra\011batalha magnífica!",
  ["62:4acd"] = "Você encontrará\nvários treinadores\011a caminho\011da PENÍNSULA\011CERULEANA.\012Eles querem ver\ncomo se saem\011contra outros\011treinadores.",
  ["62:4b46"] = "MISTY é a única\npessoa na cidade\011que derrota\011os treinadores\011da PENÍNSULA\011CERULEANA.",
  ["62:4bf1"] = "Um CENTRO #MON\nperto da caverna?\012Isso deve ser\nútil.",
  ["62:4c26"] = "O GERENTE DA USINA\nELÉTRICA está\011procurando um\011forte treinador\011#MON.\012Ele precisa de\najuda para reaver\011algo que foi\011roubado.",
  ["62:4c9e"] = "Soube que a\nEQUIPE ROCKET\011voltou em JOHTO\011mas foi destruída\011de novo.\012Eu não sabia nada\ndessas coisas.",
  ["62:4d0c"] = "Quando você sai,\npode ver o telhado\011de uma grande\011construção.\012É a USINA ELÉTRICA.",
  ["62:4ee0"] = "Um ladrão entrou na USINA ELÉTRICA…\012Aonde este mundo\nvai parar?",
  ["62:4f22"] = "Acabei de falar\ncom CERULEANA.\012Parece que um cara\nsuspeito esteve\011andando por lá.",
  ["62:4f7f"] = "Poderia pedir\npela sua\011cooperação?",
  ["62:4fa2"] = "Nós teremos que\nmelhorar nossa\011segurança.",
  ["62:4fcf"] = "Alguém sumiu com\numa parte que é\011essencial para o\011gerador.\012Sem ela, o novo\ngerador é inútil!",
  ["62:5038"] = "O gerador está bom\ne funcionando.\012Está fazendo\nbastante\011eletricidade.",
  ["62:5079"] = "Essa USINA ELÉTRICA foi\011abandonada no\011passado.\012Nós a recolocamos\nde pé para\011fornecer energia\011ao TREM ÍMÃ.",
  ["62:50ef"] = "O gerador está\nfuncionando de\011novo!",
  ["62:510e"] = "O GERENTE DA\nUSINA ELÉTRICA\011está logo ali.\012Mas como alguém\nquebrou o gerador,\011ele tem estado\011triste e furioso…",
  ["62:517f"] = "Como o gerador\nfoi consertado, o\011GERENTE tem estado\011bem alegre.",
  ["62:51c2"] = "O TREM ÍMÃ\nconsome muita\011eletricidade.\012Não pode se mover\nse o novo gerador\011não estiver\011funcionando.",
  ["62:5225"] = "Certo! Finalmente\npodemos fazer o\011TREM ÍMÃ funcionar\011de novo.",
  ["62:5264"] = "GERENTE: Eu, eu,\neu estou pronto\011para matar alguém.\012Quem ousaria\narruinar meu\011gerador?\012Gastei muito tempo\nnele!\012Quando eu pegar o\nresponsável, ele\011provará meu SUPER\011CANHÃO!",
  ["62:5308"] = "GERENTE: Não o\nperdoarei!\012O culpado pode\nchorar e se\011lamentar, mas\011ainda o\011martelarei!\n\012Gahahahah!",
  ["62:536e"] = "GERENTE: Ah!\nIsso!\012É a PEÇA perdida\ndo meu amado\011gerador!\012Você a achou?",
  ["62:53c4"] = "Wahaha! Obrigado!\012Ei! Leve esse TM\ncomo recompensa!",
  ["62:53f4"] = "GERENTE: TM07 é\no meu SUPER\011CANHÃO.\012É uma técnica\npoderosa!\012Não é o que\neu chamaria de\011precisão, mas ele\011causa bons danos!",
  ["62:5475"] = "GERENTE: Meu\namado gerador!\012Continue bombeando\na eletricidade!",
  ["62:56ce"] = "Hm? Você conhece\nBILL? Ele é meu\011neto.\012Ele está em JOHTO.\nFaz algo com\011COMPUTADORES,\011então fico em\011casa.",
  ["62:5732"] = "Se você tiver\naquele #MON,\011posso vê-lo?",
  ["62:5760"] = "Vai me mostrar?\nQue legal da sua\011parte!",
  ["62:5784"] = "Você não o tem?\nIsso é uma\011pena…",
  ["62:57a6"] = "Ah, so that is\n{STRBUF}?\012Isn't it cute!\nThat's so kind of\011you.",
  ["62:57e1"] = "Obrigado!\012Isso representa\nminha gratidão.",
  ["62:580e"] = "Venha me\nvisitar de novo.",
  ["62:582a"] = "Obrigado por me\nmostrar tantos\011#MON lindos.\012Realmente gostei.\nEstou feliz por\011ter vivido tanto.",
  ["62:5891"] = "Hm?\012Esse não é o\n#MON que eu\011tinha mencionado.",
  ["62:58c0"] = "Meu neto BILL me\ncontou sobre um\011#MON que tem\011uma língua\011grande.",
  ["62:58ff"] = "Ah, meu neto\nmencionou um\011#MON verde e\011redondo que tem\011folhas crescendo\011em sua cabeça.",
  ["62:5953"] = "Você sabe de um\n#MON do mar\011que tem uma esfera\011vermelha em seu\011corpo?\012Você sabe, aquele\nem forma de\011estrela?\012Soube que ele\naparece à noite.\012Eu certamente\ngostaria de vê-lo.",
  ["62:59fe"] = "BILL me contou\nsobre um #MON\011que é muito leal\011ao seu treinador.\012Dizem que tem bom\nRUGIDO.",
  ["62:5a57"] = "Soube de um lindo\n#MON que tem\011seis caudas.\012Eu adoraria\nabraçar um lindo\011#MON como esse.",
  ["62:5ab1"] = "Você sabe daquele\n#MON bastante\011popular?\012O #MON que tem\num corpo amarelo\011e bochechas\011vermelhas.\012Adoraria ver\ncomo ele é antes\011de sua evolução.",
  ["62:5b6c"] = "Olá!\012O REI CARATÊ,\nmestre do GINÁSIO\011DE LUTA, está em\011uma caverna em\011JOHTO treinando.",
  ["62:5bc0"] = "Tudo que vai\nvolta!",
  ["62:5be0"] = "Inimigos em todos\nos lados!",
  ["62:5cdf"] = "SABRINA: Sabia\nque você viria…\012Há três anos\ntive uma visão de\011sua chegada.\012Quer a minha\nINSÍGNIA.\012Não gosto de\nbatalhar, mas é\011meu dever como\011LÍDER de conferir\011INSÍGNIAS àqueles\011que provarem o\011seu valor.\012Como você quer,\nvou mostrá-lo meus\011poderes psíquicos!",
  ["62:5df4"] = "SABRINA: Seu\npoder…\012É bem maior do\nque eu vi…\012Talvez seja\nimpossível prever\011totalmente o\011que o futuro\011guarda…\012Certo, você venceu\ne mereceu a\011INSÍGNIA DA LAMA.",
  ["62:5e95"] = "{PLAYER} received\nMARSHBADGE.",
  ["62:5ead"] = "SABRINA: A\nINSÍGNIA DA\011LAMA libera\011seus poderes\011sobrenaturais…\012Mesmo tendo\nfalhado na\011precisão da\011previsão de seu\011poder, o que eu\011sei é verdade.\012Você se tornará um\ncelebrado a amado\011CAMPEÃO!",
  ["62:5f6c"] = "SABRINA: Seu\namor pelos seus\011#MON superou\011meus poderes\011psíquicos…\012O poder do amor,\neu acho, também\011é um tipo de poder\011psíquico…",
  ["62:5fe9"] = "O poder de todos\nque derrotou vem\011para mim!",
  ["62:601b"] = "Forte…\nMuito forte…",
  ["62:6034"] = "Qual é a fonte de\nseu poder?",
  ["62:6057"] = "O poder psíquico\né o poder de sua\011alma.",
  ["62:6081"] = "Sua alma tem mais\npoder que a minha!",
  ["62:60a6"] = "Você fortaleceu\nsua alma, não\011apenas suas\011habilidades.",
  ["62:60dd"] = "Fufufufu…\nVejo claramente.\012Posso ver dentro\nde sua alma!",
  ["62:6114"] = "Mesmo te lendo,\neu perdi…",
  ["62:6136"] = "Droga! Esqueci\nque previ que eu\011perderia para\011você.",
  ["62:616c"] = "O GINÁSIO DE\nLUTA ao lado já\011foi o GINÁSIO\011dessa cidade.",
  ["62:61a2"] = "Não fui páreo…",
  ["62:61b3"] = "O REI CARATÊ, o\nmestre do GINÁSIO\011DE LUTA, foi\011destruído pela\011SABRINA.",
  ["62:6201"] = "Ei, CAMPEÃO em\nprogresso!\012Um treinador\nhabilidoso como\011você não precisa\011ser informado\011de como lidar\011com #MON\011psíquicos, certo?\012Espero muito de\nvocê! Boa sorte!",
  ["62:62a0"] = "Essa foi\noutra fantástica\011batalha!",
  ["62:63cc"] = "Há uma grande\nTORRE DE RÁDIO\011em LAVENDER.",
  ["62:63f3"] = "Quero me\nfortalecer, mas\011não sou boa\011ainda…\012Poderia me mostrar\ncomo, um dia?",
  ["62:64a3"] = "Como são os\nCENTROS #MON\011de JOHTO?\012…Oh, entendo.\nEntão não são\011muito diferentes\011desses de KANTO.\012Então posso ir a\nJOHTO sem me\011preocupar!",
  ["62:6532"] = "Como são os\nCENTRO #MON de\011JOHTO?\012…Oh, entendo.\nEntão lá eles\011deixam você se\011ligar a pessoas\011distantes.\012Então pedirei ao\nmeu amigo em JOHTO\011para pegar um\011MARILL e trocá-lo\011comigo!",
  ["62:65d3"] = "Acabei de\natravessar o\011TÚNEL DE ROCHA.\012Havia uma\nconfusão na USINA\011ELÉTRICA.",
  ["62:662e"] = "Cavernas se\ndesmoronam\011facilmente.\012Muitas cavernas\nsumiram no\011passado, como\011aquela que fica\011fora de CERULEANA.\012Para um ANDARILHO\navançado, essa\011informação é\011básica.",
  ["62:66c5"] = "PRÉDIO DE\nESCRITÓRIO da\011CORPORAÇÃO SILPH\011e ESTAÇÃO DO\011TREM ÍMÃ são\011pontos turísticos\011em SAFFRON.",
  ["62:6798"] = "…\012…\012…\012…Já sei!\012Você queria isso!",
  ["62:67bb"] = "TM29 é o PSÍQUICO.\012Pode reduzir a\nDEFESA 2 do alvo.",
  ["62:68a9"] = "Perdão, mas o\nTREM ÍMÃ não está\011funcionando agora.",
  ["62:68dd"] = "Partiremos\nem breve para\011GOLDENROD.\012Você vai embarcar?",
  ["62:6917"] = "Posso ver seu\nPASSE de trem,\011por favor?\012Certo, é por aqui.",
  ["62:6956"] = "Perdão, mas você\nnão tem o PASSE.",
  ["62:6978"] = "Esperamos vê-lo\nde novo.",
  ["62:6993"] = "Chegamos a\nSAFFRON.\012Esperamos vê-lo\nde novo.",
  ["62:69ca"] = "O TREM ÍMÃ é um\nsuper moderno\011transporte fer-\011roviário que usa\011eletricade e\011ímãs para\011atingir incríveis\011velocidades.\012Mas, se não houver\neletricidade…",
  ["62:6a61"] = "Nossa…\012Quantas vezes eu\njá atravessei o\011caminho entre\011KANTO e JOHTO?",
  ["62:6aab"] = "Antes da ESTAÇÃO\nDO TREM ÍMÃ ser\011construída, havia\011uma casa aqui.\012Uma garotinha\nchamada DUPLICA\011morava aqui.",
  ["62:6b20"] = "Oi. Você tem\num PASSE de trem?\011Eu tenho um.\011Todas pessoas em\011SAFFRON que andam\011de TREM ÍMÃ têm\011PASSES.",
  ["62:6c03"] = "Bem-vindo. Esse é\no PRÉDIO DE\011ESCRITÓRIO DA\011CORPORAÇÃO SILPH.",
  ["62:6c36"] = "Só funcionários\npodem subir.\012Mas como você\nveio de muito\011longe, receba essa\011lembrancinha.",
  ["62:6ca8"] = "É o produto\nmais novo da\011CORPORAÇÃO SILPH.\012Não se vende em\nlugar algum ainda.",
  ["62:6d34"] = "Minha filha gosta\nde imitar pessoas.\012Sua mímica lhe\ndeu o apelido de\011DUPLICA por aqui.",
  ["62:6d95"] = "Minha filha é tão\negocêntrica…\012Ela tem poucos\namigos.",
  ["62:6dd3"] = "Ela recentemente\nperdeu a BONECA\011que um menino lhe\011deu há três anos.\012Desde lá, ela vem\nmelhorando a sua\011mímica…",
  ["62:6e4b"] = "BLISSEY: Bliisii!",
  ["62:6fda"] = "{PLAYER}: Oi! Você\ngosta de #MON?\012{PLAYER}: Uh, não,\neu só te\011perguntei.\012{PLAYER}: Huh?\nVocê é estranho!",
  ["62:7028"] = "DUPLICA: Hmm?\nChega de mímica?\012É o que mais\ngosto de fazer!",
  ["62:7064"] = "{PLAYER}: Oi! Soube\nque você perdeu\011sua BONECA\011preferida.\012{PLAYER}: Se eu\nachá-la, você me\011dará um PASSE de\011trem?\012{PLAYER}: Vou\nachá-la para você.\012Acha que a perdeu\nquando foi à\011CIDADE DE VERMILION?",
  ["62:7116"] = "DUPLICA: Perdão?\012Não deveria\ndecidir o que você\011deve fazer?\012Mas estou muito\npreocupada. E se\011alguém achá-la?",
  ["62:717f"] = "DUPLICA: Ei\n É\nminha BONECA\011CLEFAIRY!\012Vê o rasgo onde\na perna direita\011está costurada?\011É a prova!",
  ["62:71e2"] = "Certo. Eis o PASSE\nDO TREM ÍMÃ como\011prometi!",
  ["62:7214"] = "DUPLICA: É o PASSE\npara o TREM ÍMÃ.\012O rapaz\nda compania\011ferroviária me\011deu quando\011derrubaram nossa\011velha casa para\011fazer a ESTAÇÃO.",
  ["62:7298"] = "{PLAYER}: Oi!\nMuito\nobrigado pelo\011PASSE de trem!\012{PLAYER}: Perdão?\012{PLAYER}: É legal\nassim copiar todos\011meus movimentos?",
  ["62:72f5"] = "DUPLICA: Claro!\nÉ demais!",
  ["62:7316"] = "{PLAYER}: Oi. Você\ndeve gostar de\011#MON.\012{PLAYER}: Não, não\neu. Eu lhe\011perguntei.\012{PLAYER}: Perdão.\nVocê é estranho!",
  ["62:7366"] = "{PLAYER}: Oi! Você\nperdeu mesmo\011sua BONECA?\012{PLAYER}: Vai mesmo\nme dar um PASSE\011de trem se eu\011achá-la para você?\012{PLAYER}: Claro, a\nprocurarei para\011você.\012Acha que a perdeu\nquando foi à\011CIDADE DE VERMILION?",
  ["62:7415"] = "{PLAYER}: Obrigada\npelo PASSE de\011TREM.\012{PLAYER}: …Perdão?\012{PLAYER}: É legal\nmesmo imitar o\011que eu digo e \011aço?",
  ["62:7476"] = "DODRIO: Gii giii!",
  ["62:7489"] = "ESPELHO, ESPELHO\nMEU, EXISTE ALGUÉM\011MAIS JUSTO DO QUE\011EU?",
  ["62:74c4"] = "Esse é um\n#MON raro! Hã?\012É só um boneco…",
  ["62:7558"] = "Eeyaaaah!\012Sinto uma sombra\nsinistra te\011combrindo.\012Leve isso para\nexpulsá-la!",
  ["62:75bc"] = "Você estava em\nperigo mortal,\011mas está protegido\011agora.",
  ["62:7655"] = "Minha avó\nexpulsa o que ela\011acredita ser\011espíritos do mau.\012Perdoe-me se ela\nassustou você.",
  ["62:76a7"] = "Você está coleci-\nonando INSÍGNIAS\011DOS GINÁSIOS DE\011KANTO?",
  ["62:76de"] = "Várias cidades em\nJOHTO têm longas\011histórias.\012Eu adoraria\nvisitá-las!",
  ["63:4042"] = "Você já visitou o\nGINÁSIO PEWTER?\012O LÍDER usa\n#MON do tipo\011pedra.",
  ["63:4080"] = "À noite, os\nCLEFAIRY vêm\011brincar no MONTE\011LUA.\012Mas nem toda\nnoite.",
  ["63:40c6"] = "Ah, você percorreu\ntodo o caminho\011desde JOHTO?\012Isso me traz\nmemórias.\012Quando eu era\njovem, eu fui\011à JOHTO para\011treinar.\012Você me lembra\ndemais de como eu\011era quando jovem.\012Ei. Quero que\nvocê fique com\011esse item que eu\011achei em JOHTO.",
  ["63:41aa"] = "Ir a lugares novos\ne dEsconhecidos e\nver novas pessoas…\012Essas são as\ndiversões de\011uma viajem.",
  ["63:41ff"] = "CIDADE DE PEWTER\012A Cidade Cinza\nComo a Pedra.",
  ["63:421e"] = "CIDADE DE PEWTER\012LÍDER DO GINÁSIO\n#MON: BROCK\012O Treinador\n#MON Sólido\011Como uma Pedra.",
  ["63:425e"] = "Há um aviso\naqui…\012O MUSEU DE\nCIÊNCIA DE PEWTER\011está fechado para\011renovações…",
  ["63:42a9"] = "Há um aviso\naqui…\012LOJA DE PRESENTES\nDO MONTE LUA\011ABERTA AGORA!",
  ["63:42dc"] = "Gyaaas!",
  ["63:4531"] = "Gyaaas!",
  ["63:473f"] = "Uau! Você me\nsurpreendeu!\012Estava de\nÓCULOSESCURO, daí\011nem notei sua\011presença. \012O que eu faço\naqui?\012Ei, não se\npreocupe com isso.\012Eu lhe darei\num par de\011ÓCULOSESCURO,\011então esqueça que\011me viu, certo?",
  ["63:480c"] = "Os ÓCULOSESCURO\najuda golpes do\011tipo escuro.",
  ["63:49b8"] = "Espere!",
  ["63:49bf"] = "CLAIR: Perdoe-me\npor isso.\012Ei, leve isso\ncomo meu perdão.",
  ["63:49fb"] = "{PLAYER} recebeu\nTM24.",
  ["63:4a0d"] = "Iso contém o\nSOPRO DRAGÃO.\012Não, isso não tem\nnada a ver com\011meu sopro.\012Se você não\no quiser, não\011precisa levá-lo.",
  ["63:4a8b"] = "Oh? Você não tem\nespaço para isso.\012Vou voltar ao\nGINÁSIO. Libere\011espaço e vá lá me\011ver.",
  ["63:4af1"] = "CLAIR: Qual o\nproblema? Você\011não está indo à\011LIGA #MON?\012Você sabe como\nchegar lá?\012Daqui, vá à\nCIDADE DE NEW BARK.\012Depois SURFE para\no leste até a LIGA\011#MON.\012Você vai enfrentar\numa rota muito\011difícil até lá.\012Não se atreva a\nperder na LIGA\011#MON!\012Se você o fizer,\nvou me sentir pior\011do que ter perdido\011para você!\012Dê o seu máximo.",
  ["63:4c2e"] = "TOCA DO DRAGÃO\012Um santuário em\nhomenagem aos\011#MON dragões\011que supostamente\011viveram na TOCA\011DO DRAGÃO.",
  ["63:4c83"] = "…\nO quê? {PLAYER}?\012…Não, não\nbatalharei com\011você agora…\012Meus #MON não\nestão prontos para\011vencê-lo.\012Não posso exigir\nmuito deles\011agora. Devo ser\011disciplinado para\011ser o melhor\011treinador #MON…",
  ["63:4d2d"] = "…\012Ei…\012Aprenda a ficar\nlonge de mim…",
  ["63:4d53"] = "Você! Como ousa\nentrar sem\011convite!",
  ["63:4d77"] = "F-forte!",
  ["63:4d82"] = "O SANTUÁRIO abaixo\né a casa do MESTRE\011de nosso clã de\011dragões.\012Você não pode\nsimplesmente en-\011trar!",
  ["63:4de4"] = "Você não deveria\nestar aqui!",
  ["63:4dfe"] = "Oh droga, perdi!",
  ["63:4e11"] = "Logo conseguirei\nalvará do nosso\011MESTRE para usar\011dragões.\012Quando eu o\nfizer, me tornarei\011uma admirável\011treinadora de\011dragões e nosso\011MESTRE me apro-\011vará.",
  ["63:4eab"] = "É um estranho\nque não\011conhecemos.",
  ["63:4ec9"] = "Aiii.",
  ["63:4ed3"] = "Foi como ter que\nbatalhar com\011LANCE.",
  ["63:4ef8"] = "Quem é você?",
  ["63:4f06"] = "Malvado.",
  ["63:4f0f"] = "Vamos dedurá-lo.\012O MESTRE ficará\nzangado com você.",
  ["63:4f41"] = "{PLAYER} found\n{STRBUF}!",
  ["63:4f51"] = "Mas {PLAYER} não\npode levar mais\011itens.",
  ["63:52ea"] = "Hm… Que bom vê-lo\naqui.\012Não precisa de\nexplicar porque\011veio.\012CLAIR o enviou\naqui, certo?\012Aquela garota é\ndureza…\012Perdoe-me, mas eu\ndevo testá-lo.\012Não se preocupe,\nvocê só vai\011responder a umas\011questões.\012Pronto?",
  ["63:53bc"] = "O que são #MON\npara você?",
  ["63:53d3"] = "O que o ajuda a\nvencer batalhas?",
  ["63:53f3"] = "Com que tipo de\ntreinador deseja\011batalhar?",
  ["63:5420"] = "O que é mais\nimportante para\011criar #MON?",
  ["63:544a"] = "#MON forte.\n#MON fraco.\012Qual é o mais\nimportante?",
  ["63:547c"] = "Hm… Percebo…\012Você se importa\nmuito com os\011#MON.\012É magnífico.\012Essa convicção\nque é importante!\012{PLAYER}, não deixe\nde acreditar\011nisso.\012Isso vai ajudá-lo\ndurante a LIGA\011#MON.",
  ["63:5520"] = "CLAIR!\012Essa criança\né impecável, na\011técnica e no\011espírito.\012Admita a perda e\nlhe dê a INSÍGNIA\011CRESCENTE.\n\012…Ou devo contar\nisso ao LANCE?",
  ["63:55a3"] = "CLAIR…\012Reflita e veja que\nessa criança tem\011o que falta em\011você.",
  ["63:55e5"] = "Venha de novo,\nse desejar.",
  ["63:5604"] = "Hm… Que bom vê-lo\naqui.\012Sua chegada é uma\ngrande sorte.\012Eu tenho algo\npara você.\012Leve esse DRATINI\ncomo prova de que\011eu reconheci seu\011valor.",
  ["63:5697"] = "{PLAYER} recebeu\nDRATINI!",
  ["63:56ac"] = "Hm? Sua equipe\n#MON está\011cheia.",
  ["63:56ca"] = "#MON dragões\nsão simbólicos em\011nosso clã.\012Você mostrou que\nmerece confiança\011no manuseio de um.",
  ["63:5724"] = "CLAIR parece ter\naprendido uma\011lição sem valor\011monetário de você.\012Agradeço-lhe como\navô dela.",
  ["63:5782"] = "Um garoto de sua\nfaixa etária\011treinara aqui.\012Ele é parecido\ncom CLAIR quando\011jovem.\012É uma pequena\npreocupação…",
  ["63:57f6"] = "Hã? Eu não escutei\ndireito…",
  ["63:5816"] = "O que você disse?",
  ["63:582d"] = "Oh, eu entendo…",
  ["63:5840"] = "Já fazia um bom\ntempo que um\011treinador não\011ganhava a rara\011aprovação de nosso\011MESTRE.\012De fato, desde o\nMestre LANCE.",
  ["63:58b1"] = "Conhece o jovem\nMestre LANCE?\012Ele é muito\nparecido com nosso\011MESTRE quando\011jovem.\012É coisa de sangue.",
  ["63:5916"] = "Então como foi?\012Acho que nem\npreciso de\011perguntar.\012Você falhou?\012………………\012…O quê? Você\npassou?",
  ["63:5974"] = "Não pode ser!",
  ["63:5983"] = "Está mentindo!\012Nem eu fui\naprovada!",
  ["63:59ae"] = "Eu-eu entendo…",
  ["63:59bf"] = "Ei, essa é\na INSIGNIA\011CRESCENTE…\012Vá logo! Leve-a!",
  ["63:59f2"] = "{PLAYER} foi pre-\nsenteado com uma\011INSÍGNIA CRESCENTE\011DO GINÁSIO DA\011CIDADE DE BLACKTHORN.",
  ["63:5a0b"] = "A INSÍGNIA\nCRESCENTE deixará\011seu #MON\011usar o golpe\011para escalar\011cachoeiras.\012E mais, todos\n#MON o\011reconhecerão como\011treinador e\011obedecerão a\011qualquer comando\011sem questionar.",
  ["63:5b34"] = "Seus #MON\nsabem golpes HM?\012Esses golpes podem\nser usados mesmo\011se seus #MON\011desmaiarem.",
  ["63:5bee"] = "O PC DO BILL pode\nguardar até 20\011#MON por BOX.",
  ["63:5c19"] = "Você sabe algo\nsobre as BOLOTAS?\012Abra uma fenda,\ndeixe a BOLOTA\011oco e encaixe-o\011num dispositivo\011especial.\012Agora pode\ncapturar #MON\011com ele.\012Antes das #\nBOLAS, usavam-se\011as BOLOTAS.",
  ["63:5d74"] = "Todos os SLOWPOKE\ndesapareceram da\011cidade.\012O protetor da\nfloresta deve\011estar nervoso com\011nós…\012Isso deve ser um\nsinal ruim.\012Devemos ficar em\nalerta.",
  ["63:5dfd"] = "Os SLOWPOKE\nvoltaram.\012Mas meu aprendiz\nnão voltou da\011FLORESTA DE ILEX.\012Onde será que\neste preguiçoso\011está?",
  ["63:5e73"] = "Você sozinho\nperseguiu a EQUIPE\011ROCKET e foi à\011FLORESTA DE ILEX?\012Que técnicas!\nGostei disso!\011Venha treinar\011conosco.",
  ["63:5ee0"] = "Para onde foram\ntodos os SLOWPOKE?\011Será que estão\011brincando por aí?",
  ["63:5f25"] = "Perdão--esqueci\nde agradecê-lo.\012Esse é o CARVÃO\nque eu fiz.\012#MON do tipo\nfogo ficariam\011felizes ao segurar\011isso.",
  ["63:5f93"] = "Os SLOWPOKE\nvoltaram, e você\011ainda achou um\011FARFETCH'D.\012Você é o mais\nlegal!",
  ["63:5fe5"] = "FARFETCH'D: Kwaa!",
  ["63:604d"] = "Não há SUPER BOLAS\naqui. Terá que\011usar # BOLAS.\012Queria que KURT\nfizesse algumas de\011suas BOLAS.",
  ["63:60b6"] = "Uma SUPER BOLA é\nmelhor para\011capturar #MON\011que a # BOLA.\012Mas as de KURT\ndevem ser melhores\011às vezes.",
  ["63:6473"] = "Hm? Quem é você?\012{PLAYER}, eh?\nQuer que eu faça\011umas BOLAS?\012Perdão, mas terá\nque esperar.\012Você conhece a\nEQUIPE ROCKET?\012Ah, fique calmo.\nEu vou te dizer. \n\012A EQUIPE ROCKET é\ngangue malvada que\012usa POKéMONS para\nseus trabalhos\011sujos.\012Dizem que eles\ntiveram que falir\011há três anos.\012Mesmo assim,\nestão no POÇO,\n \012cortando CAUDAS de\nSLOWPOKE para a\011venda.\012Então vou dar-lhes\numa lição sobre a\011dor!\012Aguente, SLOWPOKE!\nO velho KURT está\011indo!",
  ["63:6615"] = "KURT: Oi, {PLAYER}!\012Você agiu como\num herói verdeiro\011no POÇO.\n \012Admiro seu estilo!\012Estaria honrado em\nfazer BOLAS para\012um treinador como\nvocê.\012É tudo que tenho\nagora, mas leve-a.",
  ["63:66c9"] = "KURT: Faço BOLAS\ncom BOLOTAS.\012Colete-os das ár-\nvores e traga-os\011a mim.\012Eu farei BOLAS\ncom eles.",
  ["63:6736"] = "KURT: Você tem uma\nBOLOTA para mim?\012Legal! Ela vai\nvirar uma BOLA.",
  ["63:6779"] = "KURT: Levarei um\ndia para fazer uma\012BOLA. Volte mais\ntarde.",
  ["63:67bc"] = "KURT: Oh… Que\ndesapontamento.",
  ["63:67d8"] = "KURT: Estou traba-\nlhando!\012Não me atrapalhe!",
  ["63:67fb"] = "KURT: Ah, {PLAYER}!\nAcabei de fazer\011sua BOLA. Aqui!",
  ["63:682a"] = "KURT: Foi muito\nbem feita.\012Tente capturar\nPOKÉMONS com ela.",
  ["63:6863"] = "KURT: Agora que\nminha neta me a-\012juda, posso traba-\nlhar mais rápido.",
  ["63:68ab"] = "O-o que é isso?\012Nunca vi isso\nantes.\012Parece uma #\nBOLA, mas deve\011ter algo a mais.\012Deixe-me checá-la\npara você.",
  ["63:6934"] = "Estou checando-a\nagora.",
  ["63:6949"] = "Ah-ha! Entendo!\nEntão…",
  ["63:695c"] = "{PLAYER}!\012Essa BOLA começou\na tremer enquanto\011eu a checava.\012Isso deve ter\nalgo a ver!",
  ["63:69b5"] = "Os SLOWPOKE su-\nmiram… Eles foram\012levados embora por\ngente ruim?",
  ["63:69f1"] = "O vovô saiu…\nEstou tão só…",
  ["63:6a0f"] = "O SLOWPOKE que meu\npai me deu voltou!\012Sua cauda está\ncrescendo também!",
  ["63:6a55"] = "Papai trabalha na\nSILPH onde estuda\011as # BOLAS.\012Tenho que ficar\nem casa com o\011vovô e o SLOWPOKE.",
  ["63:6ab2"] = "Vou ajudar o\nVovô agora!\012Faremos boas BOLAS\npara você, então\011aguarde!",
  ["63:6afc"] = "É divertido fazer\nBOLAS!",
  ["63:6b14"] = "Vovô está olhando\num BOLA agora.\012Estou esperando\nele acabar.",
  ["63:6b56"] = "SLOWPOKE: …\nYawn?",
  ["63:6b69"] = "…O jovem PROFESSOR\nCARVALHO?",
  ["63:6b7e"] = "É uma estátua do\nprotetor da flo-\011resta.",
  ["63:6d0b"] = "Sou BUGSY!\012Nunca perco quando\nuso #MON\011insetos.\012Minha pesquisa me\ntornará uma\011autoridade em\011#MON insetos!\012Deixe-me\ndemonstrar o que\011eu aprendi com os\011meus estudos.",
  ["63:6dae"] = "Então como foi?\012Acho que nem\npreciso de\011perguntar.\012Você falhou?\012………………\012…O quê? Você\npassou?",
  ["63:6e14"] = "{PLAYER} foi\npresenteado com\011uma INSÍGNIA DA\011COLMÉIA DO\011GINÁSIO DA CIDADE\011AZALEA.",
  ["63:6e2b"] = "Você conhece os\nbenefícios da\011INSÍGNIA DA\011COLMÉIA?\012Se a tiver, os\n#MON acima do\011NÍVEL 30 vão te\011obedecer.\012#MON que\naprenderam o\011CORTAR, poderão \011usar este golpe\011fora das batalhas\011também.\012Ei, quero que leve\nisso também.",
  ["63:6efa"] = "TM49 contém\nCORTE FÚRIA. \012Se você não errar,\nesse ataque fica\011cada vez mais\011forte.\012Quanto maior for\na batalha, melhor \011o ataque ficará. \012Isso não é ótimo?\nFui eu quem\011descobriu isso!",
  ["63:6f98"] = "#MON insetos\nsão complexos.\012Tem muitos\nmistérios a\011explorar.\012Estude seu\nfavorito por\011completo.",
  ["63:6ff8"] = "#MON insetos\nevoluem jovens.\012Daí eles ficam\nfortes mais\011rápido.",
  ["63:7037"] = "Apenas evoluir\nnão basta!",
  ["63:7053"] = "#MON ficam\nmais fortes quando\011eles evoluem!",
  ["63:7081"] = "#MON insetos\nsão legais e\011fortes! Vou lhe\011provar!",
  ["63:70b4"] = "Provou como você\né forte…",
  ["63:70d3"] = "Eles são tão\nlegais, mas não\011sei porque as\011garotas detestam\011#MON insetos…",
  ["63:7118"] = "Você salvou todos\nos SLOWPOKE? Uau,\011você é poderoso!\012Mas meu #MON\ncrescido é bem\011forte também!",
  ["63:7174"] = "Urrgggh!",
  ["63:717e"] = "Acho que devo\nensiná-los golpes\011melhores…",
  ["63:71a9"] = "AMY: Oi! Está\ndesafiando a\011LÍDER? Nem pensar!",
  ["63:71db"] = "AMY & MAY: Oh,\ndupla bondade!",
  ["63:71fc"] = "AMY: Você é mesmo\nforte!",
  ["63:7217"] = "MAY: Quer ver a\nLÍDER? Veja nós\011primeiro!",
  ["63:7248"] = "AMY & MAY: Oh,\ndupla bondade!",
  ["63:7269"] = "MAY: Nosso #MON\ninseto perdeu! Que\011vergonha.",
  ["63:7296"] = "Ei, desafiante!\012BUGSY é jovem, mas\nseu conhecimento\011de #MON\011insetos é\011incrível!\012Seria mais difícil\nsem meu aviso.\012Vamos ver…\n#MON insetos\011não gostam de\011fogo.\012Golpes de\n#MON AVES são\011super efetivos.",
  ["63:7359"] = "Parabéns! Isso\nfoi um ótimo\011choque de jovens\011treinadores\011talentosos.\012O futuro #MON\nserá brilhante com\011gente como vocês!",
  ["64:40b0"] = "Ei, garoto!\012Vejo que é\nnovo na CIDADE\011MAHOGANY.\012Como é novo, você\ndeve experimentar\011o ótimo DOCE\011DA FÚRIA!\012Agora, ele pode\nser seu por apenas\011¥300! Quer um?",
  ["64:414a"] = "Bom! Aprecie-o!",
  ["64:415b"] = "Você não tem o\ndinheiro preciso.",
  ["64:4178"] = "Oh, tudo bem…",
  ["64:4188"] = "Você não tem\nespaço para isso.",
  ["64:41a6"] = "O DOCE DA FÚRIA já\nacabou.\012Encomendarei mais.\nNão me incomode,\011garotinho.",
  ["64:41e5"] = "Você está aqui\npara ver o ritual\011dos GYARADOS no\011LAGO?",
  ["64:421d"] = "AS MAGIKARPS\nretornaram ao LAGO\011DA FÚRIA.\012Isso deve ser uma\nboa notícia para\011os pescadores de\011lá.",
  ["64:4276"] = "Como chegou tão\nlonge, dedique-se\011para passear um\011pouco.\012Você deveria ir\nao norte e\011examinar o LAGO\011DA FÚRIA agora.",
  ["64:42f2"] = "Visite a Loja da\nVovó. Ela vende\011coisas que ninguém\011tem.",
  ["64:432e"] = "CIDADE DE MAHOGANY\012Bem-vindo ao Lar\ndo Ninja.",
  ["64:435e"] = "Enquanto visita\na CIDADE DE MAHOGANY,\011prove o DOCE\011DA FÚRIA!",
  ["64:4391"] = "CIDADE DE MAHOGANY\012LÍDER DO GINÁSIO\n#MON: PRYCE\012O Professor da\nDureza do Inverno.",
  ["64:4790"] = "Espere!\nPor que a\011pressa?",
  ["64:47ab"] = "{PLAYER}, certo?\nUm rapaz usando\011óculos estava\011procurando por\011você.\012Vá vê-lo. Ele está\nte esperando no\011CENTRO #MON.",
  ["64:48b0"] = "Você já foi ao\nGINÁSIO #MON?\012Lá você pode\ntestar seu #MON\011e si mesmo.\012É parada\nobrigatória para\011todos treinadores!",
  ["64:4925"] = "Você tem bons\n#MON aí.\012Deve ser devido ao\ntreinamento que\011receberam na\011CIDADE DE VIOLET.\012O treinamento no\nGINÁSIO ajudou de\011forma excepcional.\012Como lembrança da\nCIDADE DE VIOLET,\011leve isso.\012Ele melhora o\npoder de golpes do\011tipo grama.",
  ["64:4a15"] = "Suas experiências\nna CIDADE DE VIOLET\011devem ser úteis\011para sua jornada.",
  ["64:4a59"] = "O que acha\ndeste delicioso\011e nutritivo\011RABOSLOWPOKE?\012Para você, vai\ncustar apenas\011¥1,000,000!\012Você vai gostar!",
  ["64:4acf"] = "Tch! Achava que as\ncrianças de hoje\011em dia tinham mais\011dinheiro…",
  ["64:4afc"] = "Você não quer?\nEntão vá embora.\012Xô!",
  ["64:4b21"] = "Ei! Você me fez\nperder aquele\011peixe!",
  ["64:4b44"] = "Sploosh!",
  ["64:4b4e"] = "Calma, colecionar…\nA essência da\011pesca e dos\011#MON é a\011mesma.",
  ["64:4b8f"] = "Sou tanto bom com\n#MON quanto na\011pesca.\012Eu não perderei\npara um garoto!",
  ["64:4bda"] = "Tch! Tentei mistu-\nrar as coisas…",
  ["64:4bf8"] = "Pescar é diversão\npara vida toda.\012Os #MON são\namigos de toda a\011vida!",
  ["64:4c37"] = "Um, dois, três…\nHahaha, que pesca!\011Estou exausto!\011Vá em frente e\011capture o máximo\011que puder, garoto!",
  ["64:4dcf"] = "Meu #MON?\nAcabei de pegar!",
  ["64:4de9"] = "SPLASH?",
  ["64:4df2"] = "#MON novatos\nnão são páreos\011para os já bem\011criados.",
  ["64:4e2e"] = "Eu não o vira aqui\nantes. Você se\011acha muito forte\011então?",
  ["64:4e73"] = "Você é forte!",
  ["64:4e82"] = "Eu vou tentar ser\no melhor com meus\011favoritos.\012Não vou usar os\nmesmos #MON\011que todos usam.",
  ["64:4ee8"] = "Eu achei bons\n#MON na grama!\012Acho que eles\nserão úteis para\011mim!",
  ["64:4f2b"] = "Droga. Achei que\neu ganharia.",
  ["64:4f49"] = "A grama é cheia\nde coisas legais.",
  ["64:4f6e"] = "Esse lugar… É\nincrível.",
  ["64:4f8c"] = "Hmmm. Isso é\ndespontador.",
  ["64:4faa"] = "Se não quiser\nbatalhar, evite o\011contato visual.",
  ["64:4fdf"] = "Hã-hã. É, e você\nsabe…\012Pois não? Uma\nbatalha? Estou no\011telefone. \012Oh, certo. Mas\nvamos fazê-la\011rápido.",
  ["64:503e"] = "Oh, tenho que me\ncontrolar!",
  ["64:5060"] = "A conversa estava\nlegal também.",
  ["64:507f"] = "Essa INSÍGNIA! É\nda CIDADE DE VIOLET!\012Você derrotou\nFALKNER?",
  ["64:50b4"] = "Eu conheço minhas\nfraquezas.",
  ["64:50d4"] = "Eu devo treinar de\nnovo no GINÁSIO\011da CIDADE DE VIOLET.",
  ["64:5133"] = "UARRRRR!\nAS PESSOAS FOGEM\011QUANDO EU RUJO!\011MAS VOCÊ NÃO! ISSO\011ME ALEGRA! AGORA\011LEVE ISSO!",
  ["64:518c"] = "UARRR! É O RUGIDO!\012ATÉ OS #MON\nFOGEM DE UM BOM\011RUGIDO!",
  ["64:51c1"] = "FRIEDA: Oba! Hoje\né Sexta\012Eu sou FRIEDA da\nSexta-feira!\012Prazer em\nconhecê-lo!",
  ["64:5204"] = "Aqui está uma\nBARBA VENENO!",
  ["64:5222"] = "FRIEDA: Dê isso a\num #MON que\011possui golpes do\011tipo veneno.\012Oh!\012É perigoso!\012Você vai ficar\nchocado com o bem\011que isto faz aos\011golpes venenosos!",
  ["64:529a"] = "FRIEDA: Hiia! Do\nque você gosta?\012Eu amo as Sextas.\nSem dúvida alguma.\012Você não acha\nlegal também?",
  ["64:52ff"] = "FRIEDA: Hoje não\né Sexta?\012É tão chato quando\nnão é!",
  ["64:533a"] = "ROTA 32\012CIDADE DE VIOLET-\nCIDADE DE AZALEA.",
  ["64:535e"] = "RUÍNAS ALFA\nENTRADA LESTE.",
  ["64:537b"] = "CAVERNA DA UNIÃO\nACIMA.",
  ["64:5496"] = "Eu sou o AMIGO\nPESCADOR, o mais\011velho dos IRMÃOS\011PESCADORES.\012Você encontrou o\nGURU DA PESCA no\011LAGO DA FÚRIA?\012Seu sonho é ver\na melhor MAGIKARP\011do mundo.\012Se puder, você\npoderia mostrá-lo\012qualquer MAGIKARP\nque pegar?\012Quem sabe, não en-\ncontra a MAGIKARP\011sonhada.",
  ["64:55a3"] = "É uma foto de\npessoas pescando…\012Elas estão se\ndivertindo…",
  ["64:5620"] = "Um #MON dormi-\nnhoco está descan-\011sando em frente à\011CAVERNA DOS DIGLETT.\012É uma ótima chan-\nce para pegá-lo,\012mas como acordá-\nlo?",
  ["64:5698"] = "Havia um #MON\ndorminhoco rela-\012xando em frente\nà CAVERNA DOS DIGLETT.\012Mas parece que\nele sumiu.",
  ["64:56fe"] = "A BALSA é um\nbom lugar para\012batalhar e encon-\ntrar treinadores.",
  ["64:573b"] = "Oh? Você tem IN-\nSÍGNIAS que nunca\011vi.\012Oh, entendi. Você\nas pegou em JOHTO.",
  ["64:5881"] = "Sou o PRESIDENTE\ndo FÃ CLUBE POKé-\011MON.\012Já criei uns 150\n#MON.\012Empolgo-me quando\nse trata de\011#MON.\012Veio aqui para\nouvir sobre meus\011#MON?",
  ["64:5911"] = "Bom!\nEscute então!\012Bom… meu RAPIDASH\nfavorito…\012É… lindo… amável…\npequeno…\011indomável… mais…\011incrível… oh…\011também acha?…\011Muito… selvagem…\011bonito… gentil…\011eu o amo!\012Abraçá-lo… quando…\ndorme… é quente e\011macio… Oh, e…\011espetacular…\011simplesmente\011divino…\011Opa! Olhe a\011hora! Tomei-lhe\011muito tempo!",
  ["64:5a3d"] = "Obrigado por me\nescutar. Quero que\011leve isso!",
  ["64:5a72"] = "É um DOCE DA FÚRIA\nque fortalece o\011#MON.\012Prefiro fortalecer\nmeus #MON com\012batalhas, então\npode levá-lo.",
  ["64:5ae0"] = "Olá, {PLAYER}!\012Veio aqui para\nescutar sobre\011#MON?\012Não? Oh… Não tenho\nnada para contar…",
  ["64:5b38"] = "Que pena…\012Volte se quiser\nescutar.",
  ["64:5b6d"] = "Nosso PRESIDENTE é\nbem ativo quando o\011assunto é #MON…",
  ["64:5ba0"] = "Adoro o modo que\nos CLEFAIRY me-\012xem seus dedos\nquando tentam usar\012o METRÔNOMO.\nÉ tão adorável!",
  ["64:5bff"] = "Eu amo a CLEFAIRY,\nmas nunca pude pe-\012gar uma. Então a\nsubstituo pelo\012BONECO que achei.",
  ["64:5c5a"] = "Oh, entendo. A ga-\nrota que perdeu\012esse BONECO está\ntriste…\012Certo. Você\npoderia levá-lo de\011volta àquela\011pobre\ngarotinha?\012Um dia terei minha\nprópria CLEFAIRY.\012Sem preocupações!",
  ["64:5d0a"] = "{PLAYER} recebeu\nBONECO.",
  ["64:5d1e"] = "Você verá. Ainda\nterei uma CLEFAIRY\012verdadeira como\namiga.",
  ["64:5d58"] = "Sua BOLSA está\nlotada.",
  ["64:5d73"] = "Olhe meu querido\nBAYLEEF!\012A folha em sua\ncabeça é linda!",
  ["64:5db1"] = "É uma CLEFAIRY!\nHã?\012Ah, bem. É um\nBONECO CLEFAIRY.",
  ["64:5de9"] = "BAYLEEF: Li liif!",
  ["64:5dfc"] = "Vamos todos\nescutar aos outros\011treinadores\011educadamente.",
  ["64:5e29"] = "Se alguém esnobar,\nserá esnobado!",
  ["64:5ec0"] = "Você conhece o\nTREM ÍMÃ?\012É uma ferrovia que\nvai a GOLDENROD\011em JOHTO.",
  ["64:5f16"] = "Quero ir a SAFFRON\npara ver o TREM\011ÍMÃ.",
  ["64:5f8b"] = "A EQUIPE ROCKET\nnão está mais em\011KANTO.\012Essa falta me\nalegra.",
  ["64:5fca"] = "Estou pensando em\nir às compras em\011SAFFRON.",
  ["64:6034"] = "Por muitos anos,\nos DIGLETT cavaram\011um grande túnel\011que vai a uma\011cidade distante.",
  ["64:6142"] = "SURGE: Ei, garo-\ntinho!\012Vou dar um trato\nem você. Não deve\012ser muito esperto\nme desafiar, mas\011eu aceito!\012Quando se fala de\n#MON elétri-\011cos, sou o melhor!\n\012Nunca perdi no\ncampo de batalha.\012Vou liquidá-lo\ncomo fiz com meus\011inimigos na guer-\011ra!",
  ["64:6238"] = "SURGE: Arrrgh!\nVocê é muito\011forte!\012Certo, garoto.\nVocê merece a IN-\011SÍGNIA DO TROVÃO!",
  ["64:6277"] = "{PLAYER} foi pre-\nsenteado com uma\011INSÍGNIA DO TROVÃO\011DO GINÁSIO DA\011CIDADE DE VERMILION.",
  ["64:6291"] = "SURGE: A INSÍGNIA\nDO TROVÃO acelera\011o #MON.\012Considere-a como\nprova de que me\012derrotou. Use-a\ncom orgulho,\011ouviu?",
  ["64:6303"] = "SURGE: Ei, garoto!\nAinda anda à toa\011por aí?\012Meus #MON e\neu ainda somos\011muito fortes!",
  ["64:6356"] = "Está aqui para\nvencer o TENENTE\011SURGE?\012Não se eu puder\nimpedir!",
  ["64:638c"] = "Perdão, eu falhei,\nTENENTE SURGE,\011senhor!",
  ["64:63b0"] = "Quando ainda esta-\nva no exército,\012o TENENTE SURGE\nsalvou minha vida.",
  ["64:63e8"] = "O TENENTE SURGE\nreconheceu meu\012potencial com\n#MON elétri-\011cos.\012Acha que pode\nme vencer?",
  ["64:6437"] = "Oh, que chocante!",
  ["64:644b"] = "Se as armadilhas\ndo GINÁSIO funci-\012onassem, você es-\ntaria torrado…",
  ["64:6487"] = "Vou destruí-lo!\nPrepare-se para\011ser chocado!",
  ["64:64ba"] = "Arghh! Superou\nmeus poderes…",
  ["64:64d6"] = "Não se conforte\npor me derrotar…\012O TENENTE SURGE\né forte!",
  ["64:6517"] = "Ei! CAMPEÃO em\nprogresso!\012Você teve sorte\nagora.\012O TENENTE SURGE é\nbem cauteloso. Ele\012fez armadilhas por\ntodo GINÁSIO.\012Mas--he-he--elas\nnão estão ativas\011agora.\012Não terá problemas\npara chegar a ele.",
  ["64:65df"] = "Uau! Que batalha\nelétrica!\012Certamente me dei-\nxou nervoso.",
  ["64:661e"] = "Nada! Só há lixo\naqui.",
  ["64:66fe"] = "Bem-vindo à CIDADE DE SAFFRON, lar do TREM ÍMÃ!\012…É o que eu digo normalmente,\011mas o TREM ÍMÃ não está funcionando agora.\012Não está recebendo energia porque há algo de errado\011com a USINA ELÉTRICA.",
  ["64:67cb"] = "O TREM ÍMÃ é a\ncoisa mais famosa\011de SAFFRON.",
  ["64:6d39"] = "Gostaria de\nbatalhar pelo cabo\011LINK ou pelo\011telefone celular?",
  ["64:6d7e"] = "Gostaria de\ntrocar pelo cabo\011LINK ou pelo\011telefone celular?",
  ["64:6de0"] = "Bem-vindo ao\nCOLISEU DO CLUBE\011CABO.\012Pode batalhar com\num amigo aqui.\012Você gostaria de\nbatalhar?",
  ["64:6e3a"] = "Bem-vindo ao\nCENTRO DE TROCAS\011CABO.\012Pode trocar seus\n#MON aqui com\011um amigo.\012Você gostaria de\ntrocar?",
  ["64:6e9f"] = "Bem-vindo à\nCÁPSULA DO TEMPO\011DO CLUBE CABO.\012Pode viajar ao\npassado e trocar\011seus #MON.\012Você gostaria de\ntrocar através do\011tempo?",
  ["64:6f19"] = "Seu amigo não\nestá pronto.",
  ["64:6f34"] = "Antes de conectar,\nvocê deve salvar\011o seu jogo.",
  ["64:6f67"] = "Aguarde.",
  ["64:6f75"] = "A conexão foi\ncancelada devido à\011inatividade.\012Favor contactar\nseu amigo e voltar\011depois.",
  ["64:6fd1"] = "Venha de novo.",
  ["64:7029"] = "Não pode se\nconectar ao\011passado aqui.",
  ["64:704a"] = "Escolheu salas\nincompatíveis.",
  ["64:706b"] = "Por favor entre.",
  ["64:708b"] = "Sorry--{STRBUF}\ncan't be taken.",
  ["64:70a8"] = "You can't take the\n{STRBUF} with a\011{STRBUF}.",
  ["64:70cf"] = "You can't take the\n{STRBUF} that\011has MAIL with you.",
  ["64:7100"] = "Perdoe-me, a\nCÁPSULA DO TEMPO\011está sendo\011ajustada.",
  ["64:712f"] = "Perdoe-me, a\nMÁQUINA DE TROCA\011está sendo\011ajustada.",
  ["64:715f"] = "Perdoe-me, A\nMÁQUINA DE BATALHA\011está sendo\011ajustada.",
  ["64:7190"] = "Olá! Você é\n{PLAYER}, certo?\012Eu tenho algo\npara você.",
  ["64:71c4"] = "Aqui está!",
  ["64:71d2"] = "Esperamos servi-lo\nde novo.",
  ["64:71ef"] = "Oh, você não tem\nlugar para isso.\012Pare em qualquer\nCENTRO #MON no\011mundo para\011receber o item.",
  ["64:724d"] = "Não? É muito\nestranho…",
  ["64:7266"] = "Oh, aguarde.",
  ["64:7278"] = "Precisamos mudar\no visual daqui…",
  ["64:729a"] = "O que você acha\ndesse estilo?",
  ["64:72bc"] = "Perdoe-me!\012As regras DO\nESTÁDIO exigem que\011você traga\011seis #MON\011diferentes,\011excluindo os OVOS.\011Esses #MON\011devem ser\011diferentes.\012E mais, não podem\nestar segurando\011itens.\n\012Volte quando você\nestiver pronto.",
  ["64:74a0"] = "Seu amigo está\npronto.",
  ["64:7521"] = "Seu amigo está\npronto.",
  ["64:7591"] = "Estabilizando\ncomunicações…",
  ["64:7626"] = "Estabilizando\ncomunicações…",
  ["64:7644"] = "Seus #MON\nserão totalmente\011curados antes da\011batalha.",
  ["65:426b"] = "É uma árvore\nestranha.\012Usar o POTE\nSQUIRT?",
  ["65:4290"] = "{PLAYER} usou o\nPOTE SQUIRT.",
  ["65:42aa"] = "A árvore estranha\nnão gosta do POTE\011SQUIRT!\012A árvore estranha\natacou!",
  ["65:42f1"] = "Sou FLORIA da\nLOJA DE FLORES!\012Ouça, ouça!\012Quando eu joguei\nágua naquela\011árvore agitada,\011ela pulou!\012Tem que ser um\n#MON.\012Aposto que ela\nficaria abalada se\011você molhasse seu\011disfarce!\012Já sei! Vou contar\na minha irmã e\011pegar o regador\011emprestado com\011ela!",
  ["65:43ed"] = "Quando contei a\nminha irmã da\011árvore agitada,\011ela disse que era\011perigoso.\012Se eu derrotar\nWHITNEY, talvez\011ela me empreste o\011regador…",
  ["65:446f"] = "Wa-hey!\012Eu ia arrancar\naquela árvore com\011meu soco direto.\012Mas eu não pude!\nEu sou um\011fracassado!",
  ["65:44d0"] = "Você eliminou\naquela árvore\011idiota?\012Estou\nimpressionado.\012Quero que leve\nisso.",
  ["65:452c"] = "Isso é o ESMAGA-PEDRAS.\012Você pode quebrar\numa pedra com um\011simples e bem\011mirado golpe.\012Se tiver alguma\npedra em seu\011caminho, basta\011quebrá-la!",
  ["65:4626"] = "Uma estranha\nárvore está\011fechando o\011caminho para a\011CIDADE DE GOLDENROD.\012Está me privando\nde fazer compras.\012Algo tem que ser\nfeito.",
  ["65:469e"] = "Aquela estranha\nárvore sumiu sem\011deixar rastro.\012Oh! Ela era mesmo\num #MON?",
  ["65:46ed"] = "Eu vou ler seus\npensamentos!",
  ["65:470e"] = "Eu o subestimei!",
  ["65:471e"] = "Eu seria forte\nse conseguisse\011saber o que meu\011oponente está\011pensando.",
  ["65:4760"] = "Graças a meus\nestudos, estou\011pronto para\011qualquer #MON!",
  ["65:4790"] = "Opa! Erro de\ncomputação?",
  ["65:47aa"] = "Droga! Eu estudo\ncinco horas por\011dia.\012Há outros modos\nde aprender sem\011ler livros.",
  ["65:4800"] = "ARTHUR: Quem é\nvocê?\012Sou ARTHUR da\nQuinta.",
  ["65:482d"] = "Ei. Você pode\nlevar isso.",
  ["65:4847"] = "ARTHUR: Um #MON\nque usa golpes do\011tipo pedra deve\011segurar isso.\012Ele impulsiona\ngolpes do tipo\011pedra.",
  ["65:48aa"] = "ARTHUR: Sou ARTHUR\nda Quinta.\012Sou o segundo\nfilho nascer das\011sete crianças.",
  ["65:48f3"] = "ARTHUR: Hoje não\né Quinta.\012Que desagradável.",
  ["65:4924"] = "ROTA 36.",
  ["65:492e"] = "RUÍNAS ALFA\nENTRADA NORTE.",
  ["65:494c"] = "DICAS DO TREINADOR\012O estado dos\n#MON muda,\011mesmo em tipos\011iguais.\012Suas situações\npodem ser\011parecidas no\011início.\012Porém, as\ndiferenças virão à\011medida que o\011#MON crescer.",
  ["65:49ee"] = "DICAS DO TREINADOR\012Use o CAVAR para\nvoltar à entrada\011de qualquer lugar.\012É util para\nexplorar cavernas\011e outros lugares.",
  ["65:4b45"] = "Uma pessoa da\nELITE QUATRO era o\011LÍDER DO GINÁSIO\011DE FUCHSIA.",
  ["65:4b83"] = "A filha de KOGA\no sucedeu como\011LÍDER DE GINÁSIO\011depois dele ir\011para a ELITE\011QUATRO.",
  ["65:4bd3"] = "A ZONA DO SAFÁRI\nestá fechada…\011É triste, pois é\011a maior atração\011de FUCHSIA.",
  ["65:4c22"] = "CIDADE DE FUCHSIA\n\012Olhe! É a Paixão\nRosada!",
  ["65:4c4a"] = "CIDADE DE FUCHSIA\012LÍDER DO GINÁSIO\n#MON: JANINE\012A Venenosa Mestra\nNinja.",
  ["65:4c8b"] = "Há um aviso\naqui…\012O ESCRITÓRIO DA\nZONA DO SAFÁRI\011estará fechada até\011segunda ordem.",
  ["65:4cd5"] = "ZONA DO SAFARI\012CASA DO PATRÃO.",
  ["65:4cf0"] = "O PATRÃO está\nviajando.\012Consequentemente,\na ZONA DO SAFÁRI\011está fechada.",
  ["65:4d37"] = "Não bagunce.\012Favor levar seu\nlixo com você.",
  ["65:4efa"] = "Sou CLAIR.\012A melhor mestra\nem dragão do\011mundo.\012Posso me garantir\nmesmo contra a\011ELITE QUATRO DA\011LIGA #MON.\012Ainda deseja me\ndesafiar?\012…Ótimo. Vamos lá!\012Como LÍDER DE\nGINÁSIO, usarei\011todo meu poder\011contra qualquer\011oponente!",
  ["65:4fd6"] = "Eu perdi?\012Não acredito. Deve\nhaver algum erro…",
  ["65:500e"] = "Não admitirei\nisso.\012Posso ter perdido,\nmas você aiNda\011não está pronto\011para a LIGA\011#MON.\012Já sei. Você deve\nenfrentar o\011desafio de quem\011usa dragões.\012Atrás desse\nGINÁSIO está um\011lugar chamado TOCA\011DO DRAGÃO.\012Há um pequeno\nsantuário em seu\011centro. Vá lá.\012Se puder provar\nque perdeu\011sua preguiça,\011reconhecerei você\011como treinador\011merecedor da\011INSÍGNIA DO\011GINÁSIO!",
  ["65:5162"] = "Qual o problema?\012É esperar demais\nde você?",
  ["65:5196"] = "Fez-me esperar!\012Ei! Leve isso!",
  ["65:51bf"] = "{PLAYER} recebeu\nTM24.",
  ["65:51d1"] = "Isso contém o\nSOPRO DRAGÃO.\012Não, não tem nada\na ver com meu\011sopro.\012Se não o quiser,\nvocê não precisa\011levá-lo.",
  ["65:524f"] = "O que é isso?\nVocê não tem\011espaço?",
  ["65:5272"] = "Qual o problema?\012Você não está indo\nà LIGA #MON?\012Você não sabe onde\nela fica?\012Daqui, vá à CIDADE DE\nNEW BARK. Depois\011SURFE para o\011leste. A rota que\011vem depois é\011difícil.\012Não se atreva a\nperder na LIGA\011#MON!\012Se o fizer, eu me\nsentirei ainda\011pior do que ter\011perdido para você!\012Dê o máximo de\nvocê.",
  ["65:5396"] = "Sua primeira\nbatalha contra\011dragões?\012Vou lhe\nmostrar como\011são poderosos!",
  ["65:53db"] = "Meu #MON dragão\nperdeu?",
  ["65:53f1"] = "LANCE lhe disse\nque gostaria de\011vê-lo de novo?\011Sem chance!",
  ["65:542f"] = "Minha chance de\nperder? Nem um\011porcento!",
  ["65:545b"] = "É estranho.",
  ["65:5467"] = "Conheço meus\ndefeitos agora.\012Obrigado por me\nmostrá-los!",
  ["65:549d"] = "Dragões são\n#MON sagrados.\012Eles são cheio de\nvida e energia.\012Se não for sério,\nnão será capaz de\011derrotá-los.",
  ["65:550a"] = "Vamos em frente!",
  ["65:5516"] = "Dragões são\nfracos contra\011golpes tipo\011dragão.",
  ["65:5544"] = "Ei! CAMPEÃO em\nprogresso!\012Foi uma longa\njornada, mas está\011quase acabando!\011Conte comigo!\012CLAIR usa\nos místicos e\011sagrados #MON\011tipo dragão.\012Você não pode\nferi-los com\011facilidade.\012Mas você sabe,\ndizem que eles\011são fracos contra\011golpes tipo gelo.",
  ["65:5632"] = "Você foi ótimo\nao vencer CLAIR!\012Tudo que falta\né o desafio da\011LIGA #MON.\012Você está no\ncaminho de se\011tornar o CAMPEÃO\011#MON!",
  ["65:5789"] = "Nem todos aqui\nusam #MON do\011tipo dragão.",
  ["65:57b6"] = "Droga! Se só eu\ntivesse dragões.",
  ["65:57d5"] = "Membros do nosso\nclã de dragões só\011podem usá-los após\011nosso MESTRE\011permitir.",
  ["65:582b"] = "Não posso deixar\num treinador\011qualquer passar!\012CLAIR ficaria\ndecepcionada!",
  ["65:5874"] = "Awww… Perdi…",
  ["65:5883"] = "Uh-oh… CLAIR vai\nficar maluca…",
  ["65:58a5"] = "A pedra caiu!",
  ["65:595c"] = "Um clã de\ntreinadores que\011podem comandar\011dragões livremente\011mora aqui em\011BLACKTHORN.\012Como resultado,\nhá várias lendas\011sobre dragões\011nessa cidade.",
  ["65:59ee"] = "DRATINI: Draa!",
  ["65:5a6a"] = "Você não pode\ncomprar o REVIVE\011TOTAL, que cura\011todo o HP do\011#MON desmaiado.\n\012Cuidado--Isso não\nrestaura o PP,\011PONTOS DE PODER,\011usado em golpes.",
  ["65:5ae9"] = "O REPELENTE 03\nafasta #MON\011fracos de você.\012É o REPELENTE\nde maior duração\011que existe.",
  ["65:5b85"] = "Nas profundezas do\nPLANALTO ÍNDIGO\011está a LIGA\011#MON.\012Eu soube que\nos melhores\011treinadores de\011todos os lugares\011vão lá.",
  ["65:5bfd"] = "Havia um golpe\nque eu tinha que\011ensinar ao meu\011#MON.\012Então, o APAGADOR\nDE GOLPES o fez\011esquecer um golpe\011HM.",
  ["65:5cf5"] = "Esperava comprar\numas lembranças\011da ZONA DO SAFÁRI,\011mas ela está\011fechada.",
  ["65:5d36"] = "A neta do PATRÃO\nda ZONA DO SAFÁRI\011vive na cidade.",
  ["65:5f35"] = "Fufufufu…\012Perdão por\ndesapontá-lo…\012Só estou\nbrincando!\012Sou a real!\012JANINE do GINÁSIO\nDE FUCHSIA, sou\011eu!",
  ["65:5fa1"] = "JANINE: Você\né bem forte.\011Definitivamente\011venceu…\012Eis a INSÍGNIA DA\nALMA. Leve-a.",
  ["65:5feb"] = "{PLAYER} recebeu\nOVO ESTRANHO.",
  ["65:6002"] = "JANINE: Você é\ntão forte! Tenho\011um presente\011especial!\012É o TÓXICO, um\npoderoso veneno\011que corta de pouco\011em pouco o HP da\011vítima.",
  ["65:6074"] = "JANINE: Eu\nrealmente vou me\011aplicar e melhorar\011minhas técnicas.\012Quero ser melhor\nque o meu pai e\011que você!",
  ["65:60e6"] = "Fufufu!\012Sou JANINE, a\nLÍDER DO GINÁSIO!\012Não, não sou!\nPeguei você,\011otário!",
  ["65:6126"] = "Eu o enganara…",
  ["65:6139"] = "Como saberá quem\né a LÍDER de\011verdade?",
  ["65:6166"] = "Enganei você!\nHahaha!",
  ["65:617b"] = "Ooh… Perdi…\nVocê não é fraco…",
  ["65:6199"] = "Bem? Meu disfarce\nnão era perfeito?",
  ["65:61bb"] = "Sou JANINE!\012Como sabia que\nera eu?\012Vamos batalhar!",
  ["65:61f1"] = "Droga! Eu queria\nvencer!",
  ["65:620c"] = "Você deve estar\nse cansando.",
  ["65:6228"] = "Wahahaha!\012Claro! Sou JANINE!",
  ["65:624a"] = "Meu disfarce\nestava bom, não é?",
  ["65:626b"] = "Ei, você. Meu\ndisfarce era lindo\011ou o quê, hã?",
  ["65:6299"] = "Ei, CAMPEÃO em\nprogresso!\012Opa! Dê uma olhada\nao seu redor.\011Todas treinadoras\011se parecem com a\011LÍDER JANINE.\012Qual delas é a\nJANINE de verdade?",
  ["65:6325"] = "Essa foi uma\ngrande batalha,\011treinador de\011JOHTO!",
  ["65:63c3"] = "Meu avô está na\nCASA do meu irmão\011BILL na PENÍNSULA\011CERULEANA.",
  ["65:63f9"] = "Vi esses #MON\nestranhos e lentos\011na PISTA DE\011CICLISMO.",
  ["65:6494"] = "Ei! Você tem um\nnovo tipo de\011#DEX.\012Foi o PROFESSOR\nCARVALHO quem lhe\011deu?",
  ["65:64dc"] = "Fiquei chocada\nno GINÁSIO.\012Todas as garotas\nde lá pareciam ser\011idênticas.",
  ["65:652e"] = "Sou JANINE!\nAbracadabra…\011Puf!",
  ["65:654e"] = "Vê? Pareço com\nela agora!",
  ["65:65e6"] = "Meu avô é o\nPATRÃO da ZONA DO\011SAFÁRI.\012Pelo menos era…\012Ele decidiu ir\npara umas férias\011e foi através dos\011mares por ele\011mesmo.\012Parou de comandar\na ZONA DO SAFÁRI\011desde então.",
  ["65:6691"] = "Várias pessoas se\ndesapontaram\011quando a ZONA\011DO SAFÁRI fechou,\011mas o vovô é tão\011teimoso…",
  ["65:66ea"] = "É uma foto de um\nhomem idoso que\011está cercado por\011#MON.",
  ["65:6726"] = "É uma foto\nde uma grande\011planície com\011grama e com\011#MON raros se\011divertindo.",
  ["65:67a1"] = "Está trabalhando\nna #DEX? Isso é\011algo importante.\012Não desista!",
  ["65:6834"] = "Eles estão sem\n# BOLAS!\012Quando eles\nadquirirão mais?",
  ["65:6873"] = "As # BOLAS\nchegaram! Agora\011posso capturar\011#MON!",
  ["65:68a0"] = "Quando caminhava\nna grama, um\011#MON inseto\011envenenou meu\011#MON! \012Continuei andando,\nporém meu #MON\011desmaiou. \012É recomendável que\ntenha um ANTÍDOTO\011com você.",
  ["65:698a"] = "Que bom. Posso\nguardar quantos\011#MON eu quiser\011e é de graça.",
  ["65:69c8"] = "Qualquer treinador\npode usar o\011COMPUTADOR.",
  ["65:69f1"] = "O CENTRO DE\nCOMUNICAÇÃO acima\011acabou de ser\011feito.\012Mas eles ainda\nestão fazendo\011ajustes.",
  ["65:6a46"] = "O CENTRO DE\nCOMUNICAÇÃO acima\011acabou de ser\011feito.\012Já troquei\n#MON lá!",
  ["65:6aea"] = "Você está vendo\ncomo se sai sendo\011um treinador\011#MON?\012Recomendo-lhe\nvisitar os\011GINÁSIOS #MON\011em JOHTO e coletar\011INSÍGNIAS.",
  ["65:6b65"] = "Quando eu crescer,\nserei um LÍDER DE\011GINÁSIO!\n \012Faço meus #MON\nbatalharem com os\011do meu amigo para\011fortalecê-los!",
  ["65:6c0d"] = "Quando era jovem,\neu fui um incrível\011treinador!\012Aqui vai um\nconselho: Capture\011muitos #MON!\012Trate-os com toda\ngentileza!",
  ["65:6cc3"] = "Os #MON ganham\nexperiência nas\011batalhas e mudam\011suas formas.",
  ["65:6cfc"] = "Os #MON mudam?\012Eu ficaria chocada\nse um mudasse!",
  ["65:6d82"] = "Você sabe, os\n#MON comem\011FRUTAS.\012Bem, meu #MON\nficou mais\011saudável ao comer\011uma FRUTA.\012Ei. Dividirei uma\ncom você!",
  ["65:6dec"] = "Cheque as árvores\npara obter FRUTAS.\012Elas caem das árvores.",
  ["65:6f66"] = "Olá, olá! Você\ndeve ser {PLAYER}.\012O PROFESSOR ELM\ndisse que você\011viria.",
  ["65:6fa8"] = "É isso que quero\nque o PROFESSOR\011ELM examine.",
  ["65:6fd2"] = "{PLAYER} recebeu\nOVO ESTRANHO.",
  ["65:6feb"] = "Conheço um casal\nque comanda o\011CRIATÓRIO #MON.\012Eles me deram esse\nOVO.\012Fiquei intrigado,\nentão enviei uma\011carta ao PROFESSOR\011ELM.\012Para a evolução\n#MON, o\011PROFESSOR ELM é a\011autoridade.",
  ["65:7092"] = "Até o PROFESSOR\nCARVALHO reconhece\011isso.",
  ["65:70b7"] = "Se o que acho\nfor certo, o\011PROFESSOR ELM\011saberá.",
  ["65:70ed"] = "Você está voltando\nao PROFESSOR ELM?\012Ei. Seu #MON\ndeve descansar um\011pouco.",
  ["65:7134"] = "Eu dependo de\nvocê!",
  ["65:714a"] = "A vida é ótima!\nSempre há coisas\011para descobrir!",
  ["65:7185"] = "CARVALHO: Aha!\nEntão você é\011{PLAYER}!\012Sou CARVALHO!\nUm pesquisador\011#MON.\012Estava só\nvisitando meu\011velho amigo SENHOR\011#MON.\012Soube que cumpria\numa missão para\011o PROFESSOR ELM,\011então esperei\011aqui.\012Oh! O que é isso?\nUm #MON raro!\012Vamos ver…\012Hm, entendo!\012Entendo porque o\nPROFESSOR ELM lhe\011deu um #MON\011para esta missão.\012Para pesquisadores\ncomo PROFESSOR ELM\011e eu, os #MON\011são nossos amigos.\012Ele viu que você\ntrataria seu\011#MON com amor e\011carinho.\012…Ah!\012Você parece ser\ndependente.\012Como gostaria de\nme ajudar?\012Vê? Essa é a\nversão mais\011recente da\011#DEX.\012Ela grava\nautomaticamente\011dados dos #MON\011vistos ou pegos.\012É uma enciclopédia\nde tecnologia\011alta!",
  ["65:73cc"] = "{PLAYER} recebeu\n#DEX!",
  ["65:73de"] = "Vá encontrar\nvários tipos de\011#MON e\011completar a\011#DEX!\012Fiquei aqui por\nmuito tempo.\012Devo ir a\nGOLDENROD para\011meu programa de\011rádio de costume.\012{PLAYER}, conto com\nvocê!",
  ["65:7476"] = "Hm? Essa ESCAMA!\nO que é isso? Um\011GYARADOS vermelho?\012Que raro! Eu, eu\na quero…\012{PLAYER}, se\nimporta em\011trocá-la?\012Posso oferecer\nesse DIVIDE EXP.\011que o PROFESSOR\011CARVALHO me deu.",
  ["65:750d"] = "Que pena. Isso\nparece ser muito\011raro.",
  ["65:7543"] = "Está empacotado\ncom revistas\011estrangeiras.\012Nem dá para ler\nseus títulos…",
  ["65:7584"] = "É um grande\ncomputador. Hmm.\011Está quebrado.",
  ["65:75ac"] = "Uma grande pilha\nde moedas\011estranhas!\012Talvez sejam de\num outro país…",
  ["65:763a"] = "Olá! Já visitou a\nTORRE BROTINHO?",
  ["65:7661"] = "Eu vim de longe.\nÉ melhor eu ligar\011para casa!",
  ["66:414d"] = "…Diga-me algo.\012É verdade que\na EQUIPE ROCKET\011voltou?\012O quê? Você os\nderrotou? Hah! Não\011minta.\012Não é piada?\nEntão vamos ver o\011quanto você é bom.",
  ["66:41e6"] = "… Hmph! #MON\ninúteis!\012Você, escute. Só\nvenceu porque meus\012#MON são\nfracos.",
  ["66:4233"] = "Odeio a fraqueza.\012#MON, trei-\nnadores. Não\011importa quem ou o\011quê. \012Eu serei forte\ne exterminarei a\011fraqueza.\012Isso vale para\na EQUIPE ROCKET\011também.\012Eles são fortes\nem grupo.\012Mas sozinhos,\neles são fracotes.\012Eu os odeio.\012E você saia do\nmeu caminho. Um\012fracote como você\né só distração.",
  ["66:435b"] = "…Hmph! Sabia\nque você mentiu!",
  ["66:437b"] = "É inseguro ir lá,\nentão estou em\011guarda.\012Não sou um Bom\nSamaritano?",
  ["66:43c7"] = "Você conhece o\nRABOSLOWPOKE?\011Soube que é ótimo.\012Não se alegra por\neu te contar isso.",
  ["66:441b"] = "Os SLOWPOKE sumi-\nram da cidade…\012Soube que estão\nvendendo suas CAU-\011DAS por aí.",
  ["66:4473"] = "Os SLOWPOKE vol-\ntaram.\012Como os conheço,\nsei que não passe-\012avam por aí.",
  ["66:44ce"] = "Você veio pedir\na KURT para fa-\011zer BOLAS?\012Muita gente só\nfaz isto.",
  ["66:451a"] = "Atravesse AZALEA\ne vai estar na\011FLORESTA DE ILEX.\012Mas as árvores\nmagrelas impos-\012sibilitam a pas-\nsagem.\012O #MON DO HO-\nMEM DO CARVÃO pode\011cortá-las.",
  ["66:45b0"] = "SLOWPOKE: …\012…… …… ……",
  ["66:45c3"] = "…… ……Yawn?",
  ["66:45df"] = "A FLORESTA DE ILEX\nestá agitada!\012O que está\nhavendo?",
  ["66:460b"] = "{PLAYER}, aqui está\nsua BOLA GS de\011volta!",
  ["66:4628"] = "Poderia ir ver por\nque a FLORESTA\011ILEX está tão\011agitada?",
  ["66:465a"] = "CIDADE DE AZALEA\012Onde Pessoas e\n#MON Vivem em\011Ótima Harmonia.",
  ["66:4693"] = "CASA DO KURT.",
  ["66:46a1"] = "CIDADE DE AZALEA\012LÍDER DO GINÁSIO\nPOKÉMON: BUGSY\012A Enciclopédia\n#MON Ambulante.",
  ["66:46e7"] = "POÇO DOS SLOWPOKE\012Também chamado\nde POÇO QUE FAZ\011CHOVER. \012Os habitantes\nacreditam que o\011bocejo do SLOWPOKE\011chama a chuva.\012Os registros indi-\ncam que o bocejo\011do SLOWPOKE acabou\012com uma seca há\n400 anos.",
  ["66:478d"] = "ESTUFA DE CARVÃO.",
  ["66:479c"] = "FLORESTA DE ILEX\012Entre pelo\nportão.",
  ["66:4a69"] = "Eles fizeram a\nnova TORRE DE\011RÁDIO para subs-\012tituir a velha em\nruínas.",
  ["66:4aa9"] = "Eu sei que há uma\nnova LOJA DE BICI-\011CLETAS, mas não\012consigo achá-la.",
  ["66:4ae6"] = "Aquele homem de\npreto está vesti-\012do como membro\nda EQUIPE ROCKET?\012Que tolo!",
  ["66:4b2d"] = "Aquele homem de\npreto é mesmo da\012EQUIPE ROCKET?\nNão acredito!",
  ["66:4b73"] = "A TORRE DE RÁDIO\nna CIDADE DE GOLDEN-\011ROD é um ponto\011turístico.\012Eles estão fazendo\numa campanha pro-\011mocional agora.\012Vão alterar sua\n#GEAR,\012daí ela servirá\ncomo um rádio.",
  ["66:4c14"] = "Oh, sua #GEAR\nfunciona como um\011rádio!",
  ["66:4c36"] = "E-he-he-he…\012Encrenquei-me por\njogar no porão\012da LOJA DE DEPAR-\nTAMENTOS.",
  ["66:4c83"] = "O homem naquela\ncasa avalia os\011nomes de seus\011#MON.\012Pode até renomeá-\nlos.",
  ["66:4ccf"] = "Uau! Que cidade\ngrande! Nem\012sei o lugar das\ncoisas.",
  ["66:4d0d"] = "Então essa é a\nTORRE DE RÁDIO…",
  ["66:4d2a"] = "O que você quer,\nsua peste? Some!",
  ["66:4d4e"] = "Sai do caminho!",
  ["66:4d6d"] = "Dominar a TORRE\nDE RÁDIO…\012O quê? Não é\nda sua conta!",
  ["66:4daa"] = "#MON? Não são\nnada mais que\012fábricas de di-\nnheiro!",
  ["66:4de2"] = "Nosso sonho se\nrealizará…\012Foi uma grande\nesforço…",
  ["66:4e1f"] = "Ei, pirralho!\nVocê não é daqui!\011Saia daqui!",
  ["66:4e4b"] = "Experimente o\nverdadeiro terror\011da EQUIPE ROCKET!",
  ["66:4e77"] = "ESTAÇÃO DA CIDADE\nDE GOLDENROD.",
  ["66:4e8f"] = "TORRE DE RÁDIO DA\nCIDADE DE GOLDENROD.",
  ["66:4eab"] = "Seleção Completa\nde Produtos #-\011MON!\012LOJA DE DEPARTA-\nMENTOS DA CIDADE\011GOLDENROD.",
  ["66:4ee4"] = "CIDADE DE GOLDENROD\012LÍDER DO GINÁSIO\nPOKÉMON: WHITNEY\012A Garota Incri-\nvelmente Linda!",
  ["66:4f29"] = "CIDADE DE GOLDENROD\012A Festiva Cidade\nCharmosa.",
  ["66:4f5b"] = "O Mundo é\nredondo!\011LOJA DE BICI-\nCLETAS.",
  ["66:4f81"] = "O Seu Lazer!\012CASA DE JOGOS DA\nCIDADE DE GOLDENROD.",
  ["66:4fae"] = "AVALIADOR DE NOMES\012Avalie o Apelido\nde seu #MON.",
  ["66:4fd8"] = "SUBTERRÂNEO\nENTRADA.",
  ["66:4fee"] = "SUBTERRÂNEO\nENTRADA.",
  ["66:5022"] = "Florescendo Bonito\nLOJA DE FLORES.",
  ["66:5042"] = "Posso ensinar\nótimos golpes ao\012seu #MON se\nquiser.\012Quer que eu\nensine?",
  ["66:5090"] = "Vai custar 4000\nmoedas. Certo?",
  ["66:50b4"] = "Aww… Mas eles são\nótimos…",
  ["66:50ce"] = "Haha! Você não\nse arrependerá!\012Qual golpe eu\ndevo ensinar?",
  ["66:5107"] = "Hm, que pena. Te-\nrei que pegar di-\011nheiro de casa…",
  ["66:513a"] = "Se entendessem\na preciosidade\012deste golpe,\nvocê o usaria\011como treinador.",
  ["66:518b"] = "Hahahah!\nAdeus, garoto!",
  ["66:51a4"] = "M-mas…",
  ["66:51ac"] = "…Você não tem\nmoedas suficientes\011aqui…",
  ["66:538d"] = "A garota DUPLICA\nparecia triste.\012Ela disse que\nperdeu sua BONECA\011predileta, a\011CELFAIRY.",
  ["66:540d"] = "A garota DUPLICA\nparecia triste.\012Ela disse que\nperdeu sua BONECA\011predileta, a\011CELFAIRY.",
  ["66:5460"] = "Você veio de\nJOHTO?\012Poderia voltar\npara casa se o\011TREM IMÃ estivesse\011funcionando.",
  ["66:54ae"] = "Você veio de\nJOHTO?\012Pode voltar para\ncasa através do\011TREM IMÃ.",
  ["66:54fe"] = "Fui ao GINÁSIO\nquerendo batalhar\011com treinadores…\012Tudo ficou confuso\ne eu fui parar no\011GINÁSIO ao lado.\012Cara, eu\nfiquei bastante\011embaraçado.",
  ["66:558e"] = "Essa é a\nCORPORAÇÃO SILPH,\011famosa por seus\011produtos #MON.\012No passado, a\nEQUIPE ROCKET\011queria a compania\011por causa disso.",
  ["66:55fc"] = "Chew… Chew…\012Soube que há um\ngrande problema\011na USINA ELÉTRICA.\n\012Chew… Chew…",
  ["66:564b"] = "Chew… Chew…\012Soube que havia\num grande problema\011na USINA ELÉTRICA.\012Chew… Chew…\nHaah, cansei!",
  ["66:56a5"] = "Ir ao beco pela\nprimeira vez me\011deixa ansioso.",
  ["66:56e5"] = "Há um lugar\nchamado CASA DO\011TREINADOR em\011VIRIDIAN onde\011treinadores de todos\011lugares se reúnem.",
  ["66:5745"] = "Nossa cidade foi\ncitada em um\011programa de rádio.\012É bom ouvir\nelogios para sua\011cidade, mas é\011embaraçoso também.",
  ["66:57b7"] = "CIDADE DE SAFFRON\012O Brilhante Ponto\nComercial Dourado.",
  ["66:57e6"] = "CIDADE DE SAFFRON\012LÍDER DO GINÁSIO\n#MON: SABRINA\012A Mestra\ndos #MON\011Psíquicos!",
  ["66:5829"] = "Sejam Todos\nBem-vindos!\012GINÁSIO DE LUTA.",
  ["66:584a"] = "CORPORAÇÃO SILPH\012PRÉDIO DE\nESCRITÓRIO.",
  ["66:5865"] = "CASA DO SENHOR\nPSÍQUICO.",
  ["66:5879"] = "CIDADE DE SAFRON\012ESTAÇÃO DO\nTREM ÍMÃ.",
  ["66:599c"] = "Eu soube que um\nGYARADOS vermelho\011apareceu no LAGO.\012É estranho, sendo\nque até GYARADOS\011comuns são raros\011naquele lago…",
  ["66:5a0e"] = "Meu programa de\nrádio preferido?\012É o MÚSICA\n#MON.",
  ["66:5a3d"] = "Eu escutei risos\nno rádio…\012É horripilante.",
  ["66:5b8d"] = "Os #MON\ntêm várias\011experiências em\011suas vidas, como\011nós.\012Eu, também, vi\ne sofri muito em\011minha vida.\012Como sou mais\nvelho, deixe-me\011ensinar o que eu\011quero dizer.\012Eu estive com\n#MON desde\011antes de você\011nascer.\012Eu não perco\nfacilmente.\012Eu, PRYCE--o\ntreinador do\011inverno--vou\011demonstrar meu\011poder!",
  ["66:5cb3"] = "Ah, estou\nimpressionado pela\011sua proeza.\012Ah, com sua força\nde vontade, você\011vai superar todos\011os obstáculos.\012Você merece essa\nINSÍGNIA!",
  ["66:5d3b"] = "{PLAYER} foi\npresenteado com\011uma INSÍGNIA\011GLACIAL DO GINÁSIO\011DA CIDADE\011MAHOGANY.",
  ["66:5d55"] = "Essa INSÍGNIA\nmelhorará o\011ESPECIAL dos\011#MON.\012Também permite seu\n#MON usar\011o REDEMOINHO\011para atravessar\011redemoinhos.\012E isso… Isso é um\npresente meu!",
  ["66:5def"] = "Esse TM contém o\nVENTO GELADO.\012Ele causa danos\ne reduz a\011velocidade.\012Isso demonstra a\ndureza do inverno.",
  ["66:5e59"] = "Quando o gelo e a\nneve derretem, a\011primavera chega.\012Você e seus\n#MON estarão\011juntos por muitos\011anos.\012Aproveitem juntos\nseus momentos!",
  ["66:5ee1"] = "Vou congelar seus\n#MON e não\011poderão fazer\011nada!",
  ["66:5f10"] = "Droga. Não pude\nfazer nada.",
  ["66:5f2d"] = "Acho que tem um\ngolpe que um\011#MON pode\011usar quando\011congelado.",
  ["66:5f65"] = "Esse GINÁSIO\ntem um chão\011escorregadio.\012É legal, né?\012Mas--não estamos\nbrincando aqui!",
  ["66:5fbd"] = "Você vê o quanto\nsomos sérios?",
  ["66:5fdd"] = "O GINÁSIO é ótimo.\nAdoro deslizar com\011meus #MON!",
  ["66:600f"] = "Eu sei o segredo\nde PRYCE.",
  ["66:6026"] = "Certo, lhe\ncontarei o segredo\011de PRYCE.",
  ["66:6047"] = "O segredo da força\nde PRYCE…\012Ele medita embaixo\nda cachoeira\011diariamente para\011fortalecer seu\011corpo.",
  ["66:60ae"] = "Para alcançar\nPRYCE, LÍDER DO\011GINÁSIO, você\011precisa pensar\011antes de deslizar.",
  ["66:60f4"] = "Não perderia para\nvocê no esqui!",
  ["66:6116"] = "Se você não\ndeslizar com\011precisão, não\011avançará nesse\011GINÁSIO.",
  ["66:6157"] = "Olhe meu turno\nparalelo!",
  ["66:6174"] = "Não! Deixou-me\ncom raiva!",
  ["66:618f"] = "Eu não deveria\nme gabar quanto\011ao meu esqui…",
  ["66:61bf"] = "PRYCE é um\nveterano que\011treina #MON\011por mais de 50\011anos.\012Dizem que ele é\nbom em congelar\011oponentes com\011golpes do tipo\011gelo.\012Quer dizer\nque você deve\011derretê-lo com sua\011quente ambição!",
  ["66:6275"] = "PRYCE é algo, mas\nvocê é algo a\011mais!\012Essa foi uma\nquente batalha que\011trouxe à tona o\011espaço entre\011gerações!",
  ["66:6362"] = "O que é isso?\nA EQUIPE ROCKET\011voltou?\012Eu vi um homem de\npreto no LAGO DA\011FÚRIA…",
  ["66:63b3"] = "Eu impedi meus\n#MON de\011evoluírem muito\011cedo.\012Fi-los aprender\ncertos golpes\011antes de deixá-los\011evoluir.",
  ["66:6418"] = "Os #MON ficam\nmais fortes\011quando evoluem,\011mas também\011aprendem golpes\011mais tarde.",
  ["66:64b8"] = "A MONTANHA\nMORTEIRO é um\011labirinto dentro.\012Cuidado. Não se\nperca lá.",
  ["66:654b"] = "…Você veio de\nlonge…\012Aqui eu meditei.\nDentro de mim, um\011novo poder foi\011despertado.\012Deixe-me dividir\nmeu poder com o\011seu #MON. Leve\011isso, garoto.",
  ["66:65de"] = "Pode sentir?\nÉ o PODER OCULTO!\012Ele libera o poder\ndo #MON para\011atacar.\012Lembre-se disso:\nseu tipo e poder\011depende do #MON\011que estiver\011usando.",
  ["66:6673"] = "Eu estou\nmeditando…",
  ["66:672e"] = "O LAGO DA FÚRIA é\nna verdade uma\011cratera feita\011por rituais de\011GYARADOS. Ela se\011encheu de água da\011chuva e o LAGO\011foi formado.\012Essa história é\npassada desde o\011tataravô do meu\011avô.\012Ali era um lugar\nque se podia\011capturar MAGIKARPS\011facilmente, mas…\012Eu não entendo\no que está\011acontecendo ao\011lago.",
  ["66:684d"] = "O LAGO está\nestranho desde\011quando aqueles\011homens de preto\011chegaram.",
  ["66:6890"] = "O LAGO DA FÚRIA\nvoltou ao normal.\011As MAGIKARPS\011retornaram.\012Eu ainda posso\nrealizar meu sonho\011de ver a maior\011MAGIKARP do mundo.\012Você tem uma VARA?\nAjude-me se quiser.",
  ["66:693e"] = "Ah, você tem uma\nMAGIKARP!\012Deixe-me ver o\ntamanho dela.",
  ["66:6977"] = "Uau! Essa é\nincrível!\012Eu tiro meu chapéu\npara você!\012Leve essa\nlembrança!",
  ["66:69c3"] = "O recorde que é\nimportante.\012Considere-o como\num bônus!",
  ["66:6a01"] = "Uau! essa é\nincrível!\012…Não queria dizer\nisso, mas eu já\011outras que são\011maiores.",
  ["66:6a5c"] = "O quê? Isso não é\numa MAGIKARP!",
  ["66:6a79"] = "Oh… Então você\nnão capturou uma\011muito boa para me\011mostrar?\012Talvez na\npróxima.",
  ["66:6b1f"] = "Só pessos que iam\npara o LAGO DA\011FÚRIA passaram\011por aqui\011atualmente.",
  ["66:6b65"] = "Atualmente ninguém\nvai ao LAGO DA\011FÚRIA.",
  ["66:6cd2"] = "Parado aí,\ngarotinho!\012O pedágio é ¥1000\npara atravessar.",
  ["66:6d0a"] = "Muito obrigado!",
  ["66:6d20"] = "Então pague o\nque tiver.",
  ["66:6d41"] = "He-he-he. Estamos\nficando ricos.\012Todos querem ver\no que está\011acontecendo no\011LAGO DA FÚRIA.",
  ["66:6d9b"] = "Eu fui expulso\ndo meu cargo por\011esses caras de\011preto.\012Eles esqueceram\nisso.\012Isso me deixa\ninconfortável.\011Poderia levá-lo?",
  ["66:6e2d"] = "Use esse portão\npara não andar na\011grama.",
  ["66:6ec0"] = "Oi!\012VERMELHO tem\nestado fora por um\011bom tempo.\012Ele não telefonou\ntambém.\012Logo, nem imagino\nonde ele está e\011o que está\011fazendo.\n \012Dizem que se não\nhá notícia é prova\011de que ele está\011bem, mas ainda me\011preocupo.",
  ["66:6f81"] = "Preocupo-me se\nVERMELHO adoecer\011ou se machucar,\011mas ele é um\011homenzinho.\012Orgulho-me por\nele estar fazendo\011só aquilo que\011quer.",
  ["66:6fe8"] = "Há programas aqui\nque não passam em\011JOHTO…",
  ["66:7050"] = "{PLAYER} jogou\nNINTENDO 64.\012É melhor ir, não\nhá tempo a perder!",
  ["66:7087"] = "Parece que não\né usado há um bom\011tempo…",
  ["66:7130"] = "DAISY: Oi! Meu\nirmão mais novo\011é o LÍDER DO\011GINÁSIO da CIDADE\011VERIDIANA.\012Mas ele sai tanto\nda cidade, que\011causa problemas\011aos treinadores.",
  ["66:71b6"] = "DAISY: Oi! Chegou\nem boa hora. Que\011tal um pouco de\011chá.\012Quer se juntar\na mim?\012Oh, seus #MON\nestão bem sujos.\012Gostaria que eu\ntratasse de um?",
  ["66:7244"] = "DAISY: De qual\ndeles devo\011tratar?",
  ["66:7266"] = "DAISY: Certo, vou\ndeixá-lo com bom\011visual rapidinho.",
  ["66:7296"] = "{STRBUF}\nparece contente.",
  ["66:72aa"] = "DAISY: Aqui está!\nTudo pronto.\012Vê? Não parece\nótimo.\012É um #MON\ntão lindo.",
  ["66:72fa"] = "DAISY: Sempre\ntomo chá nessa\011mesma hora.\012Junte-se a mim.",
  ["66:7334"] = "DAISY: Não quer\nque eu embeleze\011um? Certo, então\011só tomaremos cha.",
  ["66:7377"] = "DAISY: Oh, perdão.\nHonestamente,\011eu não posso\011embelezar um OVO.",
  ["66:7427"] = "CARVALHO: Ah,\n{PLAYER}!\012Foi bom você ter\npercorrido todo\011o caminho até\011KANTO.\012O que achou dos\ntreinadores daqui?\012Bem fortes, hã?",
  ["66:74a2"] = "Como vai a sua\n#DEX?\012Deixe-me ver…",
  ["66:74c8"] = "Se estiver por\naqui, espero que\011me visite de novo.",
  ["66:74fc"] = "CARVALHO: Uau!\nÉ excelente!\012Você coletou as\nINSÍGNIAS dos\011GINÁSIOS em KANTO.\011Parabéns!\012Eu estava certo a\nseu respeito.\012Vou lhe contar,\n{PLAYER}.\012Vou preparar uma\nviagem sua para\011o MONTE PRATA.\012O MONTE PRATA\né uma grande\011montanha que\011é casa de\011vários #MON\011selvagens.\012É muito perigoso\npara treinadores\011medianos, está\011fora dos limites.\012Mas podemos fazer\numa exceção em\011seu caso,\011{PLAYER}.\n\012Vá ao PLANALTO\nÍNDIGO. Pode\011chegar ao MONTE\011PRATA por lá.",
  ["66:76a2"] = "CARVALHO: Hã? Não\nestá coletando\011INSÍGNIAS DOS\011GINÁSIOS DE KANTO?\012Os LÍDERES de\nGINÁSIO daqui\011são fortes como\011aqueles com quem\011batalhou em\011JOHTO.\012Recomendo que os\ndesafie.",
  ["66:773c"] = "CARVALHO: Ah,\nestá coletando as\011INSÍGNIAS DOS\011GINÁSIOS DE KANTO.\012Deve ser difícil,\nmas a experiência\011certamente o\011ajudará.\012Venha me ver\nquando pegar\011todas.\012Vou lhe dar um\npresente.\012Continue treinando\nduro, {PLAYER}!",
  ["66:77fb"] = "O programa de\nrádio do PROFESSOR\011não passa aqui em\011KANTO.\012É uma vergonha,\neu queria ouvi-lo.",
  ["66:7859"] = "Graças a\nseu trabalho na\011#DEX, a\011pesquisa do\011PROFESSOR está\011caminhando muito\011bem.",
  ["66:78a7"] = "Não conte a\nninguém, mas o\011SHOW DO CARVALHO\011não é um programa\011ao vivo.",
  ["66:78ea"] = "Aperte START\npara abrir o MENU.",
  ["66:7909"] = "A opção SALVAR\nestá no MENU.\012Use-a de modo\nperiódico.",
  ["66:7945"] = "Não há nada\naqui…",
  ["66:795e"] = "Há uma mensagem\nde e-mail no\011COMPUTADOR.\012…\012PROFESSOR\nCARVALHO, como vai\011indo sua pesquisa?\012Eu ainda estou\ntrabalhando duro.\012Ouvi boatos de\nque {PLAYER} está\011com uma ótima\011reputação.\012Alegro-me muito\nem ouvir isso.\012ELM da CIDADE DE\nNEW BARK :-)",
  ["67:41e3"] = "Você é um trei-\nnador novato, né?\011Eu sabia!\012Certo! Todos\nsão novatos em\011alguma coisa!\012Se quiser, eu\npossou ensiná-lo\011algumas coisas.",
  ["67:426f"] = "Certo, então!\nSiga-me!",
  ["67:4285"] = "Este é um CENTRO\n#MON. Eles cu-\012ram seus #MON\nnum instante.\012Você confiará mui-\nto neles, então\012é melhor você\naprender sobre\011eles.",
  ["67:4304"] = "Esta é uma LOJA\n#MON.\012Eles vendem BOLAS\npara pegar #-\012MONS selvagens.\nE outros itens\011úteis.",
  ["67:4359"] = "A ROTA 30 é por\naqui.\012Os Treinadores ba-\ntalharão com seus\012premiados #MON\nlá.",
  ["67:43a7"] = "Este é o mar,\ncomo pode ver.\012Alguns #MON\nsó são achados\011na água.",
  ["67:43ec"] = "Ei…\012É minha casa!\nObrigado pela sua\011companhia.\012Deixe-me dar-lhe\num presentinho.",
  ["67:4438"] = "A #GEAR de\n{PLAYER} agora tem\011um MAPA!",
  ["67:4451"] = "A #GEAR se\ntorna mais útil ao\011receber CARTÕES.\012Desejo-lhe sorte\nem sua jornada!",
  ["67:449f"] = "Oh… É algo que\ngosto de fazer…\012Bom. Venha me ver\nquando quiser.",
  ["67:44e2"] = "… … …\012Você pegou um\n#MON no LABORA-\011TÓRIO.\012Que desperdício.\nUm bobão como\011você.\012… … …\012Não entendeu o\nque eu disse?\012Bem, eu tenho um\nbom #MON\011também.\012Vou mostrá-lo o\nque quero dizer!",
  ["67:457f"] = "Hmph. Está feliz\npor vencer?",
  ["67:459e"] = "… … …\012Chamo-me ???.\012Eu serei o melhor\ntreinador #MON\011do mundo.",
  ["67:45e6"] = "Hmph. Foi uma\nperca de tempo.",
  ["67:4608"] = "… … …\012Chamo-me ???.\012Eu serei o melhor\ntreinador #MON\011do mundo.",
  ["67:4650"] = "Você conversou com\no idoso perto do\011CENTRO #MON?\012Ele colocará o\nMAPA de JOHTO na\011sua #GEAR.",
  ["67:46a8"] = "Quando se está com\n#MON, ir a\011qualquer lugar é\011divertido.",
  ["67:46d6"] = "A casa do SENHOR\n#MON é mais\011acima.",
  ["67:4701"] = "Eu batalhei com\nos treinadores na\011rota.\012Meu #MON per-\ndeu. Eles estão\011feridos.\012Eu devo levá-los\nao CENTRO #MON.",
  ["67:4766"] = "Um #MON que\ncapturei tinha\011um item.\012Acho que é a\nÁGUA MÍSTICA.\012Não preciso dela,\nvocê a quer?",
  ["67:47c1"] = "De volta a pesca\npara mim, então.",
  ["67:47e0"] = "CIDADE DE CHERRYGROVE\012A Cidade das Lin-\ndas e Perfumadas\011Flores.",
  ["67:4815"] = "CASA DO GUIA.",
  ["67:4a80"] = "ROTA 44\012CAMINHO DE GELO\nacima.",
  ["67:4abb"] = "Eu estive obtendo\ndados de #MON\011no meu rádio.\012Acho que sou bom.",
  ["67:4ac4"] = "As músicas de\nrádio mudam o\011humor dos #MON\011selvagens.",
  ["67:4af8"] = "Eu mostrarei a\nminha namorada que\011sou bom!",
  ["67:4b23"] = "Você poderia ter\nperdido para mim…",
  ["67:4b47"] = "Eu fui humilhado\nem frente a minha\011namorada…",
  ["67:4b74"] = "Meu namorado é\nfraco, logo, não\011devo confiar nele.",
  ["67:4ba0"] = "Nossa! Você é\nforte!",
  ["67:4bba"] = "Posso contar mais\ncom meus #MON\011que com meu\011namorado.",
  ["67:4bea"] = "Você está indo ao\nGINÁSIO?\012Eu também!",
  ["67:4c0d"] = "Oh. Eu não pude\nvencer…",
  ["67:4c21"] = "As INSÍGNIAS de\nGINÁSIO são\011lindas.\012Eu as coleciono.",
  ["67:4c4d"] = "Que tipo de BOLAS\nvocê usa?",
  ["67:4c6e"] = "Nossa. Faltou\nrapidez!",
  ["67:4c87"] = "Alguns #MON\nfogem.\012Tente capturá-los\ncom a BOLA RÁPIDA\011do KURT.\012Sempre que acho uma\nBOLOTA BRANCA, eu\011o levo para KURT.\012Ele o transforma\neu uma BOLA.",
  ["67:4d1e"] = "Observe minha\ndestreza com\011BOLAS!",
  ["67:4d42"] = "Uau! Que abalo!",
  ["67:4d5a"] = "Eu ia faciná-lo\ncom meu #MON\011premiado.\012Mas sua proeza me\neletrocutou!",
  ["67:4daa"] = "Vou a todo lugar\nque #MON\011insetos apareçam.",
  ["67:4dd5"] = "Hã? Eu não deveria\nter perdido…",
  ["67:4df6"] = "Meu VENONAT me fez\nvencer o Concurso\011Caça-Inseto no\011PARQUE nacional.",
  ["67:4e38"] = "Uau… Olhe todos\nesses YANMAS!\012Estou tão soprado,\nque não posso me\011mexer.",
  ["67:4e76"] = "Estou praticando\nsopro de fogo.",
  ["67:4e98"] = "Ai! Queimei a\nponta de meu\011nariz!",
  ["67:4ebc"] = "A Marcha #MON\nno rádio\011atrai #MON\011selvagens.",
  ["67:4eea"] = "O perigo se\noculta à noite!",
  ["67:4f06"] = "Opa!",
  ["67:4f0f"] = "Você sabe, a\nnoite pode ser\011legal.\012Mas não abuse,\ntudo bem?",
  ["67:4f56"] = "Seus #MON\nparecem fortes.\n \012Você poderia ir a\nqualquer lugar\011seguramente.",
  ["67:4f94"] = "ROTA 35.",
  ["67:526a"] = "Eu amo #MON!\012É por isso que\ncomecei e continuo\011colecionando\011#MON!",
  ["67:52b4"] = "Como pode fazer\nisso comigo?",
  ["67:52d2"] = "O que mais gosto\nalém de #MON?\012A MARY do rádio.\nAposto que ela é\011linda!",
  ["67:5319"] = "Ei! Você tem algum\n#MON raro?",
  ["67:533a"] = "Oh, meus\npobres #MON!\011Coitados!",
  ["67:5359"] = "Ficaria feliz só\nde ter um único\011raro #MON.",
  ["67:5386"] = "Você acredita\nnisso?\012Um tal de {RIVAL}\nhumilhou meus\011#MON!\012Droga! Meus\n#MON são\011ótimos!",
  ["67:53d6"] = "Meu NIDOKING foi\nmuito bem!",
  ["67:53f8"] = "É normal as\npessoas gostarem\011de diferentes\011tipos de #MON.\012Sempre ter os\n#MON mais\011fortes não é o\011principal.",
  ["67:5461"] = "Estou afundado.\012Pode ser devido\nao meu\011equipamento.\012Vamos batalhar\npara mudar isso!",
  ["67:54b0"] = "Eu perdi, mas me\nsinto melhor.",
  ["67:54d3"] = "A BOLA ATRAÇÃO do\nKURT é a melhor\011para pegar\011#MON fisgados.\012Deve ser mais\nefetivo que uma\011ULTRA BOLA.",
  ["67:5535"] = "Faço muitas\ncoisas com meus\011#MON--é super\011legal!",
  ["67:5565"] = "Perder não é tão\nlegal…",
  ["67:557e"] = "O que está havendo\nno LAGO DA\011FÚRIA?\012Nós planejávamos\nacampar lá.",
  ["67:55c1"] = "Você está indo ao\nLAGO DA FÚRIA\011também?\012Vamos brincar um\npouco antes!",
  ["67:5604"] = "Eu brinquei\ndemais!",
  ["67:5618"] = "Estou fazendo\npiquenique com\011#MON.\012Quer entrar?",
  ["67:564b"] = "A minha CLEFAIRY\nnão é a coisa mais\011adorável?",
  ["67:567b"] = "ROTA 43\012LAGO DA FÚRIA-\nCIDADE DE MAHOGANY.",
  ["67:56a2"] = "ROTA 43\012LAGO DA FÚRIA-\nCIDADE DE MAHOGANY.",
  ["67:56c9"] = "DICAS DO TREINADOR\012Todos #MON têm\nvantagens e\011desvantagens\011dependendo do\011tipo.\012Um #MON de\nnível maior pode\011perder dependendo\011do tipo.\012Aprenda quais\ntipos são fortes\011e quais são fracos\011contra os dos seus\011#MON.",
  ["67:5a4b"] = "Aack! Você me fez\nperder um POLIWAG!\012O que você vai\nfazer agora?",
  ["67:5a91"] = "Simplesmente\nesqueça.",
  ["67:5aa8"] = "Aquele POLIWAG\nque perdi…\011Era grande.\012Eu juro que ele\ndevia ter uns\0115 metros!",
  ["67:5af7"] = "Eu pesco até não\npoder mais.\012Também batalho até\nficar derrubado.\012Essa é minha\nrelação com meus\011#MON.",
  ["67:5b55"] = "Hmmmm… Isso não\nestá certo.",
  ["67:5b6f"] = "São 100 vitórias e\n101 derrotas.\012Não batalharei de\nnovo por um tempo.",
  ["67:5baf"] = "Você sabe algo\nsobre #MON\011pássaros lendá-\011rios?",
  ["67:5bdb"] = "Uau! Você é\nquente.",
  ["67:5bf3"] = "ARTICUNO, ZAPDOS\ne MOLTRES são os\011três #MON\011pássaros lendá-\011rios.\012Eu soube que há\noutros pássaros\011lendários.",
  ["67:5c67"] = "Por que eu não\nconsigo vencê-lo?\012Oh sim, aqui\nestá. É o presente\011que não pude lhe\011dar na última\011vez.",
  ["67:5cc4"] = "Com certeza\nvencerei!",
  ["67:5cdd"] = "Argh… Foi uma\nderrota chocante…",
  ["67:5cfc"] = "É importante ter\nconvicção do seu\011lado.",
  ["67:5d2c"] = "Farei tudo para\npôr minhas mãos\011em #MON raros!",
  ["67:5d5b"] = "Oooh, seus\n#MON são tão\011atraentes.",
  ["67:5d7e"] = "Se um #MON\ntiver cores\011diferentes das\011normais, é mais\011valoroso.\012O quê? Você acha\nque não é\011verdade?",
  ["67:5ddc"] = "Posso lhe dizer\nque é um bom\011treinador ao\011vê-lo.\012Sou bom com\n#MON, e posso\011ver que você\011também é.",
  ["67:5e43"] = "Tch! É um erro da\nminha parte.",
  ["67:5e66"] = "Uau. Você tem\nmuitas INSÍGNIAS.\012Sem dúvidas você\né forte.\012Será que MORTY do\nGINÁSIO ECRUTEAK\011ainda está\011treinando?\012Ele realmente me\nmartelou.",
  ["67:5eed"] = "Você parece forte.\012Bons treinadores\nvêem fortes\011oponentes por\011instinto.",
  ["67:5f31"] = "Não! Isso não\nfunciona.",
  ["67:5f4d"] = "Todos nós\nmelhoramos ao\011passarmos por\011várias batalhas.\012Eu batalhei muito\nparam me tornar o\011que sou hoje--uma\011elite.",
  ["67:5fb3"] = "Uau! Demais!",
  ["67:5fcc"] = "ROTA 44\012CIDADE DE MAHOGANY-\nVILA DE BLACKTHORN.",
  ["67:62a1"] = "Esteja preparado\npara tudo!\012Deixe-me ver se\nseu #MON foi\011criado direito!",
  ["67:62ef"] = "Oh, perdi essa!",
  ["67:6301"] = "Voltarei ao\nCAMINHO DE GELO\011DE BLACKTHORN e\011treinar mais.",
  ["67:633d"] = "Você! É bem\ndisposto! Mas quer\011saber?\012Quando se fala de\ndisposição, eu sou\011o melhor!",
  ["67:6392"] = "Meus #MON\nnão foram muito\011dispostos!",
  ["67:63b1"] = "Cara, eu amo o\nHP MAIS! Hmmm,\011yum!\012Fico bebendo o do\nmeu #MON!\012Não posso parar!",
  ["67:63fd"] = "Meus #MON\nsão poderosos!",
  ["67:6418"] = "Hahaha! Sou o\ngrande perdedor!",
  ["67:6434"] = "Não sou muito bom\npara pensar, vê?\012Então, só faço\nuso da força!",
  ["67:647a"] = "Por que escalo\nmontanhas?\012Porque elas\nestão lá.\012Por que treino\n#MON?\012Porque eles estão\nlá!",
  ["67:64d6"] = "Derrotas…\nTambém estão lá!",
  ["67:64f1"] = "A melhor coisa\nque já me\011aconteceu foi\011descobrir os\011#MON.",
  ["67:652c"] = "Não consigo\nvencer.\012Não desistirei!\012Oh, e leve isso,\né o presente que\011você não pôde\011levar no último\011encontro.",
  ["67:659c"] = "Eu treinava aqui\nsozinho.\012Pelo poder do meu\ntrabalho!",
  ["67:65d7"] = "Waaaargh!",
  ["67:65e2"] = "Isso exige\nmedidas extremas.\012Devo ir às colinas\ne treinar na\011solidão.",
  ["67:6634"] = "Treinarei um pouco\nmais antes de sair\011para almoçar.",
  ["67:666c"] = "Temos bastante\ndescanço no\011almoço, então\011ficamos prontos\011para continuar!\011Vou treinar de\011novo!",
  ["67:66cb"] = "O que pensa\na respeito da\011criação de\011#MON?",
  ["67:66f6"] = "Ganhou meu respeito.",
  ["67:670d"] = "Vejo que cria\nseus #MON com\011carinho.\012Os laços que\nvocê construiu\011vão ajudá-lo em\011situações duras.",
  ["67:676f"] = "Qual é sua\nestratégia de\011batalha?\012É besteira usar\ngolpes fortes sem\011ter necessidade.",
  ["67:67c2"] = "Bom, perdi.",
  ["67:67d1"] = "Sou contra ao uso\nexcessivo de\011golpes fortes.\012Quero vencer, mas\nnão quero ferir os\011#MON.",
  ["67:687f"] = "Sou muito, muito\nforte!",
  ["67:6899"] = "Eu fui forte na\nTORRE DE BATALHA…",
  ["67:68bb"] = "Já foi à TORRE DE\nBATALHA?\012Eu nunca, nunca\nperdi lá, porém…",
  ["67:68fe"] = "ROTA 45\012MONTANHAS A\nSEGUIR.",
  ["67:6a7b"] = "Você já foi nadar\nno mar à noite?",
  ["67:6aad"] = "Glub…",
  ["67:6ab4"] = "À noite, o mar\nfica preto. Parece\011até que ee vai\011engolir você.",
  ["67:6afa"] = "Puff, puff…\nSó… um pouco…\011mais… até…\011FUCHSIA…",
  ["67:6b2d"] = "Estou afogando.",
  ["67:6b3b"] = "Eu… Pedi a minha\nnamorada para\011nadar até FUCHSIA…\011Gasp…",
  ["67:6b6f"] = "Detesto pessoas\nbobas!",
  ["67:6b8e"] = "Poderia vencê-lo\nna natação…",
  ["67:6bad"] = "É um nado rápido\nentre FUCHSIA e\011as ILHAS ESPUMA…\012Nossa, que grande\nhomem meu namorado\011é! Que bobão!",
  ["67:6c19"] = "Nadando?\nSou horrível\011nisso\n.\012Só estou me\ndebatendo nessas\011águas rasas.",
  ["67:6c66"] = "Pensei que podia\nvencer.",
  ["67:6c7e"] = "Posso ser ruim\nna natação, mas\011eu amo o mar.",
  ["67:6caf"] = "Perdão. Essa\nestrada está\011fechada para a\011construção.\012Se quiser chegar\na CINNABAR, é\011melhor ir pelo\011sul da CIDADE\011PALLET.",
  ["67:6d24"] = "Estou todo suado.\nHora de nadar!",
  ["67:6d45"] = "Quem sabe quanto\ndemorará para\011remover essa\011pedra…",
  ["67:6d7d"] = "A estrada já\nestá consertada.\012Agora posso ir\npescar de novo.",
  ["67:6dbc"] = "ROTA 19\012DE UCHSIA-\nILHAS ESPUMA.",
  ["67:6de5"] = "Favor ter cuidado\nse você for nadar\011nas ILHAS ESPUMA.\012POLÍCIA DE\nFUCHSIA.",
  ["67:7006"] = "MISTY: Aww! Por\nque você tem que\011aparecer agora e\011nos incomodar?\012Sabe como\nchamam-se pessoas\011como você?\012Pestes! É isso\nmesmo, peste!\012…\012…Oh? Essas\nINSÍGNIAS que\011tem… São INSÍGNIAS\011DOS GINÁSIOS DE\011JOHTO?\012Se tem oito,\ndeve ser bom.\012Certo, então.\nVenha ao GINÁSIO\011DE CERULEANA.\011Ficarei feliz em\011desafiá-lo.\012Eu, MISTY, LÍDER\nDO GINÁSIO em\011CERULEANA.",
  ["67:714d"] = "Vença os seis\ntreinadores para\011ganhar um prêmio\011fabuloso! Acha\011que consegue?",
  ["67:71a2"] = "Eu desisto!",
  ["67:71b5"] = "Fiz meu melhor.\nNão me arrependo.",
  ["67:71d8"] = "Sou a segunda.\nAgora é sério!",
  ["67:71f5"] = "Como pude perder?",
  ["67:7208"] = "Fiz meu melhor.\nNão me arrependo.",
  ["67:722b"] = "Eis o número 3.\nNão serei fácil.",
  ["67:7249"] = "Ow! Fui pisoteado!",
  ["67:725c"] = "Fiz meu melhor.\nNão me arrependo.",
  ["67:727f"] = "Sou o número 4!\nEstá cansado?",
  ["67:7299"] = "Também perdi…",
  ["67:72a6"] = "Fiz meu melhor.\nNão me arrependo.",
  ["67:72c9"] = "Certo. Sou o\nnúmero 5. Vou\011estourá-lo!",
  ["67:72e7"] = "Uau! Muito bom!",
  ["67:72f8"] = "Fiz meu melhor.\nNão me arrependo.",
  ["67:731b"] = "Sou a última da\nfila, mas lhe\011digo, sou forte!",
  ["67:734b"] = "Está brincando.",
  ["67:735b"] = "Fiz meu melhor.\nNão me arrependo.",
  ["67:737e"] = "Mufufufu…\012Não estou\nrelacionado ao\011conjunto dos seis\011treinadores.\012Esperei aqui para\nvencê-lo quando\011ficasse cansado\011de todas as\011batalhas.",
  ["67:7401"] = "Não está cansado\nmesmo?",
  ["67:741a"] = "Perdão… Não\ntrapacearei mais…",
  ["67:743b"] = "Você enfrentou uma\nbatalha a mais do\011que esperava,\011mas venceu mesmo\011assim.\012Como prometi,\nreceberá um\011prêmio.",
  ["67:749d"] = "Mas após ver\ncomo você batalha,\011quero ver como me\011saio.\012Que tal? Deixe-me\ndesafiá-lo.",
  ["67:74fd"] = "Nunca tive uma\nbatalha tão boa!",
  ["67:7520"] = "Foi uma grande\nbatalha!\012Você e seus\n#MON são\011verdadeiramente\011excepcionais!",
  ["67:7567"] = "CABANA DO MAR\nCASA DO BILL.",
  ["68:40f1"] = "Você cruzou o mar\npara chegar aqui?\012Deve ter sido\ndifícil.\012Seria bem mais\nfácil se seu\012#MON soubesse\ncomo VOAR…",
  ["68:4163"] = "Mas você não pode\nusar o VOAR sem\011a INSÍGNIA DO GI-\011NÁSIO daqui.\012Se derrotar o LÍ-\nDER DO GINÁSIO,\011venha me ver.\012Eu terei um bom\npresente para\011você.",
  ["68:41e3"] = "É a INSÍGNIA DO\nGINÁSIO CIANWOOD!\012Você deve levar\neste HM.",
  ["68:421d"] = "Ensine VOAR aos\nseus #MON.\012Você poderá VOAR\nrapidamente para\012qualquer lugar\nvisitado.",
  ["68:4277"] = "Meu marido perdeu\npara você, então\011ele deve treinar\011mais.\012É bom, pois\nele estava ficando\011gordinho.",
  ["68:42df"] = "Se usar o VOAR,\nvocê poderá voltar\012à OLIVINE rapi-\ndamente.",
  ["68:4319"] = "As Pedras ao norte\nda cidade podem\011ser quebradas.\012Podem estar escon-\ndendo algo.\012Seu #MON pode-\nria usar o ESMAGA-\011PEDRAS para quebrá-\011las.",
  ["68:4394"] = "CHUCK, o LÍDER DO\nGINÁSIO, batalha\012com seus #MON\nLUTADORES.",
  ["68:4433"] = "EUSINE: Ei,\n{PLAYER}.\012Aquele não era\num SUICUNE?\012Eu só dei uma\nrápida olhada, mas\012pensei que eu\nvira um SUICUNE\011correndo nas on-\011das.\012O SUICUNE é belo\ne grandioso.\012Ele corre pelas\ncidades e rotas\012em velocidades\nincríveis.\012É maravilhoso…\012Quero ver um\nSUICUNE de perto…\012Eu me decidi.\012Batalharei com vo-\ncê como treinador\011e ganhar respeito\011do SUICUNE.\012Venha, {PLAYER}.\nVamos batalhar\011agora!",
  ["68:45a1"] = "Odeio admitir, mas\nvocê venceu.",
  ["68:45c3"] = "Você é ótimo,\n{PLAYER}!\012Sem dúvida os\n#MON te respei-\011tam.\012Eu entendi agora.\012Continuarei procu-\nrando o SUICUNE.\012Certamente nos ve-\nremos de novo\012Até depois!",
  ["68:4660"] = "CIDADE DE CIANWOOD\012Um Porto Cercado\npor Grandes Mares.",
  ["68:468f"] = "CIDADE DE CIANWOOD\n\012LÍDER DO GINÁSIO\n#MON: CHUCK\012Sua Incrível Força\nFaz O Que ele \011Fala.",
  ["68:46d6"] = "500 Anos de\nTradição\012FARMÁCIA DA CIDADE DE\nCIANWOOD\012Estamos Aguardando\nSeus Pedidos Médi-\011cos.",
  ["68:4725"] = "CIDADE DE CIANWOOD\nESTÚDIO FOTOGRÁ-\011FICO\012Tire uma Foto de\nRecordação!",
  ["68:4760"] = "O # VIDENTE\nEM FRENTE.",
  ["68:4a6b"] = "Ei!",
  ["68:4a71"] = "Sabe o que acabou\nde fazer?\012Você deu seu\nprimeiro passo em\011KANTO.\012Confira o MAPA da\nsua #GEAR\011e veja.",
  ["68:4ad9"] = "Você parece ser\nbem forte.\012Deixe-me batalhar\ncom você!",
  ["68:4b05"] = "Uau!",
  ["68:4b0b"] = "Se você continuar\nesse caminho duro,\011a verdade será\011revelada!\012É, perdão, eu só\nquis dizer alguma\011coisa legal.",
  ["68:4b7c"] = "Hm? Você é bom,\nnão é?",
  ["68:4b98"] = "Como eu pensei!",
  ["68:4bac"] = "Um bom treinador\npode reconhecer\011outros bons\011treinadores.",
  ["68:4bdf"] = "Você não deve\ndesprezar os\011#MON selvagens\011dessas áreas.",
  ["68:4c19"] = "Oh! Você é forte\ndemais!",
  ["68:4c35"] = "Você é só uma\ncriança, mas\011não deve ser\011desprezada também.",
  ["68:4c73"] = "É raro ver alguém\nvindo aqui.\012Está treinado por\nconta própria?",
  ["68:4cb4"] = "Oh! Você é forte\nmesmo!",
  ["68:4cce"] = "Estou checando\npré e pró\011evoluções de\011#MON.\012As evoluções real-\nmente fortalecem\011os #MON.\012Mas formas\nevoluídas aprendem\011golpes mais\011devagar.",
  ["68:4d55"] = "Não diga nada!\012Deixe-me adivinhar\nseus pensamentos.\012Mmmmmmm…\012Consegui! Está\nindo ao desafio\011da LIGA #MON!",
  ["68:4dc1"] = "Você é demais!",
  ["68:4dd2"] = "Com sua\nhabilidade, irá\011bem na LIGA.\012Isso é o que\nminha premunição\011diz.",
  ["68:4e22"] = "Piu! Piu! Piiiu!",
  ["68:4e3a"] = "Piu!",
  ["68:4e42"] = "CRIADORES DE AVES\ncomo eu imitam\011sons de aves para\011comandar #MON.",
  ["68:4e7f"] = "CATARATAS TOHJO\012A LIGAÇÃO ENTRE\nKANTO E JOHTO.",
  ["68:50a7"] = "Os #MON se\nescondem na grama.\012Não se sabe quando\naparecerão…",
  ["68:50df"] = "Já te vi muitas\nvezes.\012Quantos #MON\nvocê capturou?\012Quer que eu lhe\nmostre como\011capturar #MON?",
  ["68:514d"] = "É assim que se\nfaz.\012Se enfraquecê-los\nantes, será mais\011fácil pegá-los.",
  ["68:5197"] = "Oh. Certo.\012De qualquer modo,\nvocê deve andar\011muito se quiser\011capturar #MON.",
  ["68:51e3"] = "Hã? Quer que eu\nlhe mostre como\011capturar #MON?",
  ["68:5214"] = "Ei. Como vão seus\n#MON?\012Se estiverem\nfracos e sem\011preparo para\011batalhar, fique\011fora da grama.",
  ["68:526c"] = "Vê essas beiras?\nÉ assustador\011pulá-las.\012Mas você pode ir\na NEW BARK sem\011passar pela grama.",
  ["68:52d9"] = "Eu quis descançar,\nentão salvei para\011gravar meus\011progressos.",
  ["68:534c"] = "Estou esperando\npor um #MON que\011apareça à noite.",
  ["68:537c"] = "Estou esperando\npor um #MON que\011apareça de manhã.",
  ["68:53b2"] = "TUSCANY: Essa é a\nprimeira vez que\011nos encontramos?\011Permita que eu me\011apresente.\012Sou TUSCANY da\nTerça-feira.",
  ["68:542f"] = "Aproveitando a\nintrodução, aceite\011esse presente, um\011ARCO ROSA.",
  ["68:546f"] = "TUSCANY: Não\nconcorda que é\011adorável?\012Isso fortalece\ngolpes do tipo\011normal.\012Tenho certeza que\nlhe será útil.",
  ["68:54e7"] = "TUSCANY: Já\nencontrou MÔNICA,\011minha irmã mais\011velha?\012Ou meu irmão mais\nnovo, WESLEY?\012Sou a segunda de\nsete crianças.",
  ["68:5559"] = "TUSCANY: Hoje\nnão é Terça. Que\011horrível…",
  ["68:558e"] = "ROTA 29\012CIDADE DE CHERRYGROVE-\nCIDADE DE NEW BARK.",
  ["68:55b9"] = "ROTA 29\012CIDADE DE CHERRYGROVE-\nCIDADE DE NEW BARK.",
  ["68:5806"] = "Vá, RATTATA!\012AGARRAR!",
  ["68:581c"] = "O quê? Essa é uma\ngrande batalha!\011Deixe-me só!",
  ["68:5849"] = "Acabei de perder,\nentão estou\011procurando mais\011#MON.\012Espere! Você\nparece fraco. Ei,\011vamos batalhar!",
  ["68:58a2"] = "Argh! Perdi de\nnovo! Que droga!",
  ["68:58c2"] = "Tenho que ter mais\n#MON para\011batalhar melhor?\012Não! Vou continuar\ncom esse de\011qualquer forma!",
  ["68:5928"] = "Você é um\ntreinador #MON,\011certo?\012Então você deve\nbatalhar!",
  ["68:595f"] = "Que estranho. Eu\nganhava antes.",
  ["68:597d"] = "Tornar-se um bom\ntreinador é\011realmente duro.\012Vou batalhar com\noutras pessoas\011para eu ficar\011melhor.",
  ["68:59d8"] = "Ao invés de um\n#MON inseto,\011achei um\011treinador!",
  ["68:5a03"] = "Argh! Você é bem\nforte!",
  ["68:5a1c"] = "Fiquei sem #\nBOLAS enquanto\011pegava #MON.\n \012Deveria ter\ncomprado mais…",
  ["68:5a6a"] = "Casa do SENHOR\n#MON?\012Está um pouco mais\nacima.",
  ["68:5a94"] = "Todos se divertem\nbatalhando! Você\011deveria também!",
  ["68:5ac4"] = "Não sou uma\ntreinadora.\012Mas se olhar nos\nolhos, prepare-se\011para batalhar.",
  ["68:5b0b"] = "ROTA 30\012CIDADE DE VIOLET-\nCIDADE DE CHERRYGROVE.",
  ["68:5b34"] = "CASA DO SENHOR\n#MON\012LOGO ACIMA!",
  ["68:5b55"] = "CASA DO SENHOR\n#MON.",
  ["68:5b66"] = "DICAS DO TREINADOR\012Não roube os\n#MON de outras\011pessoas!\012As # BOLAS são\npara ser jogadas\011só em #MON\011selvagens!",
  ["68:5bc0"] = "Perdi de novo…\nEi, você é forte!\012Oh claro, quase\nme esqueci que\011tinha que lhe dar\011isso.\012Use-o para ficar\nainda mais forte,\011certo.\012Vou me fortalecer\ntambém.",
  ["68:5f35"] = "Voar alto no céu,\nmeu querido\011#MON!",
  ["68:5f63"] = "Sinto-me voando\nlonge agora.",
  ["68:5f86"] = "Eu planejo treinar\nna CIDADE DE CIANWOOD\011para ensinar meu\011#MON a VOAR.",
  ["68:5fc5"] = "Deixe-me testar\nalgo que aprendi\011hoje.",
  ["68:5fee"] = "Não estudei o\nbastante, eu acho.",
  ["68:600e"] = "Eu tenho que\nfazer vários\ntestes, e não\011tenho muito tempo\011para #MON.\012Quando tenho\ntempo, eu me\011concentro demais.",
  ["68:607d"] = "Você parece ser\nbom com #MON.\012Se for, que tal\nme dar algumas\011instruções?",
  ["68:60c8"] = "Entendo. Então é\nassim que você\011batalha.",
  ["68:60ec"] = "Eu conheço algo\nbom!\012O leite da FAZENDA\nMOOMOO é famoso\011pelo seu sabor.",
  ["68:6130"] = "Você é um\ntreinador bonito!\012Posso ver seus\n#MON?",
  ["68:6164"] = "Estou feliz pois\npude ver seus\011#MON!",
  ["68:6185"] = "Quando vejo\n#MON, meus\011nervos parecem se\011acalmar.",
  ["68:61b7"] = "Eu já atravessei\nmares, logo\011conheço todos\011tipos de #MON!",
  ["68:61f0"] = "Sua habilidade é\nde classe mundial!",
  ["68:620c"] = "Todas pessoas no\nmundo vivem\011felizes com seus\011#MON.",
  ["68:624c"] = "Você não acha que\nmeus #MON e eu\011somos bonitos?",
  ["68:6279"] = "Nós bebemos LEITE\nMOOMOO todos os\011dias.",
  ["68:629a"] = "O LEITE MOOMOO é\nbom para a beleza\011e para a saúde.\012Mas tem um\nproblema, só é\011vendido uma\011garrafa por vez.",
  ["68:62fd"] = "ROTA 38\012CIDADE DE OLIVINE-\nCIDADE DE ECRUTEAK.",
  ["68:6324"] = "DICAS DO TREINADOR\012Se um #MON\nestiver tentando\011evoluir, você pode\011pará-lo.\012Aperte o botão B\ndurante a\011evolução.\012Isso assusta\no #MON e\011interrompe sua\011evolução.",
  ["68:64a2"] = "Curve-se perante\nmeus #MON\011reais!",
  ["68:64c2"] = "Como… Como ousou\nferir a realeza?",
  ["68:64e3"] = "Não é que todos\nqueriam ser rei\011um dia?",
  ["68:650f"] = "Nihihi! Gostaria\nde batalhar com\011minha gangue\011PIKACHU?",
  ["68:6542"] = "PI-PIKACHU!",
  ["68:654f"] = "Você parece ter\nvários #MON,\011mas PIKACHU ainda\011é o melhor.",
  ["68:6591"] = "Agilidade é o\natributo chave do\011#MON pássaro.",
  ["68:65bd"] = "Venceu-me com sua\nrapidez…",
  ["68:65db"] = "Seus #MON\nsão certamente bem\011treinados.",
  ["68:6604"] = "Confira meus\n#MON. Apenas\011olhe suas cores e\011suas plumagens.",
  ["68:6649"] = "Droga!\nNão muito bom!",
  ["68:6662"] = "Se enfeitá-los,\nos #MON se\011alegram.",
  ["68:6686"] = "Devo ir ao TÚNEL\nDE ROCHA para\011pegar meu ONIX.",
  ["68:66b9"] = "Perdi…",
  ["68:66c2"] = "Características\ngeológicas parecem\011não mudar.\012Mas na verdade\nmudam, bem aos\011poucos.",
  ["68:671c"] = "DICAS DO TREINADOR\012Olhe! Bem ali, à\nesquerda do da\011placa.",
  ["68:675b"] = "ROTA 13\012NORTE: PONTE DO\nSILÊNCIO.",
  ["68:677d"] = "NORTE: CIDADE DE\nLAVENDER\012OESTE: CIDADE DE\nFUCHSIA.",
  ["68:6814"] = "NIDORAN, trema!",
  ["68:6825"] = "NIDORAN: Gau gau!",
  ["68:68d0"] = "BROCK: Uau, não é\ncomum termos um\011desafiante de\011JOHTO.\012Sou BROCK, o\nLÍDER DO GINÁSIO\011de PEWTER.\012Sou perito em\n#MON do tipo\011pedra.\012Meus #MON\nsão resistentes à\011maioria dos\011ataques físicos.\011Terá dificuldades\011para lhes causar\011qualquer dano.\012Vamos lá!",
  ["68:69bb"] = "BROCK: Os\npoderosos ataques\011de seus #MON\011superaram minha\011defesa sólida…\012Você é mais forte\ndo que esperava…\012Vá em frente, leve\nessa INSÍGNIA.",
  ["68:6a3d"] = "{PLAYER} foi pre-\nsenteado com uma\011INSÍGNIA DA PEDRA\011DO GINÁSIO DA\011CIDADE DE PEWTER.",
  ["68:6a57"] = "BROCK: {PLAYER},\nobrigado. Gostei\011de batalhar com\011você, mesmo eu\011estando um pouco\011irritado.\012A INSÍGNIA DA\nPEDRA deixará seus\011#MON ainda\011mais fortes.",
  ["68:6ada"] = "BROCK: O mundo\né grande. Ainda\011há vários\011treinadores fortes\011como você.\012Apenas espere e\nveja. Vou me\011tornar bem mais\011forte também.",
  ["68:6b62"] = "Os treinadores\ndesse GINÁSIO\011usam #MON do\011tipo pedra.\012Esse tipo tem\nalta DEFESA.\012As batalhas podem\ndurar um bom\011tempo.\012Você está pronto\npara isso?",
  ["68:6bf1"] = "Tenho que vencer\nessas batalhas…",
  ["68:6c0f"] = "Ei, você!\nTreinador de\011JOHTO! BROCK é\011forte. Ele o\011punirá se você não\011levá-lo a sério.",
  ["68:6c6e"] = "Ei! CAMPEÃO em\nprogresso! Você\011está bem mesmo.\011Está batalhando\011com os LÍDERES DE\011GINÁSIO DE KANTO?\012Eles são\npessoas fortes e\011dedicadas, como\011aqueles de JOHTO.",
  ["68:6d07"] = "Ei! CAMPEÃO em\nprogresso! Esse\011GINÁSIO não lhe\011de muito problema.\012O jeito\ncomo batalhou\011é realmente\011inspirador.\012Eu falo com\nseriedAde.",
  ["68:6dd8"] = "Oi! Olha só meu\nGYARADOS!\012Eu o criei desde\na forma MAGIKARP.\011Nem acredito na\011força que possui.",
  ["68:6e3a"] = "Havia um estranho\nhomem idoso que\011vendia MAGIKARP.\012Ele dizia que as\nMAGIKARPS do\011LAGO DA FÚRIA são\011excelentes.",
  ["68:6f01"] = "…Isso, e o GINÁSIO\nem CINNABAR se\011foi. Fiquei\011chocada mesmo.\012…Sim? Estou no\ntelefone. Saia\011daqui!",
  ["68:6f5d"] = "JIGGLYPUFF: Puu\npupuu.",
  ["68:6f75"] = "A maioria dos\n#MON adormece\011se ouvem o\011JIGGLYPUFF cantar.\012Há vários golpes\nque podem ser\011usados somente\011enquanto o #MON\011dorme.",
  ["68:705f"] = "Gosto de dormir\ncom o rádio\011ligado…\011…Zzzz…",
  ["69:4105"] = "ECRUTEAK possuía\nduas torres:\012uma à leste e\ne outra a oeste.",
  ["69:4147"] = "Ah, garoto.\nVocê aprendeu a\012dançar como as\nGAROTAS KIMONO?\012Se ir ao TEATRO\nDE DANÇA delas, um\012estranho idoso lhe\ndará algo bom.",
  ["69:41db"] = "Eu vou praticar no\nTEATRO DE DANÇA.\012Se importa de me\nacompanhar?",
  ["69:421a"] = "A torre que fi-\ncava aqui…\012Minha avó me disse\nque a torre era\011bem alta.",
  ["69:4269"] = "Três grandes #-\nMONS fugiram em\011diferentes dire-\011ções.\012Onde estavam?",
  ["69:42ac"] = "Soube de um boato\nsobre o FAROL DE\011OLIVINE.\012O #MON que\nserve como guia\012adoeceu.\nParece que eles\011estão encrencados.",
  ["69:4325"] = "O #MON no FAROL\nDE OLIVINE foi cu-\011rado.\012Os Barcos podem\nnavegar pelo mar à\011noite facilmente.",
  ["69:4386"] = "Soube que #MON\nestão tumultuando\012o LAGO DA FÚRIA.\nQueria ver isto.",
  ["69:43cb"] = "Num passado dis-\ntante…\012Essa torre queimou\nno fogo. Três\012#MON sem nome\npereceram nele.\012Um #MON cor\nArco-íris desceu\012do céu e os res-\nsussitou…\012É uma lenda que\nfoi passada por\012gerações de LÍDE-\nRES DE GINÁSIO.\012Eu?\012Eu era um trei-\nnador na época.\011Hohoho!",
  ["69:44d1"] = "CIDADE DE ECRUTEAK\nA Cidade Histórica\012Onde o Passado en-\ncontra o Presente.",
  ["69:4513"] = "TORRE DO SINO\012Dizem que um #-\nMON lendário mora\011lá.",
  ["69:4548"] = "CIDADE DE ECRUTEAK\012LÍDER DO GINÁSIO\n#MON: MORTY\012O Místico Vidente\ndo Futuro.",
  ["69:458c"] = "TEATRO DE DANÇA\nDE ECRUTEAK.",
  ["69:45a4"] = "TORRE QUEIMADA\012Foi destruída por\num fogo misteri-\011oso.\012Por favor afaste-\nse, pois é insegu-\011ro.",
  ["69:477a"] = "DICAS DO TREINADOR\012Use a CABEÇADA nas\nárvores para fazer\011um #MON cair.\012Diferentes tipos\nde #MON cairão\011das árvores.\012Use a CABEÇADA em\ntoda árvore que\011avistar!",
  ["69:47f3"] = "CLAIR, nossa\nLÍDER DE GINÁSIO,\011o espera. Porém,\011seria impossível\011para um treinador\011fraco vencê-la.",
  ["69:4865"] = "Você derrotou\nCLAIR?\012É incrível!\012Nunca soube dela\nperder para alguém\011que não seja o\011LANCE.",
  ["69:48c3"] = "Não. Só treinado-\nres escolhidos\011podem treinar\011aqui. Saia por\011favor.",
  ["69:48fb"] = "Se CLAIR permitir,\nseu avô, nosso\011MESTRE, também\011vai.\012Você pode entrar.",
  ["69:494a"] = "Meu rádio pifou?\nUltimanente, só\nrecebo esse sinal\011estranho.",
  ["69:4983"] = "Aroo! Vozes em\nminha cabeça!\012Hã? Estou\nescutando ao meu\011rádio!",
  ["69:49bd"] = "Você vai fazer\nseus #MON\011esquecer uns\011golpes?",
  ["69:49f1"] = "Todos mestres em\ndragões vêm da\011VILA BLACKTHORN.",
  ["69:4a27"] = "SANTOS: …\012É Sábado…\012Sou SANTOS do\nSábado…",
  ["69:4a57"] = "Você pode levar\nisso…",
  ["69:4a6b"] = "SANTOS: …\012TALÃO MAGIA…\012Fortalece golpes\nfantasmas…\012Ele vai\nassustá-lo…",
  ["69:4ab6"] = "SANTOS: …\012Vou vê-lo de novo\nem outro Sábado…\012Não terei\nmais presentes…",
  ["69:4b00"] = "SANTOS: Hoje não\né Sábado…",
  ["69:4b1e"] = "Uau, você\natravessou o\011CAMINHO DE GELO.\011Nossa, deve ser um\011ótimo treinador!",
  ["69:4b67"] = "VILA BLACKTHORN\012Um quieto lugar\nmontanhoso.",
  ["69:4b91"] = "VILA BLACKTHORN\012LÍDER DO GINÁSIO\n#MON: CLAIR.\012A abençoada\nusuária de\011#MON dragões.",
  ["69:4bd9"] = "CASA DO APAGADOR\nDE GOLPES.",
  ["69:4bef"] = "TOCA DO DRAGÃO\nACIMA.",
  ["69:4c03"] = "DICAS DO TREINADOR\012Um #MON\nsegurando uma FRUTA\011MILAGROSA se curará\011de todo problema\011de estado.",
  ["69:4ec6"] = "Estou fazendo\nmeus últimos\011preparos para a\011LIGA #MON.",
  ["69:4efc"] = "Fui mal!",
  ["69:4f08"] = "Vai ser difícil\nvencer na LIGA\011#MON.\012Preciso treinar um\npouco mais.\012Eu soube que a\nELITE QUATRO DA\011LIGA é mais\011difícil que os\011LÍDERES DE\011GINÁSIO.",
  ["69:4f97"] = "Ao passar por\nbatalhas difíceis,\011você ganha força.",
  ["69:4fc7"] = "Gaah! Viver é\nmais difícil!",
  ["69:4fe4"] = "Para chegar a\nLIGA #MON, você\011tem que cruzar a\011ROTA DA VITÓRIA.\012Mas a ROTA DA\nVITÓRIA é dura.\012Praticamente\nninguém vai lá!",
  ["69:505c"] = "Como você chegou\ntão longe, deve\011ser muito bom.\012Vou dar o meu\nmáximo nessa\011batalha!",
  ["69:50bd"] = "Não! Não acredito\nnisso!",
  ["69:50d7"] = "Eu derrotei\noito LÍDERES DE\011GINÁSIO, logo\011estava confiante.\012Terei que me\nesforçar mais na\011próxima.",
  ["69:5136"] = "Perdi para um\ntreinador chamado\011{RIVAL}.\012Ele era forte\nmesmo, mas…\012Ele batalhava como\nse tivesse que\011ganhar a qualquer\011custo. Tenho pena\011de seus #MON.",
  ["69:51bf"] = "#MON não são\narmas bélicas.",
  ["69:51d9"] = "#MON são\nparceiros de longa\011data e sem preço.",
  ["69:5204"] = "Uau, olhe todas\nessas INSÍGNIAS.\012Estou admirado!\n \012Mas só colecioná-\nlas não o satis-\011faz, certo?",
  ["69:526a"] = "Boa batalha!",
  ["69:5278"] = "Pessoas e #MON\ncrescem com suas\011experiências.\012Não seja\num preguiçoso\011fatalista.",
  ["69:52c4"] = "Sinto-me ótimo\nhoje!\012Sinto que posso\naté vencer o\011CAMPEÃO DA LIGA!",
  ["69:530d"] = "Não! Não nessa\nbatalha!",
  ["69:5326"] = "Como na pesca,\ntudo acaba com os\011#MON quando\011você desiste.",
  ["69:5364"] = "ROTA 26\012LIGA #MON\nPORTÃO DE\011RECEPÇÃO.",
  ["69:5413"] = "ROTA 28.",
  ["69:55ff"] = "CAVERNA ESCURA…\012Se meu #MON\npudesse clareá-la,\011eu a exploraria.",
  ["69:5635"] = "Peguei muitos\n#MON. Deixe-me\011batalhar contigo!",
  ["69:5668"] = "Awwwww…",
  ["69:5671"] = "Você pode capturar\n#MON mesmo\011tendo seis com\011você.\012Se capturar um,\nele vai para\011seu BOX\011automaticamente.",
  ["69:56d9"] = "… Arf… Hã?\012Eu andei longe\nhoje procurando\011#MON.\012Meu pé dói e eu\nestou sonolento…\012Se eu fosse um\n#MON selvagem,\011seria fácil de se\011capturar…\012…Zzzz…",
  ["69:5761"] = "…Zzzz… Hã?\012O que foi? Você\ntem CARTA para\011mim?",
  ["69:5790"] = "{PLAYER} entregou o\n#MON segurando\011a CARTA.",
  ["69:57ba"] = "Vamos ver…\012CAVERNA ESCURA vai\na outra rota…\012É bom saber disso.\012Obrigado por\ntrazer isto a mim.\012Meu amigo é um\nbom rapaz, e você\011também!\012Gostaria de lhe\ndar algo bom em\011troca!\012Eu sei! Quero que\nleve isso!",
  ["69:5896"] = "O TM50 é o\nPESADELO.\012É um golpe\nterrível que corta\011periodicamente o\011HP do inimigo\011dorminhoco.\012Ooooh… Que\nassustador…\012Não quero ter\nsonhos ruins.",
  ["69:5921"] = "Essa CARTA não é\npara mim.",
  ["69:5939"] = "Por que esse\n#MON é tão\011especial?\012Ele nem tem CARTA.",
  ["69:5972"] = "O quê? Você não\nquer nada?",
  ["69:5991"] = "Se eu tomar esse\n#MON de você, o\011que usará nas\011batalhas?",
  ["69:59d5"] = "Eu achei um bom\n#MON na CAVERNA\011ESCURA.\012Vou treiná-lo para\ndesafiar FALKNER.\012Ele é o líder do\nGINÁSIO da CIDADE\011DE VIOLET.",
  ["69:5a45"] = "ROTA 31\012CIDADE DE VIOLET-\nCIDADE DE CHERRYGROVE.",
  ["69:5a6e"] = "CAVERNA ESCURA.",
  ["69:5bf9"] = "MILTANK: Mooo!",
  ["69:5c09"] = "Eu acabei de\nvoltar de OLIVINE.\012Então que tal uma\nbatalha #MON?",
  ["69:5c42"] = "Arrrrrgh!",
  ["69:5c4d"] = "Meus #MON\nforam capturados e\011criados sobre os\011mares.\012São meus parceiros\nnessas longas\011viagens.",
  ["69:5ca5"] = "Essa é uma boa\nhora para falar\011do PIKACHU com\011prepotência!",
  ["69:5cd4"] = "TOCA DO DRAGÃO\nACIMA.",
  ["69:5cf8"] = "Não estou ouvindo\no que você fala!\012Nós FÃS #MON\ntemos a política\011de não ouvir o que\011outras pessoas\011dizem!",
  ["69:5d5b"] = "Somente #MON\nlindos.\012Vamos mostrar\nnossos #MON\011juntos ao mesmo\011tempo.",
  ["69:5d9d"] = "Não me importo em\nperder.",
  ["69:5db2"] = "Você conhece\n#MON bebês?\012Eu aposto que eles\nsão adoráveis!",
  ["69:5dec"] = "É o PIKACHU! Você\nnão concorda?",
  ["69:5e0c"] = "Deixe-me ver de\nque seus #MON\011são capazes.",
  ["69:5e37"] = "Ooh, seus #MON\ntêm potencial.",
  ["69:5e57"] = "Você sabia que\nos #MON\011têm habilidades\011diferentes?\012As pessoas são\nassim também.\012Todos têm distin-\ntos potenciais.",
  ["69:5ec4"] = "Ufufufu… Espero\nque escureça logo.",
  ["69:5ee8"] = "Você veio na hora\ncerta.\012Vamos batalhar.",
  ["69:5f17"] = "Oh, que decepção…",
  ["69:5f31"] = "Eu conheci meu\nMEOWTH à noite,\011aqui na ROTA 39.\012Não sei bem\nporque, mas ele\011parece gostar de\011quando eu treino\011aqui.\012Parece ficar mais\namigável ao\011treinar aqui do\011que em outros\011lugares.",
  ["69:5fe3"] = "ROTA 39\012CIDADE DE OLIVINE-\nCIDADE DE ECRUTEAK.",
  ["69:600a"] = "FAZENDA MOOMOO\012Aprecie nosso\nLeite Delicioso e\011Fresquinho!",
  ["69:6036"] = "Nem tive tempo de\nfalar do PIKACHU…",
  ["69:622f"] = "Você tem que se\naquecer antes de\011entrar na água.\012Isso é básico.",
  ["69:626e"] = "Certo! Tio!\nDesisto!",
  ["69:6282"] = "A CIDADE DE CIANWOOD\né bem distante\011daqui.",
  ["69:62b4"] = "Ei, você é jovem\ne saudável!\011Não ande em seu\011#MON! Nade!",
  ["69:62ea"] = "Opa. Eu perdi…",
  ["69:62fa"] = "Nadar exercita\ntodo seu corpo.\011É saudável.",
  ["69:632d"] = "Você está indo\npara CIANWOOD?\012Que tal uma rápida\nbatalha primeiro?",
  ["69:6369"] = "Essa eu perdi!",
  ["69:637b"] = "Digo que nado\nmelhor do que\011você. Legal!",
  ["69:63a9"] = "Não me atrapalhe.\012Estou segurando um\n#MON aquático!",
  ["69:63dd"] = "Ooh, me sinto\ntonta!",
  ["69:63f5"] = "Enquanto eu\nflutuar assim,\011as ondas me\011carregarão.",
  ["69:6429"] = "Mesmo não podendo\nver daqui,\011CIANWOOD é após\011o mar.",
  ["69:646a"] = "Hm! Há uma grande\nconstrução acima!\012O que ela é?",
  ["69:649b"] = "Hm! Olhe esses\ntreinadores de\011olhares sérios.\012O quê? O quê?",
  ["69:64e6"] = "Eu vim para\nOLIVINE de navio\011pelas vistas e\011pela atmosfera\011úmida.\012Como é um porto,\nparece tão\011diferente de uma\011cidade.",
  ["69:6564"] = "Você já foi à\nTORRE DE BATALHA?\012Eu acho que muitos\ntreinadores fortes\011já se reuniram lá.\012Mas como tem\nvárias INSÍGNIAS,\011você não deverá ir\011tão mal assim.",
  ["69:6606"] = "MÔNICA: Estou\nfeliz em\011conhecê-lo.\012Sou MÔNICA da\nSegunda.",
  ["69:6636"] = "Como prova de\nnossa amizade,\011vou te dar um\011presente!",
  ["69:666c"] = "MÔNICA: É um item\nque aumenta o\011poder de golpes\011do tipo voador.\012Você deve equipar\num #MON pássaro\011com esse item.",
  ["69:66dc"] = "MÔNICA: Meus\nirmãos estão em\011todos lugares.\n\012Tente encontrar\ntodos eles!",
  ["69:6737"] = "MÔNICA: Acho que\nhoje não é\011Segunda.\012Que triste…",
  ["69:6767"] = "ROTA 40\012CIDADE DE CIANWOOD-\nCIDADE DE OLIVINE.",
  ["69:690f"] = "A água é morna\naqui. Estou muito\011relaxado.\012Claro, vou levá-lo\na sério!",
  ["69:6952"] = "Droga! Pareço uma\npassa!",
  ["69:696e"] = "Não é relaxante\nficar flutuando\011assim?",
  ["69:6999"] = "Estou cansado.\n\nEmpreste-me meu\011#MON se eu\011vencer.",
  ["69:69c7"] = "Uf, uf, uf…",
  ["69:69d4"] = "Está tão longe de\nCIANWOOD.\012Mas não é fácil\nvoltar para\011OLIVINE também.\012O que devo fazer?",
  ["69:6a2e"] = "Vê essas\nilhas que estão\011bloqueadas por\011redemoinhos?\012Deve ter algo\nsecreto lá!",
  ["69:6a80"] = "Qual o segredo da\nsua força?",
  ["69:6aa4"] = "Foi uma noite\nescura e chuvosa…\012Eu vi esse #MON\ngigante viando das\011ilhas.\012Estava caindo\npenas de suas asas\011de prata.",
  ["69:6b26"] = "Fui derrotado!",
  ["69:6b62"] = "As ondas são\nselvagens aqui.\012Elas te cansam\nquando você nada.",
  ["69:6b6c"] = "As correntes me\nimpedem de chegar\011à ilha.",
  ["69:6b9d"] = "Você está\nprocurando os\011segredos das ILHAS\011REDEMOINHO?",
  ["69:6bcc"] = "Ooh, você tem\nmuita paciência!",
  ["69:6bed"] = "Um segredo sobre\nas ILHAS REDEMOINHO…\012É preta por\ndentro!",
  ["69:6c24"] = "Estou a caminho\ndas ILHAS REDEMOINHO.\012Vou explorá-la com\nmeus amigos.",
  ["69:6c67"] = "É assim que você\nfaz?",
  ["69:6c7f"] = "Há, supostamente,\num grande #MON\011nas profundezas\011das ILHAS REDEMOINHO.\012O que será\nque é?",
  ["69:6cda"] = "Você parece tão\nelegante, montado\011em seu #MON.",
  ["69:6d04"] = "Fui esmagado…",
  ["69:6d11"] = "Não havia uma\ncanção sobre um\011garoto andando\011de LAPRAS?",
  ["69:6d46"] = "O tempo está tão\nbonito que fico\011deslumbrado!",
  ["69:6d72"] = "Ohhh!",
  ["69:6d79"] = "Uma queimadura\né o pior para a\011pele.\012Mas eu não uso\nprotetores.\012Não poluirei a\nágua.",
  ["69:6dd0"] = "Se quiser\ndescansar, ponha\011os pés na água.\012Você recuperará\nsua energia e\011ficará mais forte.",
  ["69:6e33"] = "Oh! Você tem mais\nenergia do que\011eu.",
  ["69:6e58"] = "Eu ouvi rugidos\ndas profundezas\011das ILHAS.",
  ["69:6e85"] = "Os STARYUS se\nreúnem na\011superfície da água\011à noite.",
  ["69:6eb7"] = "Oh, querido…",
  ["69:6ec2"] = "Os cardumes de\nSTARYU se iluminam\011ao mesmo tempo.\012É tão bonito, tão\nassustador.",
  ["69:7012"] = "Paciência é\nnecessária na\011pesca e com\011#MON.",
  ["69:7043"] = "Gwaaah!",
  ["69:704c"] = "Sou muito\nimpaciente para\011pescar…",
  ["69:706b"] = "Sinto-me tão\nfeliz, pescar\011enquanto ouço umas\011músicas em meu\011rádio.",
  ["69:70b4"] = "Meu rádio bobo me\ndistraiu!",
  ["69:70d4"] = "Já conferiu os\nprogramas de rádio\011de KANTO? Temos\011boa variedade\011aqui.",
  ["69:711d"] = "O que é mais\nimportante em\011nossas vidas todo\011dia?",
  ["69:714e"] = "A resposta já\nvai vir!",
  ["69:716d"] = "Acho que a\neletricidade é\011a coisa mais\011importante em\011nossa vida diária.\012Se não fosse, as\npessoas não teriam\011entrado em pânico\011quando a USINA ELÉTRICA parou de\011funcionar.",
  ["69:7214"] = "Você se lembra?",
  ["69:7226"] = "Você se lembra?",
  ["69:7238"] = "O puxão que sente\nna VARA quando\011você prende um\011#MON…\012É o melhor\nsentimento para\011um pescador como\011eu.",
  ["69:72a0"] = "ROTA 12\012NORTE: CIDADE DE\nLAVENDER.",
  ["69:72c1"] = "PONTO DE PESCA.",
  ["6a:40f7"] = "Uau, sua #GEAR\né impressionante!\012Foi sua mãe que\npegou pra você?",
  ["6a:4134"] = "Espere, {PLAYER}!",
  ["6a:413e"] = "O que pensa que\nestá fazendo?",
  ["6a:415e"] = "É perigoso sair\nsem um #MON!\012Um #MON\nselvagem saltou\011da grama, e foi em\011direção à próxima\011cidade.",
  ["6a:41c4"] = "Ah! Seu #MON\né adorável!\011Como eu queria ter\011um pra mim!",
  ["6a:41f2"] = "Oi, {PLAYER}!\nJá tá de saída?\012Você devia avisar\nà sua mãe que já\011está indo embora.",
  ["6a:4236"] = "Ligue para sua mãe\npelo seu #GEAR\011pra ela saber pra\011onde você está\011indo.",
  ["6a:4274"] = "E aí, {PLAYER}!\012Ouvi que PROFESSOR ELM\ndescobriu uns\011#MON novos.",
  ["6a:42a6"] = "……\012Então esse é o\nfamoso laboratório\011#MON do ELM…",
  ["6a:42cd"] = "…Tá olhando pra\nmim por quê?",
  ["6a:42e8"] = "CIDADE DE NEW BARK\012A Cidade Onde os\nVentos de um Novo\011Início Sopram",
  ["6a:4328"] = "Casa do {PLAYER}",
  ["6a:4332"] = "LABORATÓRIO\n#MON DO ELM",
  ["6a:4340"] = "CASA DO ELM",
  ["6a:4473"] = "Olá! Você é um\ntreinador?\012Já batalhou com o\nLÍDER DO GINÁSIO?",
  ["6a:44ac"] = "Ooh, la la!\nIsso é ótimo!",
  ["6a:44cb"] = "É isso? Então\nvocê deve estudar!\011Siga-me!",
  ["6a:44f9"] = "Ei, eu sou um\nprofessor. É bom\011que estude aqui!",
  ["6a:4529"] = "Dizem que aparecem\nfantasmas na TORRE\011BROTINHO.\012E golpes #MON\nnormais não fazem\012efeitos neles.",
  ["6a:4593"] = "Ei, você é um\ntreinador POKÉMON?\012Se derrotar o LÍ-\nDER DO GINÁSIO\012daqui, você estará\nbem preparado!",
  ["6a:45ef"] = "FALKNER, do GINÁ-\nSIO #MON DE\012VIOLET, é um bom\ntreinador!\012Ele herdou o giná-\nsio de seu pai\012e está fazendo um\nbom serviço com\011ele.",
  ["6a:4665"] = "Eu vi uma árvore\nlouca acima!\012Se tocá-la, ela\nse mexe e dança!\012Legal!",
  ["6a:46b2"] = "CIDADE DE VIOLET\012A Cidade dos Sen-\ntimentos Nostálgi-\011cos.",
  ["6a:46dc"] = "CIDADE DE VIOLET\012LÍDER DO GINÁSIO\nPOKÉMON: FALKNER\012O Elegante Mestre\ndos #MON Aves.",
  ["6a:4724"] = "TORRE BROTINHO\012A Experiência do\nRumo #MON.",
  ["6a:474d"] = "ACADEMIA POKéMON\nDO EARLY.",
  ["6a:48fa"] = "…\012Você de novo?\012Não entre em\npânico. Não me\012atrapalho com bo-\nbos como você.\012Falando em fraque-\nzas, a LÍDER DO\012GINÁSIO da cidade\nnão está.\012Supostamente está\ncuidando de um\012#MON doente no\nFAROL.\012Hmph! Boo-hoo!\nDeixe os #MON\011doentes irem!\012Um #MON que\nnão batalha não\011presta!\012Por que você\nnão treina no\011FAROL?\012Quem sabe não\nte deixa menos\011fraco!",
  ["6a:4a58"] = "Estradas escuras\nsão perigosas à\011noite.\012Mas na escuridão\nda noite, o\012mar é ainda mais\ntraiçoeiro!\012Sem a ajuda do\nguia do FAROL,\012nenhum navio pode\nnavegar.",
  ["6a:4b04"] = "Essa coisa que\npossui--É uma\011#GEAR, certo?\012Uau, isso é legal!",
  ["6a:4b41"] = "Uau, você tem uma\n#DEX!\012Isso é sem dú-\nvida incrível!",
  ["6a:4b71"] = "O mar é doce!\012O Pôr-do-sol no\nmar é maravilhoso!\012Cante comigo!\nYo-ho! Sopre o\011homem abaixo!…",
  ["6a:4bd0"] = "CIDADE DE OLIVINE\012O Porto Mais\nPerto das Terras\011Isoladas.",
  ["6a:4c00"] = "PORTO DE OLIVINE\nPÍER DA BALSA.",
  ["6a:4c1d"] = "CIDADE DE OLIVINE\012LÍDER DO GINÁSIO\n#MON: JASMINE\012A Garota da De-\nfesa de Aço.",
  ["6a:4c60"] = "FAROL DE OLIVINE\nTambém conhecido\011como FAROL DA LUZ.",
  ["6a:4c99"] = "TORRE DE BATALHAS\nACIMA\012Aberto agora!",
  ["6a:4e12"] = "ANN: ANNE e eu\nestamos juntas\011nessa!",
  ["6a:4e3b"] = "ANN & ANNE: Nnn…\nFortinho demais.",
  ["6a:4e62"] = "ANN: Eu posso\ndizer o que minha\011irmã e meus\011#MON pensam.",
  ["6a:4e9c"] = "ANNE: ANN e eu\nestamos juntas\011nessa!",
  ["6a:4ec5"] = "ANN & ANNE: Nnn…\nFortinho demais.",
  ["6a:4eec"] = "ANNE: Dividimos os\nmesmos sentimentos\011de nossos\011#MON.",
  ["6a:4f1b"] = "Os #MON nada\npodem fazer quando\011dormem.\012Vou lhe mostrar\no quanto isso\011é assustador!",
  ["6a:4f65"] = "… O que você\nestá olhando?",
  ["6a:4f80"] = "Pôr os #MON\npara dormir ou\011paralizá-los são\011boas técnicas de\011batalha.",
  ["6a:4fc8"] = "SUNNY: Oi!\012Sou SUNNY do\nDomingo.\012E significa que\nhoje é domingo!",
  ["6a:5004"] = "Fui mandada para\nlhe dar isso se o\011visse!",
  ["6a:502f"] = "Fui mandada para\nlhe dar isso se o\011visse!",
  ["6a:505a"] = "SUNNY: Essa coisa…\012Um…\012… O que era mesmo…\012…\012Oh! Agora me\nlembro!\012Um #MON que\nsabe golpes\011elétricos deve\011segurá-lo.\012Minha irmã MÔNICA\ndisse que ele\011melhora golpes\011elétricos!",
  ["6a:50fc"] = "SUNNY: Meus\nirmãos são:\012MÔNICA, TUSCANY,\nWESLEY, ARTHUR,\011FRIEDA e SANTOS.\012Todos são mais\nvelhos do que eu!",
  ["6a:516e"] = "SUNNY: Hoje não\né Domingo?\011Um… Esqueci!",
  ["6a:5197"] = "ROTA 37.",
  ["6a:535f"] = "LABORATÓRIO DE\nPESQUISA DO\011PROFESSOR ELM.",
  ["6a:5393"] = "O quê? Isso está\nerrado.",
  ["6a:53ab"] = "Eu quero me tornar\no treinador\011CAMPEÃO usando o\011#MON que eu\011capturei.\012É a melhor parte\nda pesca!",
  ["6a:5408"] = "Ah, é bom estar\naqui fora!\012Sinto-me tão\nlivre!",
  ["6a:5435"] = "Hahahah!",
  ["6a:543f"] = "Perder parece\ninsignificante\011comparado a olhar\011o grande céu\011azul!",
  ["6a:547c"] = "EI!\012Esse é meu lugar\nsecreto! Saia,\011seu forasteiro!",
  ["6a:54b3"] = "Eu deveria ter\nusado minha PEDRA\011DA LUA…",
  ["6a:54d6"] = "Você está\ntrabalhando na\011#DEX?\012Uau, você deve\nconhecer muitos\011#MON bonitos.\012Por favor posso\nvê-la?",
  ["6a:5537"] = "ROTA 42\012CIDADE DE ECRUTEAK-\nCIDADE DE MAHOGANY.",
  ["6a:555f"] = "Eu perdi. Isso é\nmuito triste…",
  ["6a:5580"] = "MONTANHA MORTEIRO\012CAVERNA com\nCACHOEIRAS dentro.",
  ["6a:55a1"] = "ROTA 42\012CIDADE DE ECRUTEAK-\nCIDADE DE MAHOGANY.",
  ["6a:5793"] = "Certo! vou lhe\nmostrar a força\011dos #MON da\011montanha!",
  ["6a:57c6"] = "Piedade! Mostrou-\nme seu poder!",
  ["6a:57e8"] = "Acabou. eu não\nligo.\012Nós ANDARILHOS\nsomos assim.",
  ["6a:5819"] = "Também estou\ncriando #MON!\012Você vai batalhar\ncomigo?",
  ["6a:584a"] = "Quê…?",
  ["6a:5851"] = "Dei meu melhor\nmas não pude\011vencer.\012Sem desculpas.\nAdmito a derrota.",
  ["6a:588f"] = "Também crio\n#MON!\012Você vai batalhar\ncomigo?",
  ["6a:58bb"] = "Oh, droga!",
  ["6a:58c6"] = "Estive em tantos\nGINÁSIOS, mas o\011de GOLDENROD é o\011meu favorito.\012É cheio de lindas\nflores!",
  ["6a:5927"] = "Ahh… Eu sempre\nperco!\012Vou ter que me\nesforçar mais!\012De qualquer modo,\nobrigado por\011batalhar comigo\011de novo e de novo.\012Eis o presente\npela outra vez.",
  ["6a:59be"] = "ROTA 46\012MONTANHAS A\nSEGUIR.",
  ["6a:5aa5"] = "Ei, garoto! Acabei\nde tomar uma dose\011dupla de café e\011estou bem ativo!\012Tenho que\nconversar com\011alguém, então vai\011você mesmo!\012Pode não parecer\nmuito agora, mas\011eu era perito em\011capturar #MON.\012Acredita em mim?",
  ["6a:5b6f"] = "Bom, bom. Sim,\neu era algo\011sobrenatural, vou\011te contar!",
  ["6a:5bb7"] = "O quê? Seu\ninsolente!\012Se eu fosse um\npouco mais jovem,\011eu lhe mostraria\011uma coisa, ou\011duas. Humph!",
  ["6a:5c11"] = "Esse GINÁSIO não\ntem um LÍDER\011desde agora pouco.\012Um jovem de PALLET\nse tornou o LÍDER,\011mas ele sai às\011vezes.",
  ["6a:5c7e"] = "Você vai batalhar\ncom o LÍDER?\012Boa sorte para\nvocê. Vai precisar\011dela.",
  ["6a:5cc4"] = "Yawn!\012Devo ter dormido\nno sol.\012… Eu sonhei que um\nDROWZEE estava\011comendo o meu\011sonho. Estranho,\011né?\012Hã? O quê é isso?\012De onde esse TM\nveio?\012Isso é assustador!\nEi, você pode\011ficar com esse\011TM.",
  ["6a:5d86"] = "TM42 contém o\nCOME SONHO…\012…Zzzzz…",
  ["6a:5daa"] = "Soube que há\nvários itens no\011chão da FLORESTA\011DE VIRIDIAN.",
  ["6a:5def"] = "CIDADE DE VIRIDIAN\012O Eterno Paraíso\nVerde.",
  ["6a:5e1b"] = "CIDADE DE VIRIDIAN\012LÍDER DO GINÁSIO\n#MON: …\012O resto do texto\nestá ilegível…",
  ["6a:5e60"] = "Já faz um ano\ndesde a erupção\011do vulcão.",
  ["6a:5e99"] = "BEM-VINDO À\nCIDADE DE VIRIDIAN,\012O PORTAL PARA O\nPLANALTO ÍNDIGO.",
  ["6a:5f7d"] = "Esse POLIWRATH\né meu parceiro.\012Será que ele\nainda vai evoluir\011em um #MON\011sapo?",
  ["6a:5fcb"] = "POLIWRATH: Croak!",
  ["6a:5fde"] = "Perdi nas máquinas\nde roleta de novo…\012Nós garotas também\nas jogamos agora.\012Você também\ndeveria jogá-las.",
  ["6a:6043"] = "GRIMERS têm\naparecido\011ultimamente.\012Vê aquele lago\nem frente a casa?\011Os GRIMERS vivem\011lá agora.\012De onde eles\nvieram? Esse é um\011problema sério…",
  ["6a:60dc"] = "Nihihi! Esse\nGINÁSIO é ótimo!\011Só são permitidas\011garotas aqui!",
  ["6a:6115"] = "Quer ouvir um\nsegredo?\012A MANSÃO CELADON\ntem uma porta dos\011fundos oculta.",
  ["6a:6155"] = "Estão fazendo um\nconcurso de comer\011no restaurante.\012Só de vê-los\ndevorar a comida\011já me deixa\011enjoado…",
  ["6a:61bd"] = "A LOJA DE\nDEPARTAMENTOS DE\011CELADON tem a\011maior e melhor\011seleção de\011produtos.\012Se não achar algo\naqui, não o achará\011em lugar algum.\012É… Eu pareço uma\nvendedora.",
  ["6a:6306"] = "Olhar para o chão\nenquanto andava\011me deixou tonta.",
  ["6a:6340"] = "CIDADE DE CELADON\012A Cidade dos\nSonhos Arco-íris.",
  ["6a:6369"] = "CIDADE DE CELADON\012LÍDER DO GINÁSIO\n#MON: ERIKA\012A Princesa Amante\nda Natureza.",
  ["6a:63a9"] = "Ache o que\nprecisar na LOJA\011DE DEPARTAMENTOS\011DE CELADON!",
  ["6a:63d4"] = "A Diversão\nde Todos\012CASA DE JOGOS DE\nCELADON.",
  ["6a:63e5"] = "A Diversão\nde Todos\012CASA DE JOGOS DE\nCELADON.",
  ["6a:6418"] = "DICAS DO TREINADOR\012A SUPER DEFESA\nprotege #MON\011de golpes\011ESPECIAIS como\011água e fogo.\012Compre seus\nitens na LOJA DE\011DEPARTAMENTOS DE\011CELADON!",
  ["6a:65e6"] = "Esqueceu-se de\nalguma coisa?",
  ["6a:6604"] = "Kyaaah!",
  ["6a:660d"] = "Antes de ser uma\nprofessora, eu\011esquecia muitas\011coisas.",
  ["6a:664b"] = "Em dias de\nsol, acho que\011as crianças\011prefeririam\011brincar no pátio\011da escola a\011estudar na sala\011de aula.",
  ["6a:66b3"] = "Eu não queria\nperder…",
  ["6a:66ca"] = "Estudar é\nimportante, mas\011se exercitar\011também é vital.",
  ["6a:6703"] = "Espere. Tenho\nque ligar para\011minha mãe.",
  ["6a:6725"] = "Perdão, mãe.\nFui derrotado!",
  ["6a:6740"] = "Minha mãe se\npreocupa muito\011comigo e tenho que\011sempre ligar para\011ela.",
  ["6a:6784"] = "Vamos batalhar.\nNão perderei!",
  ["6a:679f"] = "Sayonara! Acabei\nde aprender isso\011na minha aula de\011japonês.",
  ["6a:67bc"] = "Estamos numa\nexcursão de\011Estudos Sociais\011para a TORRE DE\011RÁDIO DE LAVENDER.",
  ["6a:67f1"] = "CASA DO TREINADOR\012O Clube para\nGrandes Batalhas\011entre Treinadores.",
  ["6a:6833"] = "TORRE DE BATALHAS\nACIMA.",
  ["6a:684a"] = "Cansei de andar.\nPreciso de um\011descanso.",
  ["6a:687a"] = "Minha aula\npreferida é\011ginástica!",
  ["6a:6895"] = "Oh, não! Como pude\nperder?",
  ["6a:68b0"] = "Se #MON fosse\nmatéria escolar,\011eu seria o melhor!",
  ["6a:68e3"] = "ROTA 15\012CIDADE DE FUCHSIA-\nCIDADE DE LAVENDER.",
  ["6a:6a15"] = "O PORTO DE\nVERMILION é o por-\011tão marítimo de\011KANTO.\012Luxuosos navios do\nmundo todo vêm\011aqui.",
  ["6a:6a6f"] = "Meu #MON está\npreparando a área\011para a construção.\012Mas não tenho\ndinheiro para\011começar o projeto…",
  ["6a:6aca"] = "MACHOP: Guooh\ngogogoh!",
  ["6a:6ae2"] = "O MACHOP está\nrugindo enquanto\011achata o terreno.",
  ["6a:6b1a"] = "Há oito GINÁSIOS\nem KANTO.\012Esse grande prédio\né o GINÁSIO #-\011MON DE VERMILION.",
  ["6a:6b64"] = "O SNORLAX está\nroncando em paz…",
  ["6a:6b84"] = "A #GEAR foi co-\nlocada perto\011do SNORLAX\011adormecido…\012…\012O SNORLAX acordou!",
  ["6a:6bc8"] = "Habilidosos trei-\nnadores se reúnem\011em KANTO.\012Os LÍDERES DE\nGINÁSIO são muito\011fortes.\012Não será fácil\nvencê-los.",
  ["6a:6c2b"] = "Você começou a\ncoletar INSÍGNIAS\011GINÁSIOS DE KANTO?\012Não acha fortes\nos treinadores\011daqui?",
  ["6a:6c88"] = "Acho que em breve\nterminará com sua\012conquista aos\nGINÁSIOS DE KANTO.\012Deixe-me saber se\npegou as oito\011INSÍGNIAS.",
  ["6a:6cf3"] = "Parabéns!\012Pegou todas INSI-\nGNIAS DE KANTO.\012Vou presenteá-lo\npor seus esforços.",
  ["6a:6d4a"] = "Ter vários tipos\nde #MON deve\012ajudá-lo nas\nbatalhas.\012Eu sei que as\nINSÍGNIAS DE KANTO\011vão ajudá-lo.",
  ["6a:6db9"] = "CIDADE DE VERMILION\012O Porto do lindo\nPôr-do-sol.",
  ["6a:6de7"] = "CIDADE DE VERMILION\012LÍDER DO GINÁSIO\n#MON: TENENTE\nSURGE.\012O americano relâm-\npago.",
  ["6a:6e28"] = "FÃ CLUBE #MON\012Bem-vindos Fãs\n#MON!",
  ["6a:6e4e"] = "CAVERNA DOS\nDIGLETT.",
  ["6a:6e5e"] = "ENTRADA DO PORTO\nDE VERMILION.",
  ["6a:6fa5"] = "Vim explorar o\nTÚNEL DE ROCHA.",
  ["6a:6fc5"] = "Uau! Perigo,\ncara.",
  ["6a:6fd9"] = "Meus #MON\nforam feridos\011antes mesmo de\011entrarmos no\011TÚNEL DE ROCHA.\012É melhor eu\nlevá-los ao CENTRO\011#MON.",
  ["6a:703f"] = "Já esteve em um\npiquenique?\012Eles são tão\ndivertidos!",
  ["6a:7074"] = "Ohhhh!",
  ["6a:707c"] = "Fazemos muitas\ngostosuras e as\011dividimos com\011todos.\012São deliciosas!",
  ["6a:70c2"] = "Ei, você!\nNão bagunce!",
  ["6a:70da"] = "Eu só estava\nfalando que…",
  ["6a:70f6"] = "Perdão. Você não\nestava bagunçando.\011Foi erro meu.",
  ["6a:7127"] = "As pessoas não\ndeviam deixar lixo\011para trás.",
  ["6a:7151"] = "Ohh… Perdi…",
  ["6a:715f"] = "Conservar enegia\né importante, mas\011o meio-ambiente é\011ainda mais vital.",
  ["6a:71a8"] = "Ela vai vir do\nMONTE PRATA,\011quando ela vir…\012O MONTE PRATA é\nem JOHTO, certo?",
  ["6a:71f7"] = "Estava ocupado\ncantando…",
  ["6a:7210"] = "As batalhas exigem\nconcentração.",
  ["6a:7232"] = "Contarei-lhe um\nsegredo.\012Mas primeiro,\nbatalhamos!",
  ["6a:7260"] = "Oh, droga! Perdi\nessa…",
  ["6a:7278"] = "A USINA ELÉTRICA\né após um pequeno\011rio.",
  ["6a:72a2"] = "MANSÃO CELADON.",
  ["6a:7335"] = "BLAINE, DO GINÁSIO\nDE CINNABAR parece\011viver sozinho na\011caverna das ILHAS\011CINNABAR…",
  ["6a:737f"] = "Você é forte\ndemais!",
  ["6a:740a"] = "O vulcão de\nCINNABAR entrou em\011erupção e lançou\011pedras que\011indeterminadamente\011fecharam a ROTA\01119.\012Será que as\npessoas de\011CINNABAR estão\011bem?",
  ["6a:748a"] = "Ninguém de\nCINNABAR foi\011machucado pela\011erupção.\012Que ótimo!",
  ["6a:7548"] = "BLAINE: Waaah!\012Meu GINÁSIO em\nCINNABAR queimou.\012Meus #MON de\nfogo e eu estamos\011sem casa devido\011ao vulcão.\012Waaah!\012Mas voltei aos\nnegócios como\011LÍDER DE GINÁSIO\011aqui nessa\011caverna.\012Se puder\nme derrotar,\011lhe darei uma\011INSÍGNIA.\012Ha! É melhor ter\num CURA FOGO!",
  ["6a:7646"] = "BLAINE: Excelente.\nVocê me queimou…\012Você mereceu\na INSÍGNIA DO\011VULCÃO.",
  ["6a:7683"] = "{PLAYER} foi pre-\nsenteado com uma\011INSÍGNIA DO VULCÃO\011DO GINÁSIO DAS\011ILHAS ESPUMA!",
  ["6a:769d"] = "BLAINE: Eu perdi\ndesta vez, mas\011eu vou vencer na\011próxima.\012Quando eu\nreconstruir meu\011GINÁSIO DE\011CINNABAR, teremos\011que ter outra\011batalha.",
  ["6a:771c"] = "BLAINE: Meus\n#MON de fogo\011ficarão ainda mais\011fortes. Aguarde!",
  ["6a:7759"] = "Ei!\012…Hã? Já\nacabou?\012Perdoe-me,\nperdoe-me!\012O GINÁSIO DE\nCINNABAR se foi,\011e não sabia aonde\011achar você.\012Mas, ei, você\né bem forte\011mesmo sem meus\011conselhos.\012Sabia que você\nvenceria essa\011batalha!",
  ["6a:7806"] = "Um GINÁSIO #MON\npode ser em\011qualquer lugar\011em que haja um\011LÍDER DE GINÁSIO.\012Não precisa ser\nem um prédio.",
  ["6b:40ec"] = "Eu vim através do\ntúnel, mas ainda\011tenho energia\011sobrando.",
  ["6b:4130"] = "Uau! Você tem mais\nenergia que eu!",
  ["6b:4153"] = "Nós ANDARILHOS\nsomos melhores nas\011montanhas.",
  ["6b:4180"] = "Ei, você pegou\num DUNSPARCE?\012Eu capturei um\ntambém.\012Observe-o na luz.\nEle fica com uma\011cara cômica!",
  ["6b:41e7"] = "Puf, puf…\012Eu finalmente\natravessei essa\011caverna.\012Era maior do que\neu esperava.\012Cansei-me muito\npara explorá-la\011toda, então eu\011saí.",
  ["6b:4279"] = "ROTA 33.",
  ["6b:4314"] = "Meus #MON\ninsetos são\011fortes.\012Prepare-se para a\nderrota…",
  ["6b:433d"] = "Fui massacrada…",
  ["6b:434d"] = "Vou procurar\n#MON insetos\nmais fortes.",
  ["6b:4376"] = "Se andar na grama\nalta vestindo\011um calção, vai\011se ferir?",
  ["6b:43bc"] = "Nada bom!",
  ["6b:43cf"] = "CIDADE DE LAVENDER\012A Nobre Cidade\nRoxa.",
  ["6b:43fa"] = "Estou preocupada\ncom queimaduras.",
  ["6b:4419"] = "Ai, ai, ai!",
  ["6b:4423"] = "As feridas vão\narder mesmo quando\011tomar um banho.",
  ["6b:447a"] = "Por que as garotas\nnão gostam de\011#MON insetos.",
  ["6b:449f"] = "Para treinadores,\né regra batalharem\011sempre se se\011encontrem.",
  ["6b:4583"] = "#MON insetos\nparecem bonecos\011de pelúcia quando\011se aperta suas\011barrigas.\012Eu os adoro!",
  ["6b:45b7"] = "ROTA 2\012CIDADE DE VIRIDIAN-\nCIDADE DE PEWTER.",
  ["6b:45d7"] = "Se treinadores se\nencontram, a\011primeira coisa\011que eles fazem\011é batalhar!",
  ["6b:4615"] = "Para treinadores,\né regra batalharem\011sempre se se\011encontrem.",
  ["6b:4631"] = "Você aí!\nDeseja batalhar?",
  ["6b:4640"] = "Você é forte.\012Obviamente deve\nter treinado duro.",
  ["6b:4675"] = "ROTA 1\012CIDADE DE PALLET-\nCIDADE DE VIRIDIAN.",
  ["6b:46e7"] = "Estou criando\n#MON também.\012Eles são\ncomo seguranças\011privados.",
  ["6b:4720"] = "Tecnologia é\nincrível!\012Agora pode-se\ntrocar #MON\011através do tempo\011como um e-mail.",
  ["6b:476b"] = "CIDADE DE PALLET\012Tranquilo Lugar\nde Paz & Pureza.",
  ["6b:479d"] = "Um…\nEu…",
  ["6b:47aa"] = "Glug…",
  ["6b:47c1"] = "CASA DO AZUL.",
  ["6b:4850"] = "LABORATÓRIO DE\nPESQUISA DO\011PROFESSOR CARVA-\011LHO.",
  ["6b:486c"] = "Glug…",
  ["6b:4873"] = "Terra à vista!\nVamos continuar!",
  ["6b:48a0"] = "Um garoto\narrogante estava\011no vulcão de\011CINNABAR.",
  ["6b:48d6"] = "Se eu vencer,\nterá que me ajudar\011com minha loção\011de bronzear!",
  ["6b:48f1"] = "Tenho que me\npreocupar com os\011danos causados\011pelo sol.",
  ["6b:4927"] = "Cansei de pescar.\nVamos batalhar!",
  ["6b:494c"] = "Falha total…",
  ["6b:495c"] = "Só vou voltar\na pescar…",
  ["6b:49d2"] = "Quem é você?\012Bem, é óbvio\nque você é um\011treinador…\012Meu nome é\nAZUL.\012Eu já fui o\nCAMPEÃO, porém foi\011por um curto\011tempo…\012Aquele intrometido\ndo VERMELHO me\011venceu…\012De qualquer modo,\no que você quer?\011Quer me desafiar\011ou outra coisa?\012…Odeio dizer isso,\nmas não estou\011muito à vontade\011para batalhas\011agora.\012Dê uma olhada\nao seu redor…\012Um vulcão entra em\nerupção e assim,\011uma cidade inteira\011desaparece.\n \012Em #MON se pode\nganhar ou perder.\011Mas se não\011tivermos cuidado,\011podemos perder em\011um segundo.\012…\012É desse jeito…\012Mas, de qualquer\nmodo, eu ainda\011sou um treinador.\012Se eu vejo um\noponente forte,\011me dá vontade de\011batalhar.\012Se quiser batalhar\ncomigo, venha\011ao GINÁSIO DE\011VIRIDIAN.\012Lá eu vou\ndesafiá-lo.",
  ["6b:4c73"] = "Há um aviso aqui…\012O GINÁSIO DE\nCINNABAR agora\011está nas ILHAS\011ESPUMA.\012BLAINE.",
  ["6b:4cc2"] = "ILHA CINNABAR\012A Quente Cidade\ndo Desejo Ardente.",
  ["6b:4d68"] = "Sinto-me bem mais\nleve na água.",
  ["6b:4d8a"] = "Oh, não!",
  ["6b:4d93"] = "Nadar exercita\ntodo seu corpo.\012É realmente bom\npara você.",
  ["6b:4dd0"] = "Que coleção\nincrível de\011INSÍGNIAS DE\011GINÁSIO.\012Nós devemos\nbatalhar!",
  ["6b:4e10"] = "Não!",
  ["6b:4e15"] = "SURFAR não é mais\no único golpe\011HM que se usa na\011água.",
  ["6b:4e4b"] = "Acho que é\nimpossível nadar\011todo caminho até\011JOHTO.",
  ["6b:4e83"] = "Aiyah!",
  ["6b:4e8b"] = "Além de no mar,\ntambém posso nadar\011em rios e lagos.",
  ["6b:4ec2"] = "O que essa placa\ndiz?\012GINÁSIO CINNABAR\nLÍDER: BLAINE.",
  ["6b:4f5c"] = "Se estiver procu-\nrando #MON,\011precisará olhar na\011grama alta.",
  ["6b:4f9c"] = "Aiieee!",
  ["6b:4fa5"] = "Como você é tão\nforte, deve\nser divertido\011batalhar.",
  ["6b:4fd7"] = "A PISTA DE\nCICLISMO é um\011curto atalho para\011CELADON.",
  ["6b:5005"] = "…Uau!",
  ["6b:500d"] = "Se não tiver\numa BICICLETA,\011não terá permissão\011para usar o\011atalho.",
  ["6b:5051"] = "ROTA 18\012CIDADE DE CELADON-\nCIDADE DE FUCHSIA.",
  ["6b:5108"] = "Ei, você! É de\nJOHTO, hein?",
  ["6b:512a"] = "Uau, você é\ndemais!",
  ["6b:513b"] = "Não se anime,\ndoidão de JOHTO!",
  ["6b:515c"] = "Uau. Que BICICLETA\nlegal!",
  ["6b:5178"] = "Mas você não é\ntão legal…",
  ["6b:5196"] = "Pareço legal,\nmas sou fraco,\011então não sou\011legal mesmo.\012Preciso treinar\nmais…",
  ["6b:51e0"] = "Ei! Quer ter uma\nbatalha veloz?",
  ["6b:5203"] = "Nossa! Você tem\nótimas técnicas!",
  ["6b:5225"] = "Andar sem as mãos\né considerado\011legal na PISTA DE\011CICLISMO.",
  ["6b:525c"] = "Somos as destemi-\ndas estrelas da\011pista!",
  ["6b:527a"] = "Ahh… Tenho recorde\nde derrotas…",
  ["6b:5293"] = "Dirigir sem\ncuidado causa\011acidentes!\012Pega leve!",
  ["6b:532f"] = "CASA DA ALMA\012Deixe as Almas\ndos #MON\011Descansarem em\011Paz.",
  ["6b:5388"] = "Treinadores que\nprocuram poder\011escalam o MONTE\011PRATA ignorando\011seus perigos.\012Com seus #MON\nconfiados, acham\011que podem ir a\011qualquer lugar…",
  ["6b:5456"] = "Está trancada!",
  ["6b:54c2"] = "Deixe-me lhe\ncontar, custou-me\011capturar meu\011#MON premiado.",
  ["6b:54ff"] = "Awaaah!",
  ["6b:5508"] = "SQUIRTLE,\nCHARMANDER e\011BULBASAUR…\012Acho que é uma\nmistura bem\011balanceada.",
  ["6b:5552"] = "Meu sonho é voar\ncom meu querido\011#MON pássaro.",
  ["6b:5581"] = "Posso sonhar, mas\nnunca voar…",
  ["6b:55a4"] = "Você tem #MON\nque sabem o\011golpe HM VOAR,\011não é?\012Eu o invejo.",
  ["6b:55e4"] = "Oi. Você sabia…?\012#MON ficam\nmais amigáveis se\011você treiná-los\011em um lugar de\011que se lembrem.",
  ["6b:5640"] = "Onde encontrei\nesse PSYDUCK?",
  ["6b:5660"] = "Se existisse um\nmétodo fácil de\011identificar onde\011peguei meu\011#MON…",
  ["6b:5702"] = "KANTO tem vários\nprogramas de rádio\011bons.",
  ["6b:573a"] = "Pessoas vêm de\ntodos lugares para\011homenagear as\011almas dos #MON\011mortos.",
  ["6b:575c"] = "Você precisa\nde uma #\011FLAUTA para\011acordar #MON\011dorminhocos.\012Todo treinador\ntem que saber\011disso!",
  ["6b:57ac"] = "ESTAÇÃO DE RÁDIO\nDE KANTO\012Seus Programas\nPreferidos no Ar\011o Dia Todo!",
  ["6b:57f7"] = "VOLUNTÁRIO DE\nLAVENDER\012CASA DE #MON.",
  ["6b:581c"] = "Fui chicoteado!",
  ["6b:5861"] = "CAVERNA DOS\nDIGLETT.",
  ["6b:5880"] = "CASA DO AZUL.",
  ["6b:5957"] = "A estrada estará\nfechada até o\011problema na USINA\011ELÉTRICA ser\011resolvido.",
  ["6b:599b"] = "CAMINHO DO SUBSOLO\012CIDADE DE CERULEANA-\nCIDADE DE VERMILION.",
  ["6b:59cc"] = "Meu PHANPY é o\nmais lindo do\011mundo.",
  ["6b:59f3"] = "CASA DO VERMELHO.",
  ["6b:59ff"] = "Olhe como age\nadorável meu\011PHANPY!\012Não é lindo o\nbastante para\011derreter seu\011coração?",
  ["6b:5a4f"] = "Meu TEDDIURSA é o\nmais lindo do\011mundo.",
  ["6b:5a79"] = "Meu TEDDIURSA!",
  ["6b:5a88"] = "Olhe como age\nadorável meu\011TEDDIURSA!\012Não é lindo o\nbastante para\011derreter seu\011coração?",
  ["6b:5b22"] = "O que é isso?\012Casa a venda…\nNinguém mora aqui.",
  ["6b:5b66"] = "A porta está\ntrancada…",
  ["6b:5b97"] = "CAMINHO DO SUBSOLO\012CIDADE DE CERULEANA-\nCIDADE DE VERMILION.",
  ["6b:5c2e"] = "Ei, garoto! Eu\nsou um membro da\011EQUIPE ROCKET!\012Vindo de outro\npaís, sou um\011treinador número\011um!\012Eu achei, que se\nparasse a energia,\011causaria grande\011pânico para as\011pessoas!\012É segredo da\nminha missão,\011então não lhe\011contarei!\012Mas! Se a mim\nvocê vencer, homem\011serei e meu\011segredo a você\011contarei.\012Ei, garoto!\nComeçar batalha!",
  ["6b:5d67"] = "Ayieeeh! Não, não,\nnão, nisso não\011acredito!\012Muito forte você\né! Páreo para você\011não sou!",
  ["6b:5dc0"] = "Certo. O segredo\na você contarei.\012A PEÇA DA MÁQUINA\nque roubei, a\011escondi no GINÁSIO\011de CERULEANA.\012Dentro da água a\ncoloquei. Olhe\011na água no centro\011do GINÁSIO.\012Mas você não\nme esqueça!\012Derrotá-lo a\nEQUIPE ROCKET\011certamente vai.\012Vir de JOHTO, eles\nvão, meus amigos,\011sim. Vingar-se\011vão.",
  ["6b:5ee1"] = "…\012Você disse o quê?\nEQUIPE ROCKET\011Adeeeeeus? Acabou\011foi o que disse?\012Oh, não! A partir\nde agora, o que\011devo fazer?",
  ["6b:5fb8"] = "Ah! O tempo está\nbom como sempre.",
  ["6b:5fdb"] = "Faz sol, mas\nestou molhado…",
  ["6b:5ff7"] = "Quando chove, é\ndifícil fazer\011fogo…",
  ["6b:6021"] = "Hmmm… Não sei o\nque fazer…",
  ["6b:6040"] = "Sabia que\nperderia…",
  ["6b:6051"] = "Você parecia\nforte.\012Fiquei com medo de\ndesafiá-lo…",
  ["6b:6082"] = "Posso correr como\no vento!",
  ["6b:609c"] = "Hahahahahaha!",
  ["6b:60a9"] = "Visto calções o\nano inteiro.\012É minha política\nde moda.",
  ["6b:60e7"] = "Dê um passo e dê\numa olhada!",
  ["6b:6107"] = "Uau! É quente!",
  ["6b:6118"] = "O melhor sopra\nfogo em KANTO,\011sou eu.\012Mas não sou o\nmelhor treinador…",
  ["6b:6163"] = "PRAÇA DO MONTE LUA\012Apenas suba as\nescadas.",
  ["6b:6214"] = "Estou criando meus\n#MON.\012Quer batalhar\ncomigo?",
  ["6b:6241"] = "Droga! Essa eu\nperdi…",
  ["6b:6258"] = "Se haver um\n#MON específico\011que deseja criar,\011ponha-o em\011primeiro lugar na\011lista.\012É assim que se\nfaz.",
  ["6b:62ce"] = "Sinto que eu\nvou vencer.\012Vamos ver se\ntenho razão!",
  ["6b:6306"] = "Aww, você é muito\nforte.",
  ["6b:6320"] = "Soube que\nos CLEFAIRY surgem\011no MONTE LUA.\n \012Mas onde poderiam\nestar?",
  ["6b:635e"] = "Um…\nEu…",
  ["6b:6369"] = "……Vou treinar\nmais…",
  ["6b:6384"] = "PRAÇA DO MONTE LUA\012Apenas suba as\nescadas.",
  ["6b:6421"] = "Aaaaaaa!",
  ["6b:642b"] = "Aaaaa-tchinnn!",
  ["6b:643b"] = "Binha gribe está\nme fazendo\011esbirrar!\012Aaa-TCHIN!",
  ["6b:6468"] = "Você gosta de\n#MON, não é?\012Eu também!",
  ["6b:648a"] = "Devo dizer que é\nminha derrota.",
  ["6b:64a9"] = "Veja o que fez\naos meus #MON…\012Não esquecerei\nisso…",
  ["6b:64dc"] = "ROTA 10\012CIDADE DE CERULEANA-\nCIDADE DE LAVENDER.",
  ["6b:653a"] = "PLANALTO ÍNDIGO\012O Objetivo Final\npara os Treinadores!",
  ["6b:65a0"] = "Oh, querido. Você\nme achou.\012Favor não contar\na ninguém sobre\011mim.\012Vou lhe dar isso\npor guardar meu\011segredo. Certo?",
  ["6b:6682"] = "É difícil ser uma\ncelebridade.\012Em todo lugar que\nvou as pessoas\011me perseguem.\012Só quero ser\ndeixada sozinha…",
  ["6b:66f0"] = "É difícil ser uma\ncelebridade.\012Em todo lugar que\nvou as pessoas\011me perseguem.\012Só quero ser\ndeixada sozinha…",
  ["6b:6752"] = "FEAROW: Feero!",
  ["6c:4000"] = "Bom dia!\nBem-vindo ao nosso\011CENTRO #MON.",
  ["6c:402b"] = "Olá!\nBem-vindo ao nosso\011CENTRO #MON.",
  ["6c:404f"] = "Boa noite!\nVocê veio tarde.\012Bem-vindo ao nosso\nCENTRO #MON.",
  ["6c:408a"] = "Bom dia!\012Esse é o CENTRO\nDE COMUNICAÇÃO\012#MON--ou CENTRO\n#COM.",
  ["6c:40d6"] = "Olá!\012Esse é o CENTRO\nDE COMUNICAÇÃO\012#MON--ou CENTRO\n#COM.",
  ["6c:411b"] = "Que bom vê-lo tra-\nbalhar até tarde.\012Esse é o CENTRO\nDE COMUNICAÇÃO\012#MON--ou CENTRO\n#COM.",
  ["6c:417a"] = "Podemos curar seus\n#MON deixando-\011os com saúde per-\011feita.\012Podemos curar\nseus #MON?",
  ["6c:41bd"] = "Certo, deixe-me\nver seus\011#MON.",
  ["6c:41d7"] = "Obrigado por\naguardar.\012Seus #MON\nestão totalmente\011curados.",
  ["6c:420b"] = "Esperamos vê-lo\nde novo.",
  ["6c:4241"] = "Seu #MON\nparece estar\012infectado por\npequenas formas de\011vida.\012Parece estar\nsaudável, sem\011problemas.\012Mas não podemos\nlhe dar mais\012informações em um\nCENTRO #MON.",
  ["6c:42d6"] = "Seu #MON\nparece estar\012infectado por\npequenas formas de\011vida.\012Parece estar\nsaudável, sem\011problemas.\012Mas não podemos\nlhe dar mais\012nenhuma infor-\nmação.",
  ["6c:435a"] = "Está cheio de\nlivros difíceis.",
  ["6c:4378"] = "Uma coleção in-\nteira de livros\011de figuras de\011#MON!",
  ["6c:43a3"] = "REVISTAS #MON…\nJOGOS DE #MON,\012MANUAIS #MON,\nGRÁFICOS #MON…",
  ["6c:43d9"] = "JURAMENTO DA\nEQUIPE ROCKET\012Roubar #MON\npor lucro!\012Explorar #MON\npor lucro!\012Todos #MON\nexistem para a\011glória da EQUIPE\011ROCKET!",
  ["6c:4448"] = "O que é isso?\012Oh, é um porta\nincensos!",
  ["6c:4472"] = "Muitos produtos\npara #MON!",
  ["6c:448d"] = "Este é o MAPA\nDO CONTINENTE.",
  ["6c:44a0"] = "Meu reflexo!\nEu pareço ótimo!",
  ["6c:44be"] = "É uma televisão.",
  ["6c:44c9"] = "HOME PAGE do\n#MON JORNAL…\012Não foi atuali-\nzada…",
  ["6c:4526"] = "Não há nada\naqui…",
  ["6c:457f"] = "Cure os Seus\n#MON!\012CENTRO #MON.",
  ["6c:459c"] = "Agora julgaremos\no #MON que\011você capturou.\012…\n…\012Nós escolhemos os\nvencedores!\012Você está pronto\npara isso?",
  ["6c:45bf"] = "Agora julgaremos\no #MON que\011você capturou.\012…\n…\012Nós escolhemos os\nvencedores!\012Você está pronto\npara isso?",
  ["6c:4621"] = "{PLAYER}, the No.{STRBUF}\nfinisher, wins\011{STRBUF}!",
  ["6c:4648"] = "{PLAYER} received\n{STRBUF}.",
  ["6c:465b"] = "Junte-se a nós\npara o próximo\011Concurso!",
  ["6c:4681"] = "Os outros ganham\numa FRUTA como prê-\011mio de consolação!",
  ["6c:46b7"] = "Esperamos que me-\nlhorem na próxima\011vez.",
  ["6c:46d9"] = "Vamos devolver os\n#MON que guar-\012damos para você.\nAqui está!",
  ["6c:470d"] = "Sua equipe está\ncheia, então o\012foi enviado para\nBOX no PC DO\011BILL.",
  ["6c:474e"] = "{STRBUF}\nGINÁSIO #MON",
  ["6c:475c"] = "LEADER: {STRBUF}\012WINNING TRAINERS:\n{PLAYER}",
  ["6c:477f"] = "Bem-vindo à\nCASA DE JOGOS.",
  ["6c:479c"] = "Você precisa de\nmoedas de jogo?\012Oh, você não tem\num PORTA MOEDAS\011para elas.",
  ["6c:47e3"] = "Você precisa de\nmoedas de jogo?\012O preço é ¥1000\npara 50 moedas.\011Quer algumas?",
  ["6c:4830"] = "Obrigado! \nAqui estão as\01150 moedas.",
  ["6c:484f"] = "Obrigado! \naqui estão as\011500 moedas.",
  ["6c:486f"] = "Você não tem\ndinheiro sufi-\011ciente.",
  ["6c:488c"] = "Opa! Seu PORTA\nMOEDAS está cheio.",
  ["6c:48ad"] = "Não quer moedas?\nVolte outra hora!",
  ["6c:48cc"] = "Oh? Sua BOLSA\nestá cheia.\012Vamos guardar esse\npara você hoje,\012então volte quando\nliberar espaço.",
  ["6c:492a"] = "Uau! Você e seus\n#MON são real-\011mente próximos!",
  ["6c:4954"] = "Os #MON ficam\nmais amigáveis se\012você gastar tempo\ncom eles.",
  ["6c:4989"] = "Você não domou\nseus #MON.\012Se não se derem\nbem, ele não se\011sentirá à vontade.",
  ["6c:49c4"] = "{PLAYER} registered\n{STRBUF}'s number.",
  ["6c:49e1"] = "{PLAYER} registered\n{STRBUF}'s number.",
  ["6c:49fe"] = "Seu conhecimento\né impressionante!\012Eu gosto disso!\012Quer trocar dicas\nde batalhas?\012Vou telefoná-lo\nse eu obtiver\011boas informações.\012Poderia me contar\nseu número?",
  ["6c:4a82"] = "Quer trocar dicas\nde batalhas?\012Vou telefoná-lo\nse eu obtiver\011boas informações.\012Poderia me contar\nseu número?",
  ["6c:4adb"] = "Vou telefoná-lo\nse eu souber de\011algo!",
  ["6c:4afd"] = "Certo, certo.\nQue pena…\012Bem, se quiser\nmeu número, vem\011me ver, certo?",
  ["6c:4b42"] = "Oh?\nSeu telefone\011está lotado.\012Não pode registrar\nmeu número.",
  ["6c:4b75"] = "Oi, eu estava\nesperando você\011aparecer!\012Vamos começar\nlogo!",
  ["6c:4bb6"] = "Seu MARILL é tão\nlindo e adorável!\012Você ama #MON\ncomo eu!\012Quer trocar nú-\nmeros de telefone?\012Vamos conversar!\nVai ser tão\011divertido!",
  ["6c:4c37"] = "Seu MARILL é tão\nlindo e adorável!\012Devemos conversar,\nvai ser divertido.\012Posso ter seu nú-\nmero de telefone?",
  ["6c:4c9b"] = "Para ser honesto,\neu quero um\011MARILL.\012Mas estou feliz\ncom meu lindo\011SNUBBULL.",
  ["6c:4ce0"] = "Oh… Isso é\ndesapontador…\012Adeus, MARILL…",
  ["6c:4d0b"] = "Oh? A memória de\nseu telefone está\011cheia.",
  ["6c:4d2c"] = "Oh? {PLAYER}? \nEu esperei por\012você aqui. Trouxe-\nlhe um pequeno\011presente.",
  ["6c:4d69"] = "Oh?\nVocê não tem\011espaço.\012Volte outra\nhora.",
  ["6c:4d9f"] = "Legal! É a pri-\nmeira vez que\011perco em um\011bom tempo!\012Ei, me dá seu nú-\nmero de telefone.\012Vai se divertir\nao batalhar, então\012vou ligar para\nvocê quando eu me\011fortalecer!",
  ["6c:4e2c"] = "Ei, me dá seu nú-\nmero de telefone.\012Vai se divertir\nao balahar, então\012vou ligar para\nvocê quando eu me\011fortalecer!",
  ["6c:4e89"] = "Ei, vamos batalhar\nde novo!",
  ["6c:4ea2"] = "Parece que você\né um bobo…",
  ["6c:4ebc"] = "Ei! Seu telefone\njá está lotado!",
  ["6c:4edc"] = "Ei! Estou cansado\nde esperar por\011você!",
  ["6c:4eff"] = "Oh… Sua BOLSA\nestá cheia. Vou\011lhe dar isso\011depois.",
  ["6c:4f2f"] = "Cara! Você está\nmais forte do\011que nunca!\012Já batalhei várias\nvezes com você,\012{PLAYER}, mas eu\nnunca venci.\012Comprei toneladas\nde itens para\012fortalecer meu\n#MON, mas não\011obtive resultados…\012Só itens não são\na resposta.\012Deve ser isso\nmesmo…\012Ei, leve isso,\n{PLAYER}.\012Não vou precisar\nmais dele…",
  ["6c:502e"] = "Wow, you're tough.\nI haven't battled\012that seriously in\na long time.\012Could I get your\nphone number?\012I'd like to battle\nagain when I heal\012{STRBUF} and the\nrest of my team.",
  ["6c:50d3"] = "Could I get your\nphone number?\012I'd like to battle\nagain when I heal\012{STRBUF} and the\nrest of my team.",
  ["6c:5136"] = "Como eu posso\nvencê-lo. Estou\012atormentado por\nesses pensamentos\011o tempo todo…",
  ["6c:517b"] = "Certo… Eu entendo…\nMas se mudar de\012idéia, ligue-me\na qualquer hora.",
  ["6c:51c4"] = "A memória de seu\ntelefone está\011cheia.\012Você não pode\nregistrar meu\011número.",
  ["6c:51fe"] = "Oi! Estive esperando\npor você!\012Desta vez, eu\nvencerei!",
  ["6c:5239"] = "Já fazia muito\ntempo que eu\011não perdia…\012Você é muito bom\nnas batalhas.\012Devemos batalhar\nde novo.\012Ao desafiar um\ntreinador forte\012como você, eu\nacho que posso\011melhorar também.\012Que tal então?\012Você me daria\nseu número de\011telefone?",
  ["6c:5314"] = "Ao desafiar um\ntreinador forte\012como você, eu\nacho que posso\011melhorar também.\012Que tal então?\012Você me daria\nseu número de\011telefone?",
  ["6c:5392"] = "Vamos batalhar\nde novo em outra\011hora!",
  ["6c:53af"] = "Isso é mal…\012Avise-me se você\nmudar de idéia.",
  ["6c:53e4"] = "Oh não. Seu tele-\nfone está sem\011memória.",
  ["6c:5409"] = "Você certamente\nme fez esperar!\011Vamos lá!",
  ["6c:542d"] = "If my {STRBUF}\nsees anything\012pretty, it goes\nand gets it.\012Do you like pretty\nthings?\012I could share if\nit gets some more.\012What's your phone\nnumber? I'll call.\012Don't expect a\nwhole lot, OK?",
  ["6c:54e4"] = "Você gosta de\ncoisas bonitas?\012Eu poderia dividir\nse FARFETCH'D\011pegasse mais.\012Qual é o seu nú-\nmero de telefone?\012Eu vou ligar.",
  ["6c:5553"] = "Vou ligar para\nvocê logo quando\011eu obtiver algo\011bonito.",
  ["6c:5584"] = "Você jura? Bem,\nAvise-me se mudar\011de idéia.",
  ["6c:55b6"] = "Hã? A lista de\nseu telefone\011está cheia.",
  ["6c:55d5"] = "Piiiu! Piiiiiu!\012Fez-me esperar!\nVá, FARFETCH'D!",
  ["6c:5607"] = "Fez-me esperar!\nOlha, é isso!\012Vê? Isso não\né bonito?",
  ["6c:564d"] = "Hã? Você não tem\nlugar para pôr\012issos. Volte\ndepois para isso.",
  ["6c:5690"] = "Droga…\nSou derrotada\012por tudo, até\npela má sorte…\012Gosto de você!\nDê-me seu número!\012Você pode ser\nmeu parceiro de\011prática!",
  ["6c:5710"] = "Dê-me seu número\nde telefone!\012Você vai ser\nmeu parceiro de\011prática!",
  ["6c:5755"] = "Não fique orgu-\nlho por me der-\011rotar!\012Foi sorte!",
  ["6c:578a"] = "Eu não acredito!\nVocê vai se\011arrepender!",
  ["6c:57ba"] = "O quê? Sua lista\nde telefone não\011tem espaço!",
  ["6c:57de"] = "O que te impede?\nComece logo!",
  ["6c:5800"] = "Escuta, posso\npegar seu número\011de telefone?\012Vou te telefonar\npara termos\011algumas batalhas.\n\012Sou novato também,\nentão acho que\011vai ser um bom\011motivador.",
  ["6c:587b"] = "Posso pegar seu\nnúmero de tele-\011fone?\012Não quero perder\npara você!\012Devemos batalhar\nde novo, certo?",
  ["6c:58d7"] = "Vou te telefonar\nsempre que eu\011quiser uma bata-\011lha urgente!",
  ["6c:5908"] = "Oh, certo…\012Mas eu não vou\nperder para você\011de novo!",
  ["6c:5936"] = "Hã, o quê? Seu\ntelefone está\011cheio.",
  ["6c:5954"] = "Estive esperando!\nVamos batalhar\011agora!",
  ["6c:5978"] = "Ei, espera sua\nBOLSA está lo-\011tada!\012Bem, vamos espe-\nrar até a próxima.",
  ["6c:59be"] = "E mais uma\nderrota…\012Não tenho mais\ndúvidas--você é\011forte.\012Ser derrotado\nfrequentemente\011atualmente parece\011bom agora!\012Ei, leve isso. \nUse isso para\012ficar mais forte.\nVai me fortalecer\011também!",
  ["6c:5a71"] = "Você é ótimo!\nGosto de você!\012Procuro por #-\nMONS aqui todos\011os dias.\012Quando estou na\ngrama, eu acho\011todos tipos de\011FRUTAS.\012Se gostar, eu\npoderei dividir.\012Eu poderia pegar\nseu número de\011telefone?",
  ["6c:5b1d"] = "Quando estou na\ngrama, eu acho\011todos tipos de\011FRUTAS.\012Se gostar, eu\npoderei dividir.\012Eu poderia pegar\nseu número de\011telefone?",
  ["6c:5b8e"] = "Vamos nos falar\nlogo quando eu\012achar algo de\nseu interesse.",
  ["6c:5bd2"] = "Oh bem. Não seja\ntímido se quiser\011pegar meu número.",
  ["6c:5c06"] = "Sua lista de\ntelefone não tem\011espaço para meu\011número.",
  ["6c:5c32"] = "Eu estava espe-\nrando por você.\011Vamos batalhar!",
  ["6c:5c57"] = "Que bom te ver!\nVê? É isso que\012achei.\nÉ para você!",
  ["6c:5c91"] = "Opa, sua BOLSA\nestá cheia.\012Que mal. Você\ndeve voltar aqui\011depois.",
  ["6c:5cd5"] = "Os jovens não\npescam mais?\012Eu vi raros\n#MON enquanto\011eu pescava…\012Vocês jovens\ngostam disso,\011certo?\012Quer trocar nú-\nmeros de telefone?\012Vou avisá-lo se\neu vir algo.",
  ["6c:5d85"] = "Hm? Então quer que\neu te telefone se\011eu vir #MON\011raros?",
  ["6c:5db9"] = "Sim, vou telefonar\nse eu vir #MON\011raros.\012Não se preocupe,\nnão esquecerei!",
  ["6c:5df4"] = "Oh…\nNem meus prórpios\012filhos me dão seus\nnúmeros de tele-\011fone…\012As pessoas jovens\nsão assim hoje\011em dia?",
  ["6c:5e50"] = "A memória de seu\ntelefone está\011cheia.\012Parece que todos\nos joven de hoje\011têm #GEAR.",
  ["6c:5e98"] = "Ei, garoto!\012Não perca para\nmim hoje!",
  ["6c:5ebe"] = "Oh? Você está em\numa grande jornada\011para fazer obser-\011vações? Legal!\012Vamos ser amigos!\nPosso ter seu nú-\011mero de telefone?\012Quero saber de\ntudo que você\011observar!",
  ["6c:5f4e"] = "Vamos ser amigos!\nPosso ter seu nú-\011mero de telefone?\012Quero saber de\ntudo que você\011observar!",
  ["6c:5faa"] = "Vou telefoná-lo\nse eu souber de\011algo interessante.",
  ["6c:5fdd"] = "Ahh… Não vai ser\nmeu amigo?",
  ["6c:5ffa"] = "Espere! Sua lista\nde telefone está\011cheia!",
  ["6c:601f"] = "Você está atra-\nsado! Vamos come-\011çar agora!",
  ["6c:6054"] = "MONTE PRATA.",
  ["6c:6086"] = "USINA ELÉTRICA DE KANTO.",
  ["6d:4000"] = "Alô?\012Oh, oi, {PLAYER}!\nSe esforçando?",
  ["6d:4021"] = "Oh, então está em\n{STRBUF}…\012Não é aí onde está\no {STRBUF}?\012Você já passeou\npor lá?",
  ["6d:406b"] = "É sério, você está\nem {STRBUF}?\012Eu nunca fui até\naí. Isso é bem ba-\011cana, {PLAYER}.",
  ["6d:40b1"] = "O quê? Você está\nem {STRBUF}?\012Venha visitar sua\nMÃE às vezes!",
  ["6d:40e4"] = "Está visitando\n{STRBUF}?\012Que tal passar em\ncasa, hein, bebê?",
  ["6d:411c"] = "Uau, você está em\n{STRBUF}?\012Boa sorte na sua\njornada #MON!",
  ["6d:4150"] = "Isso parece bem\ncomplicado.\012Mas {PLAYER}, eu\nsei que você está\012com sua determina-\nção em dia, certo?\011Vai dar certo!",
  ["6d:41a7"] = "Mas enfim, você já\neconomizou ¥{STRBUF}.\012Quer que eu conti-\nnue guardando?",
  ["6d:41ea"] = "É importante guar-\ndar seu dinheiro.",
  ["6d:420d"] = "Oh, {PLAYER}, você\nnão está guardando\012dinheiro. Quer que\neu guarde ele?",
  ["6d:4249"] = "Enfim, você econo-\nmizou ¥{STRBUF}.\012Quer voltar a eco-\nnomizar de novo?",
  ["6d:4289"] = "Ok. Eu vou guardar\no seu dinheiro.",
  ["6d:42a3"] = "Ok. Vou parar de\nguardar o seu\011dinheiro.",
  ["6d:42c0"] = "{PLAYER}, continue\nassim! Estou tor-\011cendo por você,\011querido!",
  ["6d:42ea"] = "Alô?\012Oh, oi, {PLAYER}!\nO PROFESSOR ELM não es-\011tá te esperando?",
  ["6d:431d"] = "Alô?\012Oh, oi, {PLAYER}!\nEstá numa missão\012para o PROFESSOR ELM?\nSe cuida, viu!",
  ["6d:435f"] = "Alô?\012Oi, {PLAYER}! Se\nvocê terminou sua\012tarefa, venha pra\ncasa, docinho.",
  ["6d:43a1"] = "Alô?\012…… {PLAYER}?\nEu ouvi do PROFESSOR\012ELM que você saiu\nde viagem.\012Eu queria que você\nme contasse antes…\012E o seu dinheiro?\nPosso guardá-lo?",
  ["6d:4427"] = "Bom dia!\012Este é o SERVIÇO\nDE ADMINISTRAÇÃO\011DO SISTEMA DE\012ARMAZENAMENTO\n#MON.",
  ["6d:4470"] = "Boa tarde!\012Este é o SERVIÇO\nDE ADMINISTRAÇÃO\011DO SISTEMA DE\012ARMAZENAMENTO\n#MON.",
  ["6d:44b5"] = "Boa noite!\012Este é o SERVIÇO\nDE ADMINISTRAÇÃO\011DO SISTEMA DE\012ARMAZENAMENTO\n#MON.",
  ["6d:44fe"] = "Quem fala?\012{PLAYER}, certo?\nSó um momento…\012……\n……",
  ["6d:452a"] = "Obrigado por\nesperar!\012{PLAYER}, a sua\nCAIXA tem espaço\011para mais {STRBUF}\011#MON.\012Fique à vontade\npara completá-la!",
  ["6d:4587"] = "Obrigado por\nesperar!\012{PLAYER}, a sua\nCAIXA tem espaço\011para apenas {STRBUF} #MON.\012Talvez você deva\ntrocar sua CAIXA.",
  ["6d:45ed"] = "Obrigado por\nesperar!\012{PLAYER}, a sua\nCAIXA está cheia!\012Você terá que\ntrocar de CAIXA se\012quiser capturar\nmais #MON.",
  ["6d:4652"] = "Alô, {PLAYER}?\nSou eu, o BILL!\012Obrigado por usar\nmeu SISTEMA DE\011ARMAZENAMENTO.\012Aquele último\n#MON que você man-\011dou encheu a sua\011CAIXA.\012Você vai ter que\ntrocar de CAIXAS\012se quiser capturar\nmais #MON.\012Até mais!",
  ["6d:46fc"] = "Alô, {PLAYER}?\012Não exagere\ndemais.\012Certifique-se de\ncurar seu #MON\011se ele se machucar.",
  ["6d:4749"] = "Alô, {PLAYER}?\012Você conheceu o\nSR. #MON? Legal!\011Cuidado na volta!",
  ["6d:4784"] = "{PLAYER}? Estou\nmuito estressado.\012Tivemos um #MON\nroubado daqui.\012Como alguém pode-\nria fazer isso?",
  ["6d:47d5"] = "Alô, {PLAYER}?\012Estamos estudando\no OVO agora.\012Parece ser um\nOVO #MON.",
  ["6d:481c"] = "Alô, {PLAYER}?\012Você viu meu as-\nsistente? Ele está\012no CENTRO #MON\nna CIDADE DE VIOLET.",
  ["6d:4868"] = "Alô, {PLAYER}?\012Como está o OVO?\nAlgo aconteceu?\012Se acontecer algo,\nme ligue, ok?",
  ["6d:48bb"] = "Alô, {PLAYER}?\nComo está o OVO?\012O quê? Ele chocou?\nUau! Que tipo de\011#MON é?\012Venha me mostrar\nagora, por favor!",
  ["6d:491f"] = "Alô, {PLAYER}?\012Acabei de fazer\numa descoberta.\012O tempo que leva\npara um OVO chocar\012varia de um #MON\npara o outro.",
  ["6d:4982"] = "Alô, {PLAYER}?\012Ainda é um misté-\nrio quais golpes\012um #MON recém-\nnascido pode apren-\011der.\012Estamos investi-\ngando isso.",
  ["6d:49e7"] = "Alô, {PLAYER}?\012Eu descobri algo\nesquisito.\012Aparentemente ex-\niste algo chamado\012#RUS que pode\ninfectar #MON.\012Sim, é como um ví-\nrus, então tem o\011nome de #RUS.\012Ele se propaga rá-\npido e infecta\012outros #MON tam-\nbém. Mas é só isso.\012Não parece ter\nnenhum sintoma,\012e vai embora com\no tempo.\012Acho que não é\nnada para se pre-\011ocupar. Tchau!",
  ["6d:4b17"] = "A-alô? {PLAYER}?\nÉ um desastre!\012Ah, hum, é simples-\nmente terrível!\012O que eu faço?\nÉ… Ah, não…\012Por favor, volte\npara cá agora!",
  ["6d:4b87"] = "Alô, {PLAYER}? Nós\ndescobrimos algo\012sobre o OVO!\012Meu assistente foi\nao CENTRO #MON\012na CIDADE DE VIOLET.\nVocê pode falar\011com ele?",
  ["6d:4c06"] = "{PLAYER}, como es-\ntão as coisas?\012Liguei porque algo\nestranho está\012acontecendo com a\ntransmissão da\011rádio.\012Estavam falando\nsobre a EQUIPE\011ROCKET.\012{PLAYER}, você sabe\nalguma coisa sobre\011isso?\012Talvez a EQUIPE\nROCKET tenha voltado.\012Não, isso não pode\nser verdade.\012Desculpe pelo incô-\nmodo. Se cuida!",
  ["6d:4d09"] = "Alô, {PLAYER}?\012Tenho algo para\nvocê aqui.\012Pode vir ao meu\nLABORATÓRIO?\012Até mais!",
  ["6d:4dc5"] = "Alô? É a\n{STRBUF} falando…\012Bom dia,\n{PLAYER}!",
  ["6d:4ded"] = "Alô? Sou eu,\n{STRBUF}…\012Como você está,\n{PLAYER}?",
  ["6d:4e16"] = "Alô? Sou eu, o\n{STRBUF}…\012Boa noite,\n{PLAYER}!",
  ["6d:4e3e"] = "{PLAYER}, bom dia!\012Sou eu, {STRBUF}.\nComo vai?",
  ["6d:4e72"] = "{PLAYER}, opa!\012Sou eu, {STRBUF}.\nO clima tá bom aí?",
  ["6d:4e9e"] = "{PLAYER}, boa\nnoite!\012Sou eu, {STRBUF}.\nTem um minutinho?",
  ["6d:4ecd"] = "How are your\nPOKéMON doing?\012My {STRBUF} is\nso curious, it's a\012problem. Maybe\nit's like me…",
  ["6d:4f21"] = "Hello, this is\n{STRBUF}.\012Oh! Good morning,\n{PLAYER}.",
  ["6d:4f4d"] = "Hello, this is\n{STRBUF}.\012Oh! Good day,\n{PLAYER}.",
  ["6d:4f75"] = "Hello, this is\n{STRBUF}.\012Oh! Good evening,\n{PLAYER}.",
  ["6d:4fa1"] = "Hello, {PLAYER}.\nGood morning.\012This is {STRBUF}.\nWere you asleep?",
  ["6d:4fda"] = "Hi, {PLAYER}.\nThis is {STRBUF}.\012How are you doing?",
  ["6d:5004"] = "Hi, {PLAYER}.\nThis is {STRBUF}.\012Were you awake?",
  ["6d:502b"] = "Keeping your\nPOKéMON happy?\012My {STRBUF} is\nhealthy. It eats a\011lot every day.",
  ["6d:5073"] = "Yeah, this is\n{STRBUF}.\012Huh? What's up,\n{PLAYER}?",
  ["6d:509b"] = "Yeah, this is\n{STRBUF}.\012Huh? What's up\n{PLAYER}?",
  ["6d:50c2"] = "Yeah, this is\n{STRBUF}.\012Huh? What's up\n{PLAYER}?",
  ["6d:50e9"] = "Yo, {PLAYER}!\nYou awake?\012It's me, {STRBUF}!\nHow's it going?",
  ["6d:511a"] = "Yo, {PLAYER}! You\nfree right now?\012It's me, {STRBUF}!\nHow's it going?",
  ["6d:5154"] = "Yo, {PLAYER}!\nWere you asleep?\012It's me, {STRBUF}!\nHow's it going?",
  ["6d:518b"] = "How are your\nPOKéMON doing?\012My POKéMON are a\nbit too energetic.\012{STRBUF},\nespecially.\012Every time it\nspots a trainer,\011it has to battle.\012It gets to be a\nbit much for me!",
  ["6d:522b"] = "My {STRBUF}'s\nlooking tougher\011than ever.\012It looks even\ntougher than me!",
  ["6d:5270"] = "Hello, this is\n{STRBUF} speaking…\012Hi, {PLAYER}!\nGood morning!",
  ["6d:52a5"] = "Hello, this is\n{STRBUF} speaking…\012Hi, {PLAYER}!",
  ["6d:52cc"] = "Hello, this is\n{STRBUF} speaking…\012Hi, {PLAYER}!\nGood evening!",
  ["6d:5301"] = "{PLAYER}, bom dia!\012Sou eu, {STRBUF}.\nComo vai?",
  ["6d:5335"] = "Hi, {PLAYER}!\012It's me, {STRBUF}.\nHow are you doing?",
  ["6d:535f"] = "{PLAYER}, good\nevening!\012It's me, {STRBUF}.\nHow are you doing?",
