  ["71:4dcd"] = "Obrigada.",
  ["71:4dd6"] = "Opa, sua BOLSA\nestá lotada.",
  ["71:4df7"] = "Você já comprou\nisso. Não tenho\011mais esse produto.",
  ["71:4e28"] = "Opa, você está com\npouco dinheiro.",
  ["71:4e46"] = "Volte aqui outra\nhora.",
  ["71:4e5f"] = "O que foi?\nPrecisa de\011remédio?",
  ["71:4e7e"] = "Quantos?",
  ["71:4e89"] = "{NUM} {STRBUF}(S)\nwill cost ¥{NUM}.",
  ["71:4eab"] = "Muito obrigada!",
